        <div className="fixed top-12 left-1/2 -translate-x-1/2 z-[300] w-full max-w-sm px-4 animate-pop-in">
           <div className="bg-white/90 dark:bg-slate-900/90 backdrop-blur-3xl border border-orange-500/20 rounded-[2.5rem] p-6 shadow-2xl flex items-start gap-5 relative overflow-hidden group">
              <div className="w-14 h-14 bg-orange-500 rounded-2xl flex items-center justify-center text-white flex-shrink-0 animate-bounce shadow-lg shadow-orange-500/30">
                 <BellRing size={28}/>
