const AuthGate: React.FC<AuthGateProps> = ({ onAuthSuccess, initialLang = Language.EN }) => {
  const [mode, setMode] = useState<'LOGIN' | 'REGISTER' | 'VERIFY'>('LOGIN');
  const [showPass, setShowPass] = useState(false);
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState<string | null>(null);
  const [logIdx, setLogIdx] = useState(0);
  const [otp, setOtp] = useState('');
  const [generatedOtp, setGeneratedOtp] = useState('');
  const [showIncomingSim, setShowIncomingSim] = useState(false);

  const [formData, setFormData] = useState({
    name: '',
    email: '', 
    phone: '',
    password: '',
    role: UserRole.CUSTOMER
  });

  const logs = [
    "SESSION: INITIALIZING KERNEL...",
    "HANDSHAKE: RSA-4096 VALIDATED",
    "NODE: JKT-S01 SIGNAL STABLE",
    "PROTOCOL: ZERO-TRUST ENABLED"
  ];

  useEffect(() => {
    // Init DB
    seedDatabase();
    const timer = setInterval(() => setLogIdx(i => (i + 1) % logs.length), 2500);
    return () => clearInterval(timer);
  }, []);

  const handleLogin = async (e: React.FormEvent) => {
    e.preventDefault();
    setLoading(true);
    setError(null);

    try {
      const user = await db.users.where('email').equals(formData.email).first();

      setTimeout(() => {
        if (user && user.password === formData.password) {
          onAuthSuccess(user);
        } else {
          setLoading(false);
          setError("NEURAL ID MISMATCH: ACCESS TERMINATED");
        }
      }, 1500); // Simulated delay for effect
    } catch (err) {
      setLoading(false);
      setError("DATABASE CONNECTION ERROR");
    }
  };

  const handleRegisterStart = (e: React.FormEvent) => {
    e.preventDefault();
    setLoading(true);
    const newOtp = Math.floor(100000 + Math.random() * 900000).toString();
    setGeneratedOtp(newOtp);
    setTimeout(() => {
      setLoading(false);
      setMode('VERIFY');
      setTimeout(() => setShowIncomingSim(true), 1200);
    }, 1800);
  };

  const handleVerifyFinal = async () => {
    if (otp !== generatedOtp) {
      setError("PARITY ERROR: TOKEN SEQUENCE REJECTED");
      setOtp('');
      return;
    }
    setLoading(true);

    try {
      const existingUser = await db.users.where('email').equals(formData.email).first();
      if (existingUser) {
        setLoading(false);
        setError("NODE ALREADY REGISTERED");
        return;
      }

      const newUser: DBUser = {
        name: formData.name,
        email: formData.email,
        phone: formData.phone,
        password: formData.password,
        role: formData.role,
        nodeId: `SP-${Math.floor(1000 + Math.random()*8999)}`,
        memberSince: new Date().toISOString(),
        trustScore: 88,
        verified: false
      };

      const id = await db.users.add(newUser);
      const createdUser = { ...newUser, id };

      setTimeout(() => {
        onAuthSuccess(createdUser);
      }, 1500);
    } catch (err) {
      setLoading(false);
      setError("REGISTRATION FAILED");
    }
  };

  return (
    <div className="min-h-screen bg-slate-50 dark:bg-[#050505] flex flex-col items-center justify-center p-6 relative overflow-hidden transition-colors duration-1000">

      {/* IMMERSIVE BACKGROUND CAPTURE */}
      <div className="absolute inset-0 bg-[url('https://grainy-gradients.vercel.app/noise.svg')] opacity-20 pointer-events-none"></div>

      {/* Orange & Grey Blurs to match website style */}
      <div className="absolute top-[-20%] right-[-10%] w-[800px] h-[800px] bg-primary-100 dark:bg-primary-500/5 rounded-full blur-[180px] animate-blob"></div>
      <div className="absolute bottom-[-10%] left-[-10%] w-[600px] h-[600px] bg-slate-200 dark:bg-slate-800/20 rounded-full blur-[160px] animate-blob animation-delay-4000"></div>

      {/* OTP SIMULATION NOTIFICATION */}
      {showIncomingSim && (
        <div className="fixed top-12 left-1/2 -translate-x-1/2 z-[300] w-full max-w-sm px-4 animate-pop-in">
           <div className="bg-white/90 dark:bg-slate-900/90 backdrop-blur-3xl border border-primary-500/20 rounded-[2.5rem] p-6 shadow-2xl flex items-start gap-5 relative overflow-hidden group">
              <div className="w-14 h-14 bg-primary-500 rounded-2xl flex items-center justify-center text-white flex-shrink-0 animate-bounce shadow-lg shadow-primary-500/30">
                 <BellRing size={28}/>
              </div>
              <div className="flex-1 space-y-1">
                 <p className="text-[0.6rem] font-black text-primary-600 dark:text-primary-400 uppercase tracking-widest">Neural Link Service</p>
                 <p className="text-xs font-bold text-slate-900 dark:text-white leading-tight">Verification sequence dispatched:</p>
                 <p className="text-2xl font-black text-slate-900 dark:text-white tracking-[0.2em]">{generatedOtp}</p>
                 <button onClick={() => setShowIncomingSim(false)} className="text-[0.55rem] font-black text-slate-400 uppercase tracking-widest mt-2 hover:text-primary-500 transition-colors flex items-center gap-1">
                   <XIcon size={10}/> Dismiss
                 </button>
              </div>
           </div>
        </div>
      )}

      <div className="w-full max-w-lg relative z-10 space-y-10">
        {/* BRAND HEADER */}
        <div className="flex flex-col items-center gap-6">
          <div className="relative group cursor-pointer" onClick={() => window.location.reload()}>
            <div className="absolute inset-0 bg-primary-500/20 rounded-full blur-[50px] animate-pulse group-hover:bg-primary-500/30 transition-all"></div>
            {/* Logo is Green, but background effect is Orange (primary) for cohesion */}
            <SurePathLogo className="w-20 h-20 relative drop-shadow-[0_0_30px_rgba(249,115,22,0.4)] transition-transform duration-1000 group-hover:scale-110" />
          </div>
          <div className="text-center space-y-1">
            <h1 className="text-4xl font-black tracking-[-0.05em] uppercase text-slate-900 dark:text-white leading-none">
