        {/* AUTH BOX */}
        <div className="bg-white/60 dark:bg-black/60 backdrop-blur-[40px] rounded-[3.5rem] p-8 lg:p-12 border-4 border-white/80 dark:border-white/5 shadow-2xl relative overflow-hidden group">

