                    />

                    <InputField 
                        icon={Binary} label="Encryption Key" type="password" name="password" placeholder="••••••••" value={formData.password} onChange={(n:any, v:any)=>setFormData(f=>({...f,password:v}))} showPass={showPass} setShowPass={setShowPass}
                    />

                    {error && <p className="text-[0.65rem] font-black text-rose-500 uppercase tracking-[0.2em] text-center animate-shake bg-rose-500/5 py-3 rounded-2xl border border-rose-500/20">{error}</p>}

                    <div className="space-y-6 pt-4">
                      <button type="submit" className="w-full py-6 bg-slate-900 dark:bg-white text-white dark:text-slate-900 rounded-[3rem] font-black uppercase text-sm tracking-[0.3em] shadow-xl shadow-slate-900/10 flex items-center justify-center gap-4 transition-all hover:bg-slate-800 hover:scale-[1.02] active:scale-95 group relative overflow-hidden">
                          <span className="relative z-10">{mode === 'REGISTER' ? 'Request Decryption' : 'Authorize Path'}</span>
                          <ArrowRight size={20} className="group-hover:translate-x-1 transition-transform relative z-10 text-primary-500"/>
                      </button>

                      {mode === 'LOGIN' && (
                        <div className="text-center">
                           <button type="button" className="text-[0.6rem] font-black text-slate-400 uppercase tracking-widest hover:text-primary-500 transition-colors">Lost Credentials Protocol</button>
                        </div>
                      )}
                    </div>
                </form>
            </>
          )}

          {/* STATUS CONSOLE */}
          <div className="mt-10 pt-6 border-t border-slate-100 dark:border-white/5">
             <div className="flex items-center justify-center gap-3 py-3 bg-slate-50 dark:bg-black/40 rounded-[2rem] border border-slate-200 dark:border-white/5 px-6">
                <Terminal size={14} className="text-primary-500 animate-pulse"/>
                <p className="text-[0.6rem] font-mono text-slate-400 uppercase tracking-widest truncate">
                    {logs[logIdx]}
                </p>
             </div>
          </div>
        </div>
      </div>

      {/* FOOTER */}
      <div className="mt-12 flex items-center gap-8 opacity-40 grayscale hover:grayscale-0 hover:opacity-80 transition-all duration-700">
         <div className="flex items-center gap-2">
            <ShieldCheck size={16} className="text-brand-500"/>
            <span className="text-[0.6rem] font-black uppercase tracking-[0.2em] text-slate-900 dark:text-white">OJK Regulated</span>
         </div>
         <div className="flex items-center gap-2">
            <Cpu size={16} className="text-slate-500"/>
            <span className="text-[0.6rem] font-black uppercase tracking-[0.2em] text-slate-900 dark:text-white">Neural Core v5</span>
         </div>
      </div>
    </div>
  );
};

