              <span className="font-black text-2xl tracking-tighter uppercase leading-none text-slate-900 dark:text-white">Sure<span className="text-brand-500">Path</span></span>
              <span className="text-[0.45rem] font-bold text-gray-400 uppercase tracking-[0.4em] mt-1">{currentUser?.name || 'Guest'}</span>
            </div>
          </div>
          <div className="flex items-center gap-3">
            <button onClick={() => setDarkMode(!darkMode)} className="p-3 bg-white dark:bg-white/10 rounded-2xl text-gray-400 hover:text-primary-500 transition-colors shadow-sm border border-gray-100 dark:border-white/5">
              {darkMode ? <Sun size={18}/> : <Moon size={18}/>}
            </button>
            <button 
              onClick={handleLogout} 
              className="p-3 bg-slate-900 dark:bg-white text-white dark:text-black rounded-2xl hover:bg-primary-500 dark:hover:bg-primary-500 transition-all shadow-lg"
            >
               <LogOut size={18}/>
            </button>
          </div>
        </header>
      )}

      <main className={`flex-1 overflow-y-auto w-full no-scrollbar z-10 relative ${isWizardFlow ? 'p-0 h-screen' : 'px-6 py-10'}`}>
        {renderPortalContent()}
      </main>

      {!isWizardFlow && (
        <nav className="flex-shrink-0 fixed bottom-8 inset-x-6 h-20 bg-white/90 dark:bg-[#111]/90 backdrop-blur-xl z-[70] flex items-center justify-around px-4 rounded-[2.8rem] shadow-[0_30px_60px_-15px_rgba(0,0,0,0.1)] border border-gray-100 dark:border-white/10 max-w-xl mx-auto transition-all duration-500">
          {[
            { id: 'home', icon: HomeIcon, label: 'Home' },
            { id: 'products', icon: Grid, label: currentUser?.role === UserRole.AGENT ? 'Sales' : 'Products' },
            { id: 'claim', icon: Zap, label: 'Claim' },
            { id: 'wallet', icon: WalletIcon, label: 'Wallet' },
            { id: 'profile', icon: UserCircle, label: 'Profile' }
          ].map(item => (
            <button 
              key={item.id} 
              onClick={() => setPage(item.id)} 
              className={`flex flex-col items-center gap-1.5 flex-1 py-3 transition-all duration-300 tap-feedback ${currentPage === item.id || (currentPage.startsWith('buy') && item.id === 'products') ? 'text-primary-500 scale-110 -translate-y-1' : 'text-gray-400 dark:text-gray-500'}`}
            >
              <item.icon size={24} className={currentPage === item.id ? 'drop-shadow-[0_0_12px_rgba(249,115,22,0.4)]' : ''} />
              <span className="text-[0.45rem] font-black uppercase tracking-[0.2em]">{item.label}</span>
            </button>
          ))}
        </nav>
      )}
    </div>
  );

  if (!isMobile && (currentUser || appMode)) {
    return (
      <div className="min-h-screen bg-[#0c0a09] flex items-center justify-center p-12 overflow-hidden relative transition-all duration-1000 ease-in-out">
        <div className="absolute inset-0 bg-neural-mesh opacity-100"></div>
        <div className="relative w-[440px] h-[880px] bg-white rounded-[5rem] border-[14px] border-[#1c1917] shadow-[0_60px_120px_-30px_rgba(0,0,0,0.6)] ring-[1px] ring-white/10 overflow-hidden group transition-all duration-700">
          <div className="h-full w-full overflow-hidden rounded-[3.8rem]">
             <AppWrapper />
          </div>
        </div>
        <div className="absolute left-10 top-1/2 -translate-y-1/2 hidden xl:flex flex-col gap-6 w-80">
           <div className="p-10 glass-card rounded-[3rem] border-white/20 space-y-6 shadow-2xl bg-white/10 backdrop-blur-xl">
              <div className="w-16 h-16 bg-brand-500 rounded-3xl flex items-center justify-center text-white shadow-lg animate-float"><Terminal size={32}/></div>
              <h4 className="text-2xl font-black text-white uppercase tracking-tighter">My Account</h4>
              <p className="text-[0.7rem] text-gray-300 font-bold leading-relaxed uppercase tracking-[0.2em]">Logged as: {currentUser?.name || 'Guest'}. Status: Secure.</p>
              <div className="pt-2">
                 <Badge color="emerald">{currentUser?.role || 'MEMBER'}</Badge>
              </div>
           </div>
        </div>
      </div>
    );
  }

  return <AppWrapper />;
};

const Badge = ({ children, color = "primary" }: { children?: React.ReactNode, color?: string }) => {
  const styles: any = {
    primary: "bg-primary-500/10 text-primary-500 border-primary-500/20",
    emerald: "bg-brand-500/10 text-brand-500 border-brand-500/20",
    blue: "bg-blue-500/10 text-blue-500 border-blue-200",
    amber: "bg-amber-500/10 text-amber-600 border-amber-200",
  };
  return (
    <span className={`px-3 py-1 rounded-full text-[0.55rem] font-black uppercase tracking-widest border ${styles[color] || styles.primary}`}>
      {children}
    </span>
  );
};

export default App;

import React, { useState, useEffect } from 'react';
import { 
  ShieldCheck, User, Mail, Phone, Lock, Eye, EyeOff, 
  ArrowRight, Binary, Terminal, BellRing,
  X as XIcon, UserPlus as UserPlusIcon, Star, Fingerprint, Smartphone, Globe, Cpu
} from 'lucide-react';
import { SurePathLogo } from './Navbar';
import { Language, UserRole } from '../types';
import { db, seedDatabase, User as DBUser } from '../db';

interface AuthGateProps {
  onAuthSuccess: (user: any) => void;
  initialLang?: Language;
}

const InputField = ({ icon: Icon, label, type, name, placeholder, value, onChange, showPass, setShowPass }: any) => (
  <div className="space-y-2 group animate-fade-in">
    <div className="flex justify-between items-center px-6">
      <label className="text-[0.6rem] font-black text-slate-400 dark:text-slate-500 uppercase tracking-[0.3em] transition-colors group-focus-within:text-primary-500">
        {label}
      </label>
      <div className="w-1 h-1 rounded-full bg-slate-200 group-focus-within:bg-primary-500 group-focus-within:animate-pulse"></div>
    </div>
    <div className="relative">
      <div className="absolute left-7 top-1/2 -translate-y-1/2 text-slate-400 dark:text-gray-500 transition-colors group-focus-within:text-primary-500">
        <Icon size={18} strokeWidth={2.5} />
      </div>
      <input 
        type={type === 'password' && showPass ? 'text' : type}
        placeholder={placeholder}
        required
        className="w-full pl-16 pr-6 py-6 bg-white dark:bg-white/[0.03] border-2 border-slate-100 dark:border-white/5 rounded-[2.5rem] outline-none transition-all font-black text-sm tracking-tight text-slate-900 dark:text-white placeholder:text-slate-300 dark:placeholder:text-gray-800 shadow-sm focus:border-primary-500 focus:bg-white focus:shadow-[0_10px_30px_rgba(249,115,22,0.1)] dark:focus:border-primary-500/40"
        value={value}
        onChange={(e) => onChange(name, e.target.value)}
      />
      {type === 'password' && (
        <button 
          type="button"
          onClick={() => setShowPass(!showPass)}
          className="absolute right-7 top-1/2 -translate-y-1/2 text-slate-300 hover:text-primary-500 transition-colors"
        >
          {showPass ? <EyeOff size={18}/> : <Eye size={18}/>}
        </button>
      )}
    </div>
  </div>
);

const AuthGate: React.FC<AuthGateProps> = ({ onAuthSuccess, initialLang = Language.EN }) => {
  const [mode, setMode] = useState<'LOGIN' | 'REGISTER' | 'VERIFY'>('LOGIN');
  const [showPass, setShowPass] = useState(false);
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState<string | null>(null);
  const [logIdx, setLogIdx] = useState(0);
  const [otp, setOtp] = useState('');
  const [generatedOtp, setGeneratedOtp] = useState('');
  const [showIncomingSim, setShowIncomingSim] = useState(false);

  const [formData, setFormData] = useState({
    name: '',
    email: '', 
    phone: '',
    password: '',
    role: UserRole.CUSTOMER
  });

  const logs = [
    "Establishing secure connection...",
    "Verifying identity protocol...",
    "Checking account status...",
    "Connection stable."
  ];

  useEffect(() => {
    // Init DB
    seedDatabase();
    const timer = setInterval(() => setLogIdx(i => (i + 1) % logs.length), 2500);
    return () => clearInterval(timer);
  }, []);

  const handleLogin = async (e: React.FormEvent) => {
    e.preventDefault();
    setLoading(true);
    setError(null);

    try {
      const user = await db.users.where('email').equals(formData.email).first();

      setTimeout(() => {
        if (user && user.password === formData.password) {
          onAuthSuccess(user);
        } else {
          setLoading(false);
          setError("Incorrect email or password.");
        }
      }, 1500); // Simulated delay for effect
    } catch (err) {
      setLoading(false);
      setError("Connection error. Please try again.");
    }
  };

  const handleRegisterStart = (e: React.FormEvent) => {
    e.preventDefault();
    setLoading(true);
    const newOtp = Math.floor(100000 + Math.random() * 900000).toString();
    setGeneratedOtp(newOtp);
    setTimeout(() => {
      setLoading(false);
      setMode('VERIFY');
      setTimeout(() => setShowIncomingSim(true), 1200);
    }, 1800);
  };

  const handleVerifyFinal = async () => {
    if (otp !== generatedOtp) {
      setError("Incorrect verification code.");
      setOtp('');
      return;
    }
    setLoading(true);

    try {
      const existingUser = await db.users.where('email').equals(formData.email).first();
      if (existingUser) {
        setLoading(false);
        setError("Email already registered.");
        return;
      }

      const newUser: DBUser = {
        name: formData.name,
        email: formData.email,
        phone: formData.phone,
        password: formData.password,
        role: formData.role,
        nodeId: `SP-${Math.floor(1000 + Math.random()*8999)}`,
        memberSince: new Date().toISOString(),
        trustScore: 88,
        verified: false
      };

      const id = await db.users.add(newUser);
      const createdUser = { ...newUser, id };

      setTimeout(() => {
        onAuthSuccess(createdUser);
      }, 1500);
    } catch (err) {
      setLoading(false);
      setError("Registration failed. Please try again.");
    }
  };

  return (
    <div className="min-h-screen bg-slate-50 dark:bg-[#050505] flex flex-col items-center justify-center p-6 relative overflow-hidden transition-colors duration-1000">

      {/* IMMERSIVE BACKGROUND CAPTURE */}
      <div className="absolute inset-0 bg-[url('https://grainy-gradients.vercel.app/noise.svg')] opacity-20 pointer-events-none"></div>

      {/* Orange & Grey Blurs to match website style */}
      <div className="absolute top-[-20%] right-[-10%] w-[800px] h-[800px] bg-primary-100 dark:bg-primary-500/5 rounded-full blur-[180px] animate-blob"></div>
      <div className="absolute bottom-[-10%] left-[-10%] w-[600px] h-[600px] bg-slate-200 dark:bg-slate-800/20 rounded-full blur-[160px] animate-blob animation-delay-4000"></div>

      {/* OTP SIMULATION NOTIFICATION */}
      {showIncomingSim && (
        <div className="fixed top-12 left-1/2 -translate-x-1/2 z-[300] w-full max-w-sm px-4 animate-pop-in">
           <div className="bg-white/90 dark:bg-slate-900/90 backdrop-blur-3xl border border-primary-500/20 rounded-[2.5rem] p-6 shadow-2xl flex items-start gap-5 relative overflow-hidden group">
              <div className="w-14 h-14 bg-primary-500 rounded-2xl flex items-center justify-center text-white flex-shrink-0 animate-bounce shadow-lg shadow-primary-500/30">
                 <BellRing size={28}/>
              </div>
              <div className="flex-1 space-y-1">
                 <p className="text-[0.6rem] font-black text-primary-600 dark:text-primary-400 uppercase tracking-widest">SurePath Security</p>
                 <p className="text-xs font-bold text-slate-900 dark:text-white leading-tight">Your verification code is:</p>
                 <p className="text-2xl font-black text-slate-900 dark:text-white tracking-[0.2em]">{generatedOtp}</p>
                 <button onClick={() => setShowIncomingSim(false)} className="text-[0.55rem] font-black text-slate-400 uppercase tracking-widest mt-2 hover:text-primary-500 transition-colors flex items-center gap-1">
                   <XIcon size={10}/> Dismiss
                 </button>
              </div>
           </div>
        </div>
      )}

      <div className="w-full max-w-lg relative z-10 space-y-10">
        {/* BRAND HEADER */}
        <div className="flex flex-col items-center gap-6">
          <div className="relative group cursor-pointer" onClick={() => window.location.reload()}>
            <div className="absolute inset-0 bg-primary-500/20 rounded-full blur-[50px] animate-pulse group-hover:bg-primary-500/30 transition-all"></div>
            {/* Logo is Green, but background effect is Orange (primary) for cohesion */}
            <SurePathLogo className="w-20 h-20 relative drop-shadow-[0_0_30px_rgba(249,115,22,0.4)] transition-transform duration-1000 group-hover:scale-110" />
          </div>
          <div className="text-center space-y-1">
            <h1 className="text-4xl font-black tracking-[-0.05em] uppercase text-slate-900 dark:text-white leading-none">
              SURE<span className="text-brand-500">PATH</span>
            </h1>
            <div className="flex items-center justify-center gap-2">
               <div className="w-1.5 h-1.5 rounded-full bg-primary-500 animate-ping"></div>
               <p className="text-[0.65rem] font-black text-slate-400 uppercase tracking-[0.5em]">Your Protection Hub</p>
            </div>
          </div>
        </div>

        {/* AUTH BOX */}
        <div className="bg-white/60 dark:bg-black/60 backdrop-blur-[40px] rounded-[3.5rem] p-8 lg:p-12 border-4 border-white/80 dark:border-white/5 shadow-2xl relative overflow-hidden group">

          {loading && (
            <div className="absolute inset-0 bg-white/95 dark:bg-black/95 backdrop-blur-3xl z-50 flex flex-col items-center justify-center gap-8 animate-fade-in">
               <div className="relative">
                  <div className="w-28 h-28 bg-primary-500/5 rounded-[3.5rem] flex items-center justify-center border-2 border-primary-500/20 shadow-2xl">
                    <Fingerprint className="text-primary-500 animate-pulse" size={60} />
                  </div>
                  <div className="absolute inset-[-15px] border-2 border-primary-500/10 rounded-[4.5rem] animate-ping opacity-40"></div>
               </div>
               <div className="text-center space-y-3">
                  <p className="text-[0.8rem] font-black text-slate-900 dark:text-white uppercase tracking-[0.4em] animate-pulse">Logging in...</p>
                  <div className="flex items-center justify-center gap-2">
                     <span className="w-1.5 h-1.5 rounded-full bg-primary-500/50 animate-bounce"></span>
                     <span className="w-1.5 h-1.5 rounded-full bg-primary-500/50 animate-bounce delay-150"></span>
                     <span className="w-1.5 h-1.5 rounded-full bg-primary-500/50 animate-bounce delay-300"></span>
                  </div>
               </div>
            </div>
          )}

          {mode === 'VERIFY' ? (
            <div className="space-y-10 animate-fade-in text-center py-4">
                <div className="space-y-6">
                    <div className="relative group">
                       <input 
                        maxLength={6}
                        placeholder="••••••"
                        className="w-full py-8 bg-slate-50 dark:bg-white/[0.03] border-2 border-slate-100 dark:border-white/5 rounded-[3rem] text-center text-5xl font-black tracking-[0.5em] text-primary-500 outline-none focus:border-primary-500 focus:bg-white transition-all placeholder:opacity-5 shadow-inner"
                        value={otp}
                        onChange={(e) => {
                          setOtp(e.target.value.replace(/\D/g, ''));
                          setError(null);
                        }}
                      />
                    </div>
                    {error && <p className="text-[0.65rem] font-black text-rose-500 uppercase tracking-[0.2em] animate-shake bg-rose-500/5 py-3 rounded-2xl border border-rose-500/20">{error}</p>}
                </div>

                <div className="space-y-4">
                   <button 
                    onClick={handleVerifyFinal}
                    disabled={otp.length < 6}
                    className="w-full py-6 bg-slate-900 dark:bg-white text-white dark:text-black rounded-[2.5rem] font-black uppercase text-sm tracking-[0.3em] shadow-xl disabled:opacity-30 active:scale-95 transition-all hover:bg-slate-800"
                  >
                    Verify & Sign In <ArrowRight size={18} className="inline-block ml-3"/>
                  </button>
                  <button onClick={() => {setMode('REGISTER'); setOtp('');}} className="text-[0.6rem] font-black text-slate-400 uppercase tracking-widest hover:text-primary-500 transition-colors">Resend Code</button>
                </div>
            </div>
          ) : (
            <>
                <div className="flex bg-slate-100 dark:bg-white/5 p-1.5 rounded-[2.5rem] mb-10 border border-slate-200 dark:border-white/5 relative">
                    <div className={`absolute top-1.5 bottom-1.5 w-[calc(50%-6px)] bg-white dark:bg-slate-800 rounded-[2rem] shadow-md transition-transform duration-500 ease-out ${mode === 'REGISTER' ? 'translate-x-full' : 'translate-x-0'}`}></div>

                    {[
                      { id: 'LOGIN', label: 'Login', icon: Lock },
                      { id: 'REGISTER', label: 'Join', icon: UserPlusIcon }
                    ].map((m) => (
                    <button 
                        key={m.id}
                        onClick={() => { setMode(m.id as any); setError(null); }}
                        className={`flex-1 py-4 rounded-[2rem] text-[0.65rem] font-black uppercase tracking-widest transition-all relative z-10 flex items-center justify-center gap-2 ${mode === m.id ? 'text-slate-900 dark:text-white' : 'text-slate-400 hover:text-slate-600'}`}
                    >
                        <m.icon size={16} strokeWidth={2.5}/> {m.label}
                    </button>
                    ))}
                </div>

                {/* DEMO: Role Preview Hint */}
                {mode === 'LOGIN' && (
                  <div className="mb-8 p-4 bg-primary-50 dark:bg-primary-500/5 rounded-[2rem] border border-primary-500/10 flex flex-col gap-2">
                     <p className="text-[0.55rem] font-black text-primary-600 uppercase tracking-widest flex items-center gap-2"><Star size={10}/> Demo Accounts</p>
                     <div className="grid grid-cols-2 gap-2">
                        <button onClick={() => setFormData({...formData, email: 'master@surepath.ai', password: 'admin'})} className="px-3 py-2 bg-white dark:bg-white/5 rounded-xl text-[0.5rem] font-bold text-slate-500 hover:text-primary-500 transition-colors border border-black/5 text-left">Master Admin Access</button>
                        <button onClick={() => setFormData({...formData, email: 'agent@surepath.ai', password: 'admin'})} className="px-3 py-2 bg-white dark:bg-white/5 rounded-xl text-[0.5rem] font-bold text-slate-500 hover:text-primary-500 transition-colors border border-black/5 text-left">Agent / Partner Access</button>
                     </div>
                  </div>
                )}

                <form onSubmit={mode === 'REGISTER' ? handleRegisterStart : handleLogin} className="space-y-6">
                    {mode === 'REGISTER' && (
                      <div className="grid grid-cols-1 gap-6 animate-fade-in">
                        <InputField icon={User} label="Full Name" type="text" name="name" placeholder="John Doe" value={formData.name} onChange={(n:any, v:any)=>setFormData(f=>({...f,name:v}))} />
                        <InputField icon={Smartphone} label="Phone Number" type="tel" name="phone" placeholder="+62 812 XXXX" value={formData.phone} onChange={(n:any, v:any)=>setFormData(f=>({...f,phone:v}))} />
                        <div className="px-6 space-y-2">
                           <label className="text-[0.6rem] font-black text-slate-400 uppercase tracking-[0.3em]">Account Type</label>
                           <div className="flex bg-slate-100 dark:bg-white/5 p-1 rounded-2xl gap-1">
                              {[UserRole.CUSTOMER, UserRole.AGENT].map(r => (
                                <button 
                                  key={r} type="button"
                                  onClick={() => setFormData({...formData, role: r})}
                                  className={`flex-1 py-2.5 rounded-xl text-[0.55rem] font-black uppercase tracking-widest transition-all ${formData.role === r ? 'bg-white dark:bg-slate-800 text-primary-500 shadow-sm' : 'text-slate-400'}`}
                                >
                                  {r === UserRole.CUSTOMER ? 'MEMBER' : 'PARTNER'}
                                </button>
                              ))}
                           </div>
                        </div>
                      </div>
                    )}

                    <InputField 
                        icon={Globe} label="Email Address" type="text" name="email" placeholder="you@surepath.ai" value={formData.email} onChange={(n:any, v:any)=>setFormData(f=>({...f,email:v}))} 
                    />

                    <InputField 
                        icon={Binary} label="Password" type="password" name="password" placeholder="••••••••" value={formData.password} onChange={(n:any, v:any)=>setFormData(f=>({...f,password:v}))} showPass={showPass} setShowPass={setShowPass}
                    />

                    {error && <p className="text-[0.65rem] font-black text-rose-500 uppercase tracking-[0.2em] text-center animate-shake bg-rose-500/5 py-3 rounded-2xl border border-rose-500/20">{error}</p>}

                    <div className="space-y-6 pt-4">
                      <button type="submit" className="w-full py-6 bg-slate-900 dark:bg-white text-white dark:text-slate-900 rounded-[3rem] font-black uppercase text-sm tracking-[0.3em] shadow-xl shadow-slate-900/10 flex items-center justify-center gap-4 transition-all hover:bg-slate-800 hover:scale-[1.02] active:scale-95 group relative overflow-hidden">
                          <span className="relative z-10">{mode === 'REGISTER' ? 'Register' : 'Sign In'}</span>
                          <ArrowRight size={20} className="group-hover:translate-x-1 transition-transform relative z-10 text-primary-500"/>
                      </button>

                      {mode === 'LOGIN' && (
                        <div className="text-center">
                           <button type="button" className="text-[0.6rem] font-black text-slate-400 uppercase tracking-widest hover:text-primary-500 transition-colors">Forgot Password?</button>
                        </div>
                      )}
                    </div>
                </form>
            </>
          )}

          {/* STATUS CONSOLE */}
          <div className="mt-10 pt-6 border-t border-slate-100 dark:border-white/5">
             <div className="flex items-center justify-center gap-3 py-3 bg-slate-50 dark:bg-black/40 rounded-[2rem] border border-slate-200 dark:border-white/5 px-6">
                <Terminal size={14} className="text-primary-500 animate-pulse"/>
                <p className="text-[0.6rem] font-mono text-slate-400 uppercase tracking-widest truncate">
                    {logs[logIdx]}
                </p>
             </div>
          </div>
        </div>
      </div>

      {/* FOOTER */}
      <div className="mt-12 flex items-center gap-8 opacity-40 grayscale hover:grayscale-0 hover:opacity-80 transition-all duration-700">
         <div className="flex items-center gap-2">
            <ShieldCheck size={16} className="text-brand-500"/>
            <span className="text-[0.6rem] font-black uppercase tracking-[0.2em] text-slate-900 dark:text-white">OJK Regulated</span>
         </div>
         <div className="flex items-center gap-2">
            <Cpu size={16} className="text-slate-500"/>
            <span className="text-[0.6rem] font-black uppercase tracking-[0.2em] text-slate-900 dark:text-white">Secure System</span>
         </div>
      </div>
    </div>
  );
};

export default AuthGate;

