              <div className="flex items-center gap-4">
                 <div className="inline-flex items-center gap-3 bg-white/10 backdrop-blur-2xl px-5 py-2 rounded-2xl border border-white/20 shadow-2xl">
                    <slide.icon size={16} className={`text-${slide.color}-400 animate-pulse`} />
                    <span className="text-[0.65rem] font-black text-white uppercase tracking-[0.4em]">SurePath Protection</span>
