              <button 
                onClick={() => {
                  const target = slide.cta.toLowerCase().includes('trip') ? 'buy-travel' : 
                                 slide.cta.toLowerCase().includes('check') ? 'buy-car' : 
                                 slide.cta.toLowerCase().includes('claim') ? 'claim' : 'products';
                  onAction(target);
