                className="mt-4 px-12 py-5 bg-white text-black rounded-[2rem] font-black uppercase text-[0.75rem] tracking-[0.3em] w-fit shadow-2xl flex items-center gap-5 transition-all hover:bg-primary-500 hover:text-white active:scale-95 group"
              >
                {slide.cta} <ArrowRight size={20} className="group-hover:translate-x-2 transition-transform"/>
