                 <p className="text-2xl font-black text-slate-900 dark:text-white tracking-[0.2em]">{generatedOtp}</p>
                 <button onClick={() => setShowIncomingSim(false)} className="text-[0.55rem] font-black text-slate-400 uppercase tracking-widest mt-2 hover:text-primary-500 transition-colors flex items-center gap-1">
                   <XIcon size={10}/> Dismiss
