                     <span className="w-1.5 h-1.5 rounded-full bg-primary-500/50 animate-bounce delay-300"></span>
                  </div>
               </div>
            </div>
          )}

          {mode === 'VERIFY' ? (
            <div className="space-y-10 animate-fade-in text-center py-4">
