                        className="w-full py-8 bg-slate-50 dark:bg-white/[0.03] border-2 border-slate-100 dark:border-white/5 rounded-[3rem] text-center text-5xl font-black tracking-[0.5em] text-primary-500 outline-none focus:border-primary-500 focus:bg-white transition-all placeholder:opacity-5 shadow-inner"
                        value={otp}
                        onChange={(e) => {
                          setOtp(e.target.value.replace(/\D/g, ''));
                          setError(null);
                        }}
                      />
                    </div>
                    {error && <p className="text-[0.65rem] font-black text-rose-500 uppercase tracking-[0.2em] animate-shake bg-rose-500/5 py-3 rounded-2xl border border-rose-500/20">{error}</p>}
                </div>

                <div className="space-y-4">
                   <button 
                    onClick={handleVerifyFinal}
                    disabled={otp.length < 6}
                    className="w-full py-6 bg-slate-900 dark:bg-white text-white dark:text-black rounded-[2.5rem] font-black uppercase text-sm tracking-[0.3em] shadow-xl disabled:opacity-30 active:scale-95 transition-all hover:bg-slate-800"
                  >
                    Verify & Sign In <ArrowRight size={18} className="inline-block ml-3"/>
