                        className={`flex-1 py-4 rounded-[2rem] text-[0.65rem] font-black uppercase tracking-widest transition-all relative z-10 flex items-center justify-center gap-2 ${mode === m.id ? 'text-slate-900 dark:text-white' : 'text-slate-400 hover:text-slate-600'}`}
                    >
                        <m.icon size={16} strokeWidth={2.5}/> {m.label}
