                    ))}
                </div>

                {/* DEMO: Role Preview Hint */}
                {mode === 'LOGIN' && (
                  <div className="mb-8 p-4 bg-primary-50 dark:bg-primary-500/5 rounded-[2rem] border border-primary-500/10 flex flex-col gap-2">
