                     </div>
                  </div>
                )}

                <form onSubmit={mode === 'REGISTER' ? handleRegisterStart : handleLogin} className="space-y-6">
                    {mode === 'REGISTER' && (
                      <div className="grid grid-cols-1 gap-6 animate-fade-in">
                        <InputField icon={User} label="Full Name" type="text" name="name" placeholder="John Doe" value={formData.name} onChange={(n:any, v:any)=>setFormData(f=>({...f,name:v}))} />
