            </button>
          ))}
        </nav>
      )}
    </div>
  );

  if (!isMobile && (currentUser || appMode)) {
    return (
      <div className="min-h-screen bg-[#0c0a09] flex items-center justify-center p-12 overflow-hidden relative transition-all duration-1000 ease-in-out">
        <div className="absolute inset-0 bg-neural-mesh opacity-100"></div>
        <div className="relative w-[440px] h-[880px] bg-white rounded-[5rem] border-[14px] border-[#1c1917] shadow-[0_60px_120px_-30px_rgba(0,0,0,0.6)] ring-[1px] ring-white/10 overflow-hidden group transition-all duration-700">
          <div className="h-full w-full overflow-hidden rounded-[3.8rem]">
             <AppWrapper />
          </div>
        </div>
        <div className="absolute left-10 top-1/2 -translate-y-1/2 hidden xl:flex flex-col gap-6 w-80">
           <div className="p-10 glass-card rounded-[3rem] border-white/20 space-y-6 shadow-2xl bg-white/10 backdrop-blur-xl">
              <div className="w-16 h-16 bg-brand-500 rounded-3xl flex items-center justify-center text-white shadow-lg animate-float"><Terminal size={32}/></div>
              <h4 className="text-2xl font-black text-white uppercase tracking-tighter">My Account</h4>
              <p className="text-[0.7rem] text-gray-300 font-bold leading-relaxed uppercase tracking-[0.2em]">Logged as: {currentUser?.name || 'Guest'}. Status: Secure.</p>
              <div className="pt-2">
                 <Badge color="emerald">{currentUser?.role || 'MEMBER'}</Badge>
              </div>
           </div>
        </div>
      </div>
    );
  }

  return <AppWrapper />;
};

const Badge = ({ children, color = "primary" }: { children?: React.ReactNode, color?: string }) => {
  const styles: any = {
    primary: "bg-primary-500/10 text-primary-500 border-primary-500/20",
    emerald: "bg-brand-500/10 text-brand-500 border-brand-500/20",
    blue: "bg-blue-500/10 text-blue-500 border-blue-200",
    amber: "bg-amber-500/10 text-amber-600 border-amber-200",
  };
  return (
    <span className={`px-3 py-1 rounded-full text-[0.55rem] font-black uppercase tracking-widest border ${styles[color] || styles.primary}`}>
      {children}
    </span>
  );
};

