  const [lang, setLang] = useState<Language>(Language.EN);

  // Persistence logic: Check for active session on boot
  useEffect(() => {
    const savedSession = localStorage.getItem('SUREPATH_SESSION');
    if (savedSession) {
      try {
        const user = JSON.parse(savedSession);
        setCurrentUser(user);
        setAppMode(true);
      } catch (e) {
        console.error("Invalid session node", e);
        localStorage.removeItem('SUREPATH_SESSION');
      }
    }

    const timezone = new Intl.DateTimeFormat().resolvedOptions().timeZone;
    const isIndo = timezone.includes('Jakarta') || timezone.includes('Makassar') || timezone.includes('Jayapura');
    if (isIndo) setLang(Language.ID);
  }, []);

  const handleAuthSuccess = (user: any) => {
    setCurrentUser(user);
    // Persist session
    localStorage.setItem('SUREPATH_SESSION', JSON.stringify(user));
    setAppMode(true);
    setPage('home');
  };

  const handleLogout = () => {
    setCurrentUser(null);
    localStorage.removeItem('SUREPATH_SESSION');
    setAppMode(false);
    setPage('home');
  };

  useEffect(() => {
    const handleResize = () => setIsMobile(window.innerWidth < 1024);
    window.addEventListener('resize', handleResize);
    return () => window.removeEventListener('resize', handleResize);
  }, []);

  // Show the WelcomeScreen (Loading Animation) first
  if (!isLoaded) return <WelcomeScreen onFinish={() => setIsLoaded(true)} />;

  // Roles that access the HQ Admin Portal
  const isAdminRole = currentUser && [UserRole.MASTER_ADMIN, UserRole.ADMIN, UserRole.FINANCE].includes(currentUser.role);

  if (isAdminRole) {
    return <AdminPortal 
      onLogout={handleLogout} 
      products={products}
      setProducts={setProducts}
      userRole={currentUser.role}
    />;
  }

  if (!isMobile && !appMode && !currentUser) {
    return (
      <DesktopWebsite 
        onEnterPortal={() => { setAppMode(true); setPage('auth'); }} 
        onAdminAccess={() => { setAppMode(true); setPage('auth'); }} 
        currentLang={lang}
        onLangChange={setLang}
      />
    );
  }

  if (!currentUser && (isMobile || appMode)) {
    return <AuthGate onAuthSuccess={handleAuthSuccess} initialLang={lang} />;
  }

  const renderPortalContent = () => {
    // Shared components between Agent and Customer if any
    const isAgent = currentUser?.role === UserRole.AGENT;

    switch(currentPage) {
      case 'home':
        return (
          <div className="space-y-8 animate-fade-in pb-24 text-gray-900 dark:text-white relative z-10">
            <PortalHero onAction={(p) => setPage(p)} />

            <div className="p-5 bg-primary-500/5 border border-primary-500/20 rounded-[2rem] flex items-center justify-between shadow-inner group">
               <div className="flex items-center gap-4">
                  <div className="w-10 h-10 bg-primary-500 rounded-2xl flex items-center justify-center text-white shadow-lg shadow-primary-500/20 group-hover:scale-110 transition-transform">
                     <ShieldIcon size={20}/>
                  </div>
                  <div>
                     <p className="text-[0.65rem] font-black uppercase tracking-widest text-primary-600 flex items-center gap-2">
                        {isAgent ? 'Partner Status' : 'My Protection'}
                        <span className="w-1.5 h-1.5 rounded-full bg-primary-500 animate-pulse"></span>
                     </p>
                     <p className="text-[0.5rem] font-bold text-gray-500 uppercase tracking-widest">ID: {currentUser?.nodeId || 'SP-GUEST'}</p>
                  </div>
               </div>
               <div className="px-3 py-1 bg-white dark:bg-white/10 rounded-full border border-black/5 dark:border-white/5 shadow-sm">
                  <span className="text-[0.5rem] font-bold text-primary-500 uppercase tracking-widest">Active</span>
               </div>
            </div>

            <div className="grid grid-cols-2 gap-4">
              <div onClick={() => setPage('products')} className="p-8 glass-card rounded-[2.8rem] border border-gray-200/50 shadow-xl cursor-pointer group overflow-hidden relative bg-white dark:bg-white/5">
                <div className="absolute -right-4 -bottom-4 opacity-[0.05] group-hover:scale-125 transition-transform text-gray-900 dark:text-white"><Grid size={140}/></div>
                <div className="w-12 h-12 bg-blue-500/10 rounded-2xl flex items-center justify-center text-blue-500 mb-5 shadow-inner"><Grid size={24}/></div>
                <p className="font-black text-lg uppercase tracking-tighter">{isAgent ? 'Sales' : 'Products'}</p>
                <p className="text-[0.6rem] font-bold text-gray-400 mt-1.5 uppercase tracking-widest">{isAgent ? 'Issue Policy' : 'Buy Insurance'}</p>
              </div>
              <div onClick={() => setPage('claim')} className="p-8 glass-card rounded-[2.8rem] border border-gray-200/50 shadow-xl cursor-pointer group overflow-hidden relative bg-white dark:bg-white/5">
                <div className="absolute -right-4 -bottom-4 opacity-[0.05] group-hover:scale-125 transition-transform text-gray-900 dark:text-white"><Zap size={140}/></div>
                <div className="w-12 h-12 bg-primary-500/10 rounded-2xl flex items-center justify-center text-primary-500 mb-5 shadow-inner"><Zap size={24}/></div>
                <p className="font-black text-lg uppercase tracking-tighter">Claim AI</p>
                <p className="text-[0.6rem] font-bold text-gray-400 mt-1.5 uppercase tracking-widest">Fast Payout</p>
              </div>
            </div>

            {/* Conditional Wallet: Customers might have a simple one, Agents have the complex matrix */}
            <div onClick={() => setPage('wallet')} className="p-8 glass-card rounded-[2.8rem] border border-gray-200/50 shadow-xl cursor-pointer group overflow-hidden relative flex items-center justify-between bg-white dark:bg-white/5">
                <div className="absolute inset-0 bg-primary-500/[0.03] opacity-0 group-hover:opacity-100 transition-opacity"></div>
                <div className="flex items-center gap-6 relative z-10">
                   <div className="w-14 h-14 bg-gray-100 dark:bg-white/10 rounded-3xl flex items-center justify-center text-gray-400 group-hover:text-primary-500 group-hover:scale-110 transition-all shadow-inner">
                      <WalletIcon size={28}/>
                   </div>
                   <div>
                      <p className="text-xl font-black uppercase tracking-tighter">{isAgent ? 'My Wallet' : 'My Policies'}</p>
                      <p className="text-[0.6rem] font-bold text-gray-400 uppercase tracking-widest mt-1">{isAgent ? 'Earnings & Withdraw' : 'Active & History'}</p>
                   </div>
                </div>
                <ChevronRight className="text-gray-300 group-hover:text-primary-500 transition-all group-hover:translate-x-1" size={24}/>
            </div>
          </div>
        );

      case 'products':
        return (
          <div className="space-y-10 animate-fade-in pb-24 text-gray-900 dark:text-white relative z-10">
            <h2 className="text-4xl font-black uppercase tracking-tighter px-2">{isAgent ? 'Policy' : 'Insurance'} <span className="text-primary-500">{isAgent ? 'Sales' : 'Store'}</span></h2>
            <div className="grid gap-4">
              {products.filter(p => p.cat === 'Retail').map(p => (
                <div 
                  key={p.id} 
                  onClick={() => p.active ? setPage(`buy-${p.id}`) : null} 
                  className={`p-6 glass-card rounded-[2.8rem] border border-gray-200 dark:border-gray-800 flex items-center justify-between transition-all group relative overflow-hidden bg-white dark:bg-white/5 ${p.active ? 'cursor-pointer hover:border-primary-500 shadow-lg' : 'opacity-40 grayscale cursor-not-allowed bg-gray-50/50'}`}
                >
                  <div className="flex items-center gap-6">
                    <div className={`w-16 h-16 bg-gray-100 dark:bg-white/10 ${p.color} rounded-3xl flex items-center justify-center shadow-inner ${p.active ? 'group-hover:scale-110 transition-transform' : ''}`}>
                      <p.icon size={32}/>
                    </div>
                    <div>
                      <h4 className="font-black text-xl uppercase tracking-tighter">{p.label}</h4>
                      <p className="text-[0.65rem] text-gray-500 font-bold uppercase tracking-[0.2em]">{p.active ? p.tech : 'Coming Soon'}</p>
                    </div>
                  </div>
                  {p.active && <ChevronRight className="text-gray-300 group-hover:text-primary-500 transition-colors" size={24}/>}
                </div>
              ))}
            </div>
          </div>
        );

      case 'claim': return <ClaimManager onComplete={() => setPage('home')} />;
      case 'wallet': return isAgent ? <AgentsWallet /> : <div className="p-10 text-center uppercase font-black text-gray-300">Customer Policies Coming Soon</div>;
      case 'profile': return <UserProfile currentUser={currentUser} />;
      case 'buy-car': return <CarInsuranceWizard onComplete={() => setPage('home')} currentUser={currentUser} />;
      case 'buy-travel': return <TravelInsuranceWizard onComplete={() => setPage('home')} currentUser={currentUser} />;
      case 'buy-pa': return <PAInsuranceWizard onComplete={() => setPage('home')} currentUser={currentUser} />;
      case 'buy-mpar': return <MPARInsuranceWizard onComplete={() => setPage('home')} currentUser={currentUser} />;
      default: return <div className="p-10 text-center uppercase font-black text-gray-300">Under Construction</div>;
    }
  };

  const isWizardFlow = currentPage.startsWith('buy-');

  const AppWrapper = () => (
    <div className={`${darkMode ? 'dark bg-[#0a0a0a] text-white' : 'bg-[#fafaf9] text-gray-900'} h-full transition-colors duration-700 font-sans flex flex-col relative overflow-hidden`}>

      {/* Ambient Background Animation */}
      <div className="absolute inset-0 pointer-events-none z-0">
        <div className="absolute top-[-20%] left-[-20%] w-[800px] h-[800px] bg-primary-500/5 rounded-full blur-[120px] animate-pulse-slow"></div>
        <div className="absolute bottom-[-20%] right-[-20%] w-[800px] h-[800px] bg-blue-500/5 rounded-full blur-[120px] animate-pulse-slow animation-delay-4000"></div>
        <div className="absolute inset-0 bg-[url('https://grainy-gradients.vercel.app/noise.svg')] opacity-10"></div>
      </div>

      {!isWizardFlow && (
        <header className="flex-shrink-0 h-24 glass-card px-8 flex items-center justify-between border-b border-gray-100 dark:border-white/5 z-[60] relative bg-white/80 dark:bg-black/20 backdrop-blur-md">
          <div className="flex items-center gap-4 cursor-pointer group" onClick={() => setPage('home')}>
            <SurePathLogo className="w-12 h-12 group-hover:scale-110 transition-transform" />
            <div className="flex flex-col">
              <span className="font-black text-2xl tracking-tighter uppercase leading-none text-slate-900 dark:text-white">Sure<span className="text-brand-500">Path</span></span>
              <span className="text-[0.45rem] font-bold text-gray-400 uppercase tracking-[0.4em] mt-1">{currentUser?.name || 'Guest'}</span>
            </div>
          </div>
          <div className="flex items-center gap-3">
            <button onClick={() => setDarkMode(!darkMode)} className="p-3 bg-white dark:bg-white/10 rounded-2xl text-gray-400 hover:text-primary-500 transition-colors shadow-sm border border-gray-100 dark:border-white/5">
              {darkMode ? <Sun size={18}/> : <Moon size={18}/>}
            </button>
            <button 
              onClick={handleLogout} 
              className="p-3 bg-slate-900 dark:bg-white text-white dark:text-black rounded-2xl hover:bg-primary-500 dark:hover:bg-primary-500 transition-all shadow-lg"
            >
               <LogOut size={18}/>
            </button>
          </div>
        </header>
      )}

      <main className={`flex-1 overflow-y-auto w-full no-scrollbar z-10 relative ${isWizardFlow ? 'p-0 h-screen' : 'px-6 py-10'}`}>
        {renderPortalContent()}
      </main>

      {!isWizardFlow && (
        <nav className="flex-shrink-0 fixed bottom-8 inset-x-6 h-20 bg-white/90 dark:bg-[#111]/90 backdrop-blur-xl z-[70] flex items-center justify-around px-4 rounded-[2.8rem] shadow-[0_30px_60px_-15px_rgba(0,0,0,0.1)] border border-gray-100 dark:border-white/10 max-w-xl mx-auto transition-all duration-500">
          {[
            { id: 'home', icon: HomeIcon, label: 'Home' },
            { id: 'products', icon: Grid, label: currentUser?.role === UserRole.AGENT ? 'Sales' : 'Products' },
            { id: 'claim', icon: Zap, label: 'Claim' },
            { id: 'wallet', icon: WalletIcon, label: 'Wallet' },
            { id: 'profile', icon: UserCircle, label: 'Profile' }
          ].map(item => (
            <button 
              key={item.id} 
              onClick={() => setPage(item.id)} 
              className={`flex flex-col items-center gap-1.5 flex-1 py-3 transition-all duration-300 tap-feedback ${currentPage === item.id || (currentPage.startsWith('buy') && item.id === 'products') ? 'text-primary-500 scale-110 -translate-y-1' : 'text-gray-400 dark:text-gray-500'}`}
            >
              <item.icon size={24} className={currentPage === item.id ? 'drop-shadow-[0_0_12px_rgba(249,115,22,0.4)]' : ''} />
              <span className="text-[0.45rem] font-black uppercase tracking-[0.2em]">{item.label}</span>
            </button>
          ))}
        </nav>
      )}
    </div>
  );

  if (!isMobile && (currentUser || appMode)) {
    return (
      <div className="min-h-screen bg-[#0c0a09] flex items-center justify-center p-12 overflow-hidden relative transition-all duration-1000 ease-in-out">
        <div className="absolute inset-0 bg-neural-mesh opacity-100"></div>
        <div className="relative w-[440px] h-[880px] bg-white rounded-[5rem] border-[14px] border-[#1c1917] shadow-[0_60px_120px_-30px_rgba(0,0,0,0.6)] ring-[1px] ring-white/10 overflow-hidden group transition-all duration-700">
          <div className="h-full w-full overflow-hidden rounded-[3.8rem]">
             <AppWrapper />
          </div>
        </div>
        <div className="absolute left-10 top-1/2 -translate-y-1/2 hidden xl:flex flex-col gap-6 w-80">
           <div className="p-10 glass-card rounded-[3rem] border-white/20 space-y-6 shadow-2xl bg-white/10 backdrop-blur-xl">
              <div className="w-16 h-16 bg-brand-500 rounded-3xl flex items-center justify-center text-white shadow-lg animate-float"><Terminal size={32}/></div>
              <h4 className="text-2xl font-black text-white uppercase tracking-tighter">My Account</h4>
              <p className="text-[0.7rem] text-gray-300 font-bold leading-relaxed uppercase tracking-[0.2em]">Logged as: {currentUser?.name || 'Guest'}. Status: Secure.</p>
              <div className="pt-2">
                 <Badge color="emerald">{currentUser?.role || 'MEMBER'}</Badge>
              </div>
           </div>
        </div>
      </div>
    );
  }

  return <AppWrapper />;
};

const Badge = ({ children, color = "primary" }: { children?: React.ReactNode, color?: string }) => {
  const styles: any = {
    primary: "bg-primary-500/10 text-primary-500 border-primary-500/20",
    emerald: "bg-brand-500/10 text-brand-500 border-brand-500/20",
    blue: "bg-blue-500/10 text-blue-500 border-blue-200",
    amber: "bg-amber-500/10 text-amber-600 border-amber-200",
  };
  return (
    <span className={`px-3 py-1 rounded-full text-[0.55rem] font-black uppercase tracking-widest border ${styles[color] || styles.primary}`}>
      {children}
    </span>
  );
};

export default App;

import React, { useState, useMemo, useEffect } from 'react';
import { Camera, BrainCircuit, CheckCircle2, Scan, Smartphone, ArrowRight, MapPin, Calendar, Clock, FileText, AlertCircle, Loader2, FileSearch, Trash2, ShieldCheck, ChevronRight, Info, Rocket } from 'lucide-react';
import { analyzeClaimPhoto, summarizeClaimDocument, ClaimAnalysisData, DocumentSummary } from '../services/geminiService';
import { db, Claim } from '../db';

const formatIDR = (num: number) => {
  return new Intl.NumberFormat('id-ID', {
    style: 'currency', currency: 'IDR', minimumFractionDigits: 0
  }).format(num);
};

interface ReportForm {
  chronology: string;
  location: string;
  date: string;
  time: string;
  thirdPartyInvolved: boolean;
}

const ClaimManager = ({ onComplete }: { onComplete: () => void }) => {
  const [step, setStep] = useState<'upload' | 'analyzing' | 'result' | 'docUpload' | 'docSummary' | 'reporting' | 'success'>('upload');
  const [claimResult, setClaimResult] = useState<ClaimAnalysisData | null>(null);
  const [docSummary, setDocSummary] = useState<DocumentSummary | null>(null);
  const [isSummarizing, setIsSummarizing] = useState(false);
  const [activeTab, setActiveTab] = useState<'evidence' | 'reasoning' | 'steps'>('evidence');
  const [currentUser, setCurrentUser] = useState<any>(null);
  const [photoBase64, setPhotoBase64] = useState<string>('');

  useEffect(() => {
    const saved = localStorage.getItem('SUREPATH_SESSION');
    if (saved) setCurrentUser(JSON.parse(saved));
  }, []);

  const [reportForm, setReportForm] = useState<ReportForm>({
    chronology: '',
    location: '',
    date: new Date().toISOString().split('T')[0],
    time: new Date().toLocaleTimeString([], { hour: '2-digit', minute: '2-digit', hour12: false }),
    thirdPartyInvolved: false
  });
  const [isSubmitting, setIsSubmitting] = useState(false);

  const dateLimits = useMemo(() => {
    const today = new Date();
    const max = today.toISOString().split('T')[0];
    const minDate = new Date();
    minDate.setDate(today.getDate() - 7);
    const min = minDate.toISOString().split('T')[0];
    return { min, max };
  }, []);

  const handleClaimUpload = async (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (!file) return;
    setStep('analyzing');
    const reader = new FileReader();
    reader.onload = async () => {
      const base64 = reader.result as string;
      setPhotoBase64(base64);
      const response = await analyzeClaimPhoto(base64);
      if (response.success && response.data) {
        setClaimResult(response.data);
        setStep('result');
      } else {
        alert(response.error || 'Audit neural gagal. Mohon gunakan foto yang lebih jelas.');
        setStep('upload');
      }
    };
    reader.readAsDataURL(file);
  };

  const handleDocUpload = async (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (!file) return;
    setIsSummarizing(true);
    const reader = new FileReader();
    reader.onload = async () => {
      const base64 = reader.result as string;
      const response = await summarizeClaimDocument(base64);
      setIsSummarizing(false);
      if (response.success && response.data) {
        setDocSummary(response.data);
        setStep('docSummary');
      } else {
        alert(response.error || 'Gagal meringkas dokumen.');
      }
    };
    reader.readAsDataURL(file);
  };

  const handleFinalReport = async (e: React.FormEvent) => {
    e.preventDefault();
    if (reportForm.chronology.length < 20) {
      alert("Berikan kronologi lebih detail (min. 20 karakter).");
      return;
    }

    if (!currentUser) return;

    setIsSubmitting(true);

    try {
        const newClaim: Claim = {
            userId: currentUser.id,
            date: reportForm.date,
            time: reportForm.time,
            location: reportForm.location,
            chronology: reportForm.chronology,
            status: 'SUBMITTED',
            amountEstimated: claimResult?.totalEstimasi || 0,
            photos: [photoBase64],
            aiAnalysis: claimResult,
            createdAt: new Date().toISOString()
        };

        await db.claims.add(newClaim);

        setTimeout(() => {
            setIsSubmitting(false);
            setStep('success');
        }, 1500);
    } catch (error) {
        console.error("Claim save failed", error);
        alert("Gagal menyimpan klaim.");
        setIsSubmitting(false);
    }
  };

  const Header = ({ title, showBack = false, onBack = () => {} }: { title: string, showBack?: boolean, onBack?: () => void }) => (
    <div className="flex items-center gap-3 mb-3">
      {showBack && (
        <button onClick={onBack} className="p-2 bg-gray-100 dark:bg-white/5 rounded-full hover:text-primary-500 transition-colors">
          <ChevronRight className="rotate-180" size={16}/>
        </button>
      )}
      <div className="w-7 h-7 bg-primary-500/10 rounded-lg flex items-center justify-center text-primary-500">
        <ShieldCheck size={16}/>
      </div>
      <h3 className="text-lg font-black uppercase tracking-tight">{title}</h3>
    </div>
  );

  if (step === 'upload') {
    return (
      <div className="space-y-3 animate-fade-in flex flex-col h-full justify-center">
        <div className="aspect-[4/3] relative rounded-[2rem] overflow-hidden bg-gray-100 dark:bg-white/5 border-2 border-dashed border-primary-500/30 flex flex-col items-center justify-center group cursor-pointer shadow-inner">
          <div className="w-14 h-14 bg-primary-500/10 rounded-full flex items-center justify-center text-primary-500 mb-2 group-hover:scale-110 transition-transform">
            <Camera size={28} />
          </div>
          <p className="text-base font-black uppercase text-gray-400 group-hover:text-primary-500 transition-colors tracking-tight">Accelerate Audit</p>
          <p className="text-[0.5rem] text-gray-400 mt-1 font-bold uppercase tracking-widest text-center px-4">Instant visual damage appraisal for express submission</p>
          <input type="file" className="absolute inset-0 opacity-0 cursor-pointer" onChange={handleClaimUpload} />
        </div>
        <div className="grid grid-cols-2 gap-2">
          <div className="p-3 rounded-xl bg-white dark:bg-white/5 border border-black/5 flex flex-col items-center text-center gap-1.5">
            <Scan size={18} className="text-primary-500" />
            <p className="text-[0.45rem] font-black uppercase tracking-widest text-gray-500">Fraud Detection</p>
          </div>
          <div className="p-3 rounded-xl bg-white dark:bg-white/5 border border-black/5 flex flex-col items-center text-center gap-1.5">
            <Rocket size={18} className="text-primary-500" />
            <p className="text-[0.45rem] font-black uppercase tracking-widest text-gray-500">Express Submit</p>
          </div>
        </div>
      </div>
    );
  }

  if (step === 'analyzing') {
    return (
      <div className="glass-card rounded-[2rem] p-6 animate-pop-in text-center space-y-8 flex flex-col h-full justify-center relative overflow-hidden bg-white dark:bg-[#0a0a0a]">
        {/* Background Grid Animation */}
        <div className="absolute inset-0 pointer-events-none opacity-5 bg-[size:40px_40px] bg-[linear-gradient(to_right,#80808012_1px,transparent_1px),linear-gradient(to_bottom,#80808012_1px,transparent_1px)]"></div>

        <div className="relative w-40 h-40 mx-auto flex items-center justify-center">
          <div className="absolute inset-0 border-4 border-primary-500/20 rounded-full animate-spin-slow"></div>
          <div className="absolute inset-4 border-4 border-dashed border-primary-500/40 rounded-full animate-reverse-spin"></div>
          <div className="absolute inset-0 flex items-center justify-center">
             <div className="w-20 h-20 bg-primary-500/10 rounded-full flex items-center justify-center animate-pulse">
                <BrainCircuit size={40} className="text-primary-500" />
             </div>
          </div>
          {/* Scanning Line */}
          <div className="absolute inset-0 w-full h-1 bg-primary-500/50 shadow-[0_0_20px_#f97316] animate-scan-fast rounded-full"></div>
        </div>

        <div className="space-y-2 z-10">
          <p className="text-[0.65rem] font-black uppercase text-primary-500 tracking-[0.4em] animate-pulse">Analyzing...</p>
          <div className="flex justify-center gap-1">
             <span className="w-1.5 h-1.5 bg-primary-500 rounded-full animate-bounce"></span>
             <span className="w-1.5 h-1.5 bg-primary-500 rounded-full animate-bounce delay-150"></span>
             <span className="w-1.5 h-1.5 bg-primary-500 rounded-full animate-bounce delay-300"></span>
          </div>
          <p className="text-[0.5rem] text-gray-400 uppercase font-bold tracking-widest mt-2">Processing Neural Layers</p>
        </div>
      </div>
    );
  }

  if (step === 'result' && claimResult) {
    return (
      <div className="space-y-3 animate-pop-in h-full flex flex-col pb-2">
        <div className="p-4 glass-card rounded-[2rem] border-2 border-primary-500/20 bg-primary-500/5 relative overflow-hidden flex-shrink-0">
          <div className="absolute top-3 right-3">
            <div className="px-2 py-0.5 bg-primary-500 text-white rounded-md font-black text-[0.45rem] uppercase tracking-widest">{claimResult.severity} Damage</div>
