const WelcomeScreen = ({ onFinish }: { onFinish: () => void }) => {
  const [progress, setProgress] = useState(0);
  const [isReady, setIsReady] = useState(false);

  useEffect(() => {
    const timer = setInterval(() => {
      setProgress(old => {
        if (old >= 100) {
          clearInterval(timer);
          setIsReady(true);
          setTimeout(onFinish, 800); // Delay before closing to show "Ready" state
          return 100;
        }
        // Non-linear progress for realism
        const diff = 100 - old;
        return old + (diff * 0.05) + 0.5;
      });
    }, 50);
    return () => clearInterval(timer);
  }, [onFinish]);

  return (
    <div className="fixed inset-0 z-[9999] bg-[#050505] flex flex-col items-center justify-center overflow-hidden font-sans text-white">
