          <div className="space-y-3 w-full">
            <div className="h-1.5 w-full bg-gray-800 rounded-full overflow-hidden relative">
                <div 
                  className={`absolute top-0 left-0 h-full bg-gradient-to-r from-emerald-600 to-emerald-400 transition-all duration-100 ease-out shadow-[0_0_15px_#10b981] ${isReady ? 'w-full' : ''}`} 
