const WelcomeScreen = ({ onFinish }: { onFinish: () => void }) => {
  const [progress, setProgress] = useState(0);
  const [opacity, setOpacity] = useState(1);

  useEffect(() => {
    // Smooth progress animation
    const timer = setInterval(() => {
      setProgress(old => {
        if (old >= 100) {
          clearInterval(timer);
          setTimeout(() => setOpacity(0), 400); // Fade out effect
          setTimeout(onFinish, 1000); // Unmount delay
          return 100;
        }
        // Random increments for organic feel
        const diff = Math.random() * 15;
        return Math.min(old + diff, 100);
      });
    }, 150);
    return () => clearInterval(timer);
  }, [onFinish]);

  if (opacity === 0) return null;

  return (
    <div 
      className="fixed inset-0 z-[9999] bg-slate-50 dark:bg-[#050505] flex flex-col items-center justify-center transition-opacity duration-700 overflow-hidden font-sans"
      style={{ opacity }}
    >
      {/* Background Blobs matching Website/AuthGate Theme */}
      <div className="absolute top-[-20%] left-[-20%] w-[600px] h-[600px] bg-emerald-500/20 rounded-full blur-[120px] animate-blob mix-blend-multiply dark:mix-blend-normal pointer-events-none"></div>
