      {/* Subtle Noise Texture */}
      <div className="absolute inset-0 bg-[url('https://grainy-gradients.vercel.app/noise.svg')] opacity-20 pointer-events-none"></div>

      <div className="relative z-10 flex flex-col items-center w-full max-w-xs px-6">
        {/* Logo Container with Glass Effect */}
        <div className="mb-10 relative group">
           <div className="absolute inset-0 bg-gradient-to-tr from-emerald-500 to-orange-500 rounded-full blur-[40px] opacity-30 animate-pulse"></div>
           <div className="relative bg-white/80 dark:bg-white/5 p-6 rounded-[2.5rem] shadow-2xl border border-white/40 dark:border-white/10 backdrop-blur-xl">
              <SurePathLogo className="w-20 h-20 drop-shadow-lg" />
           </div>
        </div>

        {/* Typography */}
        <div className="text-center space-y-2 mb-16">
           <h1 className="text-4xl font-black tracking-tighter text-slate-900 dark:text-white">
             Sure<span className="text-emerald-500">Path</span>
           </h1>
           <p className="text-[0.65rem] font-bold text-slate-400 uppercase tracking-[0.4em]">
             Your Path to Protection
           </p>
        </div>

        {/* Sleek Loader */}
        <div className="w-full space-y-4">
           {/* Progress Bar */}
           <div className="h-1.5 w-full bg-slate-200 dark:bg-white/10 rounded-full overflow-hidden shadow-inner">
              <div 
                className="h-full bg-gradient-to-r from-emerald-500 to-orange-500 transition-all duration-300 ease-out rounded-full relative"
                style={{ width: `${progress}%` }}
              >
                <div className="absolute right-0 top-0 bottom-0 w-20 bg-gradient-to-r from-transparent to-white/50 skew-x-12 animate-shimmer"></div>
              </div>
           </div>

           {/* Status Text */}
           <div className="flex justify-between items-center px-1">
              <p className="text-[0.6rem] font-bold text-slate-400 uppercase tracking-widest animate-pulse">
                {progress < 30 ? 'Initializing...' : progress < 70 ? 'Syncing Assets...' : 'Ready'}
              </p>
              <p className="text-[0.6rem] font-black text-slate-900 dark:text-white font-mono">
                {Math.round(progress)}%
