const WelcomeScreen = ({ onFinish }: { onFinish: () => void }) => {
  const [progress, setProgress] = useState(0);
  const [loadingText, setLoadingText] = useState('Initializing Neural Core...');
  const [opacity, setOpacity] = useState(1);

  useEffect(() => {
    // Neural loading simulation
    const interval = setInterval(() => {
      setProgress(prev => {
        if (prev >= 100) {
          clearInterval(interval);
          setTimeout(() => setOpacity(0), 600); // Fade out
          setTimeout(onFinish, 1200); // Unmount
          return 100;
        }

        // Dynamic status updates based on progress
        if (prev === 25) setLoadingText('Syncing Bio-Metric Shield...');
        if (prev === 55) setLoadingText('Calibrating Risk Matrix...');
        if (prev === 85) setLoadingText('Establishing Secure Link...');

        // Non-linear progress for realism
        const increment = Math.random() * 3 + 0.5; 
        return Math.min(prev + increment, 100);
      });
    }, 40);

    return () => clearInterval(interval);
  }, [onFinish]);

  if (opacity === 0) return null;

  return (
    <div 
      className="fixed inset-0 z-[9999] bg-slate-50 dark:bg-[#050505] flex flex-col items-center justify-center transition-opacity duration-700 overflow-hidden font-sans"
      style={{ opacity }}
    >
      {/* Background Blobs matching Website/AuthGate Theme */}
      <div className="absolute top-[-20%] left-[-20%] w-[600px] h-[600px] bg-emerald-500/10 rounded-full blur-[120px] animate-blob mix-blend-multiply dark:mix-blend-normal pointer-events-none"></div>
