      <div className="relative z-10 flex flex-col items-center w-full max-w-xs px-6">

        {/* Logo Container with Neural Scan Effect */}
        <div className="mb-12 relative group">
           {/* Glow behind logo */}
           <div className="absolute inset-0 bg-gradient-to-tr from-emerald-500 to-orange-500 rounded-full blur-[50px] opacity-20 animate-pulse"></div>

           <div className="relative bg-white/80 dark:bg-white/5 p-8 rounded-[3rem] shadow-2xl border border-white/40 dark:border-white/10 backdrop-blur-xl overflow-hidden">
              <SurePathLogo className="w-24 h-24 drop-shadow-lg relative z-10" />

              {/* Scanning Line Animation */}
              <div className="absolute top-0 left-0 w-full h-full z-20 animate-scan-line pointer-events-none">
                 <div className="w-full h-[2px] bg-emerald-400 shadow-[0_0_15px_rgba(52,211,153,0.8)]"></div>
                 <div className="w-full h-20 bg-gradient-to-t from-emerald-400/20 to-transparent"></div>
              </div>
           </div>
        </div>

        {/* Typography */}
        <div className="text-center space-y-3 mb-16">
           <h1 className="text-5xl font-black tracking-tighter text-slate-900 dark:text-white">
             Sure<span className="text-emerald-500">Path</span>
           </h1>
           <p className="text-[0.6rem] font-bold text-slate-400 uppercase tracking-[0.4em] animate-pulse">
             Neural Protection OS
           </p>
        </div>

        {/* Sleek Loader & Status */}
        <div className="w-full space-y-4">
           {/* Progress Bar */}
           <div className="h-1.5 w-full bg-slate-200 dark:bg-white/10 rounded-full overflow-hidden shadow-inner">
              <div 
                className="h-full bg-gradient-to-r from-emerald-500 to-emerald-300 transition-all duration-100 ease-out rounded-full relative"
                style={{ width: `${progress}%` }}
              >
                <div className="absolute right-0 top-0 bottom-0 w-20 bg-gradient-to-r from-transparent to-white/50 skew-x-12 animate-shimmer"></div>
