const WelcomeScreen = ({ onFinish }: { onFinish: () => void }) => {
  const [progress, setProgress] = useState(0);
  const [loadingText, setLoadingText] = useState('Waking up Suri...');
  const [opacity, setOpacity] = useState(1);

  useEffect(() => {
    // Simulated loading sequence
    const interval = setInterval(() => {
      setProgress(prev => {
        if (prev >= 100) {
          clearInterval(interval);
          setTimeout(() => setOpacity(0), 600); // Fade out whole screen
          setTimeout(onFinish, 1200); // Trigger app mount
          return 100;
        }

        // Narrative progression
        if (prev === 15) setLoadingText('Calibrating Shields...');
        if (prev === 40) setLoadingText('Connecting to Neural Grid...');
        if (prev === 70) setLoadingText('Securing Your Path...');
        if (prev === 90) setLoadingText('All Systems Go!');

        const increment = Math.random() * 4 + 1; 
        return Math.min(prev + increment, 100);
      });
    }, 50);

    return () => clearInterval(interval);
  }, [onFinish]);

  if (opacity === 0) return null;

  return (
    <div 
      className="fixed inset-0 z-[9999] bg-slate-50 dark:bg-[#050505] flex flex-col items-center justify-center transition-opacity duration-700 overflow-hidden font-sans"
      style={{ opacity }}
    >
      {/* Dynamic Background Elements */}
      <div className="absolute inset-0 pointer-events-none">
         <div className="absolute top-[-10%] left-[-10%] w-[500px] h-[500px] bg-emerald-500/10 rounded-full blur-[100px] animate-pulse"></div>
         <div className="absolute bottom-[-10%] right-[-10%] w-[500px] h-[500px] bg-blue-500/10 rounded-full blur-[100px] animate-pulse animation-delay-2000"></div>
         <div className="absolute inset-0 bg-[url('https://grainy-gradients.vercel.app/noise.svg')] opacity-20"></div>
      </div>

      <div className="relative z-10 flex flex-col items-center w-full max-w-sm px-8">

        {/* Mascot Container */}
        <div className="mb-12 relative">
           <div className="absolute inset-0 bg-white/50 dark:bg-white/5 blur-3xl rounded-full scale-150"></div>
           <SuriMascot />
        </div>

        {/* Text & Brand */}
        <div className="text-center space-y-2 mb-10">
           <h1 className="text-4xl font-black tracking-tighter text-slate-900 dark:text-white">
             Sure<span className="text-emerald-500">Path</span>
           </h1>
           <p className="text-[0.65rem] font-bold text-slate-400 uppercase tracking-[0.3em] animate-pulse">
             Your Neural Guardian
           </p>
        </div>

        {/* Loading UI */}
        <div className="w-full space-y-4">
           {/* Custom Progress Bar */}
           <div className="h-2 w-full bg-slate-200 dark:bg-white/10 rounded-full overflow-hidden p-[2px]">
              <div 
                className="h-full bg-gradient-to-r from-emerald-400 to-blue-500 rounded-full relative transition-all duration-200 ease-out"
                style={{ width: `${progress}%` }}
              >
                <div className="absolute right-0 top-0 bottom-0 w-2 bg-white/50 blur-[2px]"></div>
              </div>
           </div>

           {/* Status Text */}
           <div className="flex justify-between items-center px-1">
              <p className="text-[0.6rem] font-bold text-emerald-600 dark:text-emerald-400 uppercase tracking-widest min-w-[140px] truncate">
                {loadingText}
              </p>
              <p className="text-[0.65rem] font-black text-slate-900 dark:text-white font-mono">
                {Math.round(progress)}%
              </p>
           </div>
        </div>
      </div>

      {/* Footer */}
      <div className="absolute bottom-8 flex flex-col items-center gap-1 opacity-40">
         <span className="text-[0.5rem] font-bold text-slate-500 dark:text-slate-400 uppercase tracking-widest">Powered by Gemini AI</span>
      </div>
    </div>
  );
};

const App = () => {
  const [isLoaded, setIsLoaded] = useState(false);
  const [isMobile, setIsMobile] = useState(window.innerWidth < 1024);
  const [currentPage, setPage] = useState('home');
  const [currentUser, setCurrentUser] = useState<any>(null);
  const [darkMode, setDarkMode] = useState(false);
  const [appMode, setAppMode] = useState(false); 
  const [products, setProducts] = useState(INITIAL_PRODUCTS);
  const [lang, setLang] = useState<Language>(Language.EN);

  // Persistence logic: Check for active session on boot
  useEffect(() => {
    const savedSession = localStorage.getItem('SUREPATH_SESSION');
    if (savedSession) {
      try {
        const user = JSON.parse(savedSession);
        setCurrentUser(user);
        setAppMode(true);
      } catch (e) {
        console.error("Invalid session node", e);
        localStorage.removeItem('SUREPATH_SESSION');
      }
    }

    const timezone = new Intl.DateTimeFormat().resolvedOptions().timeZone;
    const isIndo = timezone.includes('Jakarta') || timezone.includes('Makassar') || timezone.includes('Jayapura');
    if (isIndo) setLang(Language.ID);
  }, []);

  const handleAuthSuccess = (user: any) => {
    setCurrentUser(user);
    // Persist session
    localStorage.setItem('SUREPATH_SESSION', JSON.stringify(user));
    setAppMode(true);
    setPage('home');
  };

  const handleLogout = () => {
    setCurrentUser(null);
    localStorage.removeItem('SUREPATH_SESSION');
    setAppMode(false);
    setPage('home');
  };

  useEffect(() => {
    const handleResize = () => setIsMobile(window.innerWidth < 1024);
    window.addEventListener('resize', handleResize);
    return () => window.removeEventListener('resize', handleResize);
  }, []);

  // Show the WelcomeScreen (Loading Animation) first
  if (!isLoaded) return <WelcomeScreen onFinish={() => setIsLoaded(true)} />;

  // Roles that access the HQ Admin Portal
  const isAdminRole = currentUser && [UserRole.MASTER_ADMIN, UserRole.ADMIN, UserRole.FINANCE].includes(currentUser.role);

