      <DesktopWebsite 
        onEnterPortal={() => { setAppMode(true); setPage('auth'); }} 
        onAdminAccess={() => { setAppMode(true); setPage('auth'); }} 
        currentLang={lang}
        onLangChange={setLang}
      />
    );
  }

