// --- WELCOME SCREEN ---
const WelcomeScreen = ({ onFinish }: { onFinish: () => void }) => {
  const [progress, setProgress] = useState(0);
  const [loadingText, setLoadingText] = useState('Suri is waking up...');
  const [opacity, setOpacity] = useState(1);

  useEffect(() => {
    const interval = setInterval(() => {
      setProgress(prev => {
        if (prev >= 100) {
          clearInterval(interval);
          setTimeout(() => setOpacity(0), 500); // Start fade out
          setTimeout(onFinish, 1200); // Unmount after fade
          return 100;
        }

        // Dynamic Text
        if (prev === 15) setLoadingText('Calibrating Neural Shields...');
        if (prev === 40) setLoadingText('Connecting to SurePath Grid...');
        if (prev === 75) setLoadingText('Securing Your Assets...');
        if (prev === 95) setLoadingText('All Systems Green!');

        return Math.min(prev + 1.5, 100);
      });
    }, 40);

    return () => clearInterval(interval);
  }, [onFinish]);

  if (opacity === 0) return null;

  return (
    <div 
      className="fixed inset-0 z-[9999] bg-slate-50 dark:bg-[#050505] flex flex-col items-center justify-center transition-opacity duration-700 overflow-hidden font-sans"
      style={{ opacity }}
