             Sure<span className="text-emerald-500">Path</span>
           </h1>
           <p className="text-[0.6rem] font-bold text-slate-400 uppercase tracking-[0.4em] animate-pulse">
             Your Neural Guardian
           </p>
        </div>

        {/* Loading Bar */}
        <div className="w-full space-y-4">
           <div className="h-2 w-full bg-slate-200 dark:bg-white/10 rounded-full overflow-hidden p-[2px] shadow-inner">
              <div 
                className="h-full bg-gradient-to-r from-emerald-400 to-blue-500 rounded-full relative transition-all duration-100 ease-out shadow-[0_0_10px_rgba(16,185,129,0.5)]"
                style={{ width: `${progress}%` }}
              >
                <div className="absolute right-0 top-0 bottom-0 w-4 bg-white/50 blur-[4px]"></div>
              </div>
           </div>

           <div className="flex justify-between items-center px-1">
              <p className="text-[0.6rem] font-bold text-emerald-600 dark:text-emerald-400 uppercase tracking-widest min-w-[140px] animate-pulse">
                {loadingText}
              </p>
              <p className="text-[0.65rem] font-black text-slate-900 dark:text-white font-mono">
                {Math.round(progress)}%
