const AuthGate: React.FC<AuthGateProps> = ({ onAuthSuccess, initialLang = Language.EN }) => {
  const [mode, setMode] = useState<'LOGIN' | 'REGISTER' | 'VERIFY'>('LOGIN');
  const [showPass, setShowPass] = useState(false);
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState<string | null>(null);
  const [otp, setOtp] = useState('');
  const [generatedOtp, setGeneratedOtp] = useState('');
  const [showIncomingSim, setShowIncomingSim] = useState(false);

  const [formData, setFormData] = useState({
    name: '',
    email: '', 
    phone: '',
    password: '',
    role: UserRole.CUSTOMER
  });

  useEffect(() => {
    // Init DB with secure seeding
    seedDatabase();
  }, []);

  const handleLogin = async (e: React.FormEvent) => {
    e.preventDefault();
    setLoading(true);
    setError(null);

    try {
      const user = await db.users.where('email').equals(formData.email).first();

      if (user && user.passwordHash && user.salt) {
        const isValid = await verifyPassword(formData.password, user.passwordHash, user.salt);
        if (isValid) {
          // Store minimal session info
          const { passwordHash, salt, ...safeUser } = user;
          onAuthSuccess(safeUser);
        } else {
          setLoading(false);
          setError("Email atau kata sandi salah.");
        }
      } else {
        setLoading(false);
        setError("Email tidak ditemukan atau kata sandi salah.");
      }
    } catch (err) {
      console.error(err);
      setLoading(false);
      setError("Gagal terhubung. Coba lagi.");
    }
  };

  const handleRegisterStart = (e: React.FormEvent) => {
    e.preventDefault();
    if (formData.password.length < 6) {
        setError("Kata sandi minimal 6 karakter.");
        return;
    }
    setLoading(true);
    // Simulate OTP generation
    const newOtp = Math.floor(100000 + Math.random() * 900000).toString();
    setGeneratedOtp(newOtp);
    setTimeout(() => {
      setLoading(false);
      setMode('VERIFY');
      setTimeout(() => setShowIncomingSim(true), 1200);
    }, 1500);
  };

  const handleVerifyFinal = async () => {
    if (otp !== generatedOtp) {
      setError("Kode verifikasi salah.");
      setOtp('');
      return;
    }
    setLoading(true);

    try {
      const existingUser = await db.users.where('email').equals(formData.email).first();
      if (existingUser) {
        setLoading(false);
        setError("Email sudah terdaftar.");
        return;
      }

      // Securely hash the password
      const { hash, salt } = await hashPassword(formData.password);

      const newUser: DBUser = {
        name: formData.name,
        email: formData.email,
        phone: formData.phone,
        passwordHash: hash,
        salt: salt,
        role: formData.role,
        nodeId: `SP-${Math.floor(1000 + Math.random()*8999)}`,
        memberSince: new Date().toISOString(),
        trustScore: 88,
        verified: false
      };

      const id = await db.users.add(newUser);
      const { passwordHash, salt: _, ...safeUser } = newUser;

      setTimeout(() => {
        onAuthSuccess({ ...safeUser, id });
      }, 1000);
    } catch (err) {
      console.error(err);
      setLoading(false);
      setError("Registrasi gagal.");
    }
  };

  return (
    <div className="min-h-screen bg-slate-50 dark:bg-[#050505] flex flex-col items-center justify-center p-6 relative overflow-hidden transition-colors duration-1000 font-sans">

      {/* --- AMBIENT BACKGROUND --- */}
      <div className="absolute inset-0 bg-[url('https://grainy-gradients.vercel.app/noise.svg')] opacity-20 pointer-events-none"></div>

      <div className="absolute top-[-10%] left-[-10%] w-[600px] h-[600px] bg-emerald-400/20 rounded-full blur-[120px] animate-blob"></div>
      <div className="absolute bottom-[-10%] right-[-10%] w-[600px] h-[600px] bg-orange-400/20 rounded-full blur-[140px] animate-blob animation-delay-2000"></div>

      {/* --- PUSH NOTIFICATION SIMULATION --- */}
      {showIncomingSim && (
        <div className="fixed top-4 left-4 right-4 z-[300] animate-pop-in cursor-pointer" onClick={() => { setOtp(generatedOtp); setShowIncomingSim(false); }}>
           <div className="bg-white/90 dark:bg-slate-900/90 backdrop-blur-xl border border-slate-200 dark:border-white/10 rounded-2xl p-4 shadow-2xl flex items-center gap-4">
              <div className="w-10 h-10 bg-emerald-500 rounded-xl flex items-center justify-center text-white flex-shrink-0 shadow-lg">
                 <BellRing size={20}/>
              </div>
              <div className="flex-1 min-w-0">
                 <div className="flex justify-between items-center mb-0.5">
                    <p className="text-[0.6rem] font-black text-slate-500 uppercase tracking-widest">SUREPATH SECURITY</p>
                    <p className="text-[0.55rem] text-slate-400">now</p>
                 </div>
                 <p className="text-sm font-bold text-slate-900 dark:text-white truncate">Kode Verifikasi Anda: <span className="font-black text-emerald-500 text-base">{generatedOtp}</span></p>
              </div>
           </div>
        </div>
      )}

      <div className="w-full max-w-md relative z-10">

        {/* --- LOGO & BRANDING --- */}
        <div className="flex flex-col items-center mb-10 group">
          <div className="relative mb-4 transition-transform duration-500 group-hover:scale-110">
            <div className="absolute inset-0 bg-gradient-to-tr from-emerald-400 to-orange-400 rounded-full blur-[40px] opacity-40 animate-pulse"></div>
