          </h1>
          <p className="text-[0.65rem] font-bold text-slate-400 uppercase tracking-[0.3em]">
            Protection Made Simple
          </p>
        </div>

        {/* --- MAIN CARD --- */}
        <div className="bg-white/70 dark:bg-black/40 backdrop-blur-2xl rounded-[3rem] p-2 border border-white/50 dark:border-white/10 shadow-[0_40px_80px_-20px_rgba(0,0,0,0.1)] relative overflow-hidden">

          {loading && (
            <div className="absolute inset-0 bg-white/80 dark:bg-black/80 backdrop-blur-sm z-50 flex flex-col items-center justify-center gap-6 animate-fade-in rounded-[3rem]">
               <div className="w-16 h-16 border-4 border-emerald-500/20 border-t-emerald-500 rounded-full animate-spin"></div>
               <p className="text-xs font-black uppercase tracking-widest text-slate-500 animate-pulse">{mode === 'REGISTER' ? 'Securing Identity...' : 'Verifying Credentials...'}</p>
            </div>
