          <div className="px-6 py-8 md:px-8">
            {mode === 'VERIFY' ? (
              <div className="space-y-8 text-center animate-fade-in">
                  <div className="space-y-2">
                    <h3 className="text-xl font-black text-slate-900 dark:text-white">Verifikasi Nomor</h3>
