                      maxLength={6}
                      className="w-full py-4 bg-transparent border-b-2 border-slate-200 dark:border-white/10 text-center text-4xl font-black tracking-[0.5em] text-emerald-500 outline-none focus:border-emerald-500 transition-all placeholder:text-slate-200"
                      value={otp}
                      onChange={(e) => {
                        setOtp(e.target.value.replace(/\D/g, ''));
                        setError(null);
                      }}
                    />
                  </div>
                  {error && <p className="text-xs font-bold text-rose-500 bg-rose-50 p-2 rounded-lg">{error}</p>}

                  <div className="space-y-3 pt-4">
                     <button 
                      onClick={handleVerifyFinal}
                      disabled={otp.length < 6}
                      className="w-full py-4 bg-slate-900 dark:bg-white text-white dark:text-black rounded-2xl font-black uppercase text-xs tracking-[0.2em] shadow-xl disabled:opacity-50 disabled:cursor-not-allowed active:scale-95 transition-all"
                    >
                      Konfirmasi
                    </button>
                    <button onClick={() => {setMode('REGISTER'); setOtp('');}} className="text-[0.6rem] font-bold text-slate-400 uppercase tracking-widest hover:text-emerald-500">Kirim Ulang</button>
                  </div>
              </div>
            ) : (
              <>
                  {/* --- TOGGLE --- */}
                  <div className="flex bg-slate-100 dark:bg-white/5 p-1.5 rounded-[1.8rem] mb-8 relative">
                      <div 
                        className={`absolute top-1.5 bottom-1.5 w-[calc(50%-6px)] bg-white dark:bg-slate-800 rounded-[1.4rem] shadow-sm transition-transform duration-300 ease-out ${mode === 'REGISTER' ? 'translate-x-full' : 'translate-x-0'}`}
                      ></div>

                      <button 
                          onClick={() => { setMode('LOGIN'); setError(null); }}
                          className={`flex-1 py-3 rounded-[1.4rem] text-[0.65rem] font-black uppercase tracking-widest transition-all relative z-10 flex items-center justify-center gap-2 ${mode === 'LOGIN' ? 'text-slate-900 dark:text-white' : 'text-slate-400 hover:text-slate-600'}`}
                      >
                          <LogIn size={14} strokeWidth={2.5}/> Masuk
                      </button>
                      <button 
