                       <button onClick={() => setFormData({...formData, email: 'master@surepath.ai', password: 'admin'})} className="flex-shrink-0 px-3 py-1.5 bg-slate-500/10 border border-slate-500/20 text-slate-600 rounded-lg text-[0.5rem] font-black uppercase tracking-wider hover:bg-slate-500 hover:text-white transition-all">Demo Admin</button>
