// --- TASK MANAGEMENT (Mobile Optimized) ---

interface Task {
  id: string;
  title: string;
  desc: string;
  priority: 'HIGH' | 'MEDIUM' | 'LOW';
  status: 'TODO' | 'IN_PROGRESS' | 'DONE';
  dueDate: string;
  assignee: string;
}

const INITIAL_TASKS: Task[] = [
  { id: 'T-101', title: 'Review Policy #9923', desc: 'Anomaly detected in claim photos.', priority: 'HIGH', status: 'TODO', dueDate: '2025-03-10', assignee: 'Admin' },
  { id: 'T-102', title: 'Agent Onboarding', desc: 'Verify documents for Agent Budi.', priority: 'MEDIUM', status: 'IN_PROGRESS', dueDate: '2025-03-12', assignee: 'HR' },
  { id: 'T-103', title: 'System Maintenance', desc: 'Weekly neural net recalibration.', priority: 'LOW', status: 'DONE', dueDate: '2025-03-01', assignee: 'DevOps' },
];

export const TasksView = () => {
  const [tasks, setTasks] = useState<Task[]>(INITIAL_TASKS);
  const [filter, setFilter] = useState<'ALL' | 'TODO' | 'IN_PROGRESS' | 'DONE'>('ALL');
  const [isEditorOpen, setIsEditorOpen] = useState(false);
  const [editingTask, setEditingTask] = useState<Task | null>(null);

  // Editor State
  const [form, setForm] = useState<Partial<Task>>({});

  const handleSave = () => {
    if (!form.title) return;

    if (editingTask) {
      setTasks(prev => prev.map(t => t.id === editingTask.id ? { ...t, ...form } as Task : t));
    } else {
      const newTask: Task = {
        id: `T-${Math.floor(Math.random() * 1000)}`,
        title: form.title!,
        desc: form.desc || '',
        priority: form.priority || 'MEDIUM',
        status: form.status || 'TODO',
        dueDate: form.dueDate || new Date().toISOString().split('T')[0],
        assignee: 'Me'
      };
      setTasks(prev => [newTask, ...prev]);
    }
    closeEditor();
  };

  const handleDelete = (id: string) => {
    if (confirm('Delete task?')) {
      setTasks(prev => prev.filter(t => t.id !== id));
      closeEditor();
    }
  };

  const openEditor = (task?: Task) => {
    setEditingTask(task || null);
    setForm(task || { priority: 'MEDIUM', status: 'TODO' });
    setIsEditorOpen(true);
  };

  const closeEditor = () => {
    setIsEditorOpen(false);
    setEditingTask(null);
    setForm({});
  };

  const filteredTasks = tasks.filter(t => filter === 'ALL' || t.status === filter);

  const getPriorityColor = (p: string) => {
    switch(p) {
      case 'HIGH': return 'bg-rose-500 text-white';
      case 'MEDIUM': return 'bg-amber-500 text-white';
      case 'LOW': return 'bg-blue-500 text-white';
      default: return 'bg-gray-500';
    }
  };

  return (
    <div className="relative h-full flex flex-col">
      {/* Header & Filter */}
      <div className="flex flex-col gap-6 mb-6">
         <div className="flex justify-between items-center">
            <div className="flex items-center gap-4">
               <div className="w-10 h-10 bg-primary-500/10 rounded-xl flex items-center justify-center text-primary-500"><CheckSquare size={22}/></div>
               <div>
                  <h3 className="font-black uppercase tracking-widest text-sm">Task Force</h3>
                  <p className="text-[0.5rem] font-bold text-gray-500 uppercase tracking-widest">{tasks.length} Active Directives</p>
               </div>
            </div>
         </div>

         <div className="flex bg-white/5 p-1 rounded-xl overflow-x-auto no-scrollbar">
            {(['ALL', 'TODO', 'IN_PROGRESS', 'DONE'] as const).map(f => (
               <button 
                 key={f}
                 onClick={() => setFilter(f)}
                 className={`flex-1 min-w-[80px] py-2 rounded-lg text-[0.55rem] font-black uppercase tracking-widest transition-all ${filter === f ? 'bg-primary-500 text-white shadow-lg' : 'text-gray-500 hover:text-white'}`}
               >
                 {f.replace('_', ' ')}
               </button>
            ))}
         </div>
      </div>

      {/* Task List */}
      <div className="space-y-3 pb-24">
         {filteredTasks.map(task => (
            <div 
              key={task.id}
              onClick={() => openEditor(task)}
              className="group p-5 bg-white/[0.03] border border-white/5 rounded-3xl active:scale-[0.98] transition-all hover:bg-white/10 hover:border-primary-500/30 cursor-pointer relative overflow-hidden"
            >
               <div className={`absolute left-0 top-0 bottom-0 w-1 ${task.status === 'DONE' ? 'bg-emerald-500' : 'bg-primary-500'}`}></div>
               <div className="flex justify-between items-start mb-2">
                  <div className="space-y-1">
                     <div className="flex items-center gap-2">
                        <span className={`px-2 py-0.5 rounded text-[0.45rem] font-black uppercase tracking-wider ${getPriorityColor(task.priority)}`}>{task.priority}</span>
                        {task.status === 'DONE' && <span className="text-emerald-500"><CheckCircle size={14}/></span>}
                     </div>
                     <h4 className={`font-black text-sm ${task.status === 'DONE' ? 'line-through opacity-50' : ''}`}>{task.title}</h4>
                  </div>
                  <button className="text-gray-500 hover:text-white p-2 -mr-2"><MoreVertical size={16}/></button>
               </div>

               <p className="text-[0.6rem] text-gray-400 line-clamp-2 mb-4 font-medium leading-relaxed">{task.desc}</p>

               <div className="flex justify-between items-center text-[0.55rem] font-bold text-gray-500 uppercase tracking-widest pt-3 border-t border-white/5">
                  <div className="flex items-center gap-2">
