               <div className="p-6 border-t border-white/5 bg-black/20 flex gap-3">
                  {editingTask && (
                     <button onClick={() => handleDelete(editingTask.id)} className="p-4 bg-rose-500/10 text-rose-500 rounded-xl hover:bg-rose-500 hover:text-white transition-all">
                        <Trash2 size={20}/>
                     </button>
                  )}
                  <button onClick={handleSave} className="flex-1 bg-primary-500 text-white rounded-xl font-black uppercase text-xs tracking-widest hover:bg-primary-600 transition-all shadow-lg active:scale-95 py-4">
                     Save Task
                  </button>
               </div>
            </div>
         </div>
      )}
    </div>
  );
};

