const WelcomeScreen = ({ onFinish }: { onFinish: () => void }) => {
  const [progress, setProgress] = useState(0);
  const [text, setText] = useState("Booting Neural OS...");

  useEffect(() => {
    // Phase 1: Boot
    setTimeout(() => setText("Syncing Neural Network..."), 1000);
    // Phase 2: Secure
    setTimeout(() => setText("Establishing Secure Link..."), 2000);
    // Phase 3: Ready
    setTimeout(() => setText("Welcome to SurePath"), 3000);

    const timer = setInterval(() => setProgress(p => (p >= 100 ? 100 : p + 2)), 60);
    const finishTimer = setTimeout(onFinish, 3800);

    return () => { clearInterval(timer); clearTimeout(finishTimer); };
  }, [onFinish]);

  return (
    <div className="fixed inset-0 z-[2000] bg-[#f0faf7] flex flex-col items-center justify-center overflow-hidden">
      {/* Background Ambience */}
      <div className="absolute inset-0 pointer-events-none">
