         <div className="absolute inset-0 bg-[url('https://grainy-gradients.vercel.app/noise.svg')] opacity-20"></div>
      </div>

      <div className="relative z-10 flex flex-col items-center">
        {/* Mascot Container */}
        <div className="mb-10 relative">
           <div className="absolute inset-0 bg-emerald-500/20 blur-[50px] rounded-full animate-pulse"></div>
           <NeuralBot className="w-48 h-48 relative z-10" mood={progress < 50 ? 'thinking' : 'happy'} />
        </div>

        {/* Text & Loader */}
        <div className="text-center space-y-6 max-w-xs w-full">
          <h1 className="text-3xl font-black text-slate-900 tracking-tight animate-fade-in">
            {text}
          </h1>

          <div className="relative h-2 bg-slate-200 rounded-full overflow-hidden w-full">
             <div 
               className="absolute top-0 left-0 h-full bg-gradient-to-r from-emerald-400 to-emerald-600 rounded-full transition-all duration-100 ease-out"
               style={{ width: `${progress}%` }}
             ></div>
          </div>

          <div className="flex justify-between text-[0.6rem] font-bold text-slate-400 uppercase tracking-widest">
             <span>System Check</span>
             <span>{Math.floor(progress)}%</span>
          </div>
        </div>
      </div>
    </div>
  );
};

