        className="w-full pl-14 pr-6 py-4 bg-white dark:bg-white/[0.03] border-2 border-slate-100 dark:border-white/5 rounded-[1.5rem] outline-none transition-all font-bold text-sm text-slate-900 dark:text-white placeholder:text-slate-300 dark:placeholder:text-gray-700 shadow-sm focus:border-primary-500 focus:ring-4 focus:ring-primary-500/10 focus:shadow-lg"
