);

const AuthGate: React.FC<AuthGateProps> = ({ onAuthSuccess, initialLang = Language.EN }) => {
  const [mode, setMode] = useState<'LOGIN' | 'REGISTER' | 'VERIFY'>('LOGIN');
  const [showPass, setShowPass] = useState(false);
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState<string | null>(null);
  const [otp, setOtp] = useState('');
  const [generatedOtp, setGeneratedOtp] = useState('');
  const [showIncomingSim, setShowIncomingSim] = useState(false);

  const [formData, setFormData] = useState({
    name: '',
    email: '', 
    phone: '',
    password: '',
    role: UserRole.CUSTOMER
  });

  useEffect(() => {
    // Init DB with secure seeding
    seedDatabase();
  }, []);

  const handleLogin = async (e: React.FormEvent) => {
    e.preventDefault();
    setLoading(true);
    setError(null);

    try {
      const user = await db.users.where('email').equals(formData.email).first();

      if (user && user.passwordHash && user.salt) {
        const isValid = await verifyPassword(formData.password, user.passwordHash, user.salt);
        if (isValid) {
          // Store minimal session info
          const { passwordHash, salt, ...safeUser } = user;
          onAuthSuccess(safeUser);
        } else {
          setLoading(false);
          setError("Email atau kata sandi salah.");
        }
      } else {
        setLoading(false);
        setError("Email tidak ditemukan atau kata sandi salah.");
      }
    } catch (err) {
      console.error(err);
      setLoading(false);
      setError("Gagal terhubung. Coba lagi.");
    }
  };

  const handleRegisterStart = (e: React.FormEvent) => {
    e.preventDefault();
    if (formData.password.length < 6) {
        setError("Kata sandi minimal 6 karakter.");
        return;
    }
    setLoading(true);
    // Simulate OTP generation
    const newOtp = Math.floor(100000 + Math.random() * 900000).toString();
    setGeneratedOtp(newOtp);
    setTimeout(() => {
      setLoading(false);
      setMode('VERIFY');
      setTimeout(() => setShowIncomingSim(true), 1200);
    }, 1500);
  };

  const handleVerifyFinal = async () => {
    if (otp !== generatedOtp) {
      setError("Kode verifikasi salah.");
      setOtp('');
      return;
    }
    setLoading(true);

    try {
      const existingUser = await db.users.where('email').equals(formData.email).first();
      if (existingUser) {
        setLoading(false);
        setError("Email sudah terdaftar.");
        return;
      }

      // Securely hash the password
      const { hash, salt } = await hashPassword(formData.password);

      const newUser: DBUser = {
        name: formData.name,
        email: formData.email,
        phone: formData.phone,
        passwordHash: hash,
        salt: salt,
        role: formData.role,
        nodeId: `SP-${Math.floor(1000 + Math.random()*8999)}`,
        memberSince: new Date().toISOString(),
        trustScore: 88,
        verified: false
