export const extractStnkData = async (base64: string): Promise<{ success: boolean; data?: any }> => {
  try {
    const ai = getAi();
    const cleanBase64 = base64.includes(',') ? base64.split(',')[1] : base64;
    const response = await ai.models.generateContent({
      model: 'gemini-3-flash-preview',
      contents: { 
        parts: [
          { text: `Analyze this image. It is likely an Indonesian Vehicle Registration Document (STNK) or Tax Notice (SKPD/Notice Pajak).

          Extract the following fields accurately regardless of layout (Landscape/Portrait):
          1. owner: Name of owner (Nama Pemilik).
          2. plate: License Plate (No. Registrasi / No. Polisi). Format usually B 1234 XYZ. Remove spaces in logic if needed, but return original here.
          3. brand: Vehicle Brand (Merk).
          4. model: Vehicle Type/Model (Tipe/Model).
          5. year: Manufacturing Year (Tahun Pembuatan / Perakitan).
          6. color: Vehicle Color (Warna).
          7. vin: Chassis Number (No. Rangka / NIK). Crucial field. Look for "No. Rangka" or "NIK".
          8. engine: Engine Number (No. Mesin). Crucial field.

          Security Audit:
          - status: 'OK' only if document looks authentic, legible, and unmanipulated.
          - If screen photo, photocopy, or blur: 'FRAUD' or 'UNCLEAR'.

          Output strictly JSON: { owner, plate, brand, model, color, year, vin, engine, status, reason (Indonesian) }.` }, 
          { inlineData: { mimeType: 'image/jpeg', data: cleanBase64 } }
        ] 
      },
      config: { responseMimeType: 'application/json', temperature: 0.1 }
    });
    return { success: true, data: JSON.parse(response.text) };
  } catch (e) { 
    console.error("STNK Extraction Error:", e);
    return { success: false }; 
  }
};

export const validateVehiclePhoto = async (base64: string, slotLabel: string): Promise<{ valid: boolean; issue?: string }> => {
