                <div className="p-3 bg-gray-50 dark:bg-white/5 rounded-2xl border border-black/5 dark:border-white/5 text-center">
                   <p className="text-[0.45rem] font-bold text-gray-400 uppercase tracking-widest mb-1 flex items-center justify-center gap-1"><Wallet size={10}/> Agent Commission</p>
                   <p className="text-sm font-black text-gray-900 dark:text-white">{formatIDR(premiumBreakdown.remainingCommission)}</p>
