        policyNumber: `POL-CR-${Date.now()}`,
        createdAt: new Date().toISOString(),
        coverageDetails: {
          vehicle: { ...vehicle, ...stnkResult },
          coverage: coverage,
          survey: survey,
          financials: premiumBreakdown // Store discount info
        }
      };

