      {/* Eyes Container */}
      <g className={mood === 'scanning' ? 'animate-pulse' : ''}>
        {mood === 'happy' && (
          <>
            {/* Left Eye */}
            <circle cx="80" cy="95" r="8" fill="#10b981" className="animate-blink" />
            {/* Right Eye */}
            <circle cx="120" cy="95" r="8" fill="#10b981" className="animate-blink" />
            {/* Smile */}
            <path d="M 85 110 Q 100 118 115 110" stroke="#10b981" strokeWidth="3" strokeLinecap="round" />
          </>
        )}

        {mood === 'thinking' && (
          <>
             {/* Thinking Eyes (Dots) */}
             <circle cx="70" cy="100" r="6" fill="#fb923c" className="animate-bounce" />
             <circle cx="100" cy="100" r="6" fill="#fb923c" className="animate-bounce delay-100" />
             <circle cx="130" cy="100" r="6" fill="#fb923c" className="animate-bounce delay-200" />
