      <line x1="100" y1="50" x2="100" y2="30" stroke="#cbd5e1" strokeWidth="4" />
      <circle cx="100" cy="25" r="6" fill={mood === 'thinking' ? '#fb923c' : '#10b981'} className="animate-ping" />
