      <rect x="30" y="80" width="10" height="40" rx="5" fill="#94a3b8" />
      <rect x="160" y="80" width="10" height="40" rx="5" fill="#94a3b8" />
    </g>

    {/* Shadow */}
    <ellipse cx="100" cy="170" rx="40" ry="5" fill="#000" opacity="0.1" className="animate-shadow-pulse" />
  </svg>
);

// --- WELCOME LOADING SCREEN ---
const WelcomeScreen = ({ onFinish }: { onFinish: () => void }) => {
  const [progress, setProgress] = useState(0);
  const [messageIdx, setMessageIdx] = useState(0);

  const messages = [
    "Initializing Neural Kernel",
    "Syncing Bio-Metric Shield",
    "Calibrating Risk Matrix",
    "Establishing Secure Link",
    "Protection Active"
  ];

  useEffect(() => {
    const timer = setInterval(() => setProgress(p => (p >= 100 ? 100 : p + 2)), 40);
    const msgTimer = setInterval(() => setMessageIdx(i => (i < messages.length - 1 ? i + 1 : i)), 800);
    const finishTimer = setTimeout(onFinish, 4000);
    return () => { clearInterval(timer); clearInterval(msgTimer); clearTimeout(finishTimer); };
  }, [onFinish]);

  return (
    <div className="fixed inset-0 z-[2000] bg-white dark:bg-[#0a0a0a] flex flex-col items-center justify-center overflow-hidden transition-colors duration-1000">
      {/* Background Ambience */}
      <div className="absolute inset-0 pointer-events-none">
