         <div className="absolute bottom-[-10%] right-[-10%] w-[700px] h-[700px] bg-primary-400/5 rounded-full blur-[140px] animate-blob animation-delay-2000"></div>
         <div className="absolute inset-0 bg-neural-mesh opacity-30"></div>
      </div>

      <div className="relative z-10 flex flex-col items-center animate-pop-in">
        <div className="mb-12 relative group">
           <div className="absolute inset-0 bg-emerald-500/20 rounded-full blur-[60px] animate-pulse"></div>
           <NeuralBot mood={progress < 40 ? 'scanning' : progress < 80 ? 'thinking' : 'happy'} className="w-48 h-48 relative drop-shadow-2xl" />
        </div>

        <div className="text-center space-y-8">
          <div className="flex flex-col items-center">
            <h1 className="text-5xl font-black tracking-[-0.05em] text-gray-900 dark:text-white uppercase flex items-center gap-2">
              SURE<span className="text-emerald-500">PATH</span>
            </h1>
