          <div className="space-y-4">
            <div className="flex items-center justify-center gap-3 h-6">
               <div className="w-1.5 h-1.5 rounded-full bg-emerald-500 animate-ping"></div>
               <p className="text-[0.75rem] font-black text-emerald-600 dark:text-emerald-400 uppercase tracking-[0.4em] transition-all duration-500">
                  {messages[messageIdx]}
               </p>
            </div>

            <div className="w-64 h-[4px] bg-gray-100 dark:bg-white/5 rounded-full overflow-hidden mx-auto border border-black/5 dark:border-white/5">
                <div 
                  className="h-full bg-emerald-500 shadow-[0_0_15px_rgba(16,185,129,0.6)] transition-all duration-300 ease-out" 
                  style={{ width: `${progress}%` }}
                ></div>
            </div>
          </div>
        </div>
      </div>

      {/* Footer System Text */}
      <div className="absolute bottom-10 flex items-center gap-4 opacity-30">
         <span className="text-[0.5rem] font-mono font-bold text-gray-500 uppercase tracking-widest">System Boot Ver. 3.4.1</span>
