const App = () => {
  const [isLoaded, setIsLoaded] = useState(false);
  const [isMobile, setIsMobile] = useState(window.innerWidth < 1024);
  const [currentPage, setPage] = useState('home');
  const [currentUser, setCurrentUser] = useState<any>(null);
  const [darkMode, setDarkMode] = useState(false);
  const [appMode, setAppMode] = useState(false); 
  const [products, setProducts] = useState(INITIAL_PRODUCTS);
  const [lang, setLang] = useState<Language>(Language.EN);

  // Persistence logic
  useEffect(() => {
    const savedSession = localStorage.getItem('SUREPATH_SESSION');
    if (savedSession) {
      try {
        const user = JSON.parse(savedSession);
        setCurrentUser(user);
        setAppMode(true);
      } catch (e) {
        console.error("Invalid session node", e);
        localStorage.removeItem('SUREPATH_SESSION');
      }
    }

    const timezone = new Intl.DateTimeFormat().resolvedOptions().timeZone;
    const isIndo = timezone.includes('Jakarta') || timezone.includes('Makassar') || timezone.includes('Jayapura');
    if (isIndo) setLang(Language.ID);
  }, []);

  const handleAuthSuccess = (user: any) => {
    setCurrentUser(user);
    localStorage.setItem('SUREPATH_SESSION', JSON.stringify(user));
    setAppMode(true);
    setPage('home');
  };

  const handleLogout = () => {
    setCurrentUser(null);
    localStorage.removeItem('SUREPATH_SESSION');
    setAppMode(false);
    setPage('home');
  };

  useEffect(() => {
    const handleResize = () => setIsMobile(window.innerWidth < 1024);
    window.addEventListener('resize', handleResize);
    return () => window.removeEventListener('resize', handleResize);
  }, []);

  // Show the WelcomeScreen first
  if (!isLoaded) return <WelcomeScreen onFinish={() => setIsLoaded(true)} />;

  // Roles that access the HQ Admin Portal
  const isAdminRole = currentUser && [UserRole.MASTER_ADMIN, UserRole.ADMIN, UserRole.FINANCE].includes(currentUser.role);

  if (isAdminRole) {
    return <AdminPortal 
      onLogout={handleLogout} 
      products={products}
      setProducts={setProducts}
      userRole={currentUser.role}
    />;
  }

  if (!isMobile && !appMode && !currentUser) {
    return (
      <DesktopWebsite 
        onEnterPortal={() => { setAppMode(true); setPage('auth'); }} 
        onAdminAccess={() => { setAppMode(true); setPage('auth'); }} 
        currentLang={lang}
        onLangChange={setLang}
      />
    );
  }

  if (!currentUser && (isMobile || appMode)) {
    return <AuthGate onAuthSuccess={handleAuthSuccess} initialLang={lang} />;
  }

  const renderPortalContent = () => {
    const isAgent = currentUser?.role === UserRole.AGENT;

    switch(currentPage) {
      case 'home':
        return (
          <div className="space-y-8 animate-fade-in pb-24 text-gray-900 dark:text-white relative z-10">
            <PortalHero onAction={(p) => setPage(p)} />

            {/* --- CUSTOMER VIEW (STORE IN HOME) --- */}
            {!isAgent ? (
              <>
                {/* 1. Active Protection Status */}
                <div className="p-5 bg-white dark:bg-white/5 border border-gray-200 dark:border-white/5 rounded-[2rem] flex items-center justify-between shadow-lg">
                   <div className="flex items-center gap-4">
                      <div className="w-10 h-10 bg-emerald-500 rounded-2xl flex items-center justify-center text-white shadow-lg shadow-emerald-500/20">
                         <ShieldIcon size={20}/>
                      </div>
                      <div>
                         <p className="text-[0.65rem] font-black uppercase tracking-widest text-gray-900 dark:text-white flex items-center gap-2">
                            My Coverage
                            <span className="w-1.5 h-1.5 rounded-full bg-emerald-500 animate-pulse"></span>
                         </p>
                         <p className="text-[0.5rem] font-bold text-gray-500 uppercase tracking-widest">ID: {currentUser?.nodeId || 'SP-USER'}</p>
                      </div>
                   </div>
                   <div className="px-4 py-2 bg-emerald-500/10 text-emerald-600 rounded-xl">
                      <span className="text-[0.55rem] font-black uppercase tracking-widest">Active</span>
                   </div>
