const NeuralBot = ({ className = "w-32 h-32", mood = "happy" }: { className?: string, mood?: 'happy' | 'thinking' | 'scanning' }) => (
  <svg viewBox="0 0 200 200" className={className} fill="none" xmlns="http://www.w3.org/2000/svg">
    <defs>
      <linearGradient id="botGradient" x1="0" y1="0" x2="200" y2="200">
        <stop offset="0%" stopColor="#fff" />
        <stop offset="100%" stopColor="#e2e8f0" />
      </linearGradient>
      <filter id="glow" x="-20%" y="-20%" width="140%" height="140%">
        <feGaussianBlur stdDeviation="5" result="blur" />
        <feComposite in="SourceGraphic" in2="blur" operator="over" />
      </filter>
    </defs>

    {/* Hover Animation Group */}
    <g className="animate-float">
      {/* Body/Head */}
      <rect x="40" y="50" width="120" height="100" rx="30" fill="url(#botGradient)" stroke="#cbd5e1" strokeWidth="2" />
      <rect x="40" y="50" width="120" height="100" rx="30" fill="url(#botGradient)" className="drop-shadow-xl" />

      {/* Screen/Face Area */}
      <rect x="55" y="70" width="90" height="60" rx="20" fill="#0f172a" />

      {/* Eyes Container */}
      <g className={mood === 'scanning' ? 'animate-pulse' : ''}>
        {mood === 'happy' && (
          <>
            {/* Left Eye */}
            <circle cx="80" cy="95" r="8" fill="#10b981" className="animate-blink" />
            {/* Right Eye */}
            <circle cx="120" cy="95" r="8" fill="#10b981" className="animate-blink" />
            {/* Smile */}
            <path d="M 85 110 Q 100 118 115 110" stroke="#10b981" strokeWidth="3" strokeLinecap="round" />
          </>
        )}

        {mood === 'thinking' && (
          <>
             {/* Thinking Eyes (Dots) */}
             <circle cx="70" cy="100" r="6" fill="#fb923c" className="animate-bounce" />
             <circle cx="100" cy="100" r="6" fill="#fb923c" className="animate-bounce delay-100" />
             <circle cx="130" cy="100" r="6" fill="#fb923c" className="animate-bounce delay-200" />
