      {/* Side Details */}
      <rect x="30" y="80" width="10" height="40" rx="5" fill="#94a3b8" />
      <rect x="160" y="80" width="10" height="40" rx="5" fill="#94a3b8" />
    </g>

    {/* Shadow */}
    <ellipse cx="100" cy="170" rx="40" ry="5" fill="#000" opacity="0.1" className="animate-shadow-pulse" />
  </svg>
);

