    const saved = localStorage.getItem(STORAGE_KEY);
    if (saved) {
      try {
        const data = JSON.parse(saved);
        if (data.step !== undefined) setStep(data.step);
        if (data.vehicle) setVehicle(data.vehicle);
        if (data.coverage) setCoverage(data.coverage);
        if (data.selectedProviderId) setSelectedProviderId(data.selectedProviderId);
        if (data.kycData) setKycData(data.kycData);
        if (data.survey) setSurvey(data.survey);
        if (data.stnkResult) setStnkResult(data.stnkResult);
      } catch (err) {
        console.error("Failed to restore wizard progress", err);
      }
    }
  }, []);

  useEffect(() => {
    const timer = setTimeout(() => {
      const stateToSave = {
        step,
        vehicle,
        coverage,
        selectedProviderId,
        kycData,
        survey,
        stnkResult
      };
      try {
        localStorage.setItem(STORAGE_KEY, JSON.stringify(stateToSave));
      } catch (err) {
        console.warn("Storage quota exceeded");
      }
    }, 1000); 
    return () => clearTimeout(timer);
  }, [step, vehicle, coverage, selectedProviderId, kycData, survey, stnkResult]);

  const clearProgress = () => {
    localStorage.removeItem(STORAGE_KEY);
  };

  useEffect(() => {
    if (vehicle.condition === 'NEW') {
        setVehicle(prev => ({ ...prev, year: 2025 }));
    }
  }, [vehicle.condition]);

  const selectedProvider = useMemo(() => INSURANCE_PROVIDERS.find(p => p.id === selectedProviderId), [selectedProviderId]);

  const premiumBreakdown = useMemo(() => {
    if (!vehicle.price) return null;
    const baseRate = getOJKRate(vehicle.price / 1000000, vehicle.region, coverage.type);
    const basicPremium = (vehicle.price * baseRate) / 100;

    const expansions = [];
    if (coverage.authorized) expansions.push({ name: 'Bengkel Resmi (Authorized)', val: (vehicle.price * AUTHORIZED_WORKSHOP_RATE) / 100, rate: AUTHORIZED_WORKSHOP_RATE });
    if (coverage.flood) expansions.push({ name: 'Banjir & Angin Ribut', val: (vehicle.price * EXPANSION_RATES.FLOOD) / 100, rate: EXPANSION_RATES.FLOOD });
    if (coverage.earthquake) expansions.push({ name: 'Gempa & Tsunami', val: (vehicle.price * EXPANSION_RATES.EARTHQUAKE) / 100, rate: EXPANSION_RATES.EARTHQUAKE });

    const srccRate = coverage.type === InsuranceType.COMPREHENSIVE ? EXPANSION_RATES.SRCC.COMPREHENSIVE : EXPANSION_RATES.SRCC.TLO;
    if (coverage.srcc) expansions.push({ name: 'SRCC (Kerusuhan)', val: (vehicle.price * srccRate) / 100, rate: srccRate });

    const tsRate = coverage.type === InsuranceType.COMPREHENSIVE ? EXPANSION_RATES.TERRORISM.COMPREHENSIVE : EXPANSION_RATES.TERRORISM.TLO;
    if (coverage.terrorism) expansions.push({ name: 'Terorisme & Sabotase', val: (vehicle.price * tsRate) / 100, rate: tsRate });

    const tplPremium = (coverage.tpl / 100); 
    const expansionTotal = expansions.reduce((acc: number, curr: any) => acc + curr.val, 0) + tplPremium;
    const netPremium = basicPremium + expansionTotal;

    return {
        baseRate, basicPremium, expansions, tplPremium,
        adminFee: selectedProvider?.adminFee || 0,
        stampDuty: STAMP_DUTY,
        netPremium,
        totalPayable: netPremium + (selectedProvider?.adminFee || 0) + STAMP_DUTY
    };
  }, [vehicle, coverage, selectedProvider]);

  const sortedProviders = useMemo(() => {
    return [...INSURANCE_PROVIDERS].sort((a, b) => {
      if (sortBy === 'RATING') return b.rating - a.rating;
      if (sortBy === 'PRICE') {
          const priceA = (premiumBreakdown?.netPremium || 0) + a.adminFee;
          const priceB = (premiumBreakdown?.netPremium || 0) + b.adminFee;
          return priceA - priceB;
      }
      return 0;
    });
  }, [sortBy, premiumBreakdown]);

  const handleNext = () => setStep(s => Math.min(s + 1, STEPS.length - 1));
  const handleBack = () => setStep(s => Math.max(s - 1, 0));

  const formatInputCurrency = (value: string) => {
    const numeric = value.replace(/\D/g, "");
    if (!numeric) return "";
    return new Intl.NumberFormat('id-ID').format(parseInt(numeric));
  };

  const handlePlateChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    let val = e.target.value.toUpperCase();
    val = val.replace(/[^A-Z0-9]/g, "");
    const parts = val.match(/^([A-Z]{1,2})([0-9]{0,4})([A-Z]{0,3})$/);
    if (parts) {
      const plate = `${parts[1]}${parts[2] ? ' ' + parts[2] : ''}${parts[3] ? ' ' + parts[3] : ''}`;
      const prefix = parts[1];
      const regionInfo = PLATE_REGIONS[prefix];
      setVehicle({
        ...vehicle, 
        plate, 
        region: regionInfo?.region || '3', 
        regionName: regionInfo ? `${regionInfo.name} (Region ${regionInfo.region})` : 'Region 3 (Lainnya)'
      });
    } else {
      setVehicle({...vehicle, plate: val});
    }
  };

  const handleFinalPayment = async () => {
    if (!currentUser || !premiumBreakdown) return;

    try {
      const isManualPending = survey.verdict === 'MANUAL_REQUIRED' || survey.manualRequestStatus === 'REQUESTED';

      const newPolicy: Policy = {
        userId: currentUser.id,
        type: 'CAR',
        status: isManualPending ? 'PENDING' : 'ACTIVE',
        startDate: new Date().toISOString(),
        endDate: new Date(new Date().setFullYear(new Date().getFullYear() + 1)).toISOString(),
        premium: premiumBreakdown.totalPayable,
        providerId: selectedProviderId || '',
        policyNumber: `POL-CR-${Date.now()}`,
        createdAt: new Date().toISOString(),
        coverageDetails: {
          vehicle: { ...vehicle, ...stnkResult },
          coverage: coverage,
          survey: survey
        }
      };

      const policyId = await db.policies.add(newPolicy);

      const newTransaction: Transaction = {
        userId: currentUser.id,
        type: 'PAYMENT',
        amount: premiumBreakdown.totalPayable,
        status: isManualPending ? 'PENDING' : 'SUCCESS',
        description: `Payment for Policy ${newPolicy.policyNumber}`,
        date: new Date().toISOString(),
        referenceId: policyId.toString()
      };

      await db.transactions.add(newTransaction);

      clearProgress();
      onComplete();
    } catch (e) {
      console.error("DB Error", e);
      alert("Gagal memproses pembayaran. Coba lagi.");
    }
  };

  return (
    <div className="flex flex-col h-full min-h-screen bg-[#f0faf7] dark:bg-dark-bg text-gray-900 dark:text-white overflow-hidden relative selection:bg-primary-100">
       <div className="px-8 pt-8 pb-4 bg-white dark:bg-white/5 border-b border-black/5 flex flex-col gap-6 flex-shrink-0 relative z-[100] shadow-sm">
          <div className="flex items-center justify-between">
            <div className="flex items-center gap-5">
               <div className="w-14 h-14 bg-midnight rounded-[1.8rem] flex items-center justify-center text-white shadow-2xl group border border-white/10"><Car size={28} className="group-hover:rotate-12 transition-transform text-primary-500"/></div>
               <div>
                  <p className="text-[0.55rem] font-black text-gray-400 uppercase tracking-[0.4em] leading-none mb-1.5">Auto-Neural Module</p>
                  <h3 className="text-xl font-black uppercase tracking-tighter leading-none">Sure<span className="text-primary-500">Path</span> Registry</h3>
               </div>
            </div>
            <div className="flex items-center gap-3">
               <button 
                onClick={() => { if(confirm("Restart progress?")) { clearProgress(); window.location.reload(); } }} 
                className="p-3 text-gray-400 hover:text-rose-500 bg-gray-50 dark:bg-white/5 rounded-2xl transition-all border border-black/5"
               >
                  <RefreshCw size={20}/>
               </button>
               <button onClick={onComplete} className="p-3 text-gray-400 hover:text-gray-900 dark:hover:text-white bg-gray-50 dark:bg-white/5 rounded-2xl transition-all border border-black/5">
                 <X size={24}/>
               </button>
            </div>
          </div>

          <div className="flex items-center justify-between">
             <div className="flex bg-gray-100 dark:bg-white/5 p-1 rounded-xl border border-black/5">
                <div className="px-4 py-1.5 text-[0.65rem] font-black text-primary-600 uppercase tracking-widest">{STEPS[step].label}</div>
             </div>
             <p className="text-[0.6rem] font-black text-gray-400 uppercase tracking-[0.2em]">Step {step + 1} of {STEPS.length}</p>
          </div>

          <div className="flex gap-2.5">
             {STEPS.map((s, i) => (<div key={i} className={`h-2 rounded-full flex-1 transition-all duration-700 ${i === step ? 'bg-primary-500 shadow-[0_0_15px_#10b981]' : i < step ? 'bg-primary-500/30' : 'bg-gray-200 dark:bg-white/10'}`}></div>))}
          </div>
       </div>

       <div className="flex-1 overflow-y-auto px-8 py-10 no-scrollbar relative z-10">
          <div className="max-w-xl mx-auto">
            {step === 0 && (
                <StepVehicle 
                    vehicle={vehicle} setVehicle={setVehicle} 
                    entryMode={entryMode} setEntryMode={setEntryMode} 
                    handlePlateChange={handlePlateChange} formatInputCurrency={formatInputCurrency} 
                    loading={loading} setLoading={setLoading}
                    loadingType={loadingType} setLoadingType={setLoadingType}
                    setStnkResult={setStnkResult}
                />
            )}
            {step === 1 && <StepCoverage coverage={coverage} setCoverage={setCoverage} />}
            {step === 2 && (
                <StepProviders 
                    sortBy={sortBy} setSortBy={setSortBy} 
                    sortedProviders={sortedProviders} selectedProviderId={selectedProviderId} 
                    setSelectedProviderId={setSelectedProviderId} premiumBreakdown={premiumBreakdown} 
                    showProviderBreakdown={showProviderBreakdown} setShowProviderBreakdown={setShowProviderBreakdown} 
                />
            )}
            {step === 3 && (
                <StepKYC 
                    kycData={kycData} setKycData={setKycData} 
                    loading={loading} setLoading={setLoading} 
                    loadingType={loadingType} setLoadingType={setLoadingType} 
                    verifiedFields={verifiedFields} setVerifiedFields={setVerifiedFields} 
                />
            )}
            {step === 4 && (
                <StepPreSummary 
                    vehicle={vehicle} coverage={coverage} 
                    premiumBreakdown={premiumBreakdown} showBreakdown={showBreakdown} 
                    setShowBreakdown={setShowBreakdown} 
                />
            )}
            {step === 5 && (
                <StepSurvey 
                    survey={survey} setSurvey={setSurvey} 
                    stnkResult={stnkResult} setStnkResult={setStnkResult} 
                    loading={loading} setLoading={setLoading} 
                    loadingType={loadingType} setLoadingType={setLoadingType} 
                    photoValidation={photoValidation} setPhotoValidation={setPhotoValidation} 
                    vehicle={vehicle} 
                />
            )}
            {step === 6 && (
                <StepFinal 
                    vehicle={vehicle} stnkResult={stnkResult} 
                    coverage={coverage} survey={survey} 
                    premiumBreakdown={premiumBreakdown} handleFinalPayment={handleFinalPayment} 
                    setStep={setStep} 
                />
            )}
          </div>
       </div>

       <div className="px-8 py-8 bg-white dark:bg-[#111] border-t border-black/5 flex items-center justify-between gap-8 flex-shrink-0 sticky bottom-0 z-[100] shadow-[0_-20px_50px_rgba(0,0,0,0.05)]">
          <div className="flex-1">
             <p className="text-[0.6rem] font-black uppercase text-gray-400 leading-none mb-1.5 tracking-[0.2em]">Matrix Premium Est.</p>
             <p className="text-3xl font-black tracking-tighter text-primary-500 leading-none">{premiumBreakdown ? formatIDR(premiumBreakdown.totalPayable) : 'Rp 0'}</p>
          </div>
          <div className="flex gap-4">
             {step > 0 && (<button onClick={handleBack} className="p-5 bg-gray-50 dark:bg-white/5 rounded-3xl text-gray-400 hover:text-primary-500 transition-all shadow-sm border border-black/5 active:scale-95"><ChevronLeft size={28}/></button>)}
             {step < STEPS.length - 1 && (
                <button 
                  onClick={handleNext} 
                  disabled={(step === 5 && (survey.score === 0 || (survey.verdict === 'MANUAL_REQUIRED' && survey.manualRequestStatus !== 'REQUESTED')))}
                  className="px-12 py-5 bg-midnight dark:bg-white text-white dark:text-black rounded-[1.8rem] font-black uppercase text-[0.75rem] tracking-[0.3em] shadow-2xl transition-all active:scale-95 flex items-center gap-3 disabled:opacity-30 disabled:grayscale group"
                >
                  {step === 5 && survey.manualVerif ? 'Submisi HQ Review' : 'Next Cycle'} <ChevronRight size={20} className="group-hover:translate-x-1 transition-transform"/>
                </button>
             )}
          </div>
       </div>
    </div>
  );
};

export default CarInsuranceWizard;

import React, { useState } from 'react';
import { Database, Edit3, ChevronDown, User, Briefcase, Building2, Zap, Timer, FileSearch, Sparkles, CheckCircle2, RefreshCw } from 'lucide-react';
import { CAR_DATABASE } from '../../constants';
import { extractStnkData } from '../../services/geminiService';
import { ScannerOverlay } from './WizardUI';

interface StepVehicleProps {
  vehicle: any;
  setVehicle: (v: any) => void;
  entryMode: 'DATABASE' | 'MANUAL';
  setEntryMode: (m: 'DATABASE' | 'MANUAL') => void;
  handlePlateChange: (e: React.ChangeEvent<HTMLInputElement>) => void;
  formatInputCurrency: (val: string) => string;
  loading: boolean;
  setLoading: (l: boolean) => void;
  loadingType: 'KTP' | 'STNK' | 'SURVEY' | null;
  setLoadingType: (t: 'KTP' | 'STNK' | 'SURVEY' | null) => void;
  setStnkResult?: (res: any) => void; 
}

const StepVehicle: React.FC<StepVehicleProps> = ({ 
  vehicle, setVehicle, entryMode, setEntryMode, handlePlateChange, formatInputCurrency,
  loading, setLoading, loadingType, setLoadingType, setStnkResult
}) => {
  // Store all extracted STNK info for editing
  const [extractedStnk, setExtractedStnk] = useState<any>(null);

  const handleStnkAutofill = async (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (!file) return;
    setLoading(true);
    setLoadingType('STNK');
    setExtractedStnk(null);

    const reader = new FileReader();
    reader.onload = async () => {
        const base64 = reader.result as string;
        const response = await extractStnkData(base64);
        setLoading(false);
        setLoadingType(null);

        if (response.success && response.data) {
            const data = response.data;
            const cleanData = {
                ownerName: data.owner || '',
                plate: data.plate || '',
                brand: data.brand || '',
                model: data.model || '',
                color: data.color || '',
                year: data.year || '',
                vin: data.vin || '',
                engine: data.engine || '',
                status: data.status || 'OK'
            };

            setExtractedStnk(cleanData);

            // Populate STNK Result for parent
            if (setStnkResult) {
                setStnkResult(cleanData);
            }

            // Database Matching
            const match = CAR_DATABASE.find(c => 
                data.brand.toUpperCase().includes(c.brand) || 
                (c.modelName && data.brand.toUpperCase().includes(c.modelName))
            );

            const yearInt = parseInt(data.year) || 2025;
            const price = match ? (match.yearPrices[yearInt] || match.yearPrices[2024] || 0) * 1000000 : 0;

            // Autofill Main Form
            setVehicle((prev: any) => ({
                ...prev,
                brand: match?.brand || data.brand.split(' ')[0] || prev.brand,
                model: match?.modelName || data.model || prev.model,
                year: yearInt || prev.year,
                plate: data.plate || prev.plate,
                vin: data.vin || prev.vin,
                engine: data.engine || prev.engine,
                price: price || prev.price,
                manualPrice: !price,
                condition: yearInt < new Date().getFullYear() ? 'USED' : 'NEW'
            }));

            if (!match) {
                setEntryMode('MANUAL');
            } else {
                setEntryMode('DATABASE');
            }
        } else {
            alert('Gagal mengekstrak data STNK. Silakan isi manual.');
        }
    };
    reader.readAsDataURL(file);
  };

  const handleStnkEdit = (field: string, value: string) => {
      const newStnk = { ...extractedStnk, [field]: value.toUpperCase() };
      setExtractedStnk(newStnk);
      if (setStnkResult) setStnkResult(newStnk);

      // Update main vehicle state for the edited field
      if (field === 'brand') setVehicle((prev: any) => ({ ...prev, brand: value.toUpperCase() }));
      if (field === 'model') setVehicle((prev: any) => ({ ...prev, model: value.toUpperCase() }));
      if (field === 'plate') setVehicle((prev: any) => ({ ...prev, plate: value.toUpperCase() }));
      if (field === 'year') setVehicle((prev: any) => ({ ...prev, year: parseInt(value) || prev.year }));
      if (field === 'vin') setVehicle((prev: any) => ({ ...prev, vin: value.toUpperCase() }));
      if (field === 'engine') setVehicle((prev: any) => ({ ...prev, engine: value.toUpperCase() }));
  };

  return (
    <div className="space-y-6 animate-fade-in relative">
      {/* Loading Overlay */}
      {loading && loadingType === 'STNK' && <ScannerOverlay label="Neural STNK Decryption" />}

      {/* STNK Express Button */}
      <label className="block w-full p-1 bg-gradient-to-r from-emerald-500 to-teal-500 rounded-[2rem] cursor-pointer shadow-lg hover:shadow-emerald-500/20 hover:scale-[1.01] transition-all active:scale-95 group">
         <div className="bg-white dark:bg-black/20 rounded-[1.9rem] p-4 flex items-center justify-between">
            <div className="flex items-center gap-4">
                <div className="w-12 h-12 bg-emerald-500/10 rounded-2xl flex items-center justify-center text-emerald-500 group-hover:bg-emerald-500 group-hover:text-white transition-colors">
                    <FileSearch size={24}/>
                </div>
                <div>
                    <h4 className="text-sm font-black uppercase tracking-tight text-gray-900 dark:text-white">Autofill with STNK</h4>
                    <p className="text-[0.55rem] font-bold text-gray-500 dark:text-emerald-100 uppercase tracking-widest flex items-center gap-1"><Sparkles size={10}/> AI Vision Extraction</p>
                </div>
            </div>
            <div className="px-4 py-2 bg-emerald-500 text-white rounded-xl text-[0.6rem] font-black uppercase tracking-widest group-hover:bg-emerald-600 transition-colors">
                Upload
            </div>
         </div>
         <input type="file" accept="image/*" className="hidden" onChange={handleStnkAutofill} />
      </label>

      {/* Extracted Info Visual Feedback & Edit Form */}
      {extractedStnk && (
        <div className="animate-pop-in bg-white dark:bg-white/5 border border-emerald-500/20 rounded-[2rem] p-6 shadow-xl relative overflow-hidden">
           <div className="absolute top-0 right-0 p-4 opacity-10 pointer-events-none"><FileSearch size={120} className="rotate-12"/></div>
           <div className="flex items-center gap-3 mb-6">
              <CheckCircle2 size={24} className="text-emerald-500 flex-shrink-0"/>
              <div>
                 <p className="text-lg font-black text-gray-900 dark:text-white uppercase tracking-tighter leading-none">Neural Scan Complete</p>
                 <p className="text-[0.55rem] font-bold text-gray-400 uppercase tracking-widest">Verify & Edit Extracted Data</p>
              </div>
              <button onClick={() => setExtractedStnk(null)} className="ml-auto p-2 bg-gray-100 dark:bg-white/10 rounded-full hover:bg-rose-500 hover:text-white transition-all"><RefreshCw size={14}/></button>
           </div>

           <div className="grid grid-cols-1 md:grid-cols-2 gap-4 relative z-10">
              {/* Primary Identity */}
              <div className="space-y-1">
                 <label className="text-[0.5rem] font-black uppercase text-gray-400 ml-1">Nama Pemilik (STNK)</label>
                 <input 
                    value={extractedStnk.ownerName} 
                    onChange={(e) => handleStnkEdit('ownerName', e.target.value)}
                    className="w-full px-4 py-3 bg-gray-50 dark:bg-black/20 border border-black/5 dark:border-white/10 rounded-xl text-xs font-bold uppercase focus:border-emerald-500 outline-none"
                 />
              </div>
              <div className="space-y-1">
                 <label className="text-[0.5rem] font-black uppercase text-gray-400 ml-1">Warna Kendaraan</label>
                 <input 
                    value={extractedStnk.color} 
                    onChange={(e) => handleStnkEdit('color', e.target.value)}
                    className="w-full px-4 py-3 bg-gray-50 dark:bg-black/20 border border-black/5 dark:border-white/10 rounded-xl text-xs font-bold uppercase focus:border-emerald-500 outline-none"
                 />
              </div>
           </div>
        </div>
      )}

      <div className="flex bg-gray-100 dark:bg-white/[0.03] p-1 rounded-[1.8rem] border border-black/5 dark:border-white/5">
         <button 
           onClick={() => setEntryMode('DATABASE')}
           className={`flex-1 py-3.5 rounded-[1.5rem] text-[0.65rem] font-black uppercase tracking-widest transition-all flex items-center justify-center gap-2 ${entryMode === 'DATABASE' ? 'bg-white dark:bg-gray-800 shadow-xl text-primary-500' : 'text-gray-400'}`}
         >
           <Database size={16}/> Neural Database
         </button>
         <button 
           onClick={() => { setEntryMode('MANUAL'); setVehicle((v: any) => ({ ...v, brand: '', model: '', basePrice: 0 })); }}
           className={`flex-1 py-3.5 rounded-[1.5rem] text-[0.65rem] font-black uppercase tracking-widest transition-all flex items-center justify-center gap-2 ${entryMode === 'MANUAL' ? 'bg-white dark:bg-gray-800 shadow-xl text-primary-500' : 'text-gray-400'}`}
         >
           <Edit3 size={16}/> Manual Registry
         </button>
      </div>

      <div className="space-y-5">
        <div className="grid grid-cols-1 md:grid-cols-2 gap-5">
          <div className="space-y-2">
            <label className="text-[0.6rem] font-black uppercase text-gray-500 ml-2 tracking-[0.2em]">Merk Kendaraan</label>
            {entryMode === 'DATABASE' ? (
                <div className="relative group">
                    <select 
                        className="w-full p-5 rounded-[1.8rem] bg-white dark:bg-white/[0.03] border-2 border-black/5 dark:border-white/5 outline-none focus:border-primary-500 font-black text-sm appearance-none transition-all cursor-pointer group-hover:border-black/10 text-primary-500"
                        value={vehicle.brand}
                        onChange={(e) => {
                            const val = e.target.value;
                            const unit = CAR_DATABASE.find(c => c.brand === val);
                            const p = (unit?.yearPrices[2024] || 0) * 1000000;
                            setVehicle({...vehicle, brand: val, model: unit?.modelName || '', price: p, basePrice: p});
                        }}
                    >
                        <option value="">Pilih Merk</option>
                        {Array.from(new Set(CAR_DATABASE.map(c => c.brand))).sort().map(b => <option key={b} value={b}>{b}</option>)}
                    </select>
                    <div className="absolute right-5 top-1/2 -translate-y-1/2 pointer-events-none text-gray-400">
                        <ChevronDown size={20}/>
                    </div>
                </div>
            ) : (
                <input 
                    placeholder="Contoh: Toyota"
                    value={vehicle.brand}
                    className="w-full p-5 rounded-[1.8rem] bg-white dark:bg-white/[0.03] border-2 border-black/5 dark:border-white/5 outline-none focus:border-primary-500 font-black text-sm transition-all text-primary-500 uppercase"
                    onChange={(e) => setVehicle({...vehicle, brand: e.target.value.toUpperCase()})}
                />
            )}
          </div>

          <div className="space-y-2">
            <label className="text-[0.6rem] font-black uppercase text-gray-500 ml-2 tracking-[0.2em]">Tipe Model</label>
            <input 
              readOnly={entryMode === 'DATABASE' && !vehicle.brand}
              placeholder={entryMode === 'DATABASE' ? (vehicle.brand ? `Model ${vehicle.brand}` : "Pilih Merk") : "Contoh: Avanza G"}
              value={vehicle.model}
              className={`w-full p-5 rounded-[1.8rem] bg-white dark:bg-white/[0.03] border-2 border-black/5 dark:border-white/5 outline-none focus:border-primary-500 font-black text-sm transition-all ${entryMode === 'DATABASE' ? 'bg-gray-50 dark:bg-black/20 text-gray-400' : 'text-primary-500 uppercase'}`}
              onChange={(e) => setVehicle({...vehicle, model: e.target.value.toUpperCase()})}
            />
          </div>
        </div>

        <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-6">
          <div className="space-y-2">
            <label className="text-[0.6rem] font-black uppercase text-gray-500 ml-2 tracking-widest">Tahun</label>
            <div className="relative group">
                <select 
