                   <span className="text-[0.45rem] font-bold text-emerald-500 uppercase tracking-widest">OJK Protected</span>
                </div>
             </div>

             {/* Action Buttons */}
             <div className="flex items-center gap-3">
                {step > 0 && (
                   <button 
                     onClick={handleBack} 
                     className="w-12 h-12 flex items-center justify-center bg-gray-50 dark:bg-white/5 rounded-2xl text-gray-400 hover:text-slate-900 dark:hover:text-white transition-all border border-black/5 active:scale-90"
                   >
                      <ChevronLeft size={20}/>
                   </button>
                )}

                {step < STEPS.length - 1 && (
                   <button 
                     onClick={handleNext} 
                     disabled={(step === 5 && (survey.score === 0 || (survey.verdict === 'MANUAL_REQUIRED' && survey.manualRequestStatus !== 'REQUESTED')))}
