      if (sortBy === 'PRICE') {
          const priceA = (premiumBreakdown?.netPremium || 0) + a.adminFee;
          const priceB = (premiumBreakdown?.netPremium || 0) + b.adminFee;
          return priceA - priceB;
      }
      return 0;
    });
