            <button key={item.id} onClick={() => setPage(item.id)} className={`flex flex-col items-center gap-1.5 flex-1 py-3 transition-all duration-300 tap-feedback ${currentPage === item.id || (currentPage.startsWith('buy') && item.id === 'products') ? 'text-primary-500 scale-110 -translate-y-1' : 'text-gray-400 dark:text-gray-500'}`}>
              <item.icon size={24} className={currentPage === item.id ? 'drop-shadow-[0_0_12px_rgba(249,115,22,0.4)]' : ''} />
              <span className="text-[0.45rem] font-black uppercase tracking-[0.2em]">{item.label}</span>
            </button>
          ))}
        </nav>
      )}
    </div>
  );

  if (!isMobile && (currentUser || appMode)) {
    return (
      <div className="min-h-screen bg-[#0c0a09] flex items-center justify-center p-12 overflow-hidden relative transition-all duration-1000 ease-in-out">
        <div className="absolute inset-0 bg-neural-mesh opacity-100"></div>
        <div className="relative w-[440px] h-[880px] bg-white rounded-[5rem] border-[14px] border-[#1c1917] shadow-[0_60px_120px_-30px_rgba(0,0,0,0.6)] ring-[1px] ring-white/10 overflow-hidden group transition-all duration-700">
          <div className="h-full w-full overflow-hidden rounded-[3.8rem]"><AppWrapper /></div>
        </div>
      </div>
    );
  }

  return <AppWrapper />;
};

