                   <p className="text-sm font-black text-gray-900 dark:text-white">{formatIDR(premiumBreakdown.remainingCommission)}</p>
                </div>
                <div className="p-3 bg-emerald-500/5 rounded-2xl border border-emerald-500/10 text-center">
                   <p className="text-[0.45rem] font-bold text-emerald-600 dark:text-emerald-400 uppercase tracking-widest mb-1 flex items-center justify-center gap-1"><ArrowDown size={10}/> Customer Saves</p>
                   <p className="text-sm font-black text-emerald-500">{formatIDR(premiumBreakdown.discountAmount)}</p>
                </div>
             </div>
          )}
       </div>
    </div>
  );
};

