const App = () => {
  const [isLoaded, setIsLoaded] = useState(false);
  const [isMobile, setIsMobile] = useState(window.innerWidth < 1024);
  const [currentPage, setPage] = useState('home');
  const [currentUser, setCurrentUser] = useState<any>(null);
  const [darkMode, setDarkMode] = useState(false);
  const [appMode, setAppMode] = useState(false); 
  const [lang, setLang] = useState<Language>(Language.EN);

  useEffect(() => {
    const saved = localStorage.getItem('SUREPATH_SESSION');
    if (saved) { setCurrentUser(JSON.parse(saved)); setAppMode(true); }
    const handleResize = () => setIsMobile(window.innerWidth < 1024);
    window.addEventListener('resize', handleResize);
    return () => window.removeEventListener('resize', handleResize);
  }, []);

  if (!isLoaded) return <WelcomeScreen onFinish={() => setIsLoaded(true)} />;

  const handleLogout = () => {
    setCurrentUser(null);
    localStorage.removeItem('SUREPATH_SESSION');
    setAppMode(false);
    setPage('home');
  };

  if (!isMobile && !appMode && !currentUser) {
    return <DesktopWebsite onEnterPortal={() => setAppMode(true)} onAdminAccess={() => setAppMode(true)} currentLang={lang} onLangChange={setLang} />;
  }

  if (!currentUser && (isMobile || appMode)) {
    return <AuthGate onAuthSuccess={(u) => { setCurrentUser(u); setAppMode(true); }} initialLang={lang} />;
  }

  const isAgent = currentUser?.role === UserRole.AGENT;
  const isAdmin = [UserRole.ADMIN, UserRole.MASTER_ADMIN].includes(currentUser?.role);

