const PRODUCTS = [
  { id: 'car', label: 'Car Insurance', icon: BotCar, color: 'text-blue-500', bg: 'bg-blue-50', sub: 'Comprehensive' },
  { id: 'travel', label: 'Travel Matrix', icon: BotPlane, color: 'text-emerald-500', bg: 'bg-emerald-50', sub: 'Worldwide' },
  { id: 'pa', label: 'Personal Safety', icon: BotShield, color: 'text-rose-500', bg: 'bg-rose-50', sub: 'Accident Guard' },
  { id: 'mpar', label: 'Asset Shield', icon: BotBox, color: 'text-amber-500', bg: 'bg-amber-50', sub: 'Home Belongings' },
  { id: 'health', label: 'Health Sync', icon: BotHeart, color: 'text-pink-500', bg: 'bg-pink-50', sub: 'Medical Care' }
];

const App = () => {
  const [isLoaded, setIsLoaded] = useState(false);
  const [isMobile, setIsMobile] = useState(window.innerWidth < 1024);
  const [currentPage, setPage] = useState('home');
  const [currentUser, setCurrentUser] = useState<any>(null);
  const [darkMode, setDarkMode] = useState(false);
  const [appMode, setAppMode] = useState(false); 
  const [lang, setLang] = useState<Language>(Language.EN);

  useEffect(() => {
    const savedSession = localStorage.getItem('SUREPATH_SESSION');
    if (savedSession) {
      try {
        const user = JSON.parse(savedSession);
        setCurrentUser(user);
        setAppMode(true);
      } catch (e) {
        localStorage.removeItem('SUREPATH_SESSION');
      }
    }
    const handleResize = () => setIsMobile(window.innerWidth < 1024);
    window.addEventListener('resize', handleResize);
    return () => window.removeEventListener('resize', handleResize);
  }, []);

  if (!isLoaded) return <WelcomeScreen onFinish={() => setIsLoaded(true)} />;

  const handleLogout = () => {
    setCurrentUser(null);
    localStorage.removeItem('SUREPATH_SESSION');
    setAppMode(false);
    setPage('home');
  };

  if (!isMobile && !appMode && !currentUser) {
    return <DesktopWebsite onEnterPortal={() => setAppMode(true)} onAdminAccess={() => setAppMode(true)} currentLang={lang} onLangChange={setLang} />;
  }

  if (!currentUser && (isMobile || appMode)) {
    return <AuthGate onAuthSuccess={(u) => { setCurrentUser(u); setAppMode(true); }} initialLang={lang} />;
  }

  const isAgent = currentUser?.role === UserRole.AGENT;
  const isAdmin = [UserRole.ADMIN, UserRole.MASTER_ADMIN].includes(currentUser?.role);

  if (isAdmin) return <AdminPortal onLogout={handleLogout} products={[]} setProducts={() => {}} userRole={currentUser.role} />;

  // --- RENDERING AGENT HOME ---
  const renderAgentHome = () => (
    <div className="space-y-10 pb-32 animate-pop-in">
       {/* 1. Performance Header */}
       <div className="flex justify-between items-start px-2 pt-6">
          <div className="space-y-1">
            <h2 className="text-3xl font-extrabold text-slate-900 dark:text-white tracking-tight">Partner Portal 📈</h2>
