        <div className="absolute inset-0 bg-neural-mesh opacity-30"></div>
      </div>

      <div className="relative z-10 flex flex-col items-center animate-pop-in">
        {/* Mascot Animation */}
        <div className="mb-12 relative group">
           <div className="absolute inset-0 bg-primary-500/20 rounded-full blur-[60px] animate-pulse group-hover:bg-brand-500/30 transition-colors duration-1000"></div>
           <NeuralBot className="w-48 h-48 relative drop-shadow-[0_0_30px_rgba(249,115,22,0.3)]" mood="happy" />

           {/* Floating Data Nodes */}
           <div className="absolute -top-4 -right-4 w-10 h-10 bg-white dark:bg-white/10 rounded-2xl flex items-center justify-center shadow-xl animate-float border border-black/5">
