  { id: 'PROVIDERS', label: 'Opsi' },
  { id: 'KYC', label: 'Nasabah' },
  { id: 'PRESUMMARY', label: 'Rincian' },
  { id: 'SURVEY', label: 'Audit' },
  { id: 'FINAL', label: 'Bayar' }
];

const STORAGE_KEY = 'SUREPATH_CAR_WIZARD_PROGRESS';

const CarInsuranceWizard = ({ onComplete, currentUser }: { onComplete: () => void, currentUser?: any }) => {
  const [step, setStep] = useState(0);
  const [loading, setLoading] = useState(false);
  const [loadingType, setLoadingType] = useState<'KTP' | 'STNK' | 'SURVEY' | null>(null);
  const [entryMode, setEntryMode] = useState<'DATABASE' | 'MANUAL'>('DATABASE');
  const [showBreakdown, setShowBreakdown] = useState(false);
  const [showProviderBreakdown, setShowProviderBreakdown] = useState(false);
  const [sortBy, setSortBy] = useState<'RATING' | 'PRICE'>('RATING');

  const [vehicle, setVehicle] = useState({
    brand: '', model: '', year: 2025, isOther: false, 
    price: 0, basePrice: 0, manualPrice: false, plate: '', 
    vin: '', engine: '',
    region: '3' as '1'|'2'|'3', regionName: 'Region Lainnya', usage: 'PRIVATE', condition: 'NEW'
  });

  const [coverage, setCoverage] = useState({
    type: InsuranceType.COMPREHENSIVE as InsuranceType,
    flood: false, earthquake: false, srcc: false, 
    terrorism: false, authorized: false, 
    tpl: 0, paDriver: false, paPassenger: false,
    promo: '', discount: 0, discountType: 'NOMINAL' as 'NOMINAL' | 'PERCENT'
  });

  const [selectedProviderId, setSelectedProviderId] = useState<string | null>(null);
  const [kycData, setKycData] = useState({ 
    name: currentUser?.name || '', 
    ktp: currentUser?.ktp || '', 
    address: currentUser?.address || '', 
    email: currentUser?.email || '', 
    phone: currentUser?.phone || '', 
    photo: null as string|null 
  });
  const [verifiedFields, setVerifiedFields] = useState<Set<string>>(new Set());

  const [stnkResult, setStnkResult] = useState({
    ownerName: '',
    plate: '',
    vin: '',
    engine: '',
    color: '',
    year: '',
    status: ''
  });

  const [survey, setSurvey] = useState({ 
    stnk: null as string|null, 
    photos: {} as Record<string, string>, 
    score: 0, 
    summary: '',
    underwritingReport: '',
    detailedIssues: [] as DamageIssue[], 
    photoFlags: [] as PhotoFlag[],
    verdict: '' as 'CLEAN' | 'REVIEW_REQUIRED' | 'REJECTED' | 'MANUAL_REQUIRED' | '',
    rejectionReason: '',
    manualVerif: false, 
    manualRequestStatus: 'NONE' as 'NONE' | 'REQUESTED',
    manualDate: '',
    manualType: 'VIDEO' as 'VIDEO' | 'PHYSICAL',
    accessories: '' 
  });

  const [photoValidation, setPhotoValidation] = useState<Record<string, { status: 'LOADING' | 'VALID' | 'INVALID', msg?: string }>>({});

  useEffect(() => {
    const saved = localStorage.getItem(STORAGE_KEY);
    if (saved) {
      try {
        const data = JSON.parse(saved);
        if (data.step !== undefined) setStep(data.step);
        if (data.vehicle) setVehicle(data.vehicle);
        if (data.coverage) setCoverage(data.coverage);
        if (data.selectedProviderId) setSelectedProviderId(data.selectedProviderId);
        if (data.kycData) setKycData(data.kycData);
        if (data.survey) setSurvey(data.survey);
        if (data.stnkResult) setStnkResult(data.stnkResult);
      } catch (err) {}
    }
  }, []);

  useEffect(() => {
    const timer = setTimeout(() => {
      const stateToSave = { step, vehicle, coverage, selectedProviderId, kycData, survey, stnkResult };
      try { localStorage.setItem(STORAGE_KEY, JSON.stringify(stateToSave)); } catch (err) {}
    }, 1000); 
    return () => clearTimeout(timer);
  }, [step, vehicle, coverage, selectedProviderId, kycData, survey, stnkResult]);

  const clearProgress = () => { localStorage.removeItem(STORAGE_KEY); };

  useEffect(() => {
    if (vehicle.condition === 'NEW') { setVehicle(prev => ({ ...prev, year: 2025 })); }
  }, [vehicle.condition]);

  const selectedProvider = useMemo(() => INSURANCE_PROVIDERS.find(p => p.id === selectedProviderId), [selectedProviderId]);

  const premiumBreakdown = useMemo(() => {
    if (!vehicle.price) return null;
    const baseRate = getOJKRate(vehicle.price / 1000000, vehicle.region, coverage.type);
    const basicPremium = (vehicle.price * baseRate) / 100;
    const expansions = [];
    if (coverage.authorized) expansions.push({ name: 'Bengkel Resmi (Authorized)', val: (vehicle.price * AUTHORIZED_WORKSHOP_RATE) / 100, rate: AUTHORIZED_WORKSHOP_RATE });
    if (coverage.flood) expansions.push({ name: 'Banjir & Angin Ribut', val: (vehicle.price * EXPANSION_RATES.FLOOD) / 100, rate: EXPANSION_RATES.FLOOD });
    if (coverage.earthquake) expansions.push({ name: 'Gempa & Tsunami', val: (vehicle.price * EXPANSION_RATES.EARTHQUAKE) / 100, rate: EXPANSION_RATES.EARTHQUAKE });
    const srccRate = coverage.type === InsuranceType.COMPREHENSIVE ? EXPANSION_RATES.SRCC.COMPREHENSIVE : EXPANSION_RATES.SRCC.TLO;
    if (coverage.srcc) expansions.push({ name: 'SRCC (Kerusuhan)', val: (vehicle.price * srccRate) / 100, rate: srccRate });
    const tsRate = coverage.type === InsuranceType.COMPREHENSIVE ? EXPANSION_RATES.TERRORISM.COMPREHENSIVE : EXPANSION_RATES.TERRORISM.TLO;
    if (coverage.terrorism) expansions.push({ name: 'Terorisme & Sabotase', val: (vehicle.price * tsRate) / 100, rate: tsRate });
    const tplPremium = (coverage.tpl / 100); 
    const expansionTotal = expansions.reduce((acc: number, curr: any) => acc + curr.val, 0) + tplPremium;
    const grossPremium = basicPremium + expansionTotal;
    const discountPercent = Math.min(coverage.discount || 0, 25);
    const discountAmount = grossPremium * (discountPercent / 100);
    const netPremium = grossPremium - discountAmount;
    const standardCommission = grossPremium * 0.25;
    const remainingCommission = Math.max(0, standardCommission - discountAmount);
    return {
        baseRate, basicPremium, expansions, tplPremium, grossPremium, discountPercent, discountAmount,
        standardCommission, remainingCommission, adminFee: selectedProvider?.adminFee || 0, stampDuty: STAMP_DUTY,
        netPremium, totalPayable: netPremium + (selectedProvider?.adminFee || 0) + STAMP_DUTY
    };
  }, [vehicle, coverage, selectedProvider]);

  const sortedProviders = useMemo(() => {
    return [...INSURANCE_PROVIDERS].sort((a, b) => {
      if (sortBy === 'RATING') return b.rating - a.rating;
      if (sortBy === 'PRICE') {
          const priceA = (premiumBreakdown?.netPremium || 0) + a.adminFee;
          const priceB = (premiumBreakdown?.netPremium || 0) + b.adminFee;
          return priceA - priceB;
      }
      return 0;
    });
  }, [sortBy, premiumBreakdown]);

  const handleNext = () => setStep(s => Math.min(s + 1, STEPS.length - 1));
  const handleBack = () => setStep(s => Math.max(s - 1, 0));

  const formatInputCurrency = (value: string) => {
    const numeric = value.replace(/\D/g, "");
    if (!numeric) return "";
    return new Intl.NumberFormat('id-ID').format(parseInt(numeric));
  };

  const handlePlateChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    let val = e.target.value.toUpperCase().replace(/[^A-Z0-9]/g, "");
    const parts = val.match(/^([A-Z]{1,2})([0-9]{0,4})([A-Z]{0,3})$/);
    if (parts) {
      const plate = `${parts[1]}${parts[2] ? ' ' + parts[2] : ''}${parts[3] ? ' ' + parts[3] : ''}`;
      const prefix = parts[1];
      const regionInfo = PLATE_REGIONS[prefix];
      setVehicle({ ...vehicle, plate, region: regionInfo?.region || '3', regionName: regionInfo ? `${regionInfo.name} (Region ${regionInfo.region})` : 'Region 3 (Lainnya)' });
    } else { setVehicle({...vehicle, plate: val}); }
  };

  const handleFinalPayment = async () => {
    if (!currentUser || !premiumBreakdown) return;
    try {
      const isManualPending = survey.verdict === 'MANUAL_REQUIRED' || survey.manualRequestStatus === 'REQUESTED';
      const newPolicy: Policy = {
        userId: currentUser.id, type: 'CAR', status: isManualPending ? 'PENDING' : 'ACTIVE',
        startDate: new Date().toISOString(), endDate: new Date(new Date().setFullYear(new Date().getFullYear() + 1)).toISOString(),
        premium: premiumBreakdown.totalPayable, providerId: selectedProviderId || '', policyNumber: `POL-CR-${Date.now()}`,
        createdAt: new Date().toISOString(), coverageDetails: { vehicle: { ...vehicle, ...stnkResult }, coverage, survey, financials: premiumBreakdown }
      };
      const policyId = await db.policies.add(newPolicy);
      await db.transactions.add({
        userId: currentUser.id, type: 'PAYMENT', amount: premiumBreakdown.totalPayable, status: isManualPending ? 'PENDING' : 'SUCCESS',
        description: `Payment for Policy ${newPolicy.policyNumber}`, date: new Date().toISOString(), referenceId: policyId.toString()
      });
      clearProgress();
      onComplete();
    } catch (e) { alert("Gagal memproses pembayaran. Coba lagi."); }
  };

  return (
    <div className="flex flex-col h-full min-h-screen bg-[#f0faf7] dark:bg-[#050505] text-gray-900 dark:text-white overflow-hidden relative selection:bg-primary-100">
       {/* HEADER SECTION */}
       <div className="px-6 pt-6 pb-4 bg-white/80 dark:bg-black/40 backdrop-blur-xl border-b border-gray-100 dark:border-white/5 flex flex-col gap-5 flex-shrink-0 relative z-[100]">
          <div className="flex items-center justify-between">
            <div className="flex items-center gap-4">
               <div className="w-12 h-12 bg-slate-900 dark:bg-white rounded-2xl flex items-center justify-center text-white dark:text-black shadow-xl group border border-white/10 transition-transform hover:scale-105 active:scale-95">
                  <Car size={24} className="group-hover:rotate-12 transition-transform text-primary-500"/>
               </div>
               <div>
                  <h3 className="text-lg font-black uppercase tracking-tighter leading-none">Sure<span className="text-primary-500">Path</span> <span className="text-gray-400 dark:text-gray-500">Auto</span></h3>
                  <p className="text-[0.45rem] font-bold text-gray-400 uppercase tracking-[0.3em] mt-1.5">Penerbitan Polis AI v4.0</p>
               </div>
            </div>
            <div className="flex items-center gap-2">
               <button 
                onClick={() => { if(confirm("Mulai ulang dari awal?")) { clearProgress(); window.location.reload(); } }} 
                className="p-2.5 text-gray-400 hover:text-rose-500 bg-gray-50 dark:bg-white/5 rounded-xl transition-all border border-black/5"
               >
                  <RefreshCw size={18}/>
               </button>
               <button onClick={onComplete} className="p-2.5 text-gray-400 hover:text-gray-900 dark:hover:text-white bg-gray-50 dark:bg-white/5 rounded-xl transition-all border border-black/5">
                 <X size={20}/>
               </button>
            </div>
          </div>

          <div className="flex items-center justify-between">
             <div className="flex items-center gap-2 bg-gray-100 dark:bg-white/5 px-3 py-1.5 rounded-lg border border-black/5">
                <span className="text-[0.55rem] font-black text-primary-500 uppercase tracking-widest">{STEPS[step].label}</span>
             </div>
             <p className="text-[0.5rem] font-black text-gray-400 uppercase tracking-[0.2em]">Siklus {step + 1} dari {STEPS.length}</p>
          </div>

          <div className="flex gap-1.5">
             {STEPS.map((s, i) => (
               <div key={i} className={`h-1 rounded-full flex-1 transition-all duration-700 ${i === step ? 'bg-primary-500 shadow-[0_0_10px_#10b981]' : i < step ? 'bg-primary-500/30' : 'bg-gray-100 dark:bg-white/10'}`}></div>
             ))}
          </div>
       </div>

       {/* MAIN CONTENT AREA */}
       <div className="flex-1 overflow-y-auto px-6 py-8 no-scrollbar relative z-10">
          <div className="max-w-xl mx-auto">
            {step === 0 && (
                <StepVehicle 
                    vehicle={vehicle} setVehicle={setVehicle} 
                    entryMode={entryMode} setEntryMode={setEntryMode} 
                    handlePlateChange={handlePlateChange} formatInputCurrency={formatInputCurrency} 
                    loading={loading} setLoading={setLoading}
                    loadingType={loadingType} setLoadingType={setLoadingType}
                    setStnkResult={setStnkResult}
                />
            )}
            {step === 1 && (
                <StepCoverage 
                    coverage={coverage} 
                    setCoverage={setCoverage} 
                    premiumBreakdown={premiumBreakdown} 
                />
            )}
            {step === 2 && (
                <StepProviders 
                    sortBy={sortBy} setSortBy={setSortBy} 
                    sortedProviders={sortedProviders} selectedProviderId={selectedProviderId} 
                    setSelectedProviderId={setSelectedProviderId} premiumBreakdown={premiumBreakdown} 
                    showProviderBreakdown={showProviderBreakdown} setShowProviderBreakdown={setShowProviderBreakdown} 
                />
            )}
            {step === 3 && (
                <StepKYC 
                    kycData={kycData} setKycData={setKycData} 
                    loading={loading} setLoading={setLoading} 
                    loadingType={loadingType} setLoadingType={setLoadingType} 
                    verifiedFields={verifiedFields} setVerifiedFields={setVerifiedFields} 
                />
            )}
            {step === 4 && (
                <StepPreSummary 
                    vehicle={vehicle} 
                    coverage={coverage} 
                    premiumBreakdown={premiumBreakdown} 
                    showBreakdown={showBreakdown} 
                    setShowBreakdown={setShowBreakdown}
                    stnkResult={stnkResult}
                    kycData={kycData}
                />
            )}
            {step === 5 && (
                <StepSurvey 
                    survey={survey} setSurvey={setSurvey} 
                    stnkResult={stnkResult} setStnkResult={setStnkResult} 
                    loading={loading} setLoading={setLoading} 
                    loadingType={loadingType} setLoadingType={setLoadingType} 
                    photoValidation={photoValidation} setPhotoValidation={setPhotoValidation} 
                    vehicle={vehicle} 
                />
            )}
            {step === 6 && (
                <StepFinal 
                    vehicle={vehicle} stnkResult={stnkResult} 
                    coverage={coverage} survey={survey} 
                    premiumBreakdown={premiumBreakdown} handleFinalPayment={handleFinalPayment} 
                    setStep={setStep} 
                />
            )}
          </div>
       </div>

       {/* REVAMPED FOOTER: Mobile Friendly & Friendly UI */}
       <div className="px-6 py-6 bg-white/95 dark:bg-[#0a0a0a]/95 backdrop-blur-2xl border-t border-gray-100 dark:border-white/5 sticky bottom-0 z-[100] shadow-[0_-15px_40px_rgba(0,0,0,0.04)] animate-slide-up">
          <div className="max-w-xl mx-auto flex items-center justify-between gap-6">
             {/* Dynamic Price Display */}
             <div className="flex flex-col gap-0.5">
                <div className="flex items-center gap-1.5">
                   <Zap size={10} className="text-primary-500 fill-primary-500"/>
                   <span className="text-[0.5rem] font-black uppercase text-gray-400 tracking-[0.2em]">Estimasi Premi</span>
                </div>
                <p className="text-2xl font-black tracking-tight text-slate-900 dark:text-white leading-none">
                   {premiumBreakdown ? formatIDR(premiumBreakdown.totalPayable) : 'Rp 0'}
                </p>
                <div className="flex items-center gap-1.5 mt-1.5">
                   <ShieldCheck size={10} className="text-emerald-500"/>
                   <span className="text-[0.45rem] font-bold text-emerald-500 uppercase tracking-widest">OJK Protected</span>
                </div>
             </div>

             {/* Action Buttons */}
             <div className="flex items-center gap-3">
                {step > 0 && (
                   <button 
                     onClick={handleBack} 
                     className="w-12 h-12 flex items-center justify-center bg-gray-50 dark:bg-white/5 rounded-2xl text-gray-400 hover:text-slate-900 dark:hover:text-white transition-all border border-black/5 active:scale-90"
                   >
                      <ChevronLeft size={20}/>
                   </button>
                )}

                {step < STEPS.length - 1 && (
                   <button 
                     onClick={handleNext} 
                     disabled={(step === 5 && (survey.score === 0 || (survey.verdict === 'MANUAL_REQUIRED' && survey.manualRequestStatus !== 'REQUESTED')))}
                     className="h-14 px-8 bg-slate-900 dark:bg-white text-white dark:text-black rounded-2xl font-black uppercase text-[0.65rem] tracking-[0.2em] shadow-xl shadow-slate-900/10 dark:shadow-white/5 transition-all active:scale-95 flex items-center justify-center gap-3 disabled:opacity-30 disabled:grayscale group"
                   >
                     {step === 5 ? (survey.manualVerif ? 'Submisi HQ' : 'Audit Selesai') : 'Lanjut'} 
                     <ChevronRight size={16} className="group-hover:translate-x-0.5 transition-transform"/>
                   </button>
                )}

                {step === STEPS.length - 1 && (
                   <button 
                     onClick={handleFinalPayment}
                     className="h-14 px-8 bg-primary-500 text-white rounded-2xl font-black uppercase text-[0.65rem] tracking-[0.2em] shadow-xl shadow-primary-500/20 transition-all active:scale-95 flex items-center justify-center gap-3 group"
                   >
                     Aktivasi Polis 
                     <Zap size={16} className="fill-white animate-pulse"/>
                   </button>
                )}
             </div>
          </div>
       </div>

       {/* Mobile-only Bottom Safety Spacing for Modern Devices */}
       <div className="h-6 bg-white dark:bg-[#0a0a0a] border-t border-gray-100 dark:border-white/5 lg:hidden"></div>
    </div>
  );
};

export default CarInsuranceWizard;

import React, { useState } from 'react';
import { 
  CreditCard, Wallet, Smartphone, Landmark, Check, 
  ChevronRight, Lock, ShieldCheck, Zap, ArrowRight,
  Clock, Copy, AlertCircle, Loader2
} from 'lucide-react';
import { formatIDR } from './WizardUI';

interface StepPaymentProps {
  premiumBreakdown: any;
  onPaymentSuccess: (method: string) => void;
  loading: boolean;
}

const StepPayment: React.FC<StepPaymentProps> = ({ premiumBreakdown, onPaymentSuccess, loading }) => {
  const [method, setMethod] = useState<'VA' | 'EWALLET' | 'CC' | null>(null);
  const [selectedSubMethod, setSelectedSubMethod] = useState<string | null>(null);
  const [isProcessing, setIsProcessing] = useState(false);

  const handlePay = () => {
    setIsProcessing(true);
    // Simulasi delay gateway
    setTimeout(() => {
      setIsProcessing(false);
      onPaymentSuccess(selectedSubMethod || 'Xendit Gateway');
    }, 2500);
  };

  const vaBanks = [
    { id: 'BCA', name: 'BCA Virtual Account', icon: 'https://upload.wikimedia.org/wikipedia/commons/5/5c/Logo_BCA.svg' },
    { id: 'MANDIRI', name: 'Mandiri Virtual Account', icon: 'https://upload.wikimedia.org/wikipedia/id/f/fa/Bank_Mandiri_logo.svg' },
    { id: 'BNI', name: 'BNI Virtual Account', icon: 'https://upload.wikimedia.org/wikipedia/id/5/55/BNI_logo.svg' }
  ];

  const eWallets = [
    { id: 'OVO', name: 'OVO', icon: 'https://upload.wikimedia.org/wikipedia/commons/e/eb/Logo_ovo_purple.svg' },
    { id: 'DANA', name: 'DANA', icon: 'https://upload.wikimedia.org/wikipedia/commons/7/72/Logo_dana_blue.svg' },
    { id: 'SHOPEEPAY', name: 'ShopeePay', icon: 'https://upload.wikimedia.org/wikipedia/commons/b/be/ShopeePay.svg' }
  ];

  return (
    <div className="space-y-6 animate-fade-in pb-20">
      {/* Header Xendit-style */}
      <div className="bg-white dark:bg-white/5 rounded-[2.5rem] border border-black/5 dark:border-white/5 p-8 shadow-xl relative overflow-hidden">
         <div className="absolute top-0 left-0 w-full h-1 bg-gradient-to-r from-blue-500 via-indigo-500 to-purple-500"></div>
         <div className="flex justify-between items-start mb-8">
            <div className="space-y-1">
               <p className="text-[0.6rem] font-black text-gray-400 uppercase tracking-widest">Total Tagihan</p>
               <h3 className="text-4xl font-black text-primary-500 tracking-tighter">{formatIDR(premiumBreakdown?.totalPayable || 0)}</h3>
            </div>
            <div className="flex flex-col items-end">
               <div className="flex items-center gap-2 px-3 py-1 bg-blue-500/10 text-blue-500 rounded-full mb-2">
                  <Lock size={12}/>
                  <span className="text-[0.5rem] font-black uppercase tracking-widest">Secure Checkout</span>
               </div>
               <p className="text-[0.5rem] font-bold text-gray-400 uppercase">Order ID: SP-{Date.now().toString().slice(-6)}</p>
            </div>
         </div>

         {/* Payment Methods Grid */}
         <div className="grid grid-cols-3 gap-3">
            <button 
               onClick={() => { setMethod('VA'); setSelectedSubMethod(null); }}
               className={`p-4 rounded-2xl border-2 flex flex-col items-center gap-2 transition-all ${method === 'VA' ? 'border-primary-500 bg-primary-500/5 text-primary-600' : 'border-black/5 text-gray-400 hover:border-black/10'}`}
            >
               <Landmark size={24}/>
               <span className="text-[0.55rem] font-black uppercase tracking-widest">Bank VA</span>
            </button>
            <button 
               onClick={() => { setMethod('EWALLET'); setSelectedSubMethod(null); }}
               className={`p-4 rounded-2xl border-2 flex flex-col items-center gap-2 transition-all ${method === 'EWALLET' ? 'border-primary-500 bg-primary-500/5 text-primary-600' : 'border-black/5 text-gray-400 hover:border-black/10'}`}
            >
               <Smartphone size={24}/>
               <span className="text-[0.55rem] font-black uppercase tracking-widest">E-Wallet</span>
            </button>
            <button 
               onClick={() => { setMethod('CC'); setSelectedSubMethod('Credit Card'); }}
               className={`p-4 rounded-2xl border-2 flex flex-col items-center gap-2 transition-all ${method === 'CC' ? 'border-primary-500 bg-primary-500/5 text-primary-600' : 'border-black/5 text-gray-400 hover:border-black/10'}`}
            >
               <CreditCard size={24}/>
               <span className="text-[0.55rem] font-black uppercase tracking-widest">Card</span>
            </button>
         </div>
      </div>

      {/* Method Details */}
      <div className="animate-fade-in min-h-[200px]">
         {method === 'VA' && (
            <div className="space-y-3">
               <p className="text-[0.6rem] font-black text-gray-400 ml-4 uppercase tracking-widest">Pilih Bank</p>
               {vaBanks.map(bank => (
                  <button 
                     key={bank.id}
                     onClick={() => setSelectedSubMethod(bank.name)}
                     className={`w-full p-5 bg-white dark:bg-white/5 rounded-[2rem] border-2 transition-all flex items-center justify-between group ${selectedSubMethod === bank.name ? 'border-primary-500 shadow-lg' : 'border-black/5'}`}
                  >
                     <div className="flex items-center gap-4">
                        <img src={bank.icon} className="h-4 w-auto grayscale group-hover:grayscale-0 transition-all" alt={bank.name} />
                        <span className="text-sm font-black uppercase tracking-tight text-gray-700 dark:text-gray-200">{bank.name}</span>
                     </div>
                     {selectedSubMethod === bank.name && <Check className="text-primary-500" size={20} strokeWidth={4}/>}
                  </button>
               ))}
            </div>
         )}

         {method === 'EWALLET' && (
            <div className="grid grid-cols-1 gap-3">
               <p className="text-[0.6rem] font-black text-gray-400 ml-4 uppercase tracking-widest">Pilih Dompet Digital</p>
               {eWallets.map(wallet => (
                  <button 
                     key={wallet.id}
                     onClick={() => setSelectedSubMethod(wallet.name)}
                     className={`p-5 bg-white dark:bg-white/5 rounded-[2rem] border-2 transition-all flex items-center justify-between group ${selectedSubMethod === wallet.name ? 'border-primary-500 shadow-lg' : 'border-black/5'}`}
                  >
                     <div className="flex items-center gap-4">
                        <img src={wallet.icon} className="h-6 w-auto" alt={wallet.name} />
                        <span className="text-sm font-black uppercase tracking-tight text-gray-700 dark:text-gray-200">{wallet.name}</span>
                     </div>
                     {selectedSubMethod === wallet.name && <Check className="text-primary-500" size={20} strokeWidth={4}/>}
                  </button>
               ))}
            </div>
         )}

         {method === 'CC' && (
            <div className="p-8 bg-white dark:bg-white/5 rounded-[3rem] border-2 border-primary-500/20 space-y-6">
               <div className="flex justify-between items-center mb-2">
                  <h4 className="text-lg font-black uppercase tracking-tighter">Debit / Credit Card</h4>
                  <div className="flex gap-2">
                     <div className="w-8 h-5 bg-gray-100 rounded"></div>
