           <p className="text-[0.5rem] font-bold text-gray-400 uppercase leading-relaxed text-center">
              High score enables instant 60s claim payouts.
           </p>
        </div>
      </div>

      {/* Tabs Control */}
      <div className="flex bg-gray-100 dark:bg-white/5 p-1 rounded-[1.8rem] border border-black/5 dark:border-white/10 mx-2">
         {[
           { id: 'OVERVIEW', label: 'Summary', icon: LayoutGrid },
           { id: 'POLICIES', label: 'Nodes', icon: ShieldCheck },
           { id: 'CLAIMS', label: 'Claims', icon: Activity },
           { id: 'SETTINGS', label: 'Sync', icon: Settings },
         ].map(tab => (
            <button 
               key={tab.id}
               onClick={() => setActiveTab(tab.id as TabType)}
               className={`flex-1 flex flex-col items-center gap-1.5 py-3 rounded-[1.4rem] transition-all duration-300 ${activeTab === tab.id ? 'bg-white dark:bg-slate-800 shadow-xl scale-105 text-primary-500' : 'text-gray-400'}`}
            >
               <tab.icon size={18}/>
               <span className="text-[0.5rem] font-black uppercase tracking-widest">{tab.label}</span>
            </button>
         ))}
      </div>

      {/* Tab Content */}
      <div className="px-2 pb-10">
         {activeTab === 'OVERVIEW' && renderOverview()}
         {activeTab === 'POLICIES' && renderPolicies()}
         {activeTab === 'CLAIMS' && renderClaims()}
         {activeTab === 'SETTINGS' && renderSettings()}
      </div>

      <div className="px-6">
        <button className="w-full py-6 bg-rose-500/10 text-rose-500 rounded-[2.5rem] border border-rose-500/20 font-black uppercase text-xs tracking-[0.2em] flex items-center justify-center gap-3 active:scale-95 transition-all">
           <LogOut size={18}/> Global Log Out
        </button>
      </div>
    </div>
  );
};

