                      </div>
                   </div>
                   <div className="px-3 py-1 bg-white dark:bg-white/10 rounded-full border border-black/5 dark:border-white/5 shadow-sm">
                      <span className="text-[0.5rem] font-bold text-primary-500 uppercase tracking-widest">Gold Tier</span>
                   </div>
                </div>
                <div className="grid grid-cols-2 gap-4">
                  <div onClick={() => setPage('products')} className="p-8 bg-white dark:bg-white/5 rounded-[2.8rem] border border-gray-200/50 shadow-xl cursor-pointer group overflow-hidden relative">
