import React, { useState, useMemo, useEffect } from 'react';
import { Camera, BrainCircuit, CheckCircle2, Scan, Smartphone, ArrowRight, MapPin, Calendar, Clock, FileText, AlertCircle, Loader2, FileSearch, Trash2, ShieldCheck, ChevronRight, Info, Rocket, Users } from 'lucide-react';
import { analyzeClaimPhoto, summarizeClaimDocument, ClaimAnalysisData, DocumentSummary } from '../services/geminiService';
import { db, Claim } from '../db';
import { NeuralBot, NeuralProcessingView } from './car-wizard/WizardUI';

const formatIDR = (num: number) => {
  return new Intl.NumberFormat('id-ID', {
    style: 'currency', currency: 'IDR', minimumFractionDigits: 0
  }).format(num);
};

interface ReportForm {
  chronology: string;
  location: string;
  date: string;
  time: string;
  thirdPartyInvolved: boolean;
}

const ClaimManager = ({ onComplete }: { onComplete: () => void }) => {
  const [step, setStep] = useState<'upload' | 'analyzing' | 'result' | 'docUpload' | 'docSummary' | 'reporting' | 'success'>('upload');
  const [claimResult, setClaimResult] = useState<ClaimAnalysisData | null>(null);
  const [docSummary, setDocSummary] = useState<DocumentSummary | null>(null);
  const [isSummarizing, setIsSummarizing] = useState(false);
  const [activeTab, setActiveTab] = useState<'evidence' | 'reasoning' | 'steps'>('evidence');
  const [currentUser, setCurrentUser] = useState<any>(null);
  const [photoBase64, setPhotoBase64] = useState<string>('');

  useEffect(() => {
    const saved = localStorage.getItem('SUREPATH_SESSION');
    if (saved) setCurrentUser(JSON.parse(saved));
  }, []);

  const [reportForm, setReportForm] = useState<ReportForm>({
    chronology: '',
    location: '',
    date: new Date().toISOString().split('T')[0],
    time: new Date().toLocaleTimeString([], { hour: '2-digit', minute: '2-digit', hour12: false }),
    thirdPartyInvolved: false
  });
  const [isSubmitting, setIsSubmitting] = useState(false);

  const dateLimits = useMemo(() => {
    const today = new Date();
    const max = today.toISOString().split('T')[0];
    const minDate = new Date();
    minDate.setDate(today.getDate() - 7);
    const min = minDate.toISOString().split('T')[0];
    return { min, max };
  }, []);

  const handleClaimUpload = async (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (!file) return;
    setStep('analyzing');
    const reader = new FileReader();
    reader.onload = async () => {
      const base64 = reader.result as string;
      setPhotoBase64(base64);
      const response = await analyzeClaimPhoto(base64);
      if (response.success && response.data) {
        setClaimResult(response.data);
        setStep('result');
      } else {
        alert(response.error || 'Audit neural gagal. Mohon gunakan foto yang lebih jelas.');
        setStep('upload');
      }
    };
    reader.readAsDataURL(file);
  };

  const handleDocUpload = async (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (!file) return;
    setIsSummarizing(true);
    const reader = new FileReader();
    reader.onload = async () => {
      const base64 = reader.result as string;
      const response = await summarizeClaimDocument(base64);
      setIsSummarizing(false);
      if (response.success && response.data) {
        setDocSummary(response.data);
        setStep('docSummary');
      } else {
        alert(response.error || 'Gagal meringkas dokumen.');
      }
    };
    reader.readAsDataURL(file);
  };

  const handleFinalReport = async (e: React.FormEvent) => {
    e.preventDefault();
    if (reportForm.chronology.length < 20) {
      alert("Berikan kronologi lebih detail (min. 20 karakter).");
      return;
    }

    if (!currentUser) return;

    setIsSubmitting(true);

    try {
        const newClaim: Claim = {
            userId: currentUser.id,
            date: reportForm.date,
            time: reportForm.time,
            location: reportForm.location,
            chronology: reportForm.chronology,
            thirdPartyInvolved: reportForm.thirdPartyInvolved,
            status: 'SUBMITTED',
            amountEstimated: claimResult?.totalEstimasi || 0,
            photos: [photoBase64],
            aiAnalysis: claimResult,
            createdAt: new Date().toISOString()
        };

        await db.claims.add(newClaim);

        setTimeout(() => {
            setIsSubmitting(false);
            setStep('success');
        }, 1500);
    } catch (error) {
        console.error("Claim save failed", error);
        alert("Gagal menyimpan klaim.");
        setIsSubmitting(false);
    }
  };

  const Header = ({ title, showBack = false, onBack = () => {} }: { title: string, showBack?: boolean, onBack?: () => void }) => (
    <div className="flex items-center gap-3 mb-3">
      {showBack && (
        <button onClick={onBack} className="p-2 bg-gray-100 dark:bg-white/5 rounded-full hover:text-primary-500 transition-colors">
          <ChevronRight className="rotate-180" size={16}/>
        </button>
      )}
      <div className="w-7 h-7 bg-primary-500/10 rounded-lg flex items-center justify-center text-primary-500">
        <ShieldCheck size={16}/>
      </div>
      <h3 className="text-lg font-black uppercase tracking-tight">{title}</h3>
    </div>
  );

  if (step === 'upload') {
    return (
      <div className="space-y-3 animate-fade-in flex flex-col h-full justify-center">
        <div className="aspect-[4/3] relative rounded-[2rem] overflow-hidden bg-gray-100 dark:bg-white/5 border-2 border-dashed border-primary-500/30 flex flex-col items-center justify-center group cursor-pointer shadow-inner">
          <div className="w-14 h-14 bg-primary-500/10 rounded-full flex items-center justify-center text-primary-500 mb-2 group-hover:scale-110 transition-transform">
            <Camera size={28} />
          </div>
          <p className="text-base font-black uppercase text-gray-400 group-hover:text-primary-500 transition-colors tracking-tight">Start Express Claim</p>
          <p className="text-[0.5rem] text-gray-400 mt-1 font-bold uppercase tracking-widest text-center px-4">Snap a photo. We'll handle the rest.</p>
          <input type="file" className="absolute inset-0 opacity-0 cursor-pointer" onChange={handleClaimUpload} />
        </div>
        <div className="grid grid-cols-2 gap-2">
          <div className="p-3 rounded-xl bg-white dark:bg-white/5 border border-black/5 flex flex-col items-center text-center gap-1.5">
            <Scan size={18} className="text-primary-500" />
            <p className="text-[0.45rem] font-black uppercase tracking-widest text-gray-500">Secure Check</p>
          </div>
          <div className="p-3 rounded-xl bg-white dark:bg-white/5 border border-black/5 flex flex-col items-center text-center gap-1.5">
            <Rocket size={18} className="text-primary-500" />
            <p className="text-[0.45rem] font-black uppercase tracking-widest text-gray-500">Express Submit</p>
          </div>
        </div>
      </div>
    );
  }

  if (step === 'analyzing') {
    return (
      <div className="glass-card rounded-[2.5rem] h-full flex flex-col items-center justify-center animate-pop-in bg-white dark:bg-midnight overflow-hidden">
        <NeuralProcessingView 
          label="Damage Audit" 
          sublabel="Our Neural Vision cluster is calculating repair costs and verifying incident validity from your evidence."
        />
      </div>
    );
  }

  if (step === 'result' && claimResult) {
    return (
      <div className="space-y-3 animate-pop-in h-full flex flex-col pb-2">
        <div className="p-4 glass-card rounded-[2rem] border-2 border-primary-500/20 bg-primary-500/5 relative overflow-hidden flex-shrink-0">
          <div className="absolute top-3 right-3">
            <div className="px-2 py-0.5 bg-primary-500 text-white rounded-md font-black text-[0.45rem] uppercase tracking-widest">{claimResult.severity} Damage</div>
          </div>
          <p className="text-[0.45rem] font-black uppercase text-primary-500 tracking-[0.3em] mb-1">Estimated Repair Cost</p>
          <h3 className="text-3xl font-black tracking-tighter mb-1">{formatIDR(claimResult.totalEstimasi)}</h3>
          <p className="text-[0.6rem] font-bold text-gray-600 dark:text-gray-300 leading-tight border-l-2 border-primary-500 pl-2">AI Analysis: {claimResult.aiInsight}</p>
        </div>

        <div className="flex bg-gray-100 dark:bg-white/5 p-0.5 rounded-lg text-[0.5rem] font-black uppercase tracking-widest">
            <button onClick={() => setActiveTab('evidence')} className={`flex-1 py-1.5 rounded-md transition-all ${activeTab === 'evidence' ? 'bg-white dark:bg-gray-700 shadow-sm text-primary-500' : 'text-gray-400'}`}>Visual Analysis</button>
            <button onClick={() => setActiveTab('reasoning')} className={`flex-1 py-1.5 rounded-md transition-all ${activeTab === 'reasoning' ? 'bg-white dark:bg-gray-700 shadow-sm text-primary-500' : 'text-gray-400'}`}>Tech Summary</button>
            <button onClick={() => setActiveTab('steps')} className={`flex-1 py-1.5 rounded-md transition-all ${activeTab === 'steps' ? 'bg-white dark:bg-gray-700 shadow-sm text-primary-500' : 'text-gray-400'}`}>Express Track</button>
        </div>

        <div className="flex-1 overflow-y-auto pr-0.5 no-scrollbar min-h-0">
          {activeTab === 'evidence' && (
            <div className="animate-fade-in space-y-2 p-1">
              {claimResult.rincianPart && claimResult.rincianPart.length > 0 ? (
                claimResult.rincianPart.map((p, i) => (
                  <div key={i} className="p-3 bg-white dark:bg-white/5 rounded-xl border border-black/5 flex items-center justify-between shadow-sm">
                    <div className="flex-1">
                      <p className="font-black uppercase text-[0.6rem] tracking-tight">{p.namaPart}</p>
                      <p className="text-[0.45rem] font-bold text-gray-400 uppercase tracking-widest mt-0.5">{p.kondisi}</p>
                    </div>
                    <div className="text-right ml-4">
                      <p className="font-black text-[0.7rem] text-primary-500 leading-none">{formatIDR(p.estimasiBiaya)}</p>
                      <div className={`mt-1.5 text-[0.45rem] font-black uppercase tracking-widest px-2 py-0.5 rounded flex items-center gap-1 ${p.tindakan === 'Ganti' ? 'bg-rose-500/10 text-rose-500' : 'bg-blue-500/10 text-blue-500'}`}>
                        {p.tindakan === 'Ganti' ? <Trash2 size={8}/> : <Wrench size={8}/>}
                        {p.tindakan}
                      </div>
                    </div>
                  </div>
                ))
              ) : (
                <div className="p-6 text-center space-y-2 bg-gray-50 dark:bg-white/5 rounded-2xl border border-dashed border-gray-200 dark:border-white/10">
                   <Info size={24} className="mx-auto text-gray-300"/>
                   <p className="text-[0.55rem] font-black uppercase text-gray-400">Scan unit untuk memvalidasi rincian klaim.</p>
                </div>
              )}
            </div>
          )}

          {activeTab === 'reasoning' && (
            <div className="animate-fade-in space-y-3 p-1">
                <div className="bg-primary-500/5 p-4 rounded-xl border border-primary-500/10">
                    <p className="text-[0.5rem] font-black uppercase text-primary-500 mb-2 tracking-widest flex items-center gap-2"><BrainCircuit size={10}/> Analysis Details</p>
                    <p className="text-[0.65rem] text-gray-600 dark:text-gray-300 leading-relaxed font-medium">
                        {claimResult.technicalReasoning}
                    </p>
                </div>
                <div className="bg-gray-50 dark:bg-white/5 p-4 rounded-xl border border-gray-100 dark:border-white/5">
                    <p className="text-[0.5rem] font-black uppercase text-gray-400 mb-2 tracking-widest">Recommended Rapid Workshop</p>
                    <p className="text-[0.65rem] font-bold uppercase tracking-tight text-gray-900 dark:text-white flex items-center gap-2"><MapPin size={10} className="text-primary-500"/> {claimResult.rekomendasiBengkel}</p>
                </div>
            </div>
          )}

          {activeTab === 'steps' && (
            <div className="animate-fade-in space-y-2 p-1">
                {claimResult.nextSteps.map((step, idx) => (
                    <div key={idx} className="flex gap-3 p-3 bg-emerald-50 dark:bg-emerald-950/20 rounded-xl border border-emerald-100 dark:border-emerald-900/30 items-center">
                        <div className="w-5 h-5 bg-emerald-500 text-white rounded-lg flex items-center justify-center flex-shrink-0 text-[0.6rem] font-black">{idx + 1}</div>
                        <p className="text-[0.6rem] font-bold text-emerald-900 dark:text-emerald-100 uppercase tracking-tight">{step}</p>
                    </div>
                ))}
            </div>
          )}
        </div>

        <div className="grid grid-cols-2 gap-2 pt-1 flex-shrink-0">
          <button onClick={() => setStep('docUpload')} className="py-3 bg-white dark:bg-white/5 border border-black/5 rounded-xl font-black uppercase text-[0.55rem] tracking-widest flex items-center justify-center gap-1.5 transition-all active:scale-95 shadow-sm">
            <FileSearch size={14}/> Fast Doc Scan
          </button>
          <button onClick={() => setStep('reporting')} className="py-3 bg-primary-500 text-white rounded-xl font-black uppercase text-[0.55rem] tracking-widest shadow-lg shadow-primary-500/20 transition-all active:scale-95">Lanjut Lapor Cepat</button>
        </div>
      </div>
    );
  }

  if (step === 'docUpload') {
    return (
      <div className="space-y-4 animate-fade-in flex flex-col h-full justify-center">
        <Header title="Accelerated Document Audit" showBack onBack={() => setStep('result')} />
        <div className="p-6 rounded-[2rem] border-2 border-dashed border-gray-300 dark:border-white/10 flex flex-col items-center justify-center text-center gap-3 relative bg-gray-50 dark:bg-white/5">
          {isSummarizing ? (
            <div className="py-6 space-y-3">
              <Loader2 className="animate-spin text-primary-500 mx-auto" size={28}/>
              <p className="text-[0.55rem] font-black uppercase text-gray-400 animate-pulse">Syncing to Insurer...</p>
            </div>
          ) : (
            <>
              <FileSearch size={32} className="text-gray-300"/>
              <div className="space-y-0.5">
                <p className="font-black text-xs uppercase tracking-tight">Rapid Document Upload</p>
                <p className="text-[0.45rem] font-bold text-gray-400 uppercase tracking-widest">Instant data extraction for claim speed</p>
              </div>
              <input type="file" className="absolute inset-0 opacity-0 cursor-pointer" onChange={handleDocUpload} />
            </>
          )}
        </div>
        {!isSummarizing && <button onClick={() => setStep('result')} className="w-full py-3 text-[0.5rem] font-black uppercase text-gray-400 tracking-widest">Kembali ke Audit</button>}
      </div>
    );
  }

  if (step === 'docSummary' && docSummary) {
    return (
      <div className="space-y-3 animate-pop-in h-full flex flex-col">
        <Header title="Claim Summary" showBack onBack={() => setStep('docUpload')} />
        <div className="p-4 bg-primary-500/5 border border-primary-500/20 rounded-xl space-y-1">
          <p className="text-[0.4rem] font-black text-primary-500 uppercase tracking-widest">Express Path Policy</p>
          <p className="font-black text-base tracking-tight uppercase">{docSummary.policyNumber}</p>
        </div>
        <div className="flex-1 overflow-y-auto space-y-3 no-scrollbar pr-1">
          <div className="space-y-1.5">
             <p className="text-[0.5rem] font-black uppercase text-gray-400 ml-1">Pre-Validated Data</p>
             <div className="grid gap-1.5">
               {docSummary.keyPoints.map((point, i) => (
                 <div key={i} className="flex gap-2 p-2.5 bg-white dark:bg-white/5 border border-black/5 rounded-xl text-[0.6rem] font-medium items-start">
                   <div className="w-3 h-3 rounded-full bg-emerald-500/10 flex items-center justify-center text-emerald-500 flex-shrink-0 mt-0.5">
                     <CheckCircle2 size={8}/>
                   </div>
                   {point}
                 </div>
               ))}
             </div>
          </div>
          <div className="p-3 bg-gray-100 dark:bg-white/5 rounded-xl space-y-1 border border-black/5">
            <p className="text-[0.45rem] font-black uppercase text-gray-400">Submission Risk Level</p>
            <p className="text-[0.6rem] italic font-bold leading-snug">{docSummary.riskAssessment}</p>
          </div>
        </div>
        <div className="grid grid-cols-2 gap-2 pt-2">
          <button onClick={() => setStep('docUpload')} className="py-3 bg-white dark:bg-white/5 border border-black/5 rounded-xl font-black uppercase text-[0.5rem] tracking-widest">Rescan Docs</button>
          <button onClick={() => setStep('reporting')} className="py-3 bg-primary-500 text-white rounded-xl font-black uppercase text-[0.5rem] tracking-widest shadow-lg">Confirm Submission</button>
        </div>
      </div>
    );
  }

  if (step === 'reporting') {
    return (
      <div className="animate-fade-in flex flex-col h-full">
        <Header title="Express Incident Report" showBack onBack={() => setStep('result')} />
        <form onSubmit={handleFinalReport} className="flex-1 overflow-y-auto pr-1 no-scrollbar space-y-3">
          <div className="grid grid-cols-2 gap-2">
            <div className="space-y-1">
              <label className="text-[0.45rem] font-black uppercase tracking-widest text-gray-400 ml-1">Tanggal (Kejadian)</label>
              <div className="relative">
                <Calendar size={12} className="absolute left-2.5 top-1/2 -translate-y-1/2 text-primary-500 pointer-events-none" />
                <input 
                  type="date" required 
                  min={dateLimits.min} max={dateLimits.max}
                  className="w-full pl-8 pr-2 py-2.5 rounded-xl bg-white dark:bg-white/5 border border-black/5 text-[0.65rem] outline-none focus:border-primary-500 font-bold" 
                  value={reportForm.date}
                  onChange={(e) => setReportForm({...reportForm, date: e.target.value})}
                />
              </div>
            </div>
            <div className="space-y-1">
              <label className="text-[0.45rem] font-black uppercase tracking-widest text-gray-400 ml-1">Waktu</label>
              <div className="relative">
                <Clock size={12} className="absolute left-2.5 top-1/2 -translate-y-1/2 text-primary-500 pointer-events-none" />
                <input 
                  type="time" required 
                  className="w-full pl-8 pr-2 py-2.5 rounded-xl bg-white dark:bg-white/5 border border-black/5 text-[0.65rem] outline-none focus:border-primary-500 font-bold" 
                  value={reportForm.time}
                  onChange={(e) => setReportForm({...reportForm, time: e.target.value})}
                />
              </div>
            </div>
          </div>

          <div className="space-y-1">
            <label className="text-[0.45rem] font-black uppercase tracking-widest text-gray-400 ml-1">Lokasi TKP</label>
            <div className="relative">
              <MapPin size={12} className="absolute left-2.5 top-1/2 -translate-y-1/2 text-primary-500" />
              <input 
                type="text" required placeholder="Alamat detail..."
                className="w-full pl-8 pr-2 py-2.5 rounded-xl bg-white dark:bg-white/5 border border-black/5 text-[0.65rem] outline-none focus:border-primary-500 font-bold" 
                value={reportForm.location}
                onChange={(e) => setReportForm({...reportForm, location: e.target.value})}
              />
            </div>
          </div>

          <div className="space-y-1">
            <label className="text-[0.45rem] font-black uppercase tracking-widest text-gray-400 ml-1">Kronologi Singkat</label>
            <textarea 
              required rows={3} placeholder="Apa yang terjadi secara detail?"
              className="w-full px-3 py-2.5 rounded-xl bg-white dark:bg-white/5 border border-black/5 text-[0.6rem] outline-none focus:border-primary-500 resize-none font-medium leading-tight shadow-inner" 
              value={reportForm.chronology}
              onChange={(e) => setReportForm({...reportForm, chronology: e.target.value})}
            />
          </div>

          <div className="pt-2">
            <label className="flex items-center gap-3 p-4 bg-white dark:bg-white/5 border border-black/5 rounded-2xl cursor-pointer hover:border-primary-500/30 transition-all">
              <div className={`w-10 h-10 rounded-xl flex items-center justify-center transition-all ${reportForm.thirdPartyInvolved ? 'bg-primary-500 text-white' : 'bg-gray-100 dark:bg-white/10 text-gray-400'}`}>
                <Users size={20}/>
              </div>
              <div className="flex-1">
                <p className="text-[0.65rem] font-black uppercase tracking-widest">Pihak Ketiga Terlibat?</p>
                <p className="text-[0.45rem] font-bold text-gray-400 uppercase">Apakah ada orang lain yang terlibat dalam kejadian?</p>
              </div>
              <div className={`w-6 h-6 rounded-lg border-2 flex items-center justify-center transition-all ${reportForm.thirdPartyInvolved ? 'bg-primary-500 border-primary-500' : 'border-gray-200'}`}>
                {reportForm.thirdPartyInvolved && <Check size={14} className="text-white" strokeWidth={4}/>}
              </div>
              <input 
                type="checkbox" 
                className="hidden" 
                checked={reportForm.thirdPartyInvolved}
                onChange={(e) => setReportForm({...reportForm, thirdPartyInvolved: e.target.checked})}
              />
            </label>
          </div>
        </form>

        <button 
          onClick={handleFinalReport} disabled={isSubmitting}
          className="mt-2 w-full py-4 bg-gray-900 dark:bg-white text-white dark:text-black rounded-xl font-black uppercase text-[0.55rem] tracking-[0.2em] shadow-xl flex items-center justify-center gap-2 disabled:opacity-50 transition-all active:scale-95"
        >
          {isSubmitting ? <Loader2 className="animate-spin" size={14}/> : <Rocket size={14}/>}
          Kirim Klaim Kilat
        </button>
      </div>
    );
  }

  if (step === 'success') {
    return (
      <div className="text-center space-y-4 py-4 animate-pop-in flex flex-col h-full justify-center">
        <div className="w-20 h-20 bg-emerald-500 rounded-full mx-auto flex items-center justify-center text-white shadow-2xl shadow-emerald-500/30">
          <CheckCircle2 size={40} strokeWidth={3} />
        </div>
        <div className="space-y-1">
          <h3 className="text-xl font-black uppercase tracking-tighter">Klaim <span className="text-primary-500">Tersubmit</span></h3>
          <p className="text-[0.55rem] text-gray-500 dark:text-gray-400 px-4 leading-relaxed font-bold uppercase tracking-widest">
            Akselerasi Neural OS aktif. Berkas Anda telah divalidasi dan dikirim langsung ke tim asuransi. Status akan diperbarui dalam <span className="text-primary-500">60 menit</span>.
          </p>
        </div>
        <div className="p-3 rounded-xl bg-gray-100 dark:bg-white/5 border border-black/5 text-left">
          <p className="text-[0.4rem] font-black text-gray-400 uppercase tracking-widest mb-0.5">Rapid Reference Hash</p>
          <p className="text-[0.55rem] font-mono text-primary-500 break-all leading-tight">SP-SPD-{Date.now().toString().slice(-8)}</p>
        </div>
        <button onClick={onComplete} className="w-full py-4 bg-gray-900 dark:bg-white text-white dark:text-black rounded-xl font-black uppercase text-[0.5rem] tracking-widest shadow-xl transition-all active:scale-95">Selesai</button>
      </div>
    );
  }

  return null;
};

const Wrench = ({ size }: { size: number }) => (
  <svg width={size} height={size} viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round"><path d="M14.7 6.3a1 1 0 0 0 0 1.4l1.6 1.6a1 1 0 0 0 1.4 0l3.77-3.77a6 6 0 0 1-7.94 7.94l-6.91 6.91a2.12 2.12 0 0 1-3-3l6.91-6.91a6 6 0 0 1 7.94-7.94l-3.76 3.76z"/></svg>
);

const Check = ({ size, className, strokeWidth }: { size: number, className?: string, strokeWidth?: number }) => (
  <svg width={size} height={size} viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth={strokeWidth || 2} strokeLinecap="round" strokeLinejoin="round" className={className}><polyline points="20 6 9 17 4 12"/></svg>
);

export default ClaimManager;

import React from 'react';
import { 
  FileText, FileSearch, Trash2, User, Camera, Loader2, AlertTriangle, Check, 
  Microscope, BrainCircuit, RefreshCw, Info, Cpu, ShieldCheck, Activity, ShieldX,
  FileSearch as ManualAuditIcon, Video, Car, CalendarClock, CheckCircle2, ImagePlus
} from 'lucide-react';
import { ScannerOverlay, NeuralProcessingView } from './WizardUI';
import { validateVehiclePhoto, analyzeVehicleSurvey, extractStnkData } from '../../services/geminiService';

interface StepSurveyProps {
  survey: any;
  setSurvey: (s: any) => void;
  stnkResult: any;
  setStnkResult: (r: any) => void;
  loading: boolean;
  setLoading: (l: boolean) => void;
  loadingType: 'KTP' | 'STNK' | 'SURVEY' | null;
  setLoadingType: (t: 'KTP' | 'STNK' | 'SURVEY' | null) => void;
  photoValidation: Record<string, { status: 'LOADING' | 'VALID' | 'INVALID', msg?: string }>;
  setPhotoValidation: React.Dispatch<React.SetStateAction<Record<string, { status: 'LOADING' | 'VALID' | 'INVALID', msg?: string }>>>;
  vehicle: any;
}

const StepSurvey: React.FC<StepSurveyProps> = ({
  survey, setSurvey, stnkResult, setStnkResult, loading, setLoading, loadingType, setLoadingType,
  photoValidation, setPhotoValidation, vehicle
}) => {

  const handleStnkUpload = async (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (!file) return;
    setLoading(true);
    setLoadingType('STNK');
    const reader = new FileReader();
    reader.onload = async () => {
      const base64 = reader.result as string;
      setSurvey((prev: any) => ({ ...prev, stnk: base64 }));
      const response = await extractStnkData(base64);
      setLoading(false);
      setLoadingType(null);
      if (response.success && response.data) {
        setStnkResult({
          ownerName: response.data.owner || 'TIDAK TERDETEKSI',
          plate: response.data.plate || 'TIDAK TERDETEKSI',
          vin: response.data.vin || 'TIDAK TERDETEKSI',
          engine: response.data.engine || 'TIDAK TERDETEKSI',
          color: response.data.color || 'TIDAK TERDETEKSI',
          year: response.data.year || vehicle.year.toString(),
          status: response.data.status
        });
      }
    };
    reader.readAsDataURL(file);
  };

  const handlePhotoUpload = async (file: File, slotId: string, slotLabel: string) => {
    if (!file) return;

    const reader = new FileReader();
    reader.onload = async (e) => {
      const base64 = e.target?.result as string;

      // Optimistic update
      setSurvey((prev: any) => ({ ...prev, photos: { ...prev.photos, [slotId]: base64 } }));

      if (file.size > 10 * 1024 * 1024) {
         setPhotoValidation(prev => ({ 
             ...prev, 
             [slotId]: { status: 'INVALID', msg: 'Max File Size 10MB' } 
         }));
         return;
      }

      const img = new Image();
      img.src = base64;
      img.onload = async () => {
          if (img.width < 600 || img.height < 400) {
             setPhotoValidation(prev => ({ 
                 ...prev, 
                 [slotId]: { status: 'INVALID', msg: 'Min Resolution 600x400' } 
             }));
             return;
          }

          setPhotoValidation(prev => ({ ...prev, [slotId]: { status: 'LOADING' } }));

          try {
            const result = await validateVehiclePhoto(base64, slotLabel);
            setPhotoValidation(prev => ({ 
              ...prev, 
              [slotId]: { 
                status: result.valid ? 'VALID' : 'INVALID',
                msg: result.issue
              } 
            }));
          } catch (e) {
            setPhotoValidation(prev => ({ ...prev, [slotId]: { status: 'VALID' } })); // Fallback
          }
      };
    };
    reader.readAsDataURL(file);
  };

  const runSurveyAI = async () => {
    const photoEntries = Object.entries(survey.photos).map(([id, data]) => ({ id, data: data as string }));
    if (photoEntries.length < 5) {
      alert("Harap lengkapi semua foto unit (5 posisi) sebelum memulai audit AI.");
      return;
    }
    setLoading(true);
    setLoadingType('SURVEY');

    const response = await analyzeVehicleSurvey(photoEntries);

    setLoading(false);
    setLoadingType(null);

    if (response.success) {
      const finalScore = response.score || 0;
      const needsManual = finalScore < 80 || response.auditVerdict === 'REVIEW_REQUIRED';
      const isRejected = response.auditVerdict === 'REJECTED';

      setSurvey((prev: any) => ({ 
        ...prev, 
        score: finalScore, 
        summary: response.summary || '',
        underwritingReport: response.underwritingReport || '',
        detailedIssues: response.detailedIssues || [],
        photoFlags: response.photoFlags || [],
        verdict: isRejected ? 'REJECTED' : (needsManual ? 'MANUAL_REQUIRED' : 'CLEAN'),
        rejectionReason: response.rejectionReason || (finalScore < 80 ? 'Skor neural di bawah ambang batas otomatis (80). Butuh verifikasi manual.' : ''),
        manualVerif: needsManual && !isRejected
      }));
    }
  };

  const submitManualRequest = () => {
    if (!survey.manualDate) {
        alert("Pilih tanggal survey");
        return;
    }
    setSurvey((prev: any) => ({ ...prev, manualRequestStatus: 'REQUESTED' }));
  };

  const photoSlots = [
    { id: 'front', label: 'Front 45°', desc: 'Depan Serong' },
    { id: 'back', label: 'Rear 45°', desc: 'Belakang Serong' },
    { id: 'right', label: 'Right Side', desc: 'Sisi Kanan' },
    { id: 'left', label: 'Left Side', desc: 'Sisi Kiri' },
    { id: 'interior', label: 'Dashboard', desc: 'Interior Depan' }
  ];
  const capturedCount = Object.keys(survey.photos).length;

  const verdictData: any = {
    'CLEAN': { icon: ShieldCheck, color: 'text-emerald-500', bg: 'bg-emerald-500/10', label: 'AUDIT PASSED', desc: 'Neural scoring within acceptable risk parameters. Immediate issuance enabled.' },
    'REVIEW_REQUIRED': { icon: Activity, color: 'text-amber-500', bg: 'bg-amber-500/10', label: 'REVIEW REQ', desc: 'Anomalies detected. Subject to high-fidelity human audit before activation.' },
    'MANUAL_REQUIRED': { icon: ManualAuditIcon, color: 'text-amber-600', bg: 'bg-amber-600/10', label: 'MANUAL AUDIT', desc: 'Neural score below 80 threshold. Physical or video assessment required.' },
    'REJECTED': { icon: ShieldX, color: 'text-rose-500', bg: 'bg-rose-500/10', label: 'REJECTED', desc: 'Critical integrity breach or damage levels exceed underwriting protocol.' },
  };

  return (
    <div className="space-y-8 animate-fade-in pb-24">
      {!survey.stnk ? (
          <div className="p-6 bg-white dark:bg-white/[0.03] border-2 border-black/5 dark:border-white/5 rounded-[2.5rem] space-y-6 shadow-xl relative overflow-hidden">
              <div className="flex items-center gap-4 mb-2">
                  <div className="w-10 h-10 bg-primary-500/10 rounded-xl flex items-center justify-center text-primary-500 shadow-inner"><FileText size={20}/></div>
                  <div><h4 className="text-[0.7rem] font-black uppercase tracking-[0.2em]">Registrasi STNK AI</h4><p className="text-[0.5rem] font-bold text-gray-400 uppercase tracking-widest">Neural Document Extraction</p></div>
              </div>
              <label className="group relative aspect-[3/1] rounded-[2rem] border-2 border-dashed border-gray-300 dark:border-white/10 flex flex-col items-center justify-center gap-2 cursor-pointer hover:border-primary-500/50 transition-all bg-gray-50 dark:bg-white/[0.02]">
                  {loading && loadingType === 'STNK' ? <ScannerOverlay label="STNK Neural Audit" /> : (
                  <>
                      <div className="flex gap-3">
                        <FileSearch size={32} className="text-gray-300 group-hover:text-primary-500 transition-colors"/>
                        <ImagePlus size={32} className="text-gray-300 group-hover:text-primary-500 transition-colors"/>
                      </div>
                      <p className="text-[0.6rem] font-black uppercase tracking-[0.2em] text-gray-500">Scan / Upload STNK</p>
                      <input type="file" accept="image/*" className="hidden" onChange={handleStnkUpload} />
                  </>
                  )}
              </label>
          </div>
      ) : (
          <div className="flex items-center justify-between p-4 bg-emerald-500/10 rounded-2xl border border-emerald-500/20">
              <div className="flex items-center gap-3">
                  <div className="p-2 bg-emerald-500 rounded-lg text-white"><Check size={14} strokeWidth={3}/></div>
                  <span className="text-[0.6rem] font-black text-emerald-800 dark:text-emerald-200 uppercase tracking-widest">STNK Verified: {stnkResult.plate}</span>
              </div>
              <button onClick={() => setSurvey({...survey, stnk: null})} className="text-gray-400 hover:text-rose-500 transition-colors"><Trash2 size={16}/></button>
          </div>
      )}

      <div className="space-y-4">
        <div className="flex items-center justify-between px-2">
           <div className="flex items-center gap-3">
              <Camera size={16} className="text-primary-500"/>
              <h4 className="text-[0.7rem] font-black uppercase tracking-[0.2em] text-gray-500">Visual Evidence Matrix</h4>
           </div>
           <div className="px-3 py-1 bg-primary-500/10 rounded-full text-[0.5rem] font-black text-primary-500 uppercase">{capturedCount}/5 Done</div>
        </div>

        <div className="grid grid-cols-2 gap-4">
           {photoSlots.map((slot) => {
              const validation = photoValidation[slot.id];
              const isLoading = validation?.status === 'LOADING';
              const isInvalid = validation?.status === 'INVALID';
              const isValid = validation?.status === 'VALID';

              return (
