                    <button 
                        onClick={(e) => { e.stopPropagation(); setKycData({...kycData, photo: null}); setVerifiedFields(new Set()); }}
                        className="absolute -top-3 -right-3 p-2.5 bg-rose-500 text-white rounded-2xl shadow-2xl active:scale-90 transition-all hover:brightness-110"
                    >
                        <RefreshCw size={18} className="animate-spin-slow"/>
                    </button>
                </div>
                <div className="mt-6 flex items-center gap-3 px-5 py-2 bg-emerald-500/10 text-emerald-500 rounded-full border border-emerald-500/20 shadow-sm animate-pulse">
                   <ShieldCheck size={16}/>
                   <p className="text-[0.65rem] font-black uppercase tracking-[0.2em]">KTP Berhasil Terbaca</p>
                </div>
            </div>
          ) : (
            <>
              <div className="relative">
                <div className="w-20 h-20 bg-white dark:bg-white/[0.03] rounded-[1.8rem] flex items-center justify-center text-gray-300 group-hover:text-primary-500 transition-colors shadow-xl group-hover:scale-110 duration-500">
                    <ImageIcon size={48}/>
                </div>
                <div className="absolute -bottom-2 -right-2 bg-primary-500 text-white rounded-xl p-2 shadow-2xl animate-bounce">
                  <Plus size={18} strokeWidth={4}/>
                </div>
              </div>
              <div className="space-y-1.5">
                <p className="text-[0.8rem] font-black uppercase tracking-[0.2em] text-gray-900 dark:text-white">Upload KTP Asli</p>
                <p className="text-[0.55rem] font-black text-gray-400 uppercase tracking-widest opacity-60">Gunakan Kamera atau Galeri</p>
              </div>
              <input 
                type="file" 
                accept="image/*"
                className="absolute inset-0 opacity-0 cursor-pointer"
                onChange={async (e) => {
                  const file = e.target.files?.[0];
                  if (!file) return;
                  setLoading(true);
                  setLoadingType('KTP');
                  const reader = new FileReader();
                  reader.onload = async () => {
                    const base64 = reader.result as string;
                    setKycData((prev: any) => ({ ...prev, photo: base64 }));
                    const response = await extractKtpData(base64);
                    setLoading(false);
                    setLoadingType(null);
                    if (response.success && response.data) {
                      const newVerified = new Set<string>();
                      if (response.data.name) newVerified.add('name');
                      if (response.data.nik) newVerified.add('ktp');
                      if (response.data.address) newVerified.add('address');
                      setVerifiedFields(newVerified);
                      setKycData((prev: any) => ({
                        ...prev,
                        name: response.data.name?.toUpperCase() || prev.name,
                        ktp: response.data.nik || prev.ktp,
                        address: response.data.address?.toUpperCase() || prev.address
                      }));
                    }
                  };
                  reader.readAsDataURL(file);
                }}
              />
            </>
          )}
        </div>

        <div className="grid gap-5">
          <div className="p-8 bg-white dark:bg-white/[0.03] border-2 border-black/5 dark:border-white/5 rounded-[2.5rem] space-y-6 shadow-xl relative overflow-hidden">
            <p className="text-[0.7rem] font-black uppercase tracking-[0.2em] text-gray-400 border-b border-black/5 pb-2">Konfirmasi Data Diri</p>

            <div className="space-y-5">
              <div className="space-y-2 relative">
                <label className="text-[0.6rem] font-black uppercase text-gray-400 ml-2 tracking-widest">Nama Lengkap</label>
                <div className="relative group">
                    <input 
                      placeholder="NAMA SESUAI KTP"
                      className={`w-full px-6 py-4 rounded-2xl bg-gray-50 dark:bg-black/40 border-2 outline-none focus:border-primary-500 font-black text-sm text-primary-500 uppercase transition-all shadow-inner ${verifiedFields.has('name') ? 'border-emerald-500/30' : 'border-black/5 dark:border-white/5'}`}
                      value={kycData.name}
                      onChange={(e) => setKycData({...kycData, name: e.target.value.toUpperCase()})}
                    />
                    {verifiedFields.has('name') && <div className="absolute right-5 top-1/2 -translate-y-1/2 text-emerald-500 animate-pop-in"><CheckCircle2 size={18}/></div>}
                </div>
              </div>

              <div className="space-y-2">
                <label className="text-[0.6rem] font-black uppercase text-gray-400 ml-2 tracking-widest">Nomor KTP (NIK)</label>
                <div className="relative">
                    <input 
                      placeholder="16 DIGIT NIK"
                      maxLength={16}
                      className={`w-full px-6 py-4 rounded-2xl bg-gray-50 dark:bg-black/40 border-2 outline-none focus:border-primary-500 font-black text-sm text-primary-500 transition-all tracking-[0.3em] shadow-inner ${verifiedFields.has('ktp') ? 'border-emerald-500/30' : 'border-black/5 dark:border-white/5'}`}
                      value={kycData.ktp}
                      onChange={(e) => setKycData({...kycData, ktp: e.target.value.replace(/\D/g, "")})}
                    />
                    {verifiedFields.has('ktp') && <div className="absolute right-5 top-1/2 -translate-y-1/2 text-emerald-500 animate-pop-in"><CheckCircle2 size={18}/></div>}
                </div>
              </div>

              <div className="grid grid-cols-2 gap-4">
                <div className="space-y-2">
                  <label className="text-[0.6rem] font-black uppercase text-gray-400 ml-2 tracking-widest">Email</label>
                  <input 
                    type="email" placeholder="contoh@mail.com"
                    className="w-full px-6 py-4 rounded-2xl bg-gray-50 dark:bg-black/40 border-2 border-black/5 dark:border-white/5 outline-none focus:border-primary-500 font-black text-xs text-primary-500 transition-all shadow-inner"
                    value={kycData.email}
                    onChange={(e) => setKycData({...kycData, email: e.target.value})}
                  />
                </div>
                <div className="space-y-2">
                  <label className="text-[0.6rem] font-black uppercase text-gray-400 ml-2 tracking-widest">No. HP</label>
                  <input 
                    placeholder="0812..."
                    className="w-full px-6 py-4 rounded-2xl bg-gray-50 dark:bg-black/40 border-2 border-black/5 dark:border-white/5 outline-none focus:border-primary-500 font-black text-xs text-primary-500 transition-all shadow-inner"
                    value={kycData.phone}
                    onChange={(e) => setKycData({...kycData, phone: e.target.value.replace(/\D/g, "")})}
                  />
                </div>
              </div>

              <div className="space-y-2">
                <label className="text-[0.6rem] font-black uppercase text-gray-400 ml-2 tracking-widest">Alamat Domisili</label>
                <div className="relative">
                    <textarea 
                      placeholder="ALAMAT LENGKAP"
                      rows={3}
                      className={`w-full px-6 py-4 rounded-2xl bg-gray-50 dark:bg-black/40 border-2 outline-none focus:border-primary-500 font-black text-[0.7rem] text-primary-500 uppercase transition-all resize-none shadow-inner leading-relaxed ${verifiedFields.has('address') ? 'border-emerald-500/30' : 'border-black/5 dark:border-white/5'}`}
                      value={kycData.address}
                      onChange={(e) => setKycData({...kycData, address: e.target.value.toUpperCase()})}
                    />
                    {verifiedFields.has('address') && <div className="absolute right-5 bottom-5 text-emerald-500 animate-pop-in"><CheckCircle2 size={18}/></div>}
                </div>
              </div>
            </div>
          </div>
        </div>
      </div>
    </div>
  );
};

