      { label: 'Cek Dokumen', value: stnkResult.status === 'OK' ? 'BERHASIL' : 'DITINJAU', icon: LinkIcon },
      { label: 'Status Audit', value: survey.verdict === 'REJECTED' ? 'DITOLAK' : (isManualPending ? 'Butuh Survey' : 'Siap Terbit'), icon: Cpu, color: survey.verdict === 'REJECTED' ? 'text-rose-500' : (isManualPending ? 'text-amber-500' : 'text-emerald-500') }
