          {survey.verdict === 'REJECTED' ? <ShieldX size={48} strokeWidth={3}/> : isManualPending ? <CalendarClock size={48} strokeWidth={3}/> : <CheckCircle2 size={48} strokeWidth={3} />}
        </div>
        <div className="space-y-1">
           <h3 className="text-3xl font-black uppercase tracking-tighter">
             {survey.verdict === 'REJECTED' ? 'Status: Ditolak' : isManualPending ? 'Jadwal Survey' : 'Polis Siap Aktif'}
           </h3>
           <p className="text-[0.6rem] font-bold text-gray-500 uppercase tracking-widest">
              {survey.verdict === 'REJECTED' ? 'Mobil tidak sesuai data atau risiko terlalu tinggi.' : isManualPending ? 'Polis akan terbit setelah survey fisik selesai.' : 'Audit selesai. Mobil Anda layak mendapatkan proteksi.'}
           </p>
        </div>
