                    <p className={`text-[0.95rem] font-black uppercase tracking-tight truncate ${item.color || 'text-gray-900 dark:text-white'}`}>{item.value}</p>
                </div>
            ))}
         </div>

         <div className="pt-8 border-t border-black/5 dark:border-white/5 flex justify-between items-center relative z-10">
            <div>
                <p className="text-[0.6rem] font-black uppercase text-gray-400 tracking-widest leading-none mb-1">Total Pembayaran</p>
