const WelcomeScreen = ({ onFinish }: { onFinish: () => void }) => {
  const [progress, setProgress] = useState(0);
  const [messageIdx, setMessageIdx] = useState(0);

  const messages = [
    "Membuka SurePath...",
    "Menghubungkan Akun...",
    "Mengamankan Data...",
    "Menyiapkan Layanan...",
    "Aplikasi Siap!"
  ];

  useEffect(() => {
    const timer = setInterval(() => {
      setProgress(p => {
        if (p >= 100) {
          clearInterval(timer);
          return 100;
        }
        return p + 2;
      });
    }, 45);

    const msgTimer = setInterval(() => {
      setMessageIdx(i => (i < messages.length - 1 ? i + 1 : i));
    }, 800);

    const finishTimer = setTimeout(onFinish, 4000);

    return () => {
      clearInterval(timer);
      clearInterval(msgTimer);
      clearTimeout(finishTimer);
    };
  }, [onFinish]);

  return (
    <div className="fixed inset-0 z-[5000] bg-[#fafaf9] dark:bg-[#0c0a09] flex flex-col items-center justify-center overflow-hidden font-sans">
      <div className="absolute inset-0 pointer-events-none">
