        <div className="absolute inset-0 bg-neural-mesh opacity-20"></div>
      </div>

      <div className="relative z-10 flex flex-col items-center animate-pop-in">
        <div className="mb-14 relative group">
           <div className="absolute inset-0 bg-primary-500/20 rounded-full blur-[60px] animate-pulse"></div>
           <NeuralBot className="w-52 h-52 relative drop-shadow-[0_0_40px_rgba(249,115,22,0.4)]" mood="happy" />

           <div className="absolute -top-6 -right-6 w-12 h-12 bg-white dark:bg-white/10 rounded-2xl flex items-center justify-center shadow-2xl animate-float border border-black/5">
              <ShieldCheck size={24} className="text-emerald-500"/>
