           <div className="absolute bottom-6 -left-10 w-14 h-14 bg-white dark:bg-white/10 rounded-2xl flex items-center justify-center shadow-xl animate-float animation-delay-2000 border border-black/5">
              <Zap size={28} className="text-primary-500 fill-primary-500"/>
