    return { valid: true }; // Fallback behavior
  }
};

export const analyzeVehicleSurvey = async (images: {id: string, data: string}[], expectedData?: { brand: string, model: string, color: string, plate: string }): Promise<SurveyAnalysisResult> => {
  try {
    const ai = getAi();
    const imageParts = images.map(img => {
      const data = img.data.includes(',') ? img.data.split(',')[1] : img.data;
      return { inlineData: { mimeType: 'image/jpeg', data } };
    });

    const contextPrompt = expectedData ? 
      `DATA EKSPEKTASI (Wajib Cocok): 
      - Merk: ${expectedData.brand}
      - Model: ${expectedData.model}
      - Warna: ${expectedData.color}
      - Plat Nomor: ${expectedData.plate}` : "";

    const prompt = `Lakukan audit pra-asuransi (Underwriting Risk Assessment) yang sangat ketat menggunakan Computer Vision. Anda adalah Chief Underwriter.

    Tugas: 
    1. VERIFIKASI IDENTITAS (PENTING):
       Bandingkan unit di foto dengan data ekspektasi berikut:
       ${contextPrompt}

       Cek apakah Merk, Model, Warna, dan Plat Nomor yang terlihat di foto SAMA dengan data ekspektasi di atas.
       Jika Plat Nomor tidak terlihat jelas di satu foto, cek foto lainnya.
       Jika Warna atau Merk/Model BERBEDA, status WAJIB 'REJECTED'.

    2. IDENTIFIKASI KERUSAKAN:
       - Periksa panel: Bumper, Pintu, Fender, Kap Mesin, Atap, Kaca.
       - Cari: Goresan (Scratch), Penyok (Dent), Pecah (Crack).

    3. PENILAIAN SKOR (0-100):
       - Skor 100: Mulus total.
       - Skor < 80: Ada kerusakan visual nyata.
       - Skor 0: JIKA IDENTITAS TIDAK COCOK (Warna beda, Mobil beda, Plat beda).

    Output JSON Wajib:
    {
      "score": number,
      "summary": "Kesimpulan underwriting singkat (Bahasa Indonesia).",
      "underwritingReport": "Laporan naratif faktual. Sebutkan jika identitas kendaraan cocok atau tidak.",
      "detailedIssues": [
        { "part": "Nama Bagian", "description": "Deskripsi kerusakan / ketidakcocokan", "severity": "Minor" | "Moderate" | "Severe", "scorePenalty": number }
      ],
      "photoFlags": [
        { "id": "id_foto", "status": "OK" | "FRAUD_DETECTED" | "POOR_QUALITY" | "NOT_MATCHING", "reason": "Reason" }
      ],
      "auditVerdict": "CLEAN" | "REVIEW_REQUIRED" | "REJECTED",
      "rejectionReason": "Sebutkan alasan spesifik jika REJECTED (misal: Warna tidak sesuai, Plat nomor berbeda)"
    }

    Verifikasi Identitas Rule:
    - Jika WARNA beda: REJECTED, Skor 0.
    - Jika MERK/MODEL beda: REJECTED, Skor 0.
    - Jika PLAT NOMOR beda: REJECTED, Skor 0.
    `;

    const response = await ai.models.generateContent({
      model: 'gemini-3-flash-preview',
      contents: { parts: [{ text: prompt }, ...imageParts.map(p => p)] },
      config: { responseMimeType: 'application/json', temperature: 0.1 }
    });

    const data = JSON.parse(response.text);

    const flagsWithIds = data.photoFlags?.map((flag: any, index: number) => ({
      ...flag,
      id: images[index]?.id || `img_${index}`
    }));

    return { success: true, ...data, photoFlags: flagsWithIds };
  } catch (e) { 
    console.error("Vehicle Survey AI Error:", e);
    return { success: false, error: "Gagal menghubungkan ke Neural Engine." }; 
  }
};

