                    <div className="absolute -right-4 -bottom-4 opacity-[0.05] group-hover:scale-125 transition-transform text-gray-900 dark:text-white"><Grid size={140}/></div>
                    <div className="w-12 h-12 bg-blue-500/10 rounded-2xl flex items-center justify-center text-blue-500 mb-5 shadow-inner"><Grid size={24}/></div>
                    <p className="font-black text-lg uppercase tracking-tighter">Penjualan</p>
                    <p className="text-[0.6rem] font-bold text-gray-400 mt-1.5 uppercase tracking-widest">Terbitkan Polis</p>
                  </div>
                  <div onClick={() => setPage('claim')} className="p-8 bg-white dark:bg-white/5 rounded-[2.8rem] border border-gray-200/50 shadow-xl cursor-pointer group overflow-hidden relative">
                    <div className="absolute -right-4 -bottom-4 opacity-[0.05] group-hover:scale-125 transition-transform text-gray-900 dark:text-white"><Zap size={140}/></div>
                    <div className="w-12 h-12 bg-primary-500/10 rounded-2xl flex items-center justify-center text-primary-500 mb-5 shadow-inner"><Zap size={24}/></div>
                    <p className="font-black text-lg uppercase tracking-tighter">Bantuan AI</p>
                    <p className="text-[0.6rem] font-bold text-gray-400 mt-1.5 uppercase tracking-widest">Support Nasabah</p>
                  </div>
                </div>
                <div onClick={() => setPage('wallet')} className="p-8 bg-white dark:bg-white/5 rounded-[2.8rem] border border-gray-200/50 shadow-xl cursor-pointer group overflow-hidden relative flex items-center justify-between">
                    <div className="absolute inset-0 bg-primary-500/[0.03] opacity-0 group-hover:opacity-100 transition-opacity"></div>
                    <div className="flex items-center gap-6 relative z-10">
                       <div className="w-14 h-14 bg-gray-100 dark:bg-white/10 rounded-3xl flex items-center justify-center text-gray-400 group-hover:text-primary-500 group-hover:scale-110 transition-all shadow-inner">
                          <WalletIcon size={28}/>
                       </div>
                       <div>
                          <p className="text-xl font-black uppercase tracking-tighter">Dompet Saya</p>
                          <p className="text-[0.6rem] font-bold text-gray-400 uppercase tracking-widest mt-1">Komisi & Penarikan</p>
                       </div>
                    </div>
                    <ChevronRight className="text-gray-300 group-hover:text-primary-500 transition-all group-hover:translate-x-1" size={24}/>
                </div>
              </>
            )}
          </div>
        );
      case 'products':
        return (
          <div className="space-y-10 animate-fade-in pb-24 text-gray-900 dark:text-white relative z-10 pt-4">
            <h2 className="text-4xl font-black uppercase tracking-tighter px-2">{isAgent ? 'Penjualan' : 'Katalog'} <span className="text-primary-500">{isAgent ? 'Polis' : 'Lengkap'}</span></h2>
            <div className="grid gap-4">
              {products.filter(p => p.cat === 'Retail').map(p => (
                <div key={p.id} onClick={() => p.active ? setPage(`buy-${p.id}`) : null} className={`p-6 bg-white dark:bg-white/5 rounded-[2.8rem] border border-gray-200 dark:border-gray-800 flex items-center justify-between transition-all group relative overflow-hidden ${p.active ? 'cursor-pointer hover:border-primary-500 shadow-lg' : 'opacity-40 grayscale cursor-not-allowed bg-gray-50/50'}`}>
                  <div className="flex items-center gap-6">
                    <div className={`w-16 h-16 bg-gray-100 dark:bg-white/10 ${p.color} rounded-3xl flex items-center justify-center shadow-inner ${p.active ? 'group-hover:scale-110 transition-transform' : ''}`}>
                      <p.icon size={32}/>
                    </div>
                    <div>
                      <h4 className="font-black text-xl uppercase tracking-tighter">{p.label}</h4>
                      <p className="text-[0.65rem] text-gray-500 font-bold uppercase tracking-[0.2em]">{p.active ? p.tech : 'Segera Hadir'}</p>
                    </div>
                  </div>
                  {p.active && <ChevronRight className="text-gray-300 group-hover:text-primary-500 transition-colors" size={24}/>}
                </div>
              ))}
            </div>
          </div>
        );
      case 'claim': return <ClaimManager onComplete={() => setPage('home')} />;
      case 'wallet': return isAgent ? <AgentsWallet /> : null;
      case 'profile': return <UserProfile currentUser={currentUser} />;
      case 'buy-car': return <CarInsuranceWizard onComplete={() => setPage('home')} currentUser={currentUser} />;
      case 'buy-travel': return <TravelInsuranceWizard onComplete={() => setPage('home')} currentUser={currentUser} />;
      case 'buy-pa': return <PAInsuranceWizard onComplete={() => setPage('home')} currentUser={currentUser} />;
      case 'buy-mpar': return <MPARInsuranceWizard onComplete={() => setPage('home')} currentUser={currentUser} />;
      default: return <div className="p-10 text-center uppercase font-black text-gray-300">Tahap Pengembangan</div>;
    }
  };

  const isWizardFlow = currentPage.startsWith('buy-');
  const isAgentInNav = currentUser?.role === UserRole.AGENT;
  const navItems = [
    { id: 'home', icon: HomeIcon, label: 'Beranda' },
    { id: 'claim', icon: Zap, label: 'Klaim' },
    ...(isAgentInNav ? [{ id: 'wallet', icon: WalletIcon, label: 'Dompet' }] : []),
    { id: 'profile', icon: UserCircle, label: 'Profil' }
  ];

  const AppWrapper = () => (
    <div className={`${darkMode ? 'dark bg-[#0a0a0a] text-white' : 'bg-[#fafaf9] text-gray-900'} h-full transition-colors duration-700 font-sans flex flex-col relative overflow-hidden`}>
      <div className="absolute inset-0 pointer-events-none z-0">
        <div className="absolute top-[-20%] left-[-20%] w-[800px] h-[800px] bg-primary-500/5 rounded-full blur-[120px] animate-pulse-slow"></div>
        <div className="absolute bottom-[-20%] right-[-20%] w-[800px] h-[800px] bg-blue-500/5 rounded-full blur-[120px] animate-pulse-slow animation-delay-4000"></div>
        <div className="absolute inset-0 bg-[url('https://grainy-gradients.vercel.app/noise.svg')] opacity-10"></div>
      </div>
      {!isWizardFlow && (
        <header className="flex-shrink-0 h-24 px-8 flex items-center justify-between border-b border-gray-100 dark:border-white/5 z-[60] relative bg-white/80 dark:bg-black/20 backdrop-blur-md">
          <div className="flex items-center gap-4 cursor-pointer group" onClick={() => setPage('home')}>
            <SurePathLogo className="w-12 h-12 group-hover:scale-110 transition-transform" />
            <div className="flex flex-col">
              <span className="font-black text-2xl tracking-tighter uppercase leading-none text-slate-900 dark:text-white">Sure<span className="text-brand-500">Path</span></span>
              <span className="text-[0.45rem] font-bold text-gray-400 uppercase tracking-[0.4em] mt-1">{currentUser?.name || 'Tamu'}</span>
            </div>
          </div>
          <div className="flex items-center gap-3">
            <button onClick={() => setDarkMode(!darkMode)} className="p-3 bg-white dark:bg-white/10 rounded-2xl text-gray-400 hover:text-primary-500 transition-colors shadow-sm border border-gray-100 dark:border-white/5">
              {darkMode ? <Sun size={18}/> : <Moon size={18}/>}
            </button>
            <button onClick={handleLogout} className="p-3 bg-slate-900 dark:bg-white text-white dark:text-black rounded-2xl hover:bg-primary-500 dark:hover:bg-primary-500 transition-all shadow-lg">
               <LogOut size={18}/>
            </button>
          </div>
        </header>
      )}
      <main className={`flex-1 overflow-y-auto w-full no-scrollbar z-10 relative ${isWizardFlow ? 'p-0 h-screen' : 'px-6 py-10'}`}>
        {renderPortalContent()}
      </main>
      {!isWizardFlow && (
        <nav className="flex-shrink-0 fixed bottom-8 inset-x-6 h-20 bg-white/90 dark:bg-[#111]/90 backdrop-blur-xl z-[70] flex items-center justify-around px-4 rounded-[2.8rem] shadow-[0_30px_60px_-15px_rgba(0,0,0,0.1)] border border-gray-100 dark:border-white/10 max-w-xl mx-auto transition-all duration-500">
          {navItems.map(item => (
            <button key={item.id} onClick={() => setPage(item.id)} className={`flex flex-col items-center gap-1.5 flex-1 py-3 transition-all duration-300 tap-feedback ${currentPage === item.id || (currentPage.startsWith('buy') && item.id === 'products') ? 'text-primary-500 scale-110 -translate-y-1' : 'text-gray-400 dark:text-gray-500'}`}>
              <item.icon size={24} className={currentPage === item.id ? 'drop-shadow-[0_0_12px_rgba(249,115,22,0.4)]' : ''} />
              <span className="text-[0.45rem] font-black uppercase tracking-[0.2em]">{item.label}</span>
            </button>
          ))}
        </nav>
      )}
    </div>
  );

  if (!isMobile && (currentUser || appMode)) {
    return (
      <div className="min-h-screen bg-[#0c0a09] flex items-center justify-center p-12 overflow-hidden relative transition-all duration-1000 ease-in-out">
        <div className="absolute inset-0 bg-neural-mesh opacity-100"></div>
        <div className="relative w-[440px] h-[880px] bg-white rounded-[5rem] border-[14px] border-[#1c1917] shadow-[0_60px_120px_-30px_rgba(0,0,0,0.6)] ring-[1px] ring-white/10 overflow-hidden group transition-all duration-700">
          <div className="h-full w-full overflow-hidden rounded-[3.8rem]"><AppWrapper /></div>
        </div>
      </div>
    );
  }

  return <AppWrapper />;
};

export default App;

import React from 'react';
import { createRoot } from 'react-dom/client';
import App from './App';

const rootElement = document.getElementById('root');
if (!rootElement) {
  throw new Error("Could not find root element to mount to");
}

const root = createRoot(rootElement);
root.render(
  <React.StrictMode>
    <App />
  </React.StrictMode>
);

import React, { useState, useEffect } from 'react';
import { 
  User, Mail, Phone, Lock, Eye, EyeOff, 
  ArrowRight, BellRing, X as XIcon, UserPlus as UserPlusIcon, 
  Smartphone, Globe, CheckCircle2, ChevronRight, LogIn,
  ShieldCheck, Cpu, Fingerprint, Sparkles, Zap
} from 'lucide-react';
import { SurePathLogo } from './Navbar';
import { Language, UserRole } from '../types';
import { db, seedDatabase, User as DBUser } from '../db';
import { hashPassword, verifyPassword } from '../services/authService';
import { NeuralBot } from './car-wizard/WizardUI';

interface AuthGateProps {
  onAuthSuccess: (user: any) => void;
  initialLang?: Language;
}

const InputField = ({ icon: Icon, label, type, name, placeholder, value, onChange, showPass, setShowPass }: any) => (
  <div className="space-y-2 group animate-fade-in">
    <div className="flex items-center justify-between px-1">
      <label className="text-[0.6rem] font-black text-slate-400 dark:text-gray-500 uppercase tracking-[0.2em] transition-colors group-focus-within:text-primary-500">
        {label}
      </label>
    </div>
    <div className="relative">
      <div className="absolute left-5 top-1/2 -translate-y-1/2 text-slate-400 dark:text-gray-600 transition-all group-focus-within:text-primary-500 group-focus-within:scale-110">
        <Icon size={18} strokeWidth={2.5} />
      </div>
      <input 
        type={type === 'password' && showPass ? 'text' : type}
        placeholder={placeholder}
        required
        className="w-full pl-14 pr-6 py-4.5 bg-white dark:bg-white/[0.03] border-2 border-slate-100 dark:border-white/5 rounded-[1.8rem] outline-none transition-all font-bold text-sm text-slate-900 dark:text-white placeholder:text-slate-300 dark:placeholder:text-gray-700 shadow-sm focus:border-primary-500 focus:ring-4 focus:ring-primary-500/10 focus:shadow-xl"
        value={value}
        onChange={(e) => onChange(name, e.target.value)}
      />
      {type === 'password' && (
        <button 
          type="button"
          onClick={() => setShowPass(!showPass)}
          className="absolute right-5 top-1/2 -translate-y-1/2 text-slate-300 hover:text-primary-500 transition-colors p-1"
        >
          {showPass ? <EyeOff size={18}/> : <Eye size={18}/>}
        </button>
      )}
    </div>
  </div>
);

const AuthGate: React.FC<AuthGateProps> = ({ onAuthSuccess, initialLang = Language.EN }) => {
  const [mode, setMode] = useState<'LOGIN' | 'REGISTER' | 'VERIFY'>('LOGIN');
  const [showPass, setShowPass] = useState(false);
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState<string | null>(null);
  const [otp, setOtp] = useState('');
  const [generatedOtp, setGeneratedOtp] = useState('');
  const [showIncomingSim, setShowIncomingSim] = useState(false);

  const [formData, setFormData] = useState({
    name: '',
    email: '', 
    phone: '',
    password: '',
    role: UserRole.CUSTOMER
  });

  useEffect(() => {
    seedDatabase();
  }, []);

  const handleLogin = async (e: React.FormEvent) => {
    e.preventDefault();
    setLoading(true);
    setError(null);

    try {
      const user = await db.users.where('email').equals(formData.email).first();

      if (user && user.passwordHash && user.salt) {
        const isValid = await verifyPassword(formData.password, user.passwordHash, user.salt);
        if (isValid) {
          const { passwordHash, salt, ...safeUser } = user;
          onAuthSuccess(safeUser);
        } else {
          setLoading(false);
          setError("Kredensial tidak valid.");
        }
      } else {
        setLoading(false);
        setError("Akun tidak ditemukan.");
      }
    } catch (err) {
      console.error(err);
      setLoading(false);
      setError("Sistem sibuk. Coba lagi.");
    }
  };

  const handleRegisterStart = (e: React.FormEvent) => {
    e.preventDefault();
    if (formData.password.length < 6) {
        setError("Sandi minimal 6 karakter.");
        return;
    }
    setLoading(true);
    const newOtp = Math.floor(100000 + Math.random() * 900000).toString();
    setGeneratedOtp(newOtp);
    setTimeout(() => {
      setLoading(false);
      setMode('VERIFY');
      setTimeout(() => setShowIncomingSim(true), 800);
    }, 1200);
  };

  const handleVerifyFinal = async () => {
    if (otp !== generatedOtp) {
      setError("Kode OTP salah.");
      setOtp('');
      return;
    }
    setLoading(true);

    try {
      const existingUser = await db.users.where('email').equals(formData.email).first();
      if (existingUser) {
        setLoading(false);
        setError("Email sudah aktif.");
        return;
      }

      const { hash, salt } = await hashPassword(formData.password);

      const newUser: DBUser = {
        name: formData.name,
        email: formData.email,
        phone: formData.phone,
        passwordHash: hash,
        salt: salt,
        role: formData.role,
        nodeId: `SP-${Math.floor(1000 + Math.random()*8999)}`,
        memberSince: new Date().toISOString(),
        trustScore: 88,
        verified: false
      };

      const id = await db.users.add(newUser);
      const { passwordHash, salt: _, ...safeUser } = newUser;

      setTimeout(() => {
        onAuthSuccess({ ...safeUser, id });
      }, 800);
    } catch (err) {
      console.error(err);
      setLoading(false);
      setError("Registrasi gagal.");
    }
  };

  return (
    <div className="min-h-screen bg-[#fafaf9] dark:bg-[#050505] flex flex-col items-center justify-center p-6 relative overflow-hidden transition-colors duration-1000">

      {/* Immersive Neural Background */}
      <div className="absolute inset-0 pointer-events-none">
        <div className="absolute top-[-10%] left-[-10%] w-[800px] h-[800px] bg-primary-500/5 rounded-full blur-[120px] animate-pulse-slow"></div>
        <div className="absolute bottom-[-10%] right-[-10%] w-[800px] h-[800px] bg-emerald-500/5 rounded-full blur-[120px] animate-pulse-slow animation-delay-4000"></div>
        <div className="absolute inset-0 bg-neural-mesh opacity-20"></div>
      </div>

      {/* Push Notification Simulation */}
      {showIncomingSim && (
        <div className="fixed top-6 left-6 right-6 z-[300] animate-pop-in cursor-pointer" onClick={() => { setOtp(generatedOtp); setShowIncomingSim(false); }}>
           <div className="bg-white/90 dark:bg-slate-900/90 backdrop-blur-xl border-2 border-emerald-500/20 rounded-3xl p-5 shadow-2xl flex items-center gap-5">
              <div className="w-12 h-12 bg-emerald-500 rounded-2xl flex items-center justify-center text-white flex-shrink-0 shadow-lg shadow-emerald-500/20">
                 <BellRing size={24}/>
              </div>
              <div className="flex-1 min-w-0">
                 <div className="flex justify-between items-center mb-0.5">
                    <p className="text-[0.65rem] font-black text-slate-500 uppercase tracking-widest">System Registry</p>
                    <p className="text-[0.55rem] text-slate-400 font-bold">NOW</p>
                 </div>
                 <p className="text-sm font-bold text-slate-900 dark:text-white truncate">OTP Code: <span className="font-black text-emerald-500 text-lg tracking-wider">{generatedOtp}</span></p>
              </div>
           </div>
        </div>
      )}

      <div className="w-full max-w-md relative z-10 space-y-10">

        {/* Animated Mascot & Branding */}
        <div className="flex flex-col items-center group">
          <div className="relative mb-6 transition-transform duration-700 group-hover:scale-105">
            <div className="absolute inset-0 bg-primary-500/20 rounded-full blur-[50px] animate-pulse"></div>
            <NeuralBot className="w-40 h-40 relative drop-shadow-2xl" mood={loading ? 'thinking' : (mode === 'REGISTER' ? 'scanning' : 'happy')} />

            {/* The Logo requested to be retained */}
            <div className="absolute -bottom-2 -right-2 bg-white dark:bg-slate-900 p-2 rounded-2xl shadow-2xl border-2 border-slate-50 dark:border-white/10 animate-float">
                <SurePathLogo className="w-10 h-10" />
            </div>
          </div>

          <div className="text-center space-y-1">
            <h1 className="text-4xl font-black tracking-tighter text-slate-900 dark:text-white uppercase flex items-center justify-center gap-1.5 leading-none">
              SURE<span className="text-primary-500">PATH</span>
            </h1>
            <p className="text-[0.65rem] font-black text-slate-400 dark:text-gray-500 uppercase tracking-[0.4em] opacity-80">
              Neural Network Hub
            </p>
          </div>
        </div>

        {/* Authentication Card */}
        <div className="bg-white/80 dark:bg-black/40 backdrop-blur-3xl rounded-[3rem] p-3 border border-white/60 dark:border-white/10 shadow-[0_40px_100px_-20px_rgba(0,0,0,0.15)] relative overflow-hidden transition-all duration-500">

          {loading && (
            <div className="absolute inset-0 bg-white/60 dark:bg-black/80 backdrop-blur-md z-50 flex flex-col items-center justify-center gap-8 animate-fade-in rounded-[2.8rem]">
               <div className="relative">
                  <div className="w-20 h-20 border-4 border-primary-500/10 rounded-full"></div>
                  <div className="absolute inset-0 border-4 border-t-primary-500 rounded-full animate-spin"></div>
               </div>
               <p className="text-[0.7rem] font-black uppercase tracking-[0.4em] text-primary-500 animate-pulse">Synchronizing Node...</p>
            </div>
          )}

          <div className="px-6 py-10 md:px-8">
            {mode === 'VERIFY' ? (
              <div className="space-y-10 text-center animate-fade-in">
                  <div className="space-y-3">
                    <h3 className="text-2xl font-black text-slate-900 dark:text-white tracking-tight uppercase">Registry OTP</h3>
                    <p className="text-[0.75rem] text-slate-500 font-bold uppercase tracking-widest leading-relaxed">Verification link sent to hardware device.</p>
                  </div>

                  <div className="relative px-4">
                     <input 
                      type="tel"
                      maxLength={6}
                      className="w-full py-6 bg-transparent border-b-4 border-slate-100 dark:border-white/5 text-center text-5xl font-black tracking-[0.4em] text-primary-500 outline-none focus:border-primary-500 transition-all placeholder:text-slate-100 dark:placeholder:text-gray-900"
                      value={otp}
                      placeholder="000000"
                      onChange={(e) => {
                        setOtp(e.target.value.replace(/\D/g, ''));
                        setError(null);
                      }}
                    />
                  </div>
                  {error && <p className="text-[0.65rem] font-black text-rose-500 bg-rose-50 dark:bg-rose-900/10 p-3 rounded-2xl border border-rose-100 dark:border-rose-900/30 uppercase tracking-widest">{error}</p>}

                  <div className="space-y-4 pt-4">
                     <button 
                      onClick={handleVerifyFinal}
                      disabled={otp.length < 6}
                      className="w-full py-5 bg-slate-900 dark:bg-white text-white dark:text-black rounded-[1.8rem] font-black uppercase text-xs tracking-[0.3em] shadow-2xl disabled:opacity-30 disabled:cursor-not-allowed active:scale-95 transition-all hover:scale-[1.02]"
                    >
                      Verify Token
                    </button>
                    <button onClick={() => {setMode('REGISTER'); setOtp('');}} className="text-[0.55rem] font-black text-slate-400 uppercase tracking-widest hover:text-primary-500 transition-colors">Resend Data Stream</button>
                  </div>
              </div>
            ) : (
              <>
                  {/* Mode Toggler */}
                  <div className="flex bg-gray-100/60 dark:bg-white/5 p-1.5 rounded-[2rem] mb-10 relative">
                      <div 
                        className={`absolute top-1.5 bottom-1.5 w-[calc(50%-6px)] bg-white dark:bg-slate-800 rounded-[1.6rem] shadow-xl transition-transform duration-500 cubic-bezier(0.16, 1, 0.3, 1) ${mode === 'REGISTER' ? 'translate-x-full' : 'translate-x-0'}`}
                      ></div>

                      <button 
                          onClick={() => { setMode('LOGIN'); setError(null); }}
                          className={`flex-1 py-4 rounded-[1.6rem] text-[0.65rem] font-black uppercase tracking-widest transition-all relative z-10 flex items-center justify-center gap-2.5 ${mode === 'LOGIN' ? 'text-primary-600 dark:text-white' : 'text-slate-400 hover:text-slate-600'}`}
                      >
                          <LogIn size={16} strokeWidth={3}/> Sign In
                      </button>
                      <button 
                          onClick={() => { setMode('REGISTER'); setError(null); }}
                          className={`flex-1 py-4 rounded-[1.6rem] text-[0.65rem] font-black uppercase tracking-widest transition-all relative z-10 flex items-center justify-center gap-2.5 ${mode === 'REGISTER' ? 'text-primary-600 dark:text-white' : 'text-slate-400 hover:text-slate-600'}`}
                      >
                          <UserPlusIcon size={16} strokeWidth={3}/> Join Path
                      </button>
                  </div>

                  {/* Form Content */}
                  <form onSubmit={mode === 'REGISTER' ? handleRegisterStart : handleLogin} className="space-y-6">
                      {mode === 'REGISTER' && (
                        <div className="space-y-6 animate-fade-in">
                          <InputField icon={User} label="Legal Name" type="text" name="name" placeholder="Full Name" value={formData.name} onChange={(n:any, v:any)=>setFormData(f=>({...f,name:v}))} />
                          <InputField icon={Smartphone} label="Network ID (Phone)" type="tel" name="phone" placeholder="08xxxxxxxx" value={formData.phone} onChange={(n:any, v:any)=>setFormData(f=>({...f,phone:v}))} />
                        </div>
                      )}

                      <InputField 
                          icon={Globe} label="Registry Link (Email)" type="email" name="email" placeholder="name@domain.ai" value={formData.email} onChange={(n:any, v:any)=>setFormData(f=>({...f,email:v}))} 
                      />

                      <InputField 
                          icon={Lock} label="Access Key (Password)" type="password" name="password" placeholder="••••••••" value={formData.password} onChange={(n:any, v:any)=>setFormData(f=>({...f,password:v}))} showPass={showPass} setShowPass={setShowPass}
                      />

                      {error && (
                        <div className="p-4 bg-rose-50 dark:bg-rose-900/10 border-2 border-rose-100 dark:border-rose-900/20 rounded-2xl flex items-center gap-4 text-rose-500 animate-fade-in shadow-inner">
                           <ShieldCheck size={20} className="flex-shrink-0"/>
                           <p className="text-[0.7rem] font-black uppercase tracking-tight leading-tight">{error}</p>
                        </div>
                      )}

                      <div className="pt-4">
