  useEffect(() => {
    seedDatabase();
    const interval = setTimeout(() => setStatusMsg(t.statusReady), 1500);
    return () => clearTimeout(interval);
  }, [lang, t.statusReady]);

  useEffect(() => {
    let interval: any;
    if (timer > 0) {
      interval = setInterval(() => setTimer(t => t - 1), 1000);
    }
    return () => clearInterval(interval);
  }, [timer]);

  const handleAuth = async (e: React.FormEvent) => {
    e.preventDefault();
    setLoading(true);
    setError(null);
    setStatusMsg(t.statusProcess);

    try {
      if (mode === 'LOGIN') {
        const user = await db.users.where('email').equals(formData.email).first();
        if (user && user.passwordHash && user.salt) {
          const isValid = await verifyPassword(formData.password, user.passwordHash, user.salt);
          if (isValid) {
            setTimeout(() => onAuthSuccess(user), 1000);
          } else {
            setError(lang === Language.ID ? "Kredensial salah" : "Invalid credentials");
            setLoading(false);
          }
        } else {
          setError(lang === Language.ID ? "Akun tidak ditemukan" : "Account not found");
          setLoading(false);
        }
      } else {
        // Register Simulation
        const newOtp = Math.floor(100000 + Math.random() * 900000).toString();
        setGeneratedOtp(newOtp);
        setTimeout(() => {
          setMode('VERIFY');
          setLoading(false);
          setShowIncomingOtp(true);
          setTimer(60);
          setStatusMsg(lang === Language.ID ? "Aliran OTP Aktif" : "OTP Stream Active");
        }, 1500);
      }
    } catch (err) {
      setError("System cluster error");
      setLoading(false);
    }
  };

  const verifyOtp = async () => {
    if (otp === generatedOtp) {
      setLoading(true);
      setStatusMsg(lang === Language.ID ? "Menyinkronkan Akun..." : "Syncing Account...");

      try {
        const { hash, salt } = await hashPassword(formData.password);
        const newUser: DBUser = {
          name: formData.name,
          email: formData.email,
          phone: formData.phone,
          passwordHash: hash,
          salt: salt,
          role: UserRole.CUSTOMER,
          nodeId: `SP-NODE-${Math.floor(1000 + Math.random() * 9000)}`,
          memberSince: new Date().toISOString(),
          trustScore: 85,
          verified: true
        };
        const id = await db.users.add(newUser);
        onAuthSuccess({ ...newUser, id });
      } catch (e) {
        setError("Gagal mendaftarkan node");
        setLoading(false);
      }
    } else {
      setError(lang === Language.ID ? "Kode OTP tidak valid" : "Invalid OTP token");
      setOtp('');
    }
  };

