        <div className="absolute bottom-[-10%] right-[-10%] w-[800px] h-[800px] bg-brand-500/5 rounded-full blur-[100px] animate-pulse-slow animation-delay-2000"></div>
        <div className="absolute inset-0 bg-neural-mesh opacity-20"></div>
      </div>

      {/* Futuristic Incoming OTP Alert (Solusi Masalah OTP Tidak Muncul) */}
      {showIncomingOtp && (
        <div className="fixed top-8 left-6 right-6 z-[200] animate-pop-in">
           <div className="bg-slate-900/90 backdrop-blur-2xl border-2 border-primary-500/50 rounded-3xl p-5 shadow-[0_20px_60px_-10px_rgba(249,115,22,0.4)] flex items-center gap-5">
              <div className="w-12 h-12 bg-primary-500 rounded-2xl flex items-center justify-center text-white flex-shrink-0 animate-pulse">
                 <BellRing size={24}/>
              </div>
              <div className="flex-1 overflow-hidden">
                 <div className="flex justify-between items-center mb-0.5">
                    <p className="text-[0.6rem] font-black text-primary-400 uppercase tracking-[0.2em]">{t.otpNotify}</p>
                    <button onClick={() => setShowIncomingOtp(false)}><X size={14} className="text-gray-500"/></button>
                 </div>
                 <div className="flex items-center gap-3">
                    <span className="text-2xl font-black text-white tracking-[0.3em] font-mono">{generatedOtp}</span>
                    <button 
                      onClick={() => { setOtp(generatedOtp); setShowIncomingOtp(false); }}
                      className="ml-auto px-4 py-1.5 bg-primary-500 text-white rounded-xl text-[0.55rem] font-black uppercase tracking-widest hover:bg-primary-600 active:scale-95 transition-all"
                    >
                      Autofill
                    </button>
                 </div>
              </div>
           </div>
