      {/* Top Protocol Bar */}
      <div className="w-full flex items-center justify-between bg-white/40 dark:bg-black/40 backdrop-blur-xl border border-black/5 dark:border-white/5 p-4 rounded-3xl z-50 mb-10 shadow-sm">
