                {lang === Language.ID ? 'NODE AKSES AMAN' : 'SECURE NODE ACCESS'}
             </p>
          </div>
        </div>

        {/* Auth Interaction Card */}
        <div className="w-full bg-white/80 dark:bg-[#121212]/80 backdrop-blur-3xl rounded-[3rem] p-2 border border-white dark:border-white/5 shadow-2xl relative overflow-hidden group/card">

          {loading && (
