const WelcomeScreen = ({ onFinish }: { onFinish: () => void }) => {
  const [progress, setProgress] = useState(0);
  const [messageIdx, setMessageIdx] = useState(0);
  const [phase, setPhase] = useState<'booting' | 'syncing' | 'ready'>('booting');

  const messages = [
    "Neural Kernel Booting",
    "Syncing Bio-Metric Shield",
    "Calibrating Risk Matrix",
    "Establishing Secure Link",
    "SurePath Matrix Ready"
  ];

  useEffect(() => {
    const timer = setInterval(() => {
      setProgress(p => {
        if (p >= 100) {
          clearInterval(timer);
          return 100;
        }
        return p + 1.8;
      });
    }, 40);

    const msgTimer = setInterval(() => {
      setMessageIdx(i => {
        if (i >= messages.length - 1) {
          setPhase('ready');
          return i;
        }
        if (i === 1) setPhase('syncing');
        return i + 1;
      });
    }, 800);

    const finishTimer = setTimeout(onFinish, 4800);

    return () => {
      clearInterval(timer);
      clearInterval(msgTimer);
      clearTimeout(finishTimer);
    };
  }, [onFinish]);

  return (
    <div className="fixed inset-0 z-[5000] bg-[#fafaf9] dark:bg-[#050505] flex flex-col items-center justify-center overflow-hidden font-sans">
