                         </p>
                         <p className="text-[0.5rem] font-bold text-gray-400 uppercase tracking-widest">ID: {currentUser?.nodeId || 'SP-USER'}</p>
                      </div>
                   </div>
                   <div className="px-4 py-2 bg-emerald-500/10 text-emerald-600 rounded-xl">
                      <span className="text-[0.55rem] font-black uppercase tracking-widest">Active</span>
