      <linearGradient id="sureShieldGrad" x1="0%" y1="0%" x2="100%" y2="100%">
        <stop offset="0%" stopColor="#10b981" /> {/* Brand 500 */}
        <stop offset="100%" stopColor="#047857" /> {/* Brand 700 */}
      </linearGradient>
    </defs>
    <path 
      d="M50 5C50 5 15 15 15 45C15 75 50 95 50 95C50 95 85 75 85 45C85 15 50 5 50 5Z" 
      fill="url(#sureShieldGrad)" 
    />
    <path 
      d="M50 90C50 90 35 75 35 55C35 40 45 35 50 25C52 35 65 40 75 30C72 45 60 75 50 90Z" 
      fill="white" 
      opacity="0.9"
    />
    <path 
      d="M50 25C50 25 45 20 42 22C40 24 45 28 50 25Z" 
      fill="#ecfccb" 
    />
  </svg>
);

const Navbar: React.FC<NavbarProps> = ({ lang, setLang, darkMode, setDarkMode, currentPage, setPage }) => {
  const [isOpen, setIsOpen] = useState(false);
  const dropdownRef = useRef<HTMLDivElement>(null);

  const menuItems = [
    { id: 'home', label: lang === Language.EN ? 'Home' : 'Beranda' },
    { id: 'products', label: lang === Language.EN ? 'Products' : 'Produk' },
    { id: 'claim', label: lang === Language.EN ? 'Claim AI' : 'Klaim AI' },
    { id: 'investor', label: lang === Language.EN ? 'Investors' : 'Investor' },
    { id: 'about', label: lang === Language.EN ? 'About Us' : 'Tentang Kami' },
    { id: 'console', label: lang === Language.EN ? 'Partner' : 'Mitra' },
  ];

  return (
    <nav className="sticky top-0 z-[100] bg-white/80 dark:bg-black/80 backdrop-blur-2xl border-b border-slate-100 dark:border-white/5 transition-all duration-500">
      <div className="max-w-7xl mx-auto px-6 lg:px-12">
        <div className="flex justify-between h-24 items-center">
          <div className="flex items-center cursor-pointer gap-4 group" onClick={() => setPage('home')}>
            <SurePathLogo className="w-12 h-12" />
            <div className="flex flex-col justify-center">
              <span className="font-black text-2xl tracking-tighter text-slate-900 dark:text-white leading-none uppercase">
                Sure<span className="text-brand-500">Path</span>
              </span>
              <span className="text-[0.5rem] text-slate-400 dark:text-gray-500 font-black tracking-[0.3em] uppercase mt-1">
                {lang === Language.EN ? 'SMART PROTECTION PLATFORM' : 'PLATFORM PROTEKSI PINTAR'}
              </span>
            </div>
          </div>

          <div className="hidden xl:flex space-x-10">
            {menuItems.map((item) => (
              <a
                key={item.id}
                href={`#${item.id === 'claim' ? 'ai-claim' : item.id}`}
                className={`${
                  currentPage === item.id
                    ? 'text-primary-500 font-black'
                    : 'text-slate-500 dark:text-gray-400 hover:text-primary-500 font-bold'
                } transition-all text-[0.7rem] uppercase tracking-[0.2em] relative py-2 group`}
              >
                {item.label}
                <span className={`absolute bottom-0 left-0 h-0.5 bg-primary-500 transition-all ${currentPage === item.id ? 'w-full' : 'w-0 group-hover:w-full'}`}></span>
              </a>
            ))}
          </div>

          <div className="hidden md:flex items-center space-x-6">
            <div className="flex bg-slate-100 dark:bg-white/5 p-1 rounded-full border border-slate-200 dark:border-white/10">
               <button onClick={() => setLang(Language.ID)} className={`px-3 py-1 rounded-full text-[0.6rem] font-black transition-all ${lang === Language.ID ? 'bg-white dark:bg-gray-700 shadow-md text-slate-900' : 'text-slate-400'}`}>ID</button>
               <button onClick={() => setLang(Language.EN)} className={`px-3 py-1 rounded-full text-[0.6rem] font-black transition-all ${lang === Language.EN ? 'bg-white dark:bg-gray-700 shadow-md text-slate-900' : 'text-slate-400'}`}>EN</button>
            </div>

            <button
              onClick={() => setDarkMode(!darkMode)}
              className="p-3 bg-slate-50 dark:bg-white/5 rounded-2xl text-slate-400 hover:text-primary-500 transition-all shadow-inner"
            >
              {darkMode ? <Sun size={20} /> : <Moon size={20} />}
            </button>

            <button 
              className="bg-slate-900 dark:bg-white text-white dark:text-black hover:bg-primary-500 hover:scale-105 px-8 py-3 rounded-full text-[0.65rem] font-black uppercase tracking-[0.2em] transition-all shadow-xl active:scale-95 flex items-center gap-2"
              onClick={() => setPage('auth')}
            >
              {lang === Language.EN ? 'Login' : 'Masuk'}
            </button>
          </div>

          <div className="xl:hidden flex items-center gap-4">
             <button onClick={() => setIsOpen(!isOpen)} className="text-slate-900 dark:text-white">
                {isOpen ? <X size={28}/> : <Menu size={28}/>}
             </button>
          </div>
        </div>
      </div>

      {/* MOBILE MENU */}
      {isOpen && (
        <div className="xl:hidden bg-white dark:bg-slate-900 border-b border-slate-100 dark:border-white/5 animate-fade-in absolute w-full shadow-2xl">
          <div className="px-6 py-8 space-y-4">
            {menuItems.map((item) => (
              <a
                key={item.id}
                href={`#${item.id === 'claim' ? 'ai-claim' : item.id}`}
                onClick={() => { setIsOpen(false); if(item.id === 'home' || item.id === 'console') setPage('auth'); }}
                className="block text-lg font-black uppercase tracking-widest text-slate-500 hover:text-primary-500"
              >
                {item.label}
              </a>
            ))}
          </div>
        </div>
      )}
    </nav>
  );
};

export default Navbar;

import React, { useState, useEffect } from 'react';
import { SurePathLogo } from './Navbar';
import { 
  ArrowRight, Check, Globe, Users, Building2, 
  Activity, Smartphone, ShieldCheck, Heart,
  Zap, ChevronDown, Smile, Coffee, Sun,
  Umbrella, Briefcase, Star, ArrowUpRight, PlayCircle,
  Car, Plane, CheckCircle2, TrendingUp, Shield, Target,
  Award, Package, FileText, Lock, Server, Network, BarChart3,
  Cpu, Anchor, Stethoscope, Code, Tractor, Megaphone,
  X, CheckCircle, Plus
} from 'lucide-react';
import { Language } from '../types';

interface DesktopWebsiteProps {
  onEnterPortal: () => void;
  onAdminAccess: () => void;
  currentLang: Language;
  onLangChange: (l: Language) => void;
}

type ProductCategory = 'INDIVIDUAL' | 'BUSINESS' | 'BROKER';

const DesktopWebsite: React.FC<DesktopWebsiteProps> = ({ onEnterPortal, onAdminAccess, currentLang, onLangChange }) => {
  const [scrolled, setScrolled] = useState(false);
  const [scrollY, setScrollY] = useState(0);
  const [activeProductTab, setActiveProductTab] = useState<ProductCategory>('INDIVIDUAL');
  const [selectedProduct, setSelectedProduct] = useState<any | null>(null);

  useEffect(() => {
    const handleScroll = () => {
        setScrolled(window.scrollY > 20);
        setScrollY(window.scrollY);
