                  <div className="absolute inset-0 border-4 border-t-primary-500 rounded-full animate-spin"></div>
               </div>
               <p className="text-[0.65rem] font-black uppercase tracking-[0.4em] text-primary-500 animate-pulse">{statusMsg}</p>
            </div>
          )}

          <div className="px-6 py-10">
             {mode === 'VERIFY' ? (
                <div className="space-y-10 text-center animate-pop-in">
                   <div className="space-y-2">
                      <h3 className="text-2xl font-black uppercase tracking-tight">{t.otpTitle}</h3>
                      <p className="text-[0.7rem] font-bold text-slate-400 uppercase leading-relaxed tracking-wider">{t.otpSub}</p>
                   </div>
                   <div className="relative">
                      <input 
                        type="tel" maxLength={6} placeholder="000000"
                        className="w-full bg-transparent border-b-4 border-slate-100 dark:border-white/10 text-center text-6xl font-black tracking-[0.3em] text-primary-500 outline-none focus:border-primary-500 transition-all placeholder:text-gray-100 dark:placeholder:text-gray-900"
                        value={otp} onChange={(e) => { setOtp(e.target.value.replace(/\D/g,'')); setError(null); }}
