                   <div className="space-y-4">
                      <button 
                        onClick={verifyOtp}
                        disabled={otp.length < 6}
                        className="w-full py-6 bg-slate-900 dark:bg-white text-white dark:text-black rounded-3xl font-black uppercase text-[0.75rem] tracking-[0.3em] shadow-2xl active:scale-95 transition-all disabled:opacity-30 disabled:cursor-not-allowed border border-white/10"
                      >
                         {t.btnSync}
                      </button>
                      <button 
                        onClick={() => { setTimer(60); setShowIncomingOtp(true); }}
                        disabled={timer > 0}
                        className="w-full text-center text-[0.6rem] font-black text-slate-400 uppercase tracking-widest hover:text-primary-500 transition-colors disabled:opacity-50"
                      >
                         {t.resend} {timer > 0 && `(${timer}s)`}
                      </button>
                   </div>
                </div>
             ) : (
                <form onSubmit={handleAuth} className="space-y-6">
                   {/* Modern Mode Switcher */}
                   <div className="flex bg-gray-100 dark:bg-white/[0.03] p-1.5 rounded-[1.8rem] mb-6 relative overflow-hidden shadow-inner border border-black/5 dark:border-white/5">
                      <div className={`absolute top-1.5 bottom-1.5 w-[calc(50%-6px)] bg-white dark:bg-slate-800 rounded-2xl shadow-xl transition-all duration-500 ease-out ${mode === 'REGISTER' ? 'translate-x-full' : 'translate-x-0'}`}></div>
                      <button type="button" onClick={() => { setMode('LOGIN'); setError(null); }} className={`flex-1 py-3 rounded-2xl text-[0.65rem] font-black uppercase tracking-widest relative z-10 transition-all ${mode === 'LOGIN' ? 'text-primary-600 dark:text-white' : 'text-gray-400'}`}>
