                      </button>
                      <button type="button" onClick={() => { setMode('REGISTER'); setError(null); }} className={`flex-1 py-3 rounded-2xl text-[0.65rem] font-black uppercase tracking-widest relative z-10 transition-all ${mode === 'REGISTER' ? 'text-primary-600 dark:text-white' : 'text-gray-400'}`}>
                        {t.register}
                      </button>
                   </div>

                   {/* Role Selection Logic (More visual for Agent vs Customer) */}
                   {mode === 'REGISTER' && (
                       <div className="grid grid-cols-2 gap-3 mb-2">
                           <button 
                             type="button"
                             onClick={() => setLoginRole(UserRole.CUSTOMER)}
                             className={`p-3 rounded-2xl border-2 flex flex-col items-center gap-1.5 transition-all ${loginRole === UserRole.CUSTOMER ? 'border-primary-500 bg-primary-500/5 text-primary-500' : 'border-black/5 text-gray-400'}`}
                           >
                               <User size={18}/>
                               <span className="text-[0.5rem] font-black uppercase tracking-widest">Individual</span>
                           </button>
                           <button 
                             type="button"
                             onClick={() => setLoginRole(UserRole.AGENT)}
                             className={`p-3 rounded-2xl border-2 flex flex-col items-center gap-1.5 transition-all ${loginRole === UserRole.AGENT ? 'border-primary-500 bg-primary-500/5 text-primary-500' : 'border-black/5 text-gray-400'}`}
                           >
                               <Briefcase size={18}/>
                               <span className="text-[0.5rem] font-black uppercase tracking-widest">Agent Node</span>
                           </button>
                       </div>
                   )}

                   {mode === 'REGISTER' && (
                     <div className="space-y-5 animate-fade-in">
                       <InputField icon={VerifiedIcon} label={t.nameLabel} value={formData.name} onChange={(v:any)=>setFormData({...formData, name: v})} placeholder="Full Name" />
                       <InputField icon={Smartphone} label={t.phoneLabel} value={formData.phone} onChange={(v:any)=>setFormData({...formData, phone: v})} placeholder="0812..." />
                     </div>
                   )}

                   <InputField icon={Globe} label={t.emailLabel} type="email" value={formData.email} onChange={(v:any)=>setFormData({...formData, email: v})} placeholder="name@registry.ai" />
                   <InputField icon={KeyRound} label={t.passLabel} type="password" value={formData.password} onChange={(v:any)=>setFormData({...formData, password: v})} showPass={showPass} setShowPass={setShowPass} placeholder="••••••••" />

                   {error && (
                     <div className="p-4 bg-rose-500/10 border border-rose-500/20 rounded-[1.8rem] flex items-center gap-4 text-rose-500 animate-pop-in">
                        <ShieldAlert size={20} className="flex-shrink-0"/>
                        <p className="text-[0.65rem] font-black uppercase tracking-tight leading-tight">{error}</p>
                     </div>
                   )}

                   <div className="pt-4 space-y-6">
                      <button type="submit" className="w-full py-6 bg-slate-900 dark:bg-white text-white dark:text-black rounded-[2rem] font-black uppercase text-[0.8rem] tracking-[0.3em] shadow-2xl flex items-center justify-center gap-4 hover:scale-[1.02] active:scale-95 transition-all group overflow-hidden relative border border-white/10">
                         <span className="relative z-10">{mode === 'LOGIN' ? t.btnStore : t.btnCreate}</span>
                         <ArrowRight size={18} className="group-hover:translate-x-1.5 transition-transform relative z-10 text-primary-500" />
                         <div className="absolute inset-0 bg-primary-500 translate-x-[-100%] group-hover:translate-x-0 transition-transform duration-700 opacity-10"></div>
                      </button>

                      {/* Alternate Logins */}
                      <div className="flex items-center gap-4 py-2 opacity-50">
                         <div className="flex-1 h-px bg-slate-200 dark:bg-white/10"></div>
                         <span className="text-[0.5rem] font-black uppercase text-gray-400 tracking-widest">Sync Options</span>
                         <div className="flex-1 h-px bg-slate-200 dark:bg-white/10"></div>
                      </div>

                      <div className="grid grid-cols-2 gap-4">
                         <button 
                            type="button" 
                            onClick={handleBiometric}
                            className="flex items-center justify-center gap-3 py-3.5 bg-gray-50 dark:bg-white/5 border border-black/5 dark:border-white/5 rounded-2xl hover:bg-white dark:hover:bg-white/10 transition-all active:scale-95"
                         >
                            <Fingerprint size={16} className="text-primary-500" />
                            <span className="text-[0.55rem] font-black uppercase tracking-[0.2em] text-slate-500 dark:text-gray-300">{t.biometric}</span>
                         </button>
                         <button 
                            type="button" 
                            className="flex items-center justify-center gap-3 py-3.5 bg-gray-50 dark:bg-white/5 border border-black/5 dark:border-white/5 rounded-2xl hover:bg-white dark:hover:bg-white/10 transition-all active:scale-95"
                         >
                            <VerifiedIcon size={16} className="text-blue-500" />
                            <span className="text-[0.55rem] font-black uppercase tracking-[0.2em] text-slate-500 dark:text-gray-300">Google</span>
                         </button>
                      </div>

                      {mode === 'LOGIN' && (
                        <button type="button" className="w-full text-center text-[0.6rem] font-black text-slate-400 uppercase tracking-widest hover:text-primary-500 transition-colors pt-2">
                           {t.forgotPass}
                        </button>
                      )}
                   </div>
                </form>
             )}
          </div>
        </div>

        {/* Security Compliance Footer */}
        <div className="flex flex-col items-center gap-5 opacity-40 hover:opacity-100 transition-opacity duration-700 pb-8">
           <div className="flex items-center gap-8">
              <div className="flex items-center gap-2.5">
                 <ShieldIcon size={14} className="text-emerald-500"/>
                 <span className="text-[0.55rem] font-black uppercase tracking-widest text-slate-500 dark:text-gray-400">OJK REG v4.2</span>
              </div>
              <div className="flex items-center gap-2.5">
                 <Fingerprint size={14} className="text-blue-500"/>
                 <span className="text-[0.55rem] font-black uppercase tracking-widest text-slate-500 dark:text-gray-400">AES-256 GCM</span>
              </div>
           </div>
           <div className="flex items-center gap-3 px-6 py-2.5 bg-white/30 dark:bg-white/[0.03] rounded-full border border-black/5 dark:border-white/5">
              <BadgeCheck size={14} className="text-primary-500"/>
              <p className="text-[0.5rem] font-bold text-slate-400 dark:text-gray-500 uppercase tracking-[0.5em]">Neural Engine OS Active</p>
           </div>
        </div>
      </div>
    </div>
  );
};

