import React, { useState } from 'react';
import { 
  Database, Edit3, ChevronDown, User, Briefcase, Building2, 
  Zap, Timer, FileSearch, Sparkles, CheckCircle2, RefreshCw,
  Camera, ImagePlus, ShieldCheck, Hash, Palette, HardDrive,
  // Added Smartphone to fix compilation error on line 232 (usage in Manual Correction Hub)
  Info, AlertCircle, Loader2, ArrowRight, Smartphone
} from 'lucide-react';
import { CAR_DATABASE } from '../../constants';
import { extractStnkData } from '../../services/geminiService';
import { ScannerOverlay } from './WizardUI';

interface StepVehicleProps {
  vehicle: any;
  setVehicle: (v: any) => void;
  entryMode: 'DATABASE' | 'MANUAL';
  setEntryMode: (m: 'DATABASE' | 'MANUAL') => void;
  handlePlateChange: (e: React.ChangeEvent<HTMLInputElement>) => void;
  formatInputCurrency: (val: string) => string;
  loading: boolean;
  setLoading: (l: boolean) => void;
  loadingType: 'KTP' | 'STNK' | 'SURVEY' | null;
  setLoadingType: (t: 'KTP' | 'STNK' | 'SURVEY' | null) => void;
  setStnkResult?: (res: any) => void; 
}

const StepVehicle: React.FC<StepVehicleProps> = ({ 
  vehicle, setVehicle, entryMode, setEntryMode, handlePlateChange, formatInputCurrency,
  loading, setLoading, loadingType, setLoadingType, setStnkResult
}) => {
  const [extractedStnk, setExtractedStnk] = useState<any>(null);
  const [scanStatus, setScanStatus] = useState<'IDLE' | 'SCANNING' | 'SUCCESS' | 'ERROR'>('IDLE');

  const handleStnkAutofill = async (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (!file) return;

    setLoading(true);
    setLoadingType('STNK');
    setScanStatus('SCANNING');
    setExtractedStnk(null);

    const reader = new FileReader();
    reader.onload = async () => {
        const base64 = reader.result as string;
        const response = await extractStnkData(base64);
        setLoading(false);
        setLoadingType(null);

        if (response.success && response.data) {
            const data = response.data;
            const cleanData = {
                ownerName: data.owner || '',
                plate: data.plate || '',
                brand: data.brand || '',
                model: data.model || '',
                color: data.color || '',
                year: data.year || '',
                vin: data.vin || '',
                engine: data.engine || '',
                status: data.status || 'OK'
            };

            setExtractedStnk(cleanData);
            setScanStatus('SUCCESS');

            if (setStnkResult) setStnkResult(cleanData);

            const match = CAR_DATABASE.find(c => 
                data.brand.toUpperCase().includes(c.brand) || 
                (c.modelName && data.brand.toUpperCase().includes(c.modelName))
            );

            const yearInt = parseInt(data.year) || 2025;
            const price = match ? (match.yearPrices[yearInt] || match.yearPrices[2024] || 0) * 1000000 : 0;

            setVehicle((prev: any) => ({
                ...prev,
                brand: match?.brand || data.brand.split(' ')[0] || prev.brand,
                model: match?.modelName || data.model || prev.model,
                year: yearInt || prev.year,
                plate: data.plate || prev.plate,
                vin: data.vin || prev.vin,
                engine: data.engine || prev.engine,
                price: price || prev.price,
                manualPrice: !price,
                condition: yearInt < new Date().getFullYear() ? 'USED' : 'NEW'
            }));

            if (!match) setEntryMode('MANUAL');
            else setEntryMode('DATABASE');
        } else {
            setScanStatus('ERROR');
        }
    };
    reader.readAsDataURL(file);
  };

  const handleStnkEdit = (field: string, value: string) => {
      const newStnk = { ...extractedStnk, [field]: value.toUpperCase() };
      setExtractedStnk(newStnk);
      if (setStnkResult) setStnkResult(newStnk);

      if (field === 'brand') setVehicle((prev: any) => ({ ...prev, brand: value.toUpperCase() }));
      if (field === 'model') setVehicle((prev: any) => ({ ...prev, model: value.toUpperCase() }));
      if (field === 'plate') setVehicle((prev: any) => ({ ...prev, plate: value.toUpperCase() }));
      if (field === 'year') setVehicle((prev: any) => ({ ...prev, year: parseInt(value) || prev.year }));
  };

  return (
    <div className="space-y-8 animate-fade-in pb-10">
      {/* 1. NEURAL SCANNING ZONE */}
      {!extractedStnk && (
        <div className="space-y-4">
          <div className="flex items-center gap-3 px-2">
             <div className="w-8 h-8 bg-emerald-500/10 rounded-xl flex items-center justify-center text-emerald-500 shadow-inner">
                <ShieldCheck size={18}/>
             </div>
             <h4 className="text-[0.7rem] font-black uppercase tracking-[0.25em] text-gray-500">Auto-Registry Module</h4>
          </div>

          <label className="group relative block w-full aspect-[16/10] bg-white dark:bg-white/5 border-2 border-dashed border-gray-200 dark:border-white/10 rounded-[3rem] transition-all hover:border-emerald-500/50 hover:bg-emerald-500/[0.02] cursor-pointer overflow-hidden shadow-xl shadow-gray-100 dark:shadow-none">
             <div className="absolute inset-0 bg-neural-mesh opacity-10 pointer-events-none"></div>

             {/* Reticles */}
             <div className="absolute top-8 left-8 w-8 h-8 border-t-2 border-l-2 border-gray-200 dark:border-white/20 rounded-tl-2xl transition-colors group-hover:border-emerald-500"></div>
             <div className="absolute top-8 right-8 w-8 h-8 border-t-2 border-r-2 border-gray-200 dark:border-white/20 rounded-tr-2xl transition-colors group-hover:border-emerald-500"></div>
             <div className="absolute bottom-8 left-8 w-8 h-8 border-b-2 border-l-2 border-gray-200 dark:border-white/20 rounded-bl-2xl transition-colors group-hover:border-emerald-500"></div>
             <div className="absolute bottom-8 right-8 w-8 h-8 border-b-2 border-r-2 border-gray-200 dark:border-white/20 rounded-br-2xl transition-colors group-hover:border-emerald-500"></div>

             <div className="absolute inset-0 flex flex-col items-center justify-center text-center p-10">
                <div className="relative mb-6">
                   <div className="w-20 h-20 bg-gray-50 dark:bg-white/5 rounded-[2rem] flex items-center justify-center text-gray-300 transition-all group-hover:scale-110 group-hover:rotate-6 group-hover:text-emerald-500 shadow-inner">
                      <FileSearch size={40}/>
                   </div>
                   <div className="absolute -bottom-2 -right-2 bg-emerald-500 text-white p-2 rounded-xl shadow-lg animate-bounce">
                      <Sparkles size={16}/>
                   </div>
                </div>
                <div className="space-y-2">
                   <p className="text-xl font-black uppercase tracking-tighter text-gray-900 dark:text-white">Snap or Upload STNK</p>
                   <p className="text-[0.6rem] font-bold text-gray-400 uppercase tracking-widest leading-relaxed max-w-[240px]">Neural Vision will extract identity, plate, and technical specs instantly.</p>
                </div>

                <div className="mt-8 flex items-center gap-3 px-6 py-2.5 bg-gray-50 dark:bg-white/10 rounded-full border border-black/5 dark:border-white/5 text-[0.55rem] font-black uppercase tracking-widest text-gray-400 group-hover:text-emerald-500 transition-colors">
                   <Camera size={14}/> START SCAN
                </div>
             </div>
             <input type="file" accept="image/*" className="hidden" onChange={handleStnkAutofill} />

             {loading && loadingType === 'STNK' && (
                <div className="absolute inset-0 z-50 bg-black/80 backdrop-blur-md flex flex-col items-center justify-center text-white animate-fade-in">
                   <div className="w-24 h-24 mb-6 relative">
                      <div className="absolute inset-0 border-4 border-emerald-500/20 rounded-full"></div>
                      <div className="absolute inset-0 border-4 border-t-emerald-500 rounded-full animate-spin"></div>
                      <div className="absolute inset-0 flex items-center justify-center">
                         <Microscope size={32} className="text-emerald-500 animate-pulse"/>
                      </div>
                   </div>
                   <p className="text-[0.8rem] font-black uppercase tracking-[0.4em] animate-pulse">Scanning Protocol...</p>
                </div>
             )}
          </label>

          <button 
            onClick={() => setEntryMode('MANUAL')}
            className="w-full py-4 text-[0.55rem] font-black text-gray-400 hover:text-primary-500 uppercase tracking-[0.3em] transition-colors"
          >
            - Skip to manual entry -
          </button>
        </div>
      )}

      {/* 2. SUCCESS CHECKLIST & VERIFICATION */}
      {extractedStnk && (
        <div className="space-y-6 animate-pop-in">
           <div className="p-8 bg-emerald-500/10 border border-emerald-500/20 rounded-[3rem] relative overflow-hidden group">
              <div className="absolute right-0 top-0 p-8 opacity-5 pointer-events-none group-hover:opacity-10 transition-opacity"><ShieldCheck size={180}/></div>
              <div className="flex flex-col sm:flex-row justify-between items-start gap-8 relative z-10">
                 <div className="flex-1 space-y-6">
                    <div className="space-y-1">
                       <h4 className="text-2xl font-black text-emerald-900 dark:text-emerald-400 uppercase tracking-tighter">Extraction Results</h4>
                       <p className="text-[0.6rem] font-bold text-emerald-700/60 uppercase tracking-widest">Neural Registry Node Verified</p>
                    </div>

                    {/* Live Parameter Checklist */}
                    <div className="grid grid-cols-2 gap-3">
                       {[
                         { id: 'owner', label: 'Identity', val: extractedStnk.ownerName },
                         { id: 'plate', label: 'Registry', val: extractedStnk.plate },
                         { id: 'vin', label: 'Chassis', val: extractedStnk.vin },
                         { id: 'specs', label: 'Technical', val: extractedStnk.model }
                       ].map(p => (
                         <div key={p.id} className="flex items-center gap-3 p-3 bg-white dark:bg-emerald-900/20 rounded-2xl border border-emerald-500/20 shadow-sm transition-transform hover:scale-[1.02]">
                            <div className="w-6 h-6 rounded-lg bg-emerald-500 flex items-center justify-center text-white"><Check size={14} strokeWidth={4}/></div>
                            <div className="overflow-hidden">
                               <p className="text-[0.45rem] font-black text-emerald-600 uppercase leading-none mb-1">{p.label}</p>
                               <p className="text-[0.65rem] font-black text-emerald-900 dark:text-emerald-100 truncate">{p.val}</p>
                            </div>
                         </div>
                       ))}
                    </div>
                 </div>
                 <button 
                   onClick={() => setExtractedStnk(null)}
                   className="p-4 bg-white dark:bg-emerald-900/40 rounded-3xl text-emerald-600 shadow-xl border border-emerald-100 dark:border-emerald-800 hover:rotate-12 transition-all active:scale-95"
                 >
                    <RefreshCw size={24}/>
                 </button>
              </div>
           </div>

           {/* Manual Correction Hub */}
           <div className="grid grid-cols-1 md:grid-cols-2 gap-5">
              <div className="p-6 bg-white dark:bg-white/5 border border-black/5 dark:border-white/5 rounded-[2.5rem] shadow-xl space-y-5 group hover:border-emerald-500/20 transition-all">
                 <div className="flex items-center gap-3 text-emerald-500">
                    <User size={16}/>
                    <span className="text-[0.55rem] font-black uppercase tracking-widest">Owner Identity</span>
                 </div>
                 <div className="space-y-1">
                    <label className="text-[0.45rem] font-black text-gray-400 uppercase tracking-widest ml-1">Legal Name</label>
                    <input 
                       value={extractedStnk.ownerName} 
                       onChange={(e) => handleStnkEdit('ownerName', e.target.value)}
                       className="w-full px-5 py-4 bg-gray-50 dark:bg-black/20 border border-black/5 dark:border-white/5 rounded-2xl text-xs font-black uppercase outline-none focus:border-emerald-500 transition-all"
                    />
                 </div>
              </div>

              <div className="p-6 bg-white dark:bg-white/5 border border-black/5 dark:border-white/5 rounded-[2.5rem] shadow-xl space-y-5 group hover:border-emerald-500/20 transition-all">
                 <div className="flex items-center gap-3 text-blue-500">
                    <Smartphone size={16}/>
                    <span className="text-[0.55rem] font-black uppercase tracking-widest">Registry Node</span>
                 </div>
                 <div className="space-y-1">
                    <label className="text-[0.45rem] font-black text-gray-400 uppercase tracking-widest ml-1">License Plate</label>
                    <input 
                       value={extractedStnk.plate} 
                       onChange={(e) => handleStnkEdit('plate', e.target.value)}
                       className="w-full px-5 py-4 bg-gray-50 dark:bg-black/20 border border-black/5 dark:border-white/10 rounded-2xl text-lg font-mono font-black text-center uppercase tracking-widest outline-none focus:border-emerald-500 transition-all"
                    />
                 </div>
              </div>
           </div>
        </div>
      )}

      {/* 3. HARDWARE & USAGE MATRIX (Traditional Form - always shown or toggleable) */}
      <div className="space-y-6">
        <div className="flex items-center justify-between px-2">
           <h4 className="text-[0.7rem] font-black uppercase tracking-[0.2em] text-gray-500">Technical Configuration</h4>
           <div className="flex bg-gray-100 dark:bg-white/10 p-1 rounded-xl shadow-inner border border-black/5">
              <button onClick={() => setEntryMode('DATABASE')} className={`px-4 py-1.5 rounded-lg text-[0.55rem] font-black uppercase transition-all ${entryMode === 'DATABASE' ? 'bg-white dark:bg-gray-700 text-primary-500 shadow-md' : 'text-gray-400'}`}>Database</button>
              <button onClick={() => setEntryMode('MANUAL')} className={`px-4 py-1.5 rounded-lg text-[0.55rem] font-black uppercase transition-all ${entryMode === 'MANUAL' ? 'bg-white dark:bg-gray-700 text-primary-500 shadow-md' : 'text-gray-400'}`}>Manual</button>
