              {entryMode === 'DATABASE' ? (
                 <div className="relative">
                    <select 
                       className="w-full p-5 rounded-[2rem] bg-white dark:bg-white/[0.03] border border-black/5 dark:border-white/5 outline-none focus:border-primary-500 font-black text-xs uppercase shadow-sm appearance-none"
                       value={vehicle.brand}
                       onChange={(e) => {
                          const unit = CAR_DATABASE.find(c => c.brand === e.target.value);
                          setVehicle({...vehicle, brand: e.target.value, model: unit?.modelName || '', price: (unit?.yearPrices[2024] || 0) * 1000000});
                       }}
                    >
                       <option value="">Select Brand</option>
                       {Array.from(new Set(CAR_DATABASE.map(c => c.brand))).sort().map(b => <option key={b} value={b}>{b}</option>)}
                    </select>
                    <ChevronDown size={18} className="absolute right-6 top-1/2 -translate-y-1/2 text-gray-400 pointer-events-none"/>
                 </div>
              ) : (
                 <input className="w-full p-5 rounded-[2rem] bg-white dark:bg-white/[0.03] border border-black/5 dark:border-white/5 outline-none focus:border-primary-500 font-black text-xs uppercase" value={vehicle.brand} onChange={(e) => handleStnkEdit('brand', e.target.value)}/>
              )}
           </div>

           <div className="space-y-2">
              <label className="text-[0.5rem] font-black uppercase text-gray-400 ml-2 tracking-widest">Model Cluster</label>
              <input 
                 placeholder="e.g. AVANZA 1.3 G"
                 className="w-full p-5 rounded-[2rem] bg-white dark:bg-white/[0.03] border border-black/5 dark:border-white/5 outline-none focus:border-primary-500 font-black text-xs uppercase" 
                 value={vehicle.model} 
                 onChange={(e) => handleStnkEdit('model', e.target.value)}
              />
           </div>
        </div>

        <div className="grid grid-cols-2 md:grid-cols-4 gap-4">
           <div className="space-y-2 col-span-2 md:col-span-1">
              <label className="text-[0.5rem] font-black uppercase text-gray-400 ml-2 tracking-widest">Unit Year</label>
              <select 
                 className="w-full p-5 rounded-[1.8rem] bg-white dark:bg-white/[0.03] border border-black/5 dark:border-white/5 outline-none focus:border-primary-500 font-black text-xs appearance-none"
                 value={vehicle.year}
                 onChange={(e) => handleStnkEdit('year', e.target.value)}
              >
                 {Array.from({length: 12}, (_, i) => 2025 - i).map(y => <option key={y} value={y}>{y}</option>)}
              </select>
           </div>
           <div className="space-y-2 col-span-2 md:col-span-3">
              <label className="text-[0.5rem] font-black uppercase text-gray-400 ml-2 tracking-widest">Estimated Value (OTR)</label>
              <div className="relative">
