const AuthGate: React.FC<AuthGateProps> = ({ onAuthSuccess, initialLang = Language.ID }) => {
  const [lang, setLang] = useState<Language>(initialLang);
  const [mode, setMode] = useState<'LOGIN' | 'REGISTER' | 'VERIFY' | 'BIOMETRIC'>('LOGIN');
  const [showPass, setShowPass] = useState(false);
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState<string | null>(null);
  const [otp, setOtp] = useState('');
  const [generatedOtp, setGeneratedOtp] = useState('');
  const [showIncomingOtp, setShowIncomingOtp] = useState(false);
  const [statusMsg, setStatusMsg] = useState(translations[lang].statusInit);
  const [timer, setTimer] = useState(0);
  const [loginRole, setLoginRole] = useState<UserRole>(UserRole.CUSTOMER);

  const t = translations[lang];
  const [formData, setFormData] = useState({ name: '', email: '', phone: '', password: '' });

  useEffect(() => {
    seedDatabase();
    const interval = setTimeout(() => setStatusMsg(t.statusReady), 1500);
    return () => clearTimeout(interval);
  }, [lang, t.statusReady]);

  const handleAuth = async (e: React.FormEvent) => {
    e.preventDefault();
    setLoading(true);
    setError(null);
    setStatusMsg(t.statusProcess);

    try {
      if (mode === 'LOGIN') {
        const user = await db.users.where('email').equals(formData.email).first();
        if (user && user.passwordHash && user.salt) {
          const isValid = await verifyPassword(formData.password, user.passwordHash, user.salt);
          if (isValid) {
            setTimeout(() => onAuthSuccess(user), 1000);
          } else {
            setError(lang === Language.ID ? "Ups! Kata sandi kamu salah nih." : "Oops! Incorrect password.");
            setLoading(false);
          }
        } else {
          setError(lang === Language.ID ? "Email tidak ditemukan. Yuk daftar dulu!" : "Email not found. Please sign up first.");
          setLoading(false);
        }
      } else {
        const newOtp = Math.floor(100000 + Math.random() * 900000).toString();
        setGeneratedOtp(newOtp);
        setTimeout(() => {
          setMode('VERIFY');
          setLoading(false);
          setShowIncomingOtp(true);
          setTimer(60);
          setStatusMsg(lang === Language.ID ? "Kode Verifikasi Terkirim" : "Verification Code Sent");
        }, 1500);
      }
    } catch (err) {
      setError("Terjadi gangguan sistem. Coba lagi ya.");
      setLoading(false);
    }
  };

  const verifyOtp = async () => {
    if (otp === generatedOtp) {
      setLoading(true);
      setStatusMsg(lang === Language.ID ? "Menyiapkan akunmu..." : "Preparing your account...");
      const { hash, salt } = await hashPassword(formData.password);
      const newUser: DBUser = {
        name: formData.name, email: formData.email, phone: formData.phone,
        passwordHash: hash, salt: salt, role: loginRole,
        nodeId: `SP-NODE-${Math.floor(1000 + Math.random() * 9000)}`,
        memberSince: new Date().toISOString(), trustScore: 85, verified: true
      };
      const id = await db.users.add(newUser);
      setTimeout(() => onAuthSuccess({ ...newUser, id }), 1000);
    } else {
      setError(lang === Language.ID ? "Kode verifikasi salah." : "Invalid code.");
      setOtp('');
    }
  };

  return (
    <div className="min-h-screen bg-[#fafaf9] dark:bg-[#080707] flex flex-col items-center p-6 relative overflow-hidden transition-colors duration-700">

      {showIncomingOtp && (
        <div className="fixed top-6 left-6 right-6 z-[300] animate-pop-in">
           <div className="bg-slate-900/95 dark:bg-white/95 backdrop-blur-xl rounded-[2rem] p-5 shadow-2xl flex items-center gap-5 border border-white/10">
              <div className="w-12 h-12 bg-primary-500 rounded-xl flex items-center justify-center text-white">
                 <BellRing size={24}/>
              </div>
              <div className="flex-1">
                 <p className="text-[0.6rem] font-black text-primary-400 uppercase tracking-widest">{t.otpNotify}</p>
                 <div className="flex items-center gap-4">
                    <span className="text-2xl font-black text-white dark:text-black tracking-[0.2em] font-mono">{generatedOtp}</span>
                    <button onClick={() => { setOtp(generatedOtp); setShowIncomingOtp(false); }} className="ml-auto px-4 py-1.5 bg-primary-500 text-white rounded-lg text-xs font-bold">Salin</button>
                 </div>
              </div>
           </div>
        </div>
      )}

      <div className="w-full flex items-center justify-between mb-10 z-50">
        <div className="flex items-center gap-2">
          <div className="w-2 h-2 rounded-full bg-emerald-500 animate-pulse shadow-[0_0_8px_#10b981]"></div>
          <p className="text-[0.6rem] font-bold text-slate-500 dark:text-gray-400 uppercase tracking-widest">{statusMsg}</p>
        </div>
        <div className="flex bg-gray-100 dark:bg-white/10 p-1 rounded-xl">
           <button onClick={() => setLang(Language.ID)} className={`px-3 py-1 rounded-lg text-[0.6rem] font-bold ${lang === Language.ID ? 'bg-white dark:bg-slate-800 text-primary-500 shadow-sm' : 'text-gray-400'}`}>ID</button>
           <button onClick={() => setLang(Language.EN)} className={`px-3 py-1 rounded-lg text-[0.6rem] font-bold ${lang === Language.EN ? 'bg-white dark:bg-slate-800 text-primary-500 shadow-sm' : 'text-gray-400'}`}>EN</button>
        </div>
      </div>

      <div className="w-full max-w-sm flex flex-col items-center space-y-8 flex-1 relative z-10">
        <div className="flex flex-col items-center">
          <div className="relative mb-6">
            <div className="p-6 bg-white dark:bg-[#111] rounded-[2.5rem] shadow-xl border border-black/5 dark:border-white/5 relative overflow-hidden">
               <SurePathLogo className="w-16 h-16 relative z-10" />
            </div>
            <div className="absolute -bottom-2 -right-2 w-10 h-10">
                <NeuralBot mood={loading ? 'thinking' : 'happy'} className="w-full h-full" />
            </div>
          </div>
          <h1 className="text-3xl font-black tracking-tighter uppercase text-slate-900 dark:text-white leading-none">
             Sure<span className="text-primary-500">Path</span>
          </h1>
          <p className="text-[0.6rem] font-bold text-slate-400 uppercase tracking-[0.4em] mt-2">Personal Protection Hub</p>
        </div>

        <div className="w-full bg-white dark:bg-[#0c0c0c] rounded-[3rem] p-8 shadow-2xl border border-slate-100 dark:border-white/5">
          {mode === 'VERIFY' ? (
            <div className="space-y-8 text-center animate-pop-in">
              <div className="space-y-2">
                <h3 className="text-xl font-black uppercase">{t.otpTitle}</h3>
                <p className="text-xs text-slate-500 font-medium">{t.otpSub}</p>
              </div>
              <input 
                type="tel" maxLength={6} placeholder="000000"
                className="w-full bg-transparent border-b-2 border-slate-100 text-center text-4xl font-black tracking-[0.4em] text-primary-500 outline-none focus:border-primary-500 transition-all"
                value={otp} onChange={(e) => { setOtp(e.target.value.replace(/\D/g,'')); setError(null); }}
              />
              <button onClick={verifyOtp} disabled={otp.length < 6} className="w-full py-4 bg-slate-900 dark:bg-white text-white dark:text-black rounded-2xl font-bold uppercase text-sm shadow-xl active:scale-95 disabled:opacity-30">{t.btnSync}</button>
            </div>
          ) : (
            <form onSubmit={handleAuth} className="space-y-6">
              <div className="flex bg-gray-100 dark:bg-white/[0.05] p-1 rounded-2xl mb-4">
                <button type="button" onClick={() => setMode('LOGIN')} className={`flex-1 py-2.5 rounded-xl text-[0.65rem] font-black uppercase tracking-wider transition-all ${mode === 'LOGIN' ? 'bg-white dark:bg-slate-700 text-primary-500 shadow-md' : 'text-gray-400'}`}>{t.login}</button>
                <button type="button" onClick={() => setMode('REGISTER')} className={`flex-1 py-2.5 rounded-xl text-[0.65rem] font-black uppercase tracking-wider transition-all ${mode === 'REGISTER' ? 'bg-white dark:bg-slate-700 text-primary-500 shadow-md' : 'text-gray-400'}`}>{t.register}</button>
              </div>

              {mode === 'REGISTER' && (
                <div className="space-y-4">
                  <InputField icon={User} label={t.nameLabel} value={formData.name} onChange={(v:any)=>setFormData({...formData, name: v})} placeholder="Nama Sesuai KTP" />
                  <InputField icon={Smartphone} label={t.phoneLabel} value={formData.phone} onChange={(v:any)=>setFormData({...formData, phone: v})} placeholder="0812..." />
                </div>
              )}

              <InputField icon={Globe} label={t.emailLabel} type="email" value={formData.email} onChange={(v:any)=>setFormData({...formData, email: v})} placeholder="email@kamu.com" />
              <InputField icon={KeyRound} label={t.passLabel} type="password" value={formData.password} onChange={(v:any)=>setFormData({...formData, password: v})} showPass={showPass} setShowPass={setShowPass} placeholder="••••••••" />

              {error && <p className="text-[0.6rem] font-bold text-rose-500 text-center uppercase tracking-wider">{error}</p>}

              <button type="submit" className="w-full py-4 bg-slate-900 dark:bg-white text-white dark:text-black rounded-2xl font-bold uppercase text-sm shadow-xl hover:scale-[1.02] active:scale-95 transition-all flex items-center justify-center gap-2 group">
                 {mode === 'LOGIN' ? t.btnStore : t.btnCreate} <ArrowRight size={18} className="group-hover:translate-x-1 transition-transform"/>
              </button>

              {mode === 'LOGIN' && <button type="button" className="w-full text-center text-[0.6rem] font-bold text-slate-400 uppercase hover:text-primary-500">{t.forgotPass}</button>}
            </form>
          )}
        </div>

        <div className="flex flex-col items-center gap-4 opacity-40 py-6">
           <div className="flex items-center gap-6">
              <div className="flex items-center gap-2"><ShieldIcon size={14} className="text-emerald-500"/><span className="text-[0.55rem] font-bold uppercase">OJK Diawasi</span></div>
              <div className="flex items-center gap-2"><Fingerprint size={14} className="text-blue-500"/><span className="text-[0.55rem] font-bold uppercase">Data Aman</span></div>
           </div>
        </div>
      </div>
    </div>
  );
};

