    setLoadingType('STNK');
    setExtractedStnk(null);

    const reader = new FileReader();
    reader.onload = async () => {
        const base64 = reader.result as string;
        const response = await extractStnkData(base64);
        setLoading(false);
        setLoadingType(null);

        if (response.success && response.data) {
            const data = response.data;
            const cleanData = {
                ownerName: data.owner || '',
                plate: data.plate || '',
                brand: data.brand || '',
                model: data.model || '',
                color: data.color || '',
                year: data.year || '',
                vin: data.vin || '',
                engine: data.engine || '',
                status: data.status || 'OK'
            };

            setExtractedStnk(cleanData);
            if (setStnkResult) setStnkResult(cleanData);

            const match = CAR_DATABASE.find(c => 
                data.brand.toUpperCase().includes(c.brand) || 
                (c.modelName && data.brand.toUpperCase().includes(c.modelName))
            );

            const yearInt = parseInt(data.year) || 2025;
            const price = match ? (match.yearPrices[yearInt] || match.yearPrices[2024] || 0) * 1000000 : 0;

            setVehicle((prev: any) => ({
                ...prev,
                brand: match?.brand || data.brand.split(' ')[0] || prev.brand,
                model: match?.modelName || data.model || prev.model,
                year: yearInt || prev.year,
                plate: data.plate || prev.plate,
                vin: data.vin || prev.vin,
                engine: data.engine || prev.engine,
                price: price || prev.price,
                manualPrice: !price,
                condition: yearInt < new Date().getFullYear() ? 'USED' : 'NEW'
            }));

            if (!match) setEntryMode('MANUAL');
            else setEntryMode('DATABASE');
        }
    };
    reader.readAsDataURL(file);
  };

  return (
    <PageTransition>
      <div className="space-y-8 pb-10">
        <div className="space-y-4">
          <div className="flex items-center gap-3 px-2">
             <div className="w-8 h-8 bg-emerald-500/10 rounded-xl flex items-center justify-center text-emerald-500">
                <ShieldCheck size={18}/>
             </div>
             <h4 className="text-[0.7rem] font-black uppercase tracking-[0.25em] text-gray-500">Data Mobil Kamu</h4>
          </div>

          {!extractedStnk ? (
            <label className="group relative block w-full aspect-[16/10] bg-white dark:bg-white/5 border-2 border-dashed border-gray-200 dark:border-white/10 rounded-[3rem] transition-all hover:border-emerald-500/50 hover:bg-emerald-500/[0.02] cursor-pointer overflow-hidden shadow-sm">
               <div className="absolute inset-0 flex flex-col items-center justify-center text-center p-8">
                  <div className="w-16 h-16 bg-gray-50 dark:bg-white/5 rounded-2xl flex items-center justify-center text-gray-300 mb-4 group-hover:scale-110 transition-transform">
                     <FileSearch size={32}/>
                  </div>
                  <div className="space-y-1">
                     <p className="text-lg font-black uppercase tracking-tight text-gray-900 dark:text-white">Foto STNK Kamu</p>
                     <p className="text-xs text-gray-400 font-medium max-w-[200px]">Cukup upload foto STNK, biar AI kami yang isi datanya otomatis.</p>
                  </div>
                  <div className="mt-6 flex items-center gap-2 px-5 py-2 bg-emerald-500 text-white rounded-full text-[0.6rem] font-black uppercase shadow-lg active:scale-95 transition-all">
                     <Camera size={14}/> MULAI SCAN
                  </div>
               </div>
               <input type="file" accept="image/*" className="hidden" onChange={handleStnkAutofill} />
               {loading && loadingType === 'STNK' && <ScannerOverlay label="Membaca STNK..." />}
            </label>
          ) : (
            <div className="p-6 bg-emerald-50 dark:bg-emerald-950/20 border border-emerald-200 dark:border-emerald-900/40 rounded-[2.5rem] animate-pop-in">
               <div className="flex items-center justify-between mb-4">
                  <div className="flex items-center gap-3">
                     <div className="w-8 h-8 bg-emerald-500 rounded-lg flex items-center justify-center text-white"><CheckCircle2 size={18}/></div>
                     <p className="text-sm font-black uppercase tracking-tight">Data Berhasil Diambil!</p>
                  </div>
                  <button onClick={() => setExtractedStnk(null)} className="p-2 text-emerald-600 hover:rotate-90 transition-all"><RefreshCw size={18}/></button>
               </div>
               <div className="grid grid-cols-2 gap-4">
                  <div className="p-3 bg-white/50 dark:bg-black/20 rounded-xl border border-emerald-100 dark:border-emerald-900/30">
                     <p className="text-[0.5rem] font-bold text-gray-400 uppercase mb-0.5">Pemilik</p>
                     <p className="text-xs font-black uppercase truncate">{extractedStnk.ownerName}</p>
                  </div>
                  <div className="p-3 bg-white/50 dark:bg-black/20 rounded-xl border border-emerald-100 dark:border-emerald-900/30">
                     <p className="text-[0.5rem] font-bold text-gray-400 uppercase mb-0.5">Plat Nomor</p>
                     <p className="text-xs font-black uppercase">{extractedStnk.plate}</p>
                  </div>
               </div>
            </div>
          )}
        </div>

        <div className="space-y-6">
          <div className="flex items-center justify-between px-2">
             <h4 className="text-[0.7rem] font-black uppercase tracking-[0.2em] text-gray-500">Atau Isi Manual</h4>
             <div className="flex bg-gray-100 dark:bg-white/10 p-1 rounded-xl">
                <button onClick={() => setEntryMode('DATABASE')} className={`px-3 py-1 rounded-lg text-[0.6rem] font-black uppercase transition-all ${entryMode === 'DATABASE' ? 'bg-white text-primary-500 shadow-sm' : 'text-gray-400'}`}>Cari Mobil</button>
                <button onClick={() => setEntryMode('MANUAL')} className={`px-3 py-1 rounded-lg text-[0.6rem] font-black uppercase transition-all ${entryMode === 'MANUAL' ? 'bg-white text-primary-500 shadow-sm' : 'text-gray-400'}`}>Tulis Manual</button>
             </div>
          </div>

          <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
             <div className="space-y-2">
                <label className="text-[0.5rem] font-bold uppercase text-gray-400 ml-2">Merk Mobil</label>
                {entryMode === 'DATABASE' ? (
                   <div className="relative">
                      <select 
                         className="w-full p-4 rounded-2xl bg-white dark:bg-white/5 border border-black/5 outline-none focus:border-primary-500 font-bold text-sm appearance-none"
                         value={vehicle.brand}
                         onChange={(e) => {
                            const unit = CAR_DATABASE.find(c => c.brand === e.target.value);
                            setVehicle({...vehicle, brand: e.target.value, model: unit?.modelName || '', price: (unit?.yearPrices[2024] || 0) * 1000000});
                         }}
                      >
                         <option value="">Pilih Merk</option>
                         {Array.from(new Set(CAR_DATABASE.map(c => c.brand))).sort().map(b => <option key={b} value={b}>{b}</option>)}
                      </select>
                      <ChevronDown size={18} className="absolute right-4 top-1/2 -translate-y-1/2 text-gray-400 pointer-events-none"/>
                   </div>
                ) : (
                   <input className="w-full p-4 rounded-2xl bg-white dark:bg-white/5 border border-black/5 outline-none focus:border-primary-500 font-bold text-sm uppercase" value={vehicle.brand} onChange={(e) => setVehicle({...vehicle, brand: e.target.value.toUpperCase()})}/>
                )}
             </div>
             <div className="space-y-2">
