             </div>
          </div>
        </div>

        <div className="p-6 bg-gray-50 dark:bg-white/5 rounded-[2.5rem] border border-black/5 space-y-5">
           <p className="text-[0.6rem] font-black uppercase text-gray-400 tracking-widest text-center">Kondisi & Penggunaan</p>
