                { id: 'PRIVATE', label: 'Pribadi', icon: User },
                { id: 'COMMERCIAL', label: 'Niaga/Grab', icon: Briefcase },
                { id: 'NEW', label: 'Mobil Baru', icon: Zap },
                { id: 'USED', label: 'Mobil Bekas', icon: Timer }
