import React from 'react';
import { 
  FileText, FileSearch, Trash2, User, Camera, Loader2, AlertTriangle, Check, 
  Microscope, BrainCircuit, RefreshCw, Info, Cpu, ShieldCheck, Activity, ShieldX,
  FileSearch as ManualAuditIcon, Video, Car, CalendarClock, CheckCircle2, ImagePlus
} from 'lucide-react';
import { ScannerOverlay, NeuralProcessingView, PageTransition } from './WizardUI';
import { validateVehiclePhoto, analyzeVehicleSurvey, extractStnkData } from '../../services/geminiService';

interface StepSurveyProps {
  survey: any;
  setSurvey: (s: any) => void;
  stnkResult: any;
  setStnkResult: (r: any) => void;
  loading: boolean;
  setLoading: (l: boolean) => void;
  loadingType: 'KTP' | 'STNK' | 'SURVEY' | null;
  setLoadingType: (t: 'KTP' | 'STNK' | 'SURVEY' | null) => void;
  photoValidation: Record<string, { status: 'LOADING' | 'VALID' | 'INVALID', msg?: string }>;
  setPhotoValidation: React.Dispatch<React.SetStateAction<Record<string, { status: 'LOADING' | 'VALID' | 'INVALID', msg?: string }>>>;
  vehicle: any;
}

const StepSurvey: React.FC<StepSurveyProps> = ({
  survey, setSurvey, stnkResult, setStnkResult, loading, setLoading, loadingType, setLoadingType,
  photoValidation, setPhotoValidation, vehicle
}) => {

  const handlePhotoUpload = async (file: File, slotId: string, slotLabel: string) => {
    if (!file) return;
    setSurvey((prev: any) => ({ ...prev, photos: { ...prev.photos, [slotId]: URL.createObjectURL(file) } }));

    const reader = new FileReader();
    reader.onload = async (e) => {
      const base64 = e.target?.result as string;
      setSurvey((prev: any) => ({ ...prev, photos: { ...prev.photos, [slotId]: base64 } }));
      setPhotoValidation(prev => ({ ...prev, [slotId]: { status: 'LOADING' } }));
      try {
        const result = await validateVehiclePhoto(base64, slotLabel);
        setPhotoValidation(prev => ({ ...prev, [slotId]: { status: result.valid ? 'VALID' : 'INVALID', msg: result.issue } }));
      } catch (e) {
        setPhotoValidation(prev => ({ ...prev, [slotId]: { status: 'VALID' } }));
      }
    };
    reader.readAsDataURL(file);
  };

  const runSurveyAI = async () => {
    const photoEntries = Object.entries(survey.photos).map(([id, data]) => ({ id, data: data as string }));
    if (photoEntries.length < 5) {
      alert("Yuk, lengkapi dulu ke-5 foto mobilnya.");
      return;
    }
    setLoading(true);
    setLoadingType('SURVEY');

    const expectedData = {
      brand: vehicle.brand,
      model: vehicle.model,
      color: stnkResult?.color || "N/A",
      plate: vehicle.plate
    };

    const response = await analyzeVehicleSurvey(photoEntries, expectedData);
    setLoading(false);
    setLoadingType(null);

    if (response.success) {
      const finalScore = response.score || 0;
      const isRejected = response.auditVerdict === 'REJECTED';
      const needsManual = (finalScore < 80 || response.auditVerdict === 'REVIEW_REQUIRED') && !isRejected;

      setSurvey((prev: any) => ({ 
        ...prev, 
        score: finalScore, 
        summary: response.summary || '',
        underwritingReport: response.underwritingReport || '',
        detailedIssues: response.detailedIssues || [],
        photoFlags: response.photoFlags || [],
        verdict: isRejected ? 'REJECTED' : (needsManual ? 'MANUAL_REQUIRED' : 'CLEAN'),
        rejectionReason: response.rejectionReason || (isRejected ? 'Mobil sepertinya tidak sesuai data.' : ''),
        manualVerif: needsManual
      }));
    }
  };

  const photoSlots = [
    { id: 'front', label: 'Depan Serong', desc: 'Sisi depan mobil' },
    { id: 'back', label: 'Belakang Serong', desc: 'Sisi belakang mobil' },
    { id: 'right', label: 'Sisi Kanan', desc: 'Samping kanan' },
    { id: 'left', label: 'Sisi Kiri', desc: 'Samping kiri' },
    { id: 'interior', label: 'Dashboard', desc: 'Bagian dalam mobil' }
  ];

  return (
    <PageTransition>
      <div className="space-y-8 pb-24">
        <div className="p-6 bg-blue-50 dark:bg-blue-900/10 rounded-[2.5rem] border border-blue-100 dark:border-blue-900/40 flex gap-4">
           <Info className="text-blue-500 flex-shrink-0" size={24}/>
           <p className="text-xs font-medium text-blue-800 dark:text-blue-200 leading-relaxed">
              Yuk, ambil foto mobil kamu. Pastikan mobil dalam keadaan bersih dan pencahayaan cukup ya, biar AI kami bisa menilai dengan akurat.
           </p>
        </div>

        <div className="grid grid-cols-2 gap-4">
           {photoSlots.map((slot) => {
              const val = photoValidation[slot.id];
              return (
              <div key={slot.id} className={`group relative aspect-video rounded-[2rem] border-2 border-dashed transition-all flex flex-col items-center justify-center p-4 text-center overflow-hidden shadow-sm ${survey.photos[slot.id] ? (val?.status === 'INVALID' ? 'border-rose-500 bg-rose-50' : 'border-primary-500 bg-primary-50') : 'border-gray-200 bg-white dark:bg-white/5'}`}>
                 {survey.photos[slot.id] ? (
                   <>
                      <img src={survey.photos[slot.id]} className="absolute inset-0 w-full h-full object-cover rounded-[1.8rem]" alt={slot.label} />
                      {val?.status === 'LOADING' && (
                         <div className="absolute inset-0 bg-black/60 flex flex-col items-center justify-center text-white gap-2">
                            <Loader2 size={24} className="animate-spin text-primary-500"/>
                            <span className="text-[0.6rem] font-bold uppercase">Mengecek...</span>
                         </div>
                      )}
                      {val?.status === 'INVALID' && (
                         <div className="absolute inset-0 bg-rose-500/80 flex flex-col items-center justify-center text-white p-2">
                            <AlertTriangle size={20}/>
                            <span className="text-[0.5rem] font-black uppercase mt-1 leading-tight">{val.msg || 'Foto kurang jelas'}</span>
                         </div>
                      )}
                      <button onClick={() => { const n = {...survey.photos}; delete n[slot.id]; setSurvey({...survey, photos: n, score: 0}); }} className="absolute inset-0 bg-black/40 opacity-0 group-hover:opacity-100 transition-all flex items-center justify-center text-white rounded-[1.8rem] z-30"><Trash2 size={24}/></button>
                      <div className="absolute top-2 left-3 px-2 py-0.5 bg-black/60 text-white rounded-full text-[0.5rem] font-bold uppercase z-20">{slot.label}</div>
                   </>
                 ) : (
                   <>
                      <Camera size={24} className="text-gray-300 mb-2 group-hover:text-primary-500 transition-colors"/>
                      <p className="text-[0.65rem] font-black uppercase text-gray-500">{slot.label}</p>
                      <input type="file" accept="image/*" className="absolute inset-0 opacity-0 cursor-pointer" onChange={(e) => { const f = e.target.files?.[0]; if (f) handlePhotoUpload(f, slot.id, slot.desc); }} />
                   </>
                 )}
              </div>
           )})}
        </div>

        {Object.keys(survey.photos).length === 5 && (
           <div className="space-y-6 pt-4 animate-pop-in">
              {loading ? (
                <NeuralProcessingView label="Meneliti Kondisi Mobil" sublabel="AI kami sedang menganalisis setiap detail panel mobil kamu. Sebentar lagi selesai..." />
              ) : survey.score > 0 ? (
                <div className="p-8 bg-white dark:bg-white/5 border border-black/5 rounded-[3rem] shadow-xl space-y-6">
                   <div className="flex items-center gap-6">
                      <div className="relative w-20 h-20 flex items-center justify-center">
                         <svg className="w-full h-full transform -rotate-90">
                            <circle cx="40" cy="40" r="36" stroke="currentColor" strokeWidth="6" fill="transparent" className="text-gray-100 dark:text-gray-800"/>
                            <circle cx="40" cy="40" r="36" stroke="currentColor" strokeWidth="6" fill="transparent" strokeDasharray={226.2} strokeDashoffset={226.2 - (226.2 * survey.score) / 100} className={`transition-all duration-1000 ${survey.score >= 80 ? 'text-emerald-500' : 'text-amber-500'}`}/>
                         </svg>
                         <span className="absolute text-xl font-black">{survey.score}</span>
                      </div>
                      <div>
                         <p className="text-[0.6rem] font-bold text-gray-400 uppercase tracking-widest">Skor Kondisi Mobil</p>
                         <h4 className="text-lg font-black uppercase text-slate-900 dark:text-white">
                            {survey.verdict === 'CLEAN' ? 'Mobil Terawat!' : 'Perlu Review Manual'}
                         </h4>
                         <p className="text-xs text-gray-500 font-medium mt-1">{survey.summary}</p>
                      </div>
                   </div>
                   <div className="p-4 bg-gray-50 dark:bg-white/5 rounded-2xl text-[0.7rem] font-medium leading-relaxed italic text-gray-600 dark:text-gray-300">
                      "{survey.underwritingReport}"
                   </div>
                </div>
              ) : (
                <button onClick={runSurveyAI} className="w-full py-6 bg-slate-900 dark:bg-white text-white dark:text-black rounded-[2rem] font-black uppercase text-sm shadow-2xl active:scale-95 transition-all flex items-center justify-center gap-4 group">
                   <BrainCircuit size={24} className="group-hover:rotate-12 transition-transform text-primary-500"/> Cek Kondisi Sekarang
                </button>
              )}
           </div>
        )}
      </div>
    </PageTransition>
  );
};

export default StepSurvey;

