import React, { useState } from 'react';
import { Database, Edit3, ChevronDown, User, Briefcase, Building2, Zap, Timer, FileSearch, Sparkles, CheckCircle2, RefreshCw } from 'lucide-react';
import { CAR_DATABASE } from '../../constants';
import { extractStnkData } from '../../services/geminiService';
import { ScannerOverlay } from './WizardUI';

interface StepVehicleProps {
  vehicle: any;
  setVehicle: (v: any) => void;
  entryMode: 'DATABASE' | 'MANUAL';
  setEntryMode: (m: 'DATABASE' | 'MANUAL') => void;
  handlePlateChange: (e: React.ChangeEvent<HTMLInputElement>) => void;
  formatInputCurrency: (val: string) => string;
  loading: boolean;
  setLoading: (l: boolean) => void;
  loadingType: 'KTP' | 'STNK' | 'SURVEY' | null;
  setLoadingType: (t: 'KTP' | 'STNK' | 'SURVEY' | null) => void;
  setStnkResult?: (res: any) => void; 
}

const StepVehicle: React.FC<StepVehicleProps> = ({ 
  vehicle, setVehicle, entryMode, setEntryMode, handlePlateChange, formatInputCurrency,
  loading, setLoading, loadingType, setLoadingType, setStnkResult
}) => {
  // Store all extracted STNK info for editing
  const [extractedStnk, setExtractedStnk] = useState<any>(null);

  const handleStnkAutofill = async (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (!file) return;
    setLoading(true);
    setLoadingType('STNK');
    setExtractedStnk(null);

    const reader = new FileReader();
    reader.onload = async () => {
        const base64 = reader.result as string;
        const response = await extractStnkData(base64);
        setLoading(false);
        setLoadingType(null);

        if (response.success && response.data) {
            const data = response.data;
            const cleanData = {
                ownerName: data.owner || '',
                plate: data.plate || '',
                brand: data.brand || '',
                model: data.model || '',
                color: data.color || '',
                year: data.year || '',
                vin: data.vin || '',
                engine: data.engine || '',
                status: data.status || 'OK'
            };

            setExtractedStnk(cleanData);

            // Populate STNK Result for parent
            if (setStnkResult) {
                setStnkResult(cleanData);
            }

            // Database Matching
            const match = CAR_DATABASE.find(c => 
                data.brand.toUpperCase().includes(c.brand) || 
                (c.modelName && data.brand.toUpperCase().includes(c.modelName))
            );

            const yearInt = parseInt(data.year) || 2025;
            const price = match ? (match.yearPrices[yearInt] || match.yearPrices[2024] || 0) * 1000000 : 0;

            // Autofill Main Form
            setVehicle((prev: any) => ({
                ...prev,
                brand: match?.brand || data.brand.split(' ')[0] || prev.brand,
                model: match?.modelName || data.model || prev.model,
                year: yearInt || prev.year,
                plate: data.plate || prev.plate,
                vin: data.vin || prev.vin,
                engine: data.engine || prev.engine,
                price: price || prev.price,
                manualPrice: !price,
                condition: yearInt < new Date().getFullYear() ? 'USED' : 'NEW'
            }));

            if (!match) {
                setEntryMode('MANUAL');
            } else {
                setEntryMode('DATABASE');
            }
        } else {
            alert('Gagal mengekstrak data STNK. Silakan isi manual.');
        }
    };
    reader.readAsDataURL(file);
  };

  const handleStnkEdit = (field: string, value: string) => {
      const newStnk = { ...extractedStnk, [field]: value.toUpperCase() };
      setExtractedStnk(newStnk);
      if (setStnkResult) setStnkResult(newStnk);

      // Update main vehicle state for the edited field
      if (field === 'brand') setVehicle((prev: any) => ({ ...prev, brand: value.toUpperCase() }));
      if (field === 'model') setVehicle((prev: any) => ({ ...prev, model: value.toUpperCase() }));
      if (field === 'plate') setVehicle((prev: any) => ({ ...prev, plate: value.toUpperCase() }));
      if (field === 'year') setVehicle((prev: any) => ({ ...prev, year: parseInt(value) || prev.year }));
      if (field === 'vin') setVehicle((prev: any) => ({ ...prev, vin: value.toUpperCase() }));
      if (field === 'engine') setVehicle((prev: any) => ({ ...prev, engine: value.toUpperCase() }));
  };

  return (
    <div className="space-y-6 animate-fade-in relative">
      {/* Loading Overlay */}
      {loading && loadingType === 'STNK' && <ScannerOverlay label="Neural STNK Decryption" />}

      {/* STNK Express Button */}
      <label className="block w-full p-1 bg-gradient-to-r from-emerald-500 to-teal-500 rounded-[2rem] cursor-pointer shadow-lg hover:shadow-emerald-500/20 hover:scale-[1.01] transition-all active:scale-95 group">
         <div className="bg-white dark:bg-black/20 rounded-[1.9rem] p-4 flex items-center justify-between">
            <div className="flex items-center gap-4">
                <div className="w-12 h-12 bg-emerald-500/10 rounded-2xl flex items-center justify-center text-emerald-500 group-hover:bg-emerald-500 group-hover:text-white transition-colors">
                    <FileSearch size={24}/>
                </div>
                <div>
                    <h4 className="text-sm font-black uppercase tracking-tight text-gray-900 dark:text-white">Autofill with STNK</h4>
                    <p className="text-[0.55rem] font-bold text-gray-500 dark:text-emerald-100 uppercase tracking-widest flex items-center gap-1"><Sparkles size={10}/> AI Vision Extraction</p>
                </div>
            </div>
            <div className="px-4 py-2 bg-emerald-500 text-white rounded-xl text-[0.6rem] font-black uppercase tracking-widest group-hover:bg-emerald-600 transition-colors">
                Upload
            </div>
         </div>
         <input type="file" accept="image/*" className="hidden" onChange={handleStnkAutofill} />
      </label>

      {/* Extracted Info Visual Feedback & Edit Form */}
      {extractedStnk && (
        <div className="animate-pop-in bg-white dark:bg-white/5 border border-emerald-500/20 rounded-[2rem] p-6 shadow-xl relative overflow-hidden">
           <div className="absolute top-0 right-0 p-4 opacity-10 pointer-events-none"><FileSearch size={120} className="rotate-12"/></div>
           <div className="flex items-center gap-3 mb-6">
              <CheckCircle2 size={24} className="text-emerald-500 flex-shrink-0"/>
              <div>
                 <p className="text-lg font-black text-gray-900 dark:text-white uppercase tracking-tighter leading-none">Neural Scan Complete</p>
                 <p className="text-[0.55rem] font-bold text-gray-400 uppercase tracking-widest">Verify & Edit Extracted Data</p>
              </div>
              <button onClick={() => setExtractedStnk(null)} className="ml-auto p-2 bg-gray-100 dark:bg-white/10 rounded-full hover:bg-rose-500 hover:text-white transition-all"><RefreshCw size={14}/></button>
           </div>

           <div className="grid grid-cols-1 md:grid-cols-2 gap-4 relative z-10">
              {/* Primary Identity */}
              <div className="space-y-1">
                 <label className="text-[0.5rem] font-black uppercase text-gray-400 ml-1">Nama Pemilik (STNK)</label>
                 <input 
                    value={extractedStnk.ownerName} 
                    onChange={(e) => handleStnkEdit('ownerName', e.target.value)}
                    className="w-full px-4 py-3 bg-gray-50 dark:bg-black/20 border border-black/5 dark:border-white/10 rounded-xl text-xs font-bold uppercase focus:border-emerald-500 outline-none"
                 />
              </div>
              <div className="space-y-1">
                 <label className="text-[0.5rem] font-black uppercase text-gray-400 ml-1">Warna Kendaraan</label>
                 <input 
                    value={extractedStnk.color} 
                    onChange={(e) => handleStnkEdit('color', e.target.value)}
                    className="w-full px-4 py-3 bg-gray-50 dark:bg-black/20 border border-black/5 dark:border-white/10 rounded-xl text-xs font-bold uppercase focus:border-emerald-500 outline-none"
                 />
              </div>
           </div>
        </div>
      )}

      <div className="flex bg-gray-100 dark:bg-white/[0.03] p-1 rounded-[1.8rem] border border-black/5 dark:border-white/5">
         <button 
           onClick={() => setEntryMode('DATABASE')}
           className={`flex-1 py-3.5 rounded-[1.5rem] text-[0.65rem] font-black uppercase tracking-widest transition-all flex items-center justify-center gap-2 ${entryMode === 'DATABASE' ? 'bg-white dark:bg-gray-800 shadow-xl text-primary-500' : 'text-gray-400'}`}
         >
           <Database size={16}/> Neural Database
         </button>
         <button 
           onClick={() => { setEntryMode('MANUAL'); setVehicle((v: any) => ({ ...v, brand: '', model: '', basePrice: 0 })); }}
           className={`flex-1 py-3.5 rounded-[1.5rem] text-[0.65rem] font-black uppercase tracking-widest transition-all flex items-center justify-center gap-2 ${entryMode === 'MANUAL' ? 'bg-white dark:bg-gray-800 shadow-xl text-primary-500' : 'text-gray-400'}`}
         >
           <Edit3 size={16}/> Manual Registry
         </button>
      </div>

      <div className="space-y-5">
        <div className="grid grid-cols-1 md:grid-cols-2 gap-5">
          <div className="space-y-2">
            <label className="text-[0.6rem] font-black uppercase text-gray-500 ml-2 tracking-[0.2em]">Merk Kendaraan</label>
            {entryMode === 'DATABASE' ? (
                <div className="relative group">
                    <select 
                        className="w-full p-5 rounded-[1.8rem] bg-white dark:bg-white/[0.03] border-2 border-black/5 dark:border-white/5 outline-none focus:border-primary-500 font-black text-sm appearance-none transition-all cursor-pointer group-hover:border-black/10 text-primary-500"
                        value={vehicle.brand}
                        onChange={(e) => {
                            const val = e.target.value;
                            const unit = CAR_DATABASE.find(c => c.brand === val);
                            const p = (unit?.yearPrices[2024] || 0) * 1000000;
                            setVehicle({...vehicle, brand: val, model: unit?.modelName || '', price: p, basePrice: p});
                        }}
                    >
                        <option value="">Pilih Merk</option>
                        {Array.from(new Set(CAR_DATABASE.map(c => c.brand))).sort().map(b => <option key={b} value={b}>{b}</option>)}
                    </select>
                    <div className="absolute right-5 top-1/2 -translate-y-1/2 pointer-events-none text-gray-400">
                        <ChevronDown size={20}/>
                    </div>
                </div>
            ) : (
                <input 
                    placeholder="Contoh: Toyota"
                    value={vehicle.brand}
                    className="w-full p-5 rounded-[1.8rem] bg-white dark:bg-white/[0.03] border-2 border-black/5 dark:border-white/5 outline-none focus:border-primary-500 font-black text-sm transition-all text-primary-500 uppercase"
                    onChange={(e) => setVehicle({...vehicle, brand: e.target.value.toUpperCase()})}
                />
            )}
          </div>

          <div className="space-y-2">
            <label className="text-[0.6rem] font-black uppercase text-gray-500 ml-2 tracking-[0.2em]">Tipe Model</label>
            <input 
              readOnly={entryMode === 'DATABASE' && !vehicle.brand}
              placeholder={entryMode === 'DATABASE' ? (vehicle.brand ? `Model ${vehicle.brand}` : "Pilih Merk") : "Contoh: Avanza G"}
              value={vehicle.model}
              className={`w-full p-5 rounded-[1.8rem] bg-white dark:bg-white/[0.03] border-2 border-black/5 dark:border-white/5 outline-none focus:border-primary-500 font-black text-sm transition-all ${entryMode === 'DATABASE' ? 'bg-gray-50 dark:bg-black/20 text-gray-400' : 'text-primary-500 uppercase'}`}
              onChange={(e) => setVehicle({...vehicle, model: e.target.value.toUpperCase()})}
            />
          </div>
        </div>

        <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-6">
          <div className="space-y-2">
            <label className="text-[0.6rem] font-black uppercase text-gray-500 ml-2 tracking-widest">Tahun</label>
            <div className="relative group">
                <select 
                className="w-full p-5 rounded-[1.8rem] bg-white dark:bg-white/[0.03] border-2 border-black/5 dark:border-white/5 outline-none focus:border-primary-500 font-black text-sm appearance-none"
                value={vehicle.year}
                onChange={(e) => setVehicle({...vehicle, year: parseInt(e.target.value)})}
                >
                {Array.from({ length: 11 }, (_, i) => 2025 - i).map(y => (
                    <option key={y} value={y}>{y}{y === 2025 ? ' (Gress)' : ''}</option>
                ))}
                </select>
                <div className="absolute right-5 top-1/2 -translate-y-1/2 pointer-events-none text-gray-400">
                    <ChevronDown size={20}/>
                </div>
            </div>
          </div>

          <div className="space-y-2">
            <label className="text-[0.6rem] font-black uppercase text-gray-500 ml-2 tracking-widest">Harga OTR</label>
            <div className="relative">
              <span className="absolute left-5 top-1/2 -translate-y-1/2 font-black text-gray-400 text-sm">Rp</span>
              <input 
                type="text"
                inputMode="numeric"
                className="w-full pl-12 pr-5 py-5 rounded-[1.8rem] bg-white dark:bg-white/[0.03] border-2 border-black/5 dark:border-white/5 focus:border-primary-500 outline-none font-black text-lg text-primary-500"
                value={formatInputCurrency(vehicle.price.toString())}
                onChange={(e) => {
                  const val = e.target.value.replace(/\D/g, "");
                  setVehicle({...vehicle, price: parseInt(val || "0"), manualPrice: true});
                }}
              />
            </div>
          </div>

          <div className="space-y-2">
            <label className="text-[0.6rem] font-black uppercase text-gray-500 ml-2 tracking-widest">Plat Polisi</label>
            <div className="relative h-[72px] rounded-[1.8rem] bg-white dark:bg-[#0a0a0a] border-2 border-black/10 dark:border-white/10 p-1 flex items-center justify-center shadow-inner group transition-all focus-within:border-primary-500">
               <input 
                 placeholder="B 1234 XYZ"
                 maxLength={12}
                 className="w-full bg-transparent text-center font-black text-2xl tracking-[0.2em] text-black dark:text-white uppercase outline-none placeholder:text-gray-300 dark:placeholder:text-gray-800"
                 value={vehicle.plate}
                 onChange={handlePlateChange}
               />
               <div className="absolute right-6 text-[0.45rem] font-black text-primary-500/60 uppercase tracking-widest leading-none text-right">
                    {vehicle.regionName.split('(')[0]} <br/>
                    <span className="text-[0.35rem] opacity-50">Region {vehicle.region}</span>
               </div>
            </div>
          </div>
        </div>

        {/* Chassis and Engine Numbers Row */}
        <div className="grid grid-cols-1 md:grid-cols-2 gap-5 pt-2">
            <div className="space-y-2">
                <label className="text-[0.6rem] font-black uppercase text-gray-500 ml-2 tracking-[0.2em]">Nomor Rangka (VIN)</label>
                <input 
                    placeholder="Contoh: MHF123..."
                    value={vehicle.vin}
                    onChange={(e) => setVehicle({...vehicle, vin: e.target.value.toUpperCase()})}
                    className="w-full p-5 rounded-[1.8rem] bg-white dark:bg-white/[0.03] border-2 border-black/5 dark:border-white/5 outline-none focus:border-primary-500 font-black text-sm text-primary-500 uppercase transition-all font-mono"
                />
            </div>
            <div className="space-y-2">
                <label className="text-[0.6rem] font-black uppercase text-gray-500 ml-2 tracking-[0.2em]">Nomor Mesin</label>
                <input 
                    placeholder="Contoh: K14B..."
                    value={vehicle.engine}
                    onChange={(e) => setVehicle({...vehicle, engine: e.target.value.toUpperCase()})}
                    className="w-full p-5 rounded-[1.8rem] bg-white dark:bg-white/[0.03] border-2 border-black/5 dark:border-white/5 outline-none focus:border-primary-500 font-black text-sm text-primary-500 uppercase transition-all font-mono"
                />
            </div>
        </div>
      </div>

      <div className="space-y-5">
        <label className="text-[0.65rem] font-black uppercase text-gray-500 ml-2 tracking-[0.3em]">Usage & Conditions Matrix</label>
        <div className="grid grid-cols-1 md:grid-cols-2 gap-5">
            <div className="grid grid-cols-3 gap-3">
                {[
                    { id: 'PRIVATE', icon: User, label: 'Pribadi' },
                    { id: 'COMMERCIAL', icon: Briefcase, label: 'Niaga' },
                    { id: 'DINAS', icon: Building2, label: 'Dinas' }
                ].map(u => (
                    <button 
                        key={u.id}
                        onClick={() => setVehicle({...vehicle, usage: u.id as any})}
                        className={`p-4 rounded-[1.8rem] border-2 flex flex-col items-center text-center gap-2 transition-all tap-feedback ${vehicle.usage === u.id ? 'border-primary-500 bg-primary-500/[0.03] shadow-lg' : 'border-black/5 bg-white dark:bg-white/[0.03] opacity-60'}`}
                    >
                        <u.icon size={22} className={vehicle.usage === u.id ? 'text-primary-500' : 'text-gray-400'}/>
                        <span className={`text-[0.55rem] font-black uppercase tracking-widest ${vehicle.usage === u.id ? 'text-primary-600' : 'text-gray-500'}`}>{u.label}</span>
                    </button>
                ))}
            </div>
            <div className="grid grid-cols-2 gap-3">
                {[
                    { id: 'NEW', icon: Zap, label: 'Gress (Baru)' },
                    { id: 'USED', icon: Timer, label: 'Bekas' }
                ].map(c => (
                    <button 
                        key={c.id}
                        onClick={() => setVehicle({...vehicle, condition: c.id as any})}
                        className={`p-4 rounded-[1.8rem] border-2 flex flex-col items-center text-center gap-2 transition-all tap-feedback ${vehicle.condition === c.id ? 'border-primary-500 bg-primary-500/[0.03] shadow-lg' : 'border-black/5 bg-white dark:bg-white/[0.03] opacity-60'}`}
                    >
                        <c.icon size={22} className={vehicle.condition === c.id ? 'text-primary-500' : 'text-gray-400'}/>
                        <span className={`text-[0.55rem] font-black uppercase tracking-widest ${vehicle.condition === c.id ? 'text-primary-600' : 'text-gray-500'}`}>{c.label}</span>
                    </button>
                ))}
            </div>
        </div>
      </div>
    </div>
  );
};

export default StepVehicle;

import React, { useState, useMemo, useEffect } from 'react';
import { Car, RefreshCw, X, ChevronLeft, ChevronRight, Zap, ShieldCheck, CheckCircle2, FileText, ArrowRight } from 'lucide-react';
import { getOJKRate, EXPANSION_RATES, AUTHORIZED_WORKSHOP_RATE, STAMP_DUTY, PLATE_REGIONS, INSURANCE_PROVIDERS } from '../constants';
import { InsuranceType } from '../types';
import { db, Policy, Transaction } from '../db';
import { DamageIssue, PhotoFlag } from '../services/geminiService';
import { formatIDR } from './car-wizard/WizardUI';

// Import Steps
import StepVehicle from './car-wizard/StepVehicle';
import StepCoverage from './car-wizard/StepCoverage';
import StepProviders from './car-wizard/StepProviders';
import StepKYC from './car-wizard/StepKYC';
import StepPreSummary from './car-wizard/StepPreSummary';
import StepSurvey from './car-wizard/StepSurvey';
import StepFinal from './car-wizard/StepFinal';
import StepPayment from './car-wizard/StepPayment';

const STEPS = [
  { id: 'VEHICLE', label: 'Unit' },
  { id: 'COVERAGE', label: 'Polis' },
  { id: 'PROVIDERS', label: 'Opsi' },
  { id: 'KYC', label: 'Nasabah' },
  { id: 'PRESUMMARY', label: 'Rincian' },
  { id: 'SURVEY', label: 'Audit' },
  { id: 'REVIEW', label: 'Review' },
  { id: 'PAYMENT', label: 'Bayar' }
];

const CarInsuranceWizard = ({ onComplete, currentUser }: { onComplete: () => void, currentUser?: any }) => {
  const [step, setStep] = useState(0);
  const [loading, setLoading] = useState(false);
  const [loadingType, setLoadingType] = useState<'KTP' | 'STNK' | 'SURVEY' | null>(null);
  const [entryMode, setEntryMode] = useState<'DATABASE' | 'MANUAL'>('DATABASE');
  const [showBreakdown, setShowBreakdown] = useState(false);
  const [showProviderBreakdown, setShowProviderBreakdown] = useState(false);
  const [sortBy, setSortBy] = useState<'RATING' | 'PRICE'>('RATING');
  const [isSuccess, setIsSuccess] = useState(false);
  const [generatedPolicy, setGeneratedPolicy] = useState<Policy | null>(null);

  const [vehicle, setVehicle] = useState({
    brand: '', model: '', year: 2025, isOther: false, 
    price: 0, basePrice: 0, manualPrice: false, plate: '', 
    vin: '', engine: '',
    region: '3' as '1'|'2'|'3', regionName: 'Region Lainnya', usage: 'PRIVATE', condition: 'NEW'
  });

  const [coverage, setCoverage] = useState({
    type: InsuranceType.COMPREHENSIVE as InsuranceType,
    flood: false, earthquake: false, srcc: false, 
    terrorism: false, authorized: false, 
    tpl: 0, paDriver: false, paPassenger: false,
    promo: '', discount: 0, discountType: 'NOMINAL' as 'NOMINAL' | 'PERCENT'
  });

  const [selectedProviderId, setSelectedProviderId] = useState<string | null>(null);
  const [kycData, setKycData] = useState({ 
    name: currentUser?.name || '', 
    ktp: currentUser?.ktp || '', 
    address: currentUser?.address || '', 
    email: currentUser?.email || '', 
    phone: currentUser?.phone || '', 
    photo: null as string|null 
  });
  const [verifiedFields, setVerifiedFields] = useState<Set<string>>(new Set());

  const [stnkResult, setStnkResult] = useState({
    ownerName: '',
    plate: '',
    vin: '',
    engine: '',
    color: '',
    year: '',
    status: ''
  });

  const [survey, setSurvey] = useState({ 
    stnk: null as string|null, 
    photos: {} as Record<string, string>, 
    score: 0, 
    summary: '',
    underwritingReport: '',
    detailedIssues: [] as DamageIssue[], 
    photoFlags: [] as PhotoFlag[],
    verdict: '' as 'CLEAN' | 'REVIEW_REQUIRED' | 'REJECTED' | 'MANUAL_REQUIRED' | '',
    rejectionReason: '',
    manualVerif: false, 
    manualRequestStatus: 'NONE' as 'NONE' | 'REQUESTED',
    manualDate: '',
    manualType: 'VIDEO' as 'VIDEO' | 'PHYSICAL',
    accessories: '' 
  });

  const [photoValidation, setPhotoValidation] = useState<Record<string, { status: 'LOADING' | 'VALID' | 'INVALID', msg?: string }>>({});

  const selectedProvider = useMemo(() => INSURANCE_PROVIDERS.find(p => p.id === selectedProviderId), [selectedProviderId]);

  const premiumBreakdown = useMemo(() => {
    if (!vehicle.price) return null;
    const baseRate = getOJKRate(vehicle.price / 1000000, vehicle.region, coverage.type);
    const basicPremium = (vehicle.price * baseRate) / 100;

    const expansions = [];
    if (coverage.authorized) expansions.push({ name: 'Bengkel Resmi (Authorized)', val: (vehicle.price * AUTHORIZED_WORKSHOP_RATE) / 100, rate: AUTHORIZED_WORKSHOP_RATE });
    if (coverage.flood) expansions.push({ name: 'Banjir & Angin Ribut', val: (vehicle.price * EXPANSION_RATES.FLOOD) / 100, rate: EXPANSION_RATES.FLOOD });
    if (coverage.earthquake) expansions.push({ name: 'Gempa & Tsunami', val: (vehicle.price * EXPANSION_RATES.EARTHQUAKE) / 100, rate: EXPANSION_RATES.EARTHQUAKE });

    const srccRate = coverage.type === InsuranceType.COMPREHENSIVE ? EXPANSION_RATES.SRCC.COMPREHENSIVE : EXPANSION_RATES.SRCC.TLO;
    if (coverage.srcc) expansions.push({ name: 'SRCC (Kerusuhan)', val: (vehicle.price * srccRate) / 100, rate: srccRate });

    const tsRate = coverage.type === InsuranceType.COMPREHENSIVE ? EXPANSION_RATES.TERRORISM.COMPREHENSIVE : EXPANSION_RATES.TERRORISM.TLO;
    if (coverage.terrorism) expansions.push({ name: 'Terorisme & Sabotase', val: (vehicle.price * tsRate) / 100, rate: tsRate });

    const tplPremium = (coverage.tpl / 100); 
    const expansionTotal = expansions.reduce((acc: number, curr: any) => acc + curr.val, 0) + tplPremium;
    const grossPremium = basicPremium + expansionTotal;

    const discountPercent = Math.min(coverage.discount || 0, 25);
    const discountAmount = grossPremium * (discountPercent / 100);
    const netPremium = grossPremium - discountAmount;

    return {
        baseRate, basicPremium, expansions, tplPremium, grossPremium, discountPercent, discountAmount,
        adminFee: selectedProvider?.adminFee || 0,
        stampDuty: STAMP_DUTY,
        netPremium,
        totalPayable: netPremium + (selectedProvider?.adminFee || 0) + STAMP_DUTY
    };
  }, [vehicle, coverage, selectedProvider]);

  const sortedProviders = useMemo(() => {
    return [...INSURANCE_PROVIDERS].sort((a, b) => {
      if (sortBy === 'RATING') return b.rating - a.rating;
      if (sortBy === 'PRICE') {
          const priceA = (premiumBreakdown?.netPremium || 0) + a.adminFee;
          const priceB = (premiumBreakdown?.netPremium || 0) + b.adminFee;
          return priceA - priceB;
      }
      return 0;
    });
  }, [sortBy, premiumBreakdown]);

  const handleNext = () => setStep(s => Math.min(s + 1, STEPS.length - 1));
  const handleBack = () => setStep(s => Math.max(s - 1, 0));

  const formatInputCurrency = (value: string) => {
    const numeric = value.replace(/\D/g, "");
    if (!numeric) return "";
    return new Intl.NumberFormat('id-ID').format(parseInt(numeric));
  };

  const handlePlateChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    let val = e.target.value.toUpperCase().replace(/[^A-Z0-9]/g, "");
    const parts = val.match(/^([A-Z]{1,2})([0-9]{0,4})([A-Z]{0,3})$/);
    if (parts) {
      const plate = `${parts[1]}${parts[2] ? ' ' + parts[2] : ''}${parts[3] ? ' ' + parts[3] : ''}`;
      const prefix = parts[1];
      const regionInfo = PLATE_REGIONS[prefix];
      setVehicle({
        ...vehicle, 
        plate, 
        region: regionInfo?.region || '3', 
        regionName: regionInfo ? `${regionInfo.name} (Region ${regionInfo.region})` : 'Region 3 (Lainnya)'
      });
    } else {
      setVehicle({...vehicle, plate: val});
    }
  };

  const handlePaymentSuccess = async (method: string) => {
    if (!currentUser || !premiumBreakdown) return;
    try {
      const isManualPending = survey.verdict === 'MANUAL_REQUIRED' || survey.manualRequestStatus === 'REQUESTED';

      const newPolicy: Policy = {
        userId: currentUser.id,
        type: 'CAR',
        status: isManualPending ? 'PENDING' : 'ACTIVE',
        startDate: new Date().toISOString(),
        endDate: new Date(new Date().setFullYear(new Date().getFullYear() + 1)).toISOString(),
        premium: premiumBreakdown.totalPayable,
        providerId: selectedProvider?.name || selectedProviderId || '',
        policyNumber: `POL-AUTO-${Date.now().toString().slice(-8)}`,
        createdAt: new Date().toISOString(),
        coverageDetails: { 
            vehicle: { ...vehicle, ...stnkResult }, 
            coverage, 
            survey, 
            kycData,
            financials: { ...premiumBreakdown, paymentMethod: method } 
        }
      };

      const policyId = await db.policies.add(newPolicy);
      setGeneratedPolicy({ ...newPolicy, id: policyId });

      await db.transactions.add({
        userId: currentUser.id,
        type: 'PAYMENT',
        amount: premiumBreakdown.totalPayable,
        status: 'SUCCESS',
        description: `Payment for ${newPolicy.policyNumber} via ${method}`,
        date: new Date().toISOString(),
        referenceId: policyId.toString()
      });

      localStorage.removeItem('SUREPATH_CAR_WIZARD_PROGRESS');
      setIsSuccess(true);
    } catch (e) {
      alert("Neural sync error: Gagal menyimpan data polis. " + e);
    }
  };

  if (isSuccess && generatedPolicy) {
     return (
        <div className="flex flex-col items-center justify-center h-full min-h-screen p-8 text-center bg-[#f0faf7] dark:bg-[#050505] animate-fade-in">
           <div className="w-24 h-24 bg-emerald-500 rounded-[2.5rem] flex items-center justify-center text-white shadow-2xl mb-8 animate-pop-in">
              <ShieldCheck size={56} strokeWidth={2.5}/>
           </div>
           <div className="space-y-4 mb-12">
              <h2 className="text-4xl font-black uppercase tracking-tighter text-slate-900 dark:text-white">Policy <span className="text-emerald-500">Live</span></h2>
              <p className="text-[0.7rem] font-bold text-gray-500 uppercase tracking-widest max-w-sm mx-auto">
                 Neural Node Activated. Your protection matrix has been synchronized with our core registry.
              </p>
           </div>

           <div className="w-full max-w-sm bg-white dark:bg-white/5 border border-black/5 dark:border-white/5 rounded-[3rem] p-8 space-y-6 shadow-xl mb-10">
              <div className="flex justify-between items-center text-[0.6rem] font-black uppercase text-gray-400 tracking-widest">
                 <span>Policy Node ID</span>
                 <span className="text-primary-500 font-mono">{generatedPolicy.policyNumber}</span>
              </div>
              <div className="flex justify-between items-center text-[0.6rem] font-black uppercase text-gray-400 tracking-widest">
                 <span>Status</span>
                 <BadgeComponent color="emerald">{generatedPolicy.status}</BadgeComponent>
              </div>
              <div className="pt-6 border-t border-black/5 flex justify-between items-center">
                 <div className="flex items-center gap-3">
                    <div className="w-10 h-10 bg-blue-500/10 rounded-xl flex items-center justify-center text-blue-500"><Car size={20}/></div>
                    <div className="text-left">
                       <p className="text-xs font-black uppercase text-slate-900 dark:text-white">{vehicle.brand} {vehicle.model}</p>
                       <p className="text-[0.5rem] font-bold text-gray-400 uppercase tracking-widest">{vehicle.plate}</p>
                    </div>
                 </div>
                 <FileText size={20} className="text-primary-500"/>
              </div>
           </div>

           <div className="w-full max-w-sm space-y-4">
              <button 
                onClick={onComplete}
                className="w-full py-5 bg-slate-900 dark:bg-white text-white dark:text-black rounded-2xl font-black uppercase text-sm tracking-[0.2em] shadow-xl active:scale-95 transition-all flex items-center justify-center gap-3"
              >
                Go to Dashboard <ArrowRight size={18}/>
              </button>
           </div>
        </div>
     );
  }

  return (
    <div className="flex flex-col h-full min-h-screen bg-[#f0faf7] dark:bg-[#050505] text-gray-900 dark:text-white overflow-hidden relative">
       {/* HEADER SECTION */}
       <div className="px-6 pt-6 pb-4 bg-white/80 dark:bg-black/40 backdrop-blur-xl border-b border-gray-100 dark:border-white/5 flex flex-col gap-5 flex-shrink-0 relative z-[100]">
          <div className="flex items-center justify-between">
            <div className="flex items-center gap-4">
               <div className="w-12 h-12 bg-slate-900 dark:bg-white rounded-2xl flex items-center justify-center text-white dark:text-black shadow-xl group border border-white/10 transition-transform hover:scale-105">
                  <Car size={24} className="group-hover:rotate-12 transition-transform text-primary-500"/>
               </div>
               <div>
                  <h3 className="text-lg font-black uppercase tracking-tighter leading-none">Sure<span className="text-primary-500">Path</span> <span className="text-gray-400">Auto</span></h3>
                  <p className="text-[0.45rem] font-bold text-gray-400 uppercase tracking-[0.3em] mt-1.5">Penerbitan Polis AI v4.0</p>
               </div>
            </div>
            <div className="flex items-center gap-2">
               <button onClick={onComplete} className="p-2.5 text-gray-400 hover:text-gray-900 dark:hover:text-white bg-gray-50 dark:bg-white/5 rounded-xl transition-all border border-black/5"><X size={20}/></button>
            </div>
          </div>

          <div className="flex items-center justify-between">
             <div className="flex items-center gap-2 bg-gray-100 dark:bg-white/5 px-3 py-1.5 rounded-lg border border-black/5">
                <span className="text-[0.55rem] font-black text-primary-500 uppercase tracking-widest">{STEPS[step].label}</span>
             </div>
             <p className="text-[0.5rem] font-black text-gray-400 uppercase tracking-[0.2em]">Step {step + 1} of {STEPS.length}</p>
          </div>

          <div className="flex gap-1.5">
             {STEPS.map((s, i) => (
               <div key={i} className={`h-1 rounded-full flex-1 transition-all duration-700 ${i === step ? 'bg-primary-500 shadow-[0_0_10px_#10b981]' : i < step ? 'bg-primary-500/30' : 'bg-gray-100 dark:bg-white/10'}`}></div>
             ))}
          </div>
       </div>

       {/* MAIN CONTENT AREA */}
       <div className="flex-1 overflow-y-auto px-6 py-8 no-scrollbar relative z-10">
          <div className="max-w-xl mx-auto">
            {step === 0 && <StepVehicle vehicle={vehicle} setVehicle={setVehicle} entryMode={entryMode} setEntryMode={setEntryMode} handlePlateChange={handlePlateChange} formatInputCurrency={formatInputCurrency} loading={loading} setLoading={setLoading} loadingType={loadingType} setLoadingType={setLoadingType} setStnkResult={setStnkResult} />}
            {step === 1 && <StepCoverage coverage={coverage} setCoverage={setCoverage} premiumBreakdown={premiumBreakdown} />}
            {step === 2 && <StepProviders sortBy={sortBy} setSortBy={setSortBy} sortedProviders={sortedProviders} selectedProviderId={selectedProviderId} setSelectedProviderId={setSelectedProviderId} premiumBreakdown={premiumBreakdown} showProviderBreakdown={showProviderBreakdown} setShowProviderBreakdown={setShowProviderBreakdown} />}
            {step === 3 && <StepKYC kycData={kycData} setKycData={setKycData} loading={loading} setLoading={setLoading} loadingType={loadingType} setLoadingType={setLoadingType} verifiedFields={verifiedFields} setVerifiedFields={setVerifiedFields} />}
            {step === 4 && <StepPreSummary vehicle={vehicle} coverage={coverage} premiumBreakdown={premiumBreakdown} showBreakdown={showBreakdown} setShowBreakdown={setShowBreakdown} stnkResult={stnkResult} kycData={kycData} />}
            {step === 5 && <StepSurvey survey={survey} setSurvey={setSurvey} stnkResult={stnkResult} setStnkResult={setStnkResult} loading={loading} setLoading={setLoading} loadingType={loadingType} setLoadingType={setLoadingType} photoValidation={photoValidation} setPhotoValidation={setPhotoValidation} vehicle={vehicle} />}
            {step === 6 && <StepFinal vehicle={vehicle} stnkResult={stnkResult} coverage={coverage} survey={survey} premiumBreakdown={premiumBreakdown} handleFinalPayment={handleNext} setStep={setStep} />}
            {step === 7 && <StepPayment premiumBreakdown={premiumBreakdown} onPaymentSuccess={handlePaymentSuccess} loading={loading} />}
          </div>
       </div>

       {/* FOOTER */}
       {step < 7 && (
         <div className="px-6 py-6 bg-white/95 dark:bg-[#0a0a0a]/95 backdrop-blur-2xl border-t border-gray-100 dark:border-white/5 sticky bottom-0 z-[100] shadow-[0_-15px_40px_rgba(0,0,0,0.04)]">
            <div className="max-w-xl mx-auto flex items-center justify-between gap-6">
               <div className="flex flex-col gap-0.5">
                  <div className="flex items-center gap-1.5"><Zap size={10} className="text-primary-500 fill-primary-500"/><span className="text-[0.5rem] font-black uppercase text-gray-400 tracking-[0.2em]">Estimasi Premi</span></div>
                  <p className="text-2xl font-black tracking-tight text-slate-900 dark:text-white leading-none">{premiumBreakdown ? formatIDR(premiumBreakdown.totalPayable) : 'Rp 0'}</p>
               </div>
               <div className="flex items-center gap-3">
                  {step > 0 && (<button onClick={handleBack} className="w-12 h-12 flex items-center justify-center bg-gray-50 dark:bg-white/5 rounded-2xl text-gray-400 hover:text-slate-900 dark:hover:text-white transition-all border border-black/5 active:scale-90"><ChevronLeft size={20}/></button>)}
                  <button 
                     onClick={handleNext} 
                     disabled={(step === 5 && survey.score === 0) || (step === 6 && survey.verdict === 'REJECTED')}
                     className="h-14 px-8 bg-slate-900 dark:bg-white text-white dark:text-black rounded-2xl font-black uppercase text-[0.65rem] tracking-[0.2em] shadow-xl shadow-slate-900/10 transition-all active:scale-95 flex items-center justify-center gap-3 disabled:opacity-30 group"
                  >
                     {step === 6 ? 'Checkout' : 'Lanjut'} <ChevronRight size={16} className="group-hover:translate-x-0.5 transition-transform"/>
                  </button>
               </div>
            </div>
         </div>
       )}
    </div>
  );
};

