interface StepVehicleProps {
  vehicle: any;
  setVehicle: (v: any) => void;
  entryMode: 'DATABASE' | 'MANUAL';
  setEntryMode: (m: 'DATABASE' | 'MANUAL') => void;
  handlePlateChange: (e: React.ChangeEvent<HTMLInputElement>) => void;
  formatInputCurrency: (val: string) => string;
  loading: boolean;
  setLoading: (l: boolean) => void;
  loadingType: 'KTP' | 'STNK' | 'SURVEY' | null;
  setLoadingType: (t: 'KTP' | 'STNK' | 'SURVEY' | null) => void;
  setStnkResult?: (res: any) => void; 
}

const StepVehicle: React.FC<StepVehicleProps> = ({ 
  vehicle, setVehicle, entryMode, setEntryMode, handlePlateChange, formatInputCurrency,
  loading, setLoading, loadingType, setLoadingType, setStnkResult
}) => {
  const [extractedStnk, setExtractedStnk] = useState<any>(null);

  const handleStnkAutofill = async (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (!file) return;
    setLoading(true);
    setLoadingType('STNK');
    setExtractedStnk(null);

    const reader = new FileReader();
    reader.onload = async () => {
        const base64 = reader.result as string;
        const response = await extractStnkData(base64);
        setLoading(false);
        setLoadingType(null);

        if (response.success && response.data) {
            const data = response.data;
            const cleanData = {
                ownerName: data.owner || '',
                plate: data.plate || '',
                brand: data.brand || '',
                model: data.model || '',
                color: data.color || '',
                year: data.year || '',
                vin: data.vin || '',
                engine: data.engine || '',
                status: data.status || 'OK'
            };

            setExtractedStnk(cleanData);
            if (setStnkResult) setStnkResult(cleanData);

            const match = CAR_DATABASE.find(c => 
                data.brand.toUpperCase().includes(c.brand) || 
                (c.modelName && data.brand.toUpperCase().includes(c.modelName))
            );

            const yearInt = parseInt(data.year) || 2025;
            const price = match ? (match.yearPrices[yearInt] || match.yearPrices[2024] || 0) * 1000000 : 0;

            setVehicle((prev: any) => ({
                ...prev,
                brand: match?.brand || data.brand.split(' ')[0] || prev.brand,
                model: match?.modelName || data.model || prev.model,
                year: yearInt || prev.year,
                plate: data.plate || prev.plate,
                vin: data.vin || prev.vin,
                engine: data.engine || prev.engine,
                color: data.color || prev.color,
                price: price || prev.price,
                manualPrice: !price,
                condition: yearInt < new Date().getFullYear() ? 'USED' : 'NEW'
            }));

            if (!match) setEntryMode('MANUAL');
            else setEntryMode('DATABASE');
        }
    };
    reader.readAsDataURL(file);
  };

  return (
    <div className="space-y-8 animate-fade-in relative pb-10">
      {loading && loadingType === 'STNK' && <ScannerOverlay label="Neural STNK Decryption" />}

      {/* Plate UI Redesign */}
      <div className="space-y-4">
        <label className="text-[0.6rem] font-black uppercase text-gray-500 ml-2 tracking-[0.3em]">Vehicle Identification</label>
        <div className="relative group">
          <div className="absolute -inset-1 bg-gradient-to-r from-primary-500 to-brand-500 rounded-[2.2rem] opacity-20 blur-lg group-focus-within:opacity-40 transition-opacity"></div>
          <div className="relative h-24 rounded-[2rem] bg-white dark:bg-[#0c0c0c] border-2 border-slate-200 dark:border-white/5 flex items-center shadow-inner overflow-hidden">
             <div className="w-20 h-full bg-slate-900 flex flex-col items-center justify-center border-r border-white/10">
                <span className="text-[0.5rem] font-black text-white/40 uppercase tracking-widest leading-none mb-1">RI</span>
                <span className="text-xl font-black text-primary-500">{vehicle.plate.split(' ')[0] || 'B'}</span>
             </div>
             <input 
               placeholder="1234 XYZ"
               className="flex-1 h-full bg-transparent px-6 text-3xl font-black text-slate-900 dark:text-white uppercase outline-none placeholder:text-slate-100 dark:placeholder:text-white/5 tracking-[0.1em]"
               value={vehicle.plate.substring(vehicle.plate.indexOf(' ') + 1)}
               onChange={(e) => handlePlateChange(e)}
             />
             <div className="pr-8 flex flex-col items-end opacity-40">
                <Smartphone size={24}/>
                <span className="text-[0.45rem] font-bold uppercase mt-1">Manual Input</span>
             </div>
          </div>
          <div className="mt-2 flex justify-between px-4">
             <p className="text-[0.55rem] font-bold text-primary-500 uppercase tracking-widest">{vehicle.regionName}</p>
             <p className="text-[0.55rem] font-bold text-gray-400 uppercase tracking-widest">Plate Validated</p>
          </div>
        </div>
      </div>

      <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
         <div className="space-y-2">
            <label className="text-[0.5rem] font-black uppercase text-gray-400 ml-2">Merk Unit</label>
            <div className="relative">
                <select 
                    className="w-full p-5 rounded-2xl bg-white dark:bg-white/5 border border-black/5 outline-none focus:border-primary-500 font-black text-sm appearance-none"
                    value={vehicle.brand}
                    onChange={(e) => setVehicle({...vehicle, brand: e.target.value})}
                >
                    <option value="">Cari Merk</option>
                    {Array.from(new Set(CAR_DATABASE.map(c => c.brand))).sort().map(b => <option key={b} value={b}>{b}</option>)}
                </select>
                <ChevronDown size={18} className="absolute right-4 top-1/2 -translate-y-1/2 text-gray-400 pointer-events-none"/>
            </div>
         </div>
         <div className="space-y-2">
            <label className="text-[0.5rem] font-black uppercase text-gray-400 ml-2">Model / Tipe</label>
            <input 
              placeholder="Contoh: AVANZA G 1.3"
              className="w-full p-5 rounded-2xl bg-white dark:bg-white/5 border border-black/5 outline-none focus:border-primary-500 font-black text-sm uppercase"
              value={vehicle.model}
              onChange={(e) => setVehicle({...vehicle, model: e.target.value.toUpperCase()})}
            />
         </div>
      </div>

      <div className="grid grid-cols-2 lg:grid-cols-4 gap-4">
         <div className="space-y-2">
            <label className="text-[0.5rem] font-black uppercase text-gray-400 ml-2">Tahun</label>
            <select className="w-full p-4 rounded-2xl bg-white dark:bg-white/5 border border-black/5 font-black text-sm" value={vehicle.year} onChange={(e) => setVehicle({...vehicle, year: parseInt(e.target.value)})}>
                {Array.from({length: 12}, (_, i) => 2025 - i).map(y => <option key={y} value={y}>{y}</option>)}
            </select>
         </div>
         <div className="space-y-2">
            <label className="text-[0.5rem] font-black uppercase text-gray-400 ml-2">Warna (STNK)</label>
            <div className="relative">
              <Palette size={14} className="absolute left-4 top-1/2 -translate-y-1/2 text-gray-400"/>
              <input className="w-full pl-10 pr-4 py-4 rounded-2xl bg-white dark:bg-white/5 border border-black/5 font-black text-sm uppercase" value={vehicle.color} onChange={(e) => setVehicle({...vehicle, color: e.target.value.toUpperCase()})} placeholder="HITAM"/>
            </div>
         </div>
         <div className="space-y-2 lg:col-span-2">
            <label className="text-[0.5rem] font-black uppercase text-gray-400 ml-2">Estimasi Harga Unit</label>
            <div className="relative">
               <span className="absolute left-4 top-1/2 -translate-y-1/2 font-black text-primary-500 text-xs">Rp</span>
               <input className="w-full pl-10 pr-4 py-4 rounded-2xl bg-white dark:bg-white/5 border border-black/5 font-black text-sm text-primary-500" value={formatInputCurrency(vehicle.price.toString())} onChange={(e) => setVehicle({...vehicle, price: parseInt(e.target.value.replace(/\D/g, '')) || 0, manualPrice: true})}/>
            </div>
         </div>
      </div>

      {/* Tech Info Row */}
      <div className="grid grid-cols-1 md:grid-cols-2 gap-4 pt-2">
         <div className="p-6 bg-white dark:bg-white/5 border border-black/5 rounded-[2rem] space-y-4">
            <div className="flex items-center gap-3 text-primary-500">
               <Hash size={16}/>
               <span className="text-[0.6rem] font-black uppercase tracking-widest">No. Rangka (VIN)</span>
            </div>
            <input 
              placeholder="Input 17 digit VIN"
              className="w-full bg-transparent border-b border-black/10 dark:border-white/10 pb-2 text-xs font-mono font-bold tracking-widest outline-none focus:border-primary-500 uppercase"
              value={vehicle.vin}
              onChange={(e) => setVehicle({...vehicle, vin: e.target.value.toUpperCase()})}
            />
         </div>
         <div className="p-6 bg-white dark:bg-white/5 border border-black/5 rounded-[2rem] space-y-4">
            <div className="flex items-center gap-3 text-primary-500">
               <Cpu size={16}/>
               <span className="text-[0.6rem] font-black uppercase tracking-widest">Nomor Mesin</span>
            </div>
            <input 
              placeholder="Input No. Mesin"
              className="w-full bg-transparent border-b border-black/10 dark:border-white/10 pb-2 text-xs font-mono font-bold tracking-widest outline-none focus:border-primary-500 uppercase"
              value={vehicle.engine}
              onChange={(e) => setVehicle({...vehicle, engine: e.target.value.toUpperCase()})}
            />
         </div>
      </div>

      <button 
        className="w-full p-1 bg-gradient-to-r from-emerald-500 to-teal-500 rounded-2xl group active:scale-[0.98] transition-all"
        onClick={() => document.getElementById('stnk-upload')?.click()}
      >
        <div className="bg-white dark:bg-slate-900 rounded-[0.9rem] p-4 flex items-center justify-between">
           <div className="flex items-center gap-4">
              <div className="w-10 h-10 bg-emerald-500/10 rounded-xl flex items-center justify-center text-emerald-500"><FileSearch size={24}/></div>
              <div className="text-left">
                 <p className="text-xs font-black uppercase tracking-tight text-slate-900 dark:text-white">Neural STNK Scanner</p>
                 <p className="text-[0.55rem] font-bold text-gray-400 uppercase">Ekstrak data otomatis lewat foto</p>
              </div>
           </div>
           <Sparkles size={18} className="text-emerald-500 animate-pulse"/>
        </div>
        <input id="stnk-upload" type="file" accept="image/*" className="hidden" onChange={handleStnkAutofill} />
      </button>
    </div>
  );
};

