           <button onClick={() => setLang(Language.EN)} className={`px-3 py-1 rounded-lg text-[0.6rem] font-bold ${lang === Language.EN ? 'bg-white dark:bg-slate-800 text-primary-500 shadow-sm' : 'text-gray-400'}`}>EN</button>
        </div>
      </div>

      <div className="w-full max-w-sm flex flex-col items-center space-y-8 flex-1 relative z-10">
        <div className="flex flex-col items-center">
          <div className="relative mb-6">
            <div className="p-6 bg-white dark:bg-[#111] rounded-[2.5rem] shadow-xl border border-black/5 dark:border-white/5 relative overflow-hidden">
               <SurePathLogo className="w-16 h-16 relative z-10" />
