          </div>
          <h1 className="text-3xl font-black tracking-tighter uppercase text-slate-900 dark:text-white leading-none">
             Sure<span className="text-primary-500">Path</span>
          </h1>
          <p className="text-[0.6rem] font-bold text-slate-400 uppercase tracking-[0.4em] mt-2">Personal Protection Hub</p>
        </div>

        <div className="w-full bg-white dark:bg-[#0c0c0c] rounded-[3rem] p-8 shadow-2xl border border-slate-100 dark:border-white/5">
          {mode === 'VERIFY' ? (
            <div className="space-y-8 text-center animate-pop-in">
              <div className="space-y-2">
                <h3 className="text-xl font-black uppercase">{t.otpTitle}</h3>
