  { id: 'car', title: 'Asuransi Mobil', label: 'Mobil', icon: Car, color: 'text-blue-500', active: true, cat: 'Retail', tech: 'Cek Visual AI' },
  { id: 'travel', title: 'Asuransi Travel', label: 'Travel', icon: Plane, color: 'text-emerald-500', active: true, cat: 'Retail', tech: 'Proteksi Global' },
