  const [showProviderBreakdown, setShowProviderBreakdown] = useState(false);
  const [sortBy, setSortBy] = useState<'RATING' | 'PRICE'>('RATING');
  const [isSuccess, setIsSuccess] = useState(false);
  const [generatedPolicy, setGeneratedPolicy] = useState<Policy | null>(null);

  const [vehicle, setVehicle] = useState({
    brand: '', model: '', year: 2025, isOther: false, 
    price: 0, basePrice: 0, manualPrice: false, plate: '', 
    vin: '', engine: '', color: '',
    region: '3' as '1'|'2'|'3', regionName: 'Region Lainnya', usage: 'PRIVATE', condition: 'NEW'
  });

  const [coverage, setCoverage] = useState({
    type: InsuranceType.COMPREHENSIVE as InsuranceType,
    flood: false, earthquake: false, srcc: false, 
    terrorism: false, authorized: false, 
    tpl: 0, paDriver: false, paPassenger: false,
    promo: '', discount: 0, discountType: 'NOMINAL' as 'NOMINAL' | 'PERCENT'
  });

  const [selectedProviderId, setSelectedProviderId] = useState<string | null>(null);
  const [kycData, setKycData] = useState({ 
    name: currentUser?.name || '', 
    ktp: currentUser?.ktp || '', 
    address: currentUser?.address || '', 
    email: currentUser?.email || '', 
    phone: currentUser?.phone || '', 
    photo: null as string|null 
  });
  const [verifiedFields, setVerifiedFields] = useState<Set<string>>(new Set());

  const [stnkResult, setStnkResult] = useState({
    ownerName: '',
    plate: '',
    vin: '',
    engine: '',
    color: '',
    year: '',
    status: ''
  });

  const [survey, setSurvey] = useState({ 
    stnk: null as string|null, 
    photos: {} as Record<string, string>, 
    score: 0, 
    summary: '',
    underwritingReport: '',
    detailedIssues: [] as DamageIssue[], 
    photoFlags: [] as PhotoFlag[],
    verdict: '' as 'CLEAN' | 'REVIEW_REQUIRED' | 'REJECTED' | 'MANUAL_REQUIRED' | '',
    rejectionReason: '',
    manualVerif: false, 
    manualRequestStatus: 'NONE' as 'NONE' | 'REQUESTED',
    manualDate: '',
    manualType: 'VIDEO' as 'VIDEO' | 'PHYSICAL',
    accessories: '' 
  });

  const [photoValidation, setPhotoValidation] = useState<Record<string, { status: 'LOADING' | 'VALID' | 'INVALID', msg?: string }>>({});

  const selectedProvider = useMemo(() => INSURANCE_PROVIDERS.find(p => p.id === selectedProviderId), [selectedProviderId]);

  const premiumBreakdown = useMemo(() => {
    if (!vehicle.price) return null;
    const baseRate = getOJKRate(vehicle.price / 1000000, vehicle.region, coverage.type);
    const basicPremium = (vehicle.price * baseRate) / 100;

    const expansions = [];
    if (coverage.authorized) expansions.push({ name: 'Bengkel Resmi (Authorized)', val: (vehicle.price * AUTHORIZED_WORKSHOP_RATE) / 100, rate: AUTHORIZED_WORKSHOP_RATE });
    if (coverage.flood) expansions.push({ name: 'Banjir & Angin Ribut', val: (vehicle.price * EXPANSION_RATES.FLOOD) / 100, rate: EXPANSION_RATES.FLOOD });
    if (coverage.earthquake) expansions.push({ name: 'Gempa & Tsunami', val: (vehicle.price * EXPANSION_RATES.EARTHQUAKE) / 100, rate: EXPANSION_RATES.EARTHQUAKE });

    const srccRate = coverage.type === InsuranceType.COMPREHENSIVE ? EXPANSION_RATES.SRCC.COMPREHENSIVE : EXPANSION_RATES.SRCC.TLO;
    if (coverage.srcc) expansions.push({ name: 'SRCC (Kerusuhan)', val: (vehicle.price * srccRate) / 100, rate: srccRate });

    const tsRate = coverage.type === InsuranceType.COMPREHENSIVE ? EXPANSION_RATES.TERRORISM.COMPREHENSIVE : EXPANSION_RATES.TERRORISM.TLO;
    if (coverage.terrorism) expansions.push({ name: 'Terorisme & Sabotase', val: (vehicle.price * tsRate) / 100, rate: tsRate });

    const tplPremium = (coverage.tpl / 100); 
    const expansionTotal = expansions.reduce((acc: number, curr: any) => acc + curr.val, 0) + tplPremium;
    const grossPremium = basicPremium + expansionTotal;

    const discountPercent = Math.min(coverage.discount || 0, 25);
    const discountAmount = grossPremium * (discountPercent / 100);
    const netPremium = grossPremium - discountAmount;

    return {
        baseRate, basicPremium, expansions, tplPremium, grossPremium, discountPercent, discountAmount,
        adminFee: selectedProvider?.adminFee || 0,
        stampDuty: STAMP_DUTY,
        netPremium,
        totalPayable: netPremium + (selectedProvider?.adminFee || 0) + STAMP_DUTY
    };
  }, [vehicle, coverage, selectedProvider]);

  const handleNext = () => setStep(s => Math.min(s + 1, STEPS.length - 1));
  const handleBack = () => setStep(s => Math.max(s - 1, 0));

  const handlePlateChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    let inputVal = e.target.value.toUpperCase().replace(/[^A-Z0-9 ]/g, "");
    const prefix = inputVal.split(' ')[0];
    const regionInfo = PLATE_REGIONS[prefix];

    setVehicle({
      ...vehicle, 
      plate: inputVal, 
      region: regionInfo?.region || '3', 
      regionName: regionInfo ? `${regionInfo.name} (Region ${regionInfo.region})` : 'Luar Kota'
    });
  };

  const handlePaymentSuccess = async (method: string) => {
    if (!currentUser || !premiumBreakdown) return;
    try {
      const isManualPending = survey.verdict === 'MANUAL_REQUIRED' || survey.manualRequestStatus === 'REQUESTED';

      const newPolicy: Policy = {
        userId: currentUser.id,
        type: 'CAR',
        status: isManualPending ? 'PENDING' : 'ACTIVE',
        startDate: new Date().toISOString(),
        endDate: new Date(new Date().setFullYear(new Date().getFullYear() + 1)).toISOString(),
        premium: premiumBreakdown.totalPayable,
        providerId: selectedProvider?.name || selectedProviderId || '',
        policyNumber: `POL-AUTO-${Date.now().toString().slice(-8)}`,
        createdAt: new Date().toISOString(),
        coverageDetails: { 
            vehicle: { ...vehicle, ...stnkResult }, 
            coverage, 
            survey, 
            kycData,
            financials: { ...premiumBreakdown, paymentMethod: method } 
        }
      };

      const policyId = await db.policies.add(newPolicy);
      setGeneratedPolicy({ ...newPolicy, id: policyId });

      await db.transactions.add({
        userId: currentUser.id,
        type: 'PAYMENT',
        amount: premiumBreakdown.totalPayable,
        status: 'SUCCESS',
        description: `Pembayaran ${newPolicy.policyNumber} via ${method}`,
        date: new Date().toISOString(),
        referenceId: policyId.toString()
      });

      localStorage.removeItem('SUREPATH_CAR_WIZARD_PROGRESS');
      setIsSuccess(true);
    } catch (e) {
      alert("Gagal menyimpan data asuransi. Silakan coba lagi.");
    }
  };

  return (
    <div className="flex flex-col h-full min-h-screen bg-[#f0faf7] dark:bg-[#050505] text-gray-900 dark:text-white overflow-hidden relative">
       <div className="px-6 pt-6 pb-4 bg-white/80 dark:bg-black/40 backdrop-blur-xl border-b border-gray-100 dark:border-white/5 flex flex-col gap-5 flex-shrink-0 relative z-[100]">
          <div className="flex items-center justify-between">
            <div className="flex items-center gap-4">
               <div className="w-12 h-12 bg-slate-900 dark:bg-white rounded-2xl flex items-center justify-center text-white dark:text-black shadow-xl group border border-white/10 transition-transform hover:scale-105">
                  <Car size={24} className="group-hover:rotate-12 transition-transform text-primary-500"/>
               </div>
               <div>
                  <h3 className="text-lg font-black uppercase tracking-tighter leading-none">Asuransi <span className="text-primary-500">Mobil</span></h3>
                  <p className="text-[0.45rem] font-bold text-gray-400 uppercase tracking-[0.2em] mt-1.5">Pendaftaran Cepat SurePath</p>
               </div>
            </div>
            <div className="flex items-center gap-2">
               <button onClick={onComplete} className="p-2.5 text-gray-400 hover:text-gray-900 dark:hover:text-white bg-gray-50 dark:bg-white/5 rounded-xl transition-all border border-black/5"><X size={20}/></button>
            </div>
          </div>

          <div className="flex items-center justify-between">
             <div className="flex items-center gap-2 bg-gray-100 dark:bg-white/5 px-3 py-1.5 rounded-lg border border-black/5">
                <span className="text-[0.55rem] font-black text-primary-500 uppercase tracking-widest">{STEPS[step].label}</span>
             </div>
             <p className="text-[0.5rem] font-black text-gray-400 uppercase tracking-[0.2em]">Langkah {step + 1} dari {STEPS.length}</p>
          </div>

          <div className="flex gap-1.5">
             {STEPS.map((s, i) => (
               <div key={i} className={`h-1 rounded-full flex-1 transition-all duration-700 ${i === step ? 'bg-primary-500 shadow-[0_0_10px_#10b981]' : i < step ? 'bg-primary-500/30' : 'bg-gray-100 dark:bg-white/10'}`}></div>
             ))}
          </div>
       </div>

       <div className="flex-1 overflow-y-auto px-6 py-8 no-scrollbar relative z-10">
          <div className="max-w-xl mx-auto">
            {step === 0 && <StepVehicle vehicle={vehicle} setVehicle={setVehicle} entryMode={entryMode} setEntryMode={setEntryMode} handlePlateChange={handlePlateChange} formatInputCurrency={(val) => new Intl.NumberFormat('id-ID').format(parseInt(val || "0"))} loading={loading} setLoading={setLoading} loadingType={loadingType} setLoadingType={setLoadingType} setStnkResult={setStnkResult} />}
            {step === 1 && <StepCoverage coverage={coverage} setCoverage={setCoverage} premiumBreakdown={premiumBreakdown} />}
            {step === 2 && <StepProviders sortBy={sortBy} setSortBy={setSortBy} sortedProviders={INSURANCE_PROVIDERS} selectedProviderId={selectedProviderId} setSelectedProviderId={setSelectedProviderId} premiumBreakdown={premiumBreakdown} showProviderBreakdown={showProviderBreakdown} setShowProviderBreakdown={setShowProviderBreakdown} />}
            {step === 3 && <StepKYC kycData={kycData} setKycData={setKycData} loading={loading} setLoading={setLoading} loadingType={loadingType} setLoadingType={setLoadingType} verifiedFields={verifiedFields} setVerifiedFields={setVerifiedFields} />}
            {step === 4 && <StepPreSummary vehicle={vehicle} coverage={coverage} premiumBreakdown={premiumBreakdown} showBreakdown={showBreakdown} setShowBreakdown={setShowBreakdown} stnkResult={stnkResult} kycData={kycData} />}
            {step === 5 && <StepSurvey survey={survey} setSurvey={setSurvey} stnkResult={stnkResult} setStnkResult={setStnkResult} loading={loading} setLoading={setLoading} loadingType={loadingType} setLoadingType={setLoadingType} photoValidation={photoValidation} setPhotoValidation={setPhotoValidation} vehicle={vehicle} />}
            {step === 6 && <StepFinal vehicle={vehicle} stnkResult={stnkResult} coverage={coverage} survey={survey} premiumBreakdown={premiumBreakdown} handleFinalPayment={handleNext} setStep={setStep} />}
            {step === 7 && <StepPayment premiumBreakdown={premiumBreakdown} onPaymentSuccess={handlePaymentSuccess} loading={loading} />}
          </div>
       </div>

       {step < 7 && (
         <div className="px-6 py-6 bg-white/95 dark:bg-[#0a0a0a]/95 backdrop-blur-2xl border-t border-gray-100 dark:border-white/5 sticky bottom-0 z-[100] shadow-[0_-15px_40px_rgba(0,0,0,0.04)]">
            <div className="max-w-xl mx-auto flex items-center justify-between gap-6">
               <div className="flex flex-col gap-0.5">
                  <div className="flex items-center gap-1.5"><Zap size={10} className="text-primary-500 fill-primary-500"/><span className="text-[0.5rem] font-black uppercase text-gray-400 tracking-[0.2em]">Total Harga</span></div>
                  <p className="text-2xl font-black tracking-tight text-slate-900 dark:text-white leading-none">{premiumBreakdown ? formatIDR(premiumBreakdown.totalPayable) : 'Rp 0'}</p>
               </div>
               <div className="flex items-center gap-3">
                  {step > 0 && (<button onClick={handleBack} className="w-12 h-12 flex items-center justify-center bg-gray-50 dark:bg-white/5 rounded-2xl text-gray-400 hover:text-slate-900 dark:hover:text-white transition-all border border-black/5 active:scale-90"><ChevronLeft size={20}/></button>)}
                  <button 
                     onClick={handleNext} 
                     disabled={(step === 5 && survey.score === 0) || (step === 6 && survey.verdict === 'REJECTED')}
                     className="h-14 px-8 bg-slate-900 dark:bg-white text-white dark:text-black rounded-2xl font-black uppercase text-[0.65rem] tracking-[0.2em] shadow-xl shadow-slate-900/10 transition-all active:scale-95 flex items-center justify-center gap-3 disabled:opacity-30 group"
                  >
                     {step === 6 ? 'Selesai' : 'Lanjut'} <ChevronRight size={16} className="group-hover:translate-x-0.5 transition-transform"/>
                  </button>
               </div>
            </div>
         </div>
       )}
    </div>
  );
};

export default CarInsuranceWizard;

import React, { useState } from 'react';
import { Database, Edit3, ChevronDown, User, Briefcase, Building2, Zap, Timer, FileSearch, Sparkles, CheckCircle2, RefreshCw, Smartphone, Hash, Palette, Cpu, UploadCloud, AlertCircle } from 'lucide-react';
import { CAR_DATABASE } from '../../constants';
import { extractStnkData } from '../../services/geminiService';
import { ScannerOverlay } from './WizardUI';

interface StepVehicleProps {
  vehicle: any;
  setVehicle: (v: any) => void;
  entryMode: 'DATABASE' | 'MANUAL';
  setEntryMode: (m: 'DATABASE' | 'MANUAL') => void;
  handlePlateChange: (e: React.ChangeEvent<HTMLInputElement>) => void;
  formatInputCurrency: (val: string) => string;
  loading: boolean;
  setLoading: (l: boolean) => void;
  loadingType: 'KTP' | 'STNK' | 'SURVEY' | null;
  setLoadingType: (t: 'KTP' | 'STNK' | 'SURVEY' | null) => void;
  setStnkResult?: (res: any) => void; 
}

const StepVehicle: React.FC<StepVehicleProps> = ({ 
  vehicle, setVehicle, entryMode, setEntryMode, handlePlateChange, formatInputCurrency,
  loading, setLoading, loadingType, setLoadingType, setStnkResult
}) => {
  const [extractedStnk, setExtractedStnk] = useState<any>(null);
  const [showManualForm, setShowManualForm] = useState(false);

  const handleStnkAutofill = async (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (!file) return;
    setLoading(true);
    setLoadingType('STNK');
    setExtractedStnk(null);
    setShowManualForm(false);

    const reader = new FileReader();
    reader.onload = async () => {
        const base64 = reader.result as string;
        const response = await extractStnkData(base64);
        setLoading(false);
        setLoadingType(null);

        if (response.success && response.data) {
            const data = response.data;
            const cleanData = {
                ownerName: data.owner || '',
                plate: data.plate || '',
                brand: data.brand || '',
                model: data.model || '',
                color: data.color || '',
                year: data.year || '',
                vin: data.vin || '',
                engine: data.engine || '',
                status: data.status || 'OK'
            };

            setExtractedStnk(cleanData);
            if (setStnkResult) setStnkResult(cleanData);

            const match = CAR_DATABASE.find(c => 
                data.brand.toUpperCase().includes(c.brand) || 
                (c.modelName && data.brand.toUpperCase().includes(c.modelName))
            );

            const yearInt = parseInt(data.year) || 2025;
            const price = match ? (match.yearPrices[yearInt] || match.yearPrices[2024] || 0) * 1000000 : 0;

            setVehicle((prev: any) => ({
                ...prev,
                brand: match?.brand || data.brand.split(' ')[0] || prev.brand,
                model: match?.modelName || data.model || prev.model,
                year: yearInt || prev.year,
                plate: data.plate || prev.plate,
                vin: data.vin || prev.vin,
                engine: data.engine || prev.engine,
                price: price || prev.price,
                manualPrice: !price,
                condition: yearInt < new Date().getFullYear() ? 'USED' : 'NEW'
            }));

            if (!match) setEntryMode('MANUAL');
            else setEntryMode('DATABASE');
            setShowManualForm(true);
        } else {
            alert('Gagal membaca STNK. Yuk, isi datanya manual saja.');
            setEntryMode('MANUAL');
            setShowManualForm(true);
        }
    };
    reader.readAsDataURL(file);
  };

  return (
    <div className="space-y-8 animate-fade-in relative">
      {loading && loadingType === 'STNK' && <ScannerOverlay label="Membaca Data STNK" />}

      {!extractedStnk && !showManualForm && (
        <div className="space-y-6">
            <div className="text-center space-y-2 mb-8">
                <h2 className="text-3xl font-black uppercase tracking-tighter">Data <span className="text-primary-500">Mobil</span></h2>
                <p className="text-xs text-gray-500 font-medium uppercase tracking-widest px-8">Upload foto STNK agar data terisi otomatis</p>
            </div>

            <label className="block w-full p-2 bg-gradient-to-br from-emerald-500 via-teal-500 to-blue-500 rounded-[3rem] cursor-pointer shadow-2xl hover:scale-[1.02] transition-all active:scale-95 group relative overflow-hidden">
                <div className="absolute inset-0 bg-white/10 opacity-0 group-hover:opacity-20 transition-opacity"></div>
                <div className="bg-white dark:bg-black/40 rounded-[2.8rem] py-16 flex flex-col items-center justify-center text-center gap-6 relative z-10 border border-white/20">
                    <div className="w-24 h-24 bg-emerald-500/10 rounded-[2rem] flex items-center justify-center text-emerald-500 shadow-inner group-hover:scale-110 transition-transform duration-500">
                        <UploadCloud size={48} className="animate-bounce" />
                    </div>
                    <div>
                        <h4 className="text-xl font-black uppercase tracking-tight text-gray-900 dark:text-white">Foto STNK Kamu</h4>
                        <p className="text-[0.65rem] font-bold text-emerald-600 dark:text-emerald-400 uppercase tracking-widest mt-2 flex items-center justify-center gap-2">
                           <Sparkles size={12}/> Ambil Foto / Upload Gambar
                        </p>
                    </div>
                    <div className="px-10 py-4 bg-emerald-500 text-white rounded-2xl text-[0.75rem] font-black uppercase tracking-[0.2em] shadow-lg shadow-emerald-500/20 group-hover:bg-emerald-600 transition-colors">
                        Mulai Scan
                    </div>
                </div>
                <input type="file" accept="image/*" className="hidden" onChange={handleStnkAutofill} />
            </label>

            <button 
                onClick={() => setShowManualForm(true)}
                className="w-full py-4 text-[0.6rem] font-black uppercase text-gray-400 hover:text-primary-500 transition-all tracking-[0.3em]"
            >
                Atau Isi Data Manual Saja
            </button>
        </div>
      )}

      {(extractedStnk || showManualForm) && (
        <div className="space-y-6 animate-pop-in">
           {extractedStnk && (
             <div className="p-6 bg-emerald-500/10 border-2 border-emerald-500/20 rounded-[2rem] flex items-center justify-between mb-2">
                <div className="flex items-center gap-4">
                    <div className="p-3 bg-emerald-500 rounded-2xl text-white shadow-lg"><CheckCircle2 size={24}/></div>
                    <div>
                        <p className="text-[0.55rem] font-black text-emerald-600 uppercase tracking-widest">Selesai Membaca</p>
                        <h4 className="text-sm font-black uppercase text-gray-900 dark:text-white">Data STNK Ditemukan</h4>
                    </div>
                </div>
                <button 
                    onClick={() => { setExtractedStnk(null); setShowManualForm(false); }}
                    className="p-3 bg-white dark:bg-white/10 rounded-xl text-gray-400 hover:text-rose-500 transition-all border border-black/5"
                >
                    <RefreshCw size={18}/>
                </button>
             </div>
           )}

           <div className="flex bg-gray-100 dark:bg-white/[0.03] p-1.5 rounded-[2rem] border border-black/5 dark:border-white/5 shadow-inner">
                <button 
                onClick={() => setEntryMode('DATABASE')}
                className={`flex-1 py-4 rounded-[1.8rem] text-[0.65rem] font-black uppercase tracking-widest transition-all flex items-center justify-center gap-2 ${entryMode === 'DATABASE' ? 'bg-white dark:bg-gray-800 shadow-xl text-primary-500 scale-100' : 'text-gray-400 scale-95'}`}
                >
                <Database size={16}/> Cari di Daftar
                </button>
                <button 
                onClick={() => setEntryMode('MANUAL')}
                className={`flex-1 py-4 rounded-[1.8rem] text-[0.65rem] font-black uppercase tracking-widest transition-all flex items-center justify-center gap-2 ${entryMode === 'MANUAL' ? 'bg-white dark:bg-gray-800 shadow-xl text-primary-500 scale-100' : 'text-gray-400 scale-95'}`}
                >
                <Edit3 size={16}/> Ketik Manual
                </button>
           </div>

           <div className="space-y-5">
              <div className="grid grid-cols-1 md:grid-cols-2 gap-5">
                <div className="space-y-2">
                    <label className="text-[0.6rem] font-black uppercase text-gray-500 ml-2 tracking-[0.2em]">Merk Mobil</label>
                    {entryMode === 'DATABASE' ? (
                        <div className="relative">
                            <select 
                                className="w-full p-5 rounded-[1.8rem] bg-white dark:bg-white/[0.03] border-2 border-black/5 dark:border-white/5 outline-none focus:border-primary-500 font-black text-sm appearance-none transition-all text-primary-500 uppercase"
                                value={vehicle.brand}
                                onChange={(e) => {
                                    const val = e.target.value;
                                    const unit = CAR_DATABASE.find(c => c.brand === val);
                                    const p = (unit?.yearPrices[2024] || 0) * 1000000;
                                    setVehicle({...vehicle, brand: val, model: unit?.modelName || '', price: p, basePrice: p});
                                }}
                            >
                                <option value="">Pilih Merk</option>
                                {Array.from(new Set(CAR_DATABASE.map(c => c.brand))).sort().map(b => <option key={b} value={b}>{b}</option>)}
                            </select>
                            <ChevronDown size={20} className="absolute right-5 top-1/2 -translate-y-1/2 text-gray-400 pointer-events-none"/>
                        </div>
                    ) : (
                        <input 
                            placeholder="Contoh: Toyota"
                            className="w-full p-5 rounded-[1.8rem] bg-white dark:bg-white/[0.03] border-2 border-black/5 dark:border-white/5 outline-none focus:border-primary-500 font-black text-sm transition-all text-primary-500 uppercase shadow-inner"
                            value={vehicle.brand}
                            onChange={(e) => setVehicle({...vehicle, brand: e.target.value.toUpperCase()})}
                        />
                    )}
                </div>

                <div className="space-y-2">
                    <label className="text-[0.6rem] font-black uppercase text-gray-500 ml-2 tracking-[0.2em]">Tipe / Model</label>
                    <input 
                        placeholder="Contoh: Avanza G"
                        className="w-full p-5 rounded-[1.8rem] bg-white dark:bg-white/[0.03] border-2 border-black/5 dark:border-white/5 outline-none focus:border-primary-500 font-black text-sm transition-all text-primary-500 uppercase shadow-inner"
                        value={vehicle.model}
                        onChange={(e) => setVehicle({...vehicle, model: e.target.value.toUpperCase()})}
                    />
                </div>
              </div>

              <div className="grid grid-cols-2 lg:grid-cols-3 gap-5">
                 <div className="space-y-2">
                    <label className="text-[0.6rem] font-black uppercase text-gray-500 ml-2 tracking-widest">Tahun</label>
                    <div className="relative">
                        <select 
                            className="w-full p-5 rounded-[1.8rem] bg-white dark:bg-white/[0.03] border-2 border-black/5 dark:border-white/5 outline-none focus:border-primary-500 font-black text-sm appearance-none"
                            value={vehicle.year}
                            onChange={(e) => setVehicle({...vehicle, year: parseInt(e.target.value)})}
                        >
                            {Array.from({ length: 11 }, (_, i) => 2025 - i).map(y => (
                                <option key={y} value={y}>{y}</option>
                            ))}
                        </select>
                        <ChevronDown size={18} className="absolute right-4 top-1/2 -translate-y-1/2 text-gray-400 pointer-events-none"/>
                    </div>
                 </div>

                 <div className="space-y-2 lg:col-span-1">
                    <label className="text-[0.6rem] font-black uppercase text-gray-500 ml-2 tracking-widest">Harga Mobil</label>
                    <div className="relative">
                        <span className="absolute left-5 top-1/2 -translate-y-1/2 font-black text-gray-400 text-sm">Rp</span>
                        <input 
                            type="text" inputMode="numeric"
                            className="w-full pl-12 pr-5 py-5 rounded-[1.8rem] bg-white dark:bg-white/[0.03] border-2 border-black/5 dark:border-white/5 focus:border-primary-500 outline-none font-black text-lg text-primary-500 shadow-inner"
                            value={formatInputCurrency(vehicle.price.toString())}
                            onChange={(e) => {
                                const val = e.target.value.replace(/\D/g, "");
                                setVehicle({...vehicle, price: parseInt(val || "0"), manualPrice: true});
                            }}
                        />
                    </div>
                 </div>

                 <div className="space-y-2 col-span-2 lg:col-span-1">
                    <label className="text-[0.6rem] font-black uppercase text-gray-500 ml-2 tracking-widest">Nomor Polisi</label>
                    <div className="relative group focus-within:ring-2 ring-primary-500/20 rounded-[1.8rem]">
                        <input 
                            placeholder="B 1234 ABC"
                            maxLength={12}
                            className="w-full p-5 rounded-[1.8rem] bg-white dark:bg-[#0a0a0a] border-2 border-black/10 dark:border-white/10 text-center font-black text-xl tracking-[0.2em] text-black dark:text-white uppercase outline-none shadow-inner group-focus-within:border-primary-500"
                            value={vehicle.plate}
                            onChange={handlePlateChange}
                        />
                        <div className="absolute right-4 top-1/2 -translate-y-1/2 opacity-30 group-focus-within:opacity-100 transition-opacity">
                            <Smartphone size={20}/>
                        </div>
                    </div>
                 </div>
              </div>

              <div className="grid grid-cols-1 md:grid-cols-2 gap-5 pt-4">
                 <div className="p-6 bg-white dark:bg-white/5 border border-black/5 rounded-[2.5rem] space-y-4 shadow-sm">
                    <div className="flex items-center gap-3 text-primary-500">
                       <Hash size={16}/>
                       <span className="text-[0.6rem] font-black uppercase tracking-widest">No. Rangka (VIN)</span>
                    </div>
                    <input 
                        placeholder="Cek di STNK..."
                        className="w-full bg-transparent border-b border-black/10 dark:border-white/10 pb-2 text-xs font-mono font-bold tracking-[0.2em] outline-none focus:border-primary-500 uppercase"
                        value={vehicle.vin}
                        onChange={(e) => setVehicle({...vehicle, vin: e.target.value.toUpperCase()})}
                    />
                 </div>
                 <div className="p-6 bg-white dark:bg-white/5 border border-black/5 rounded-[2.5rem] space-y-4 shadow-sm">
                    <div className="flex items-center gap-3 text-primary-500">
                       <Cpu size={16}/>
                       <span className="text-[0.6rem] font-black uppercase tracking-widest">Nomor Mesin</span>
                    </div>
                    <input 
                        placeholder="Cek di STNK..."
                        className="w-full bg-transparent border-b border-black/10 dark:border-white/10 pb-2 text-xs font-mono font-bold tracking-[0.2em] outline-none focus:border-primary-500 uppercase"
                        value={vehicle.engine}
                        onChange={(e) => setVehicle({...vehicle, engine: e.target.value.toUpperCase()})}
                    />
                 </div>
              </div>
           </div>

           <div className="space-y-4 pt-6">
                <label className="text-[0.6rem] font-black uppercase text-gray-400 ml-2 tracking-[0.4em]">Penggunaan</label>
                <div className="grid grid-cols-3 gap-3">
                    {[
                        { id: 'PRIVATE', icon: User, label: 'Pribadi' },
                        { id: 'COMMERCIAL', icon: Briefcase, label: 'Komersial' },
                        { id: 'DINAS', icon: Building2, label: 'Dinas' }
                    ].map(u => (
                        <button 
                            key={u.id}
                            onClick={() => setVehicle({...vehicle, usage: u.id as any})}
                            className={`p-5 rounded-[2rem] border-2 flex flex-col items-center gap-3 transition-all ${vehicle.usage === u.id ? 'border-primary-500 bg-primary-500/5 text-primary-500 shadow-lg' : 'border-black/5 bg-white dark:bg-white/5 text-gray-400 opacity-60'}`}
                        >
                            <u.icon size={22} className={vehicle.usage === u.id ? 'text-primary-500' : 'text-gray-400'}/>
                            <span className="text-[0.55rem] font-black uppercase tracking-widest">{u.label}</span>
                        </button>
                    ))}
                </div>
           </div>

           <button 
             onClick={() => { setExtractedStnk(null); setShowManualForm(false); }}
             className="w-full py-4 text-[0.55rem] font-black uppercase text-gray-400 hover:text-rose-500 transition-colors tracking-widest"
           >
              Ganti Mobil
           </button>
        </div>
      )}
    </div>
  );
};

export default StepVehicle;

import React, { useState, useMemo, useEffect } from 'react';
import { Camera, BrainCircuit, CheckCircle2, Scan, Smartphone, ArrowRight, MapPin, Calendar, Clock, FileText, AlertCircle, Loader2, FileSearch, Trash2, ShieldCheck, ChevronRight, Info, Rocket, Users } from 'lucide-react';
import { analyzeClaimPhoto, summarizeClaimDocument, ClaimAnalysisData, DocumentSummary } from '../services/geminiService';
import { db, Claim } from '../db';
import { NeuralBot } from './car-wizard/WizardUI';

const formatIDR = (num: number) => {
  return new Intl.NumberFormat('id-ID', {
    style: 'currency', currency: 'IDR', minimumFractionDigits: 0
  }).format(num);
};

interface ReportForm {
  chronology: string;
  location: string;
  date: string;
  time: string;
  thirdPartyInvolved: boolean;
}

const ClaimManager = ({ onComplete }: { onComplete: () => void }) => {
  const [step, setStep] = useState<'upload' | 'analyzing' | 'result' | 'docUpload' | 'docSummary' | 'reporting' | 'success'>('upload');
  const [claimResult, setClaimResult] = useState<ClaimAnalysisData | null>(null);
  const [docSummary, setDocSummary] = useState<DocumentSummary | null>(null);
  const [isSummarizing, setIsSummarizing] = useState(false);
  const [activeTab, setActiveTab] = useState<'evidence' | 'reasoning' | 'steps'>('evidence');
  const [currentUser, setCurrentUser] = useState<any>(null);
  const [photoBase64, setPhotoBase64] = useState<string>('');

  useEffect(() => {
    const saved = localStorage.getItem('SUREPATH_SESSION');
    if (saved) setCurrentUser(JSON.parse(saved));
  }, []);

  const [reportForm, setReportForm] = useState<ReportForm>({
    chronology: '',
    location: '',
    date: new Date().toISOString().split('T')[0],
    time: new Date().toLocaleTimeString([], { hour: '2-digit', minute: '2-digit', hour12: false }),
    thirdPartyInvolved: false
  });
  const [isSubmitting, setIsSubmitting] = useState(false);

  const dateLimits = useMemo(() => {
    const today = new Date();
    const max = today.toISOString().split('T')[0];
    const minDate = new Date();
    minDate.setDate(today.getDate() - 7);
    const min = minDate.toISOString().split('T')[0];
    return { min, max };
  }, []);

  const handleClaimUpload = async (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (!file) return;
    setStep('analyzing');
    const reader = new FileReader();
    reader.onload = async () => {
      const base64 = reader.result as string;
      setPhotoBase64(base64);
      const response = await analyzeClaimPhoto(base64);
      if (response.success && response.data) {
        setClaimResult(response.data);
        setStep('result');
      } else {
        alert('Maaf, AI gagal memeriksa foto. Coba gunakan foto yang lebih jelas ya.');
        setStep('upload');
      }
    };
    reader.readAsDataURL(file);
  };

  const handleDocUpload = async (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (!file) return;
    setIsSummarizing(true);
    const reader = new FileReader();
    reader.onload = async () => {
      const base64 = reader.result as string;
      const response = await summarizeClaimDocument(base64);
      setIsSummarizing(false);
      if (response.success && response.data) {
        setDocSummary(response.data);
        setStep('docSummary');
      } else {
        alert('Gagal membaca dokumen.');
      }
    };
    reader.readAsDataURL(file);
  };

  const handleFinalReport = async (e: React.FormEvent) => {
    e.preventDefault();
    if (reportForm.chronology.length < 20) {
      alert("Ceritakan kronologi lebih detail sedikit ya (min. 20 karakter).");
      return;
    }
    if (!currentUser) return;
    setIsSubmitting(true);

    try {
        const newClaim: Claim = {
            userId: currentUser.id,
            date: reportForm.date,
            time: reportForm.time,
            location: reportForm.location,
            chronology: reportForm.chronology,
            thirdPartyInvolved: reportForm.thirdPartyInvolved,
            status: 'SUBMITTED',
            amountEstimated: claimResult?.totalEstimasi || 0,
            photos: [photoBase64],
            aiAnalysis: claimResult,
            createdAt: new Date().toISOString()
        };
        await db.claims.add(newClaim);
        setTimeout(() => {
            setIsSubmitting(false);
            setStep('success');
        }, 1500);
    } catch (error) {
        alert("Gagal mengirim klaim.");
        setIsSubmitting(false);
    }
  };

  const Header = ({ title, showBack = false, onBack = () => {} }: { title: string, showBack?: boolean, onBack?: () => void }) => (
    <div className="flex items-center gap-3 mb-3">
      {showBack && (
        <button onClick={onBack} className="p-2 bg-gray-100 dark:bg-white/5 rounded-full hover:text-primary-500 transition-colors">
          <ChevronRight className="rotate-180" size={16}/>
        </button>
      )}
      <div className="w-7 h-7 bg-primary-500/10 rounded-lg flex items-center justify-center text-primary-500">
        <ShieldCheck size={16}/>
      </div>
      <h3 className="text-lg font-black uppercase tracking-tight">{title}</h3>
    </div>
  );

  if (step === 'upload') {
    return (
      <div className="space-y-3 animate-fade-in flex flex-col h-full justify-center">
        <div className="aspect-[4/3] relative rounded-[2rem] overflow-hidden bg-gray-100 dark:bg-white/5 border-2 border-dashed border-primary-500/30 flex flex-col items-center justify-center group cursor-pointer shadow-inner">
          <div className="w-14 h-14 bg-primary-500/10 rounded-full flex items-center justify-center text-primary-500 mb-2 group-hover:scale-110 transition-transform">
            <Camera size={28} />
          </div>
          <p className="text-base font-black uppercase text-gray-400 group-hover:text-primary-500 transition-colors tracking-tight">Foto Kerusakan</p>
          <p className="text-[0.5rem] text-gray-400 mt-1 font-bold uppercase tracking-widest text-center px-4">Cukup foto bagian yang rusak. AI kami akan menghitung biayanya.</p>
          <input type="file" className="absolute inset-0 opacity-0 cursor-pointer" onChange={handleClaimUpload} />
        </div>
        <div className="grid grid-cols-2 gap-2">
          <div className="p-3 rounded-xl bg-white dark:bg-white/5 border border-black/5 flex flex-col items-center text-center gap-1.5">
            <Scan size={18} className="text-primary-500" />
            <p className="text-[0.45rem] font-black uppercase tracking-widest text-gray-500">Cek Aman</p>
          </div>
          <div className="p-3 rounded-xl bg-white dark:bg-white/5 border border-black/5 flex flex-col items-center text-center gap-1.5">
            <Rocket size={18} className="text-primary-500" />
            <p className="text-[0.45rem] font-black uppercase tracking-widest text-gray-500">Kirim Kilat</p>
          </div>
        </div>
      </div>
    );
  }

  if (step === 'analyzing') {
    return (
      <div className="glass-card rounded-[2rem] p-6 animate-pop-in text-center space-y-8 flex flex-col h-full justify-center relative overflow-hidden bg-white dark:bg-[#0a0a0a]">
        <div className="absolute inset-0 pointer-events-none opacity-5 bg-[size:40px_40px] bg-[linear-gradient(to_right,#80808012_1px,transparent_1px),linear-gradient(to_bottom,#80808012_1px,transparent_1px)]"></div>

        <div className="relative mx-auto flex items-center justify-center mb-6">
           <div className="absolute inset-0 bg-primary-500/20 blur-3xl rounded-full"></div>
           <NeuralBot className="w-40 h-40 relative z-10" mood="thinking" />
        </div>

        <div className="space-y-3 z-10">
          <p className="text-[0.65rem] font-black uppercase text-primary-500 tracking-[0.2em] animate-pulse">Menghitung Kerusakan...</p>
          <div className="w-48 h-1.5 bg-gray-100 dark:bg-white/10 rounded-full mx-auto overflow-hidden">
             <div className="h-full bg-primary-500 rounded-full w-[60%] animate-shimmer-fast"></div>
          </div>
          <p className="text-[0.55rem] text-gray-400 font-bold uppercase">AI sedang memeriksa setiap detail foto.</p>
        </div>
      </div>
    );
  }

  if (step === 'result' && claimResult) {
    return (
      <div className="space-y-3 animate-pop-in h-full flex flex-col pb-2">
        <div className="p-4 glass-card rounded-[2rem] border-2 border-primary-500/20 bg-primary-500/5 relative overflow-hidden flex-shrink-0">
          <div className="absolute top-3 right-3">
            <div className="px-2 py-0.5 bg-primary-500 text-white rounded-md font-black text-[0.45rem] uppercase tracking-widest">Rusak {claimResult.severity}</div>
          </div>
          <p className="text-[0.45rem] font-black uppercase text-primary-500 tracking-[0.2em] mb-1">Estimasi Biaya Perbaikan</p>
          <h3 className="text-3xl font-black tracking-tighter mb-1">{formatIDR(claimResult.totalEstimasi)}</h3>
          <p className="text-[0.6rem] font-bold text-gray-600 dark:text-gray-300 leading-tight border-l-2 border-primary-500 pl-2">Hasil AI: {claimResult.aiInsight}</p>
        </div>

        <div className="flex bg-gray-100 dark:bg-white/5 p-0.5 rounded-lg text-[0.5rem] font-black uppercase tracking-widest">
            <button onClick={() => setActiveTab('evidence')} className={`flex-1 py-1.5 rounded-md transition-all ${activeTab === 'evidence' ? 'bg-white dark:bg-gray-700 shadow-sm text-primary-500' : 'text-gray-400'}`}>Rincian Part</button>
            <button onClick={() => setActiveTab('reasoning')} className={`flex-1 py-1.5 rounded-md transition-all ${activeTab === 'reasoning' ? 'bg-white dark:bg-gray-700 shadow-sm text-primary-500' : 'text-gray-400'}`}>Analisa AI</button>
            <button onClick={() => setActiveTab('steps')} className={`flex-1 py-1.5 rounded-md transition-all ${activeTab === 'steps' ? 'bg-white dark:bg-gray-700 shadow-sm text-primary-500' : 'text-gray-400'}`}>Langkah Klaim</button>
        </div>

        <div className="flex-1 overflow-y-auto pr-0.5 no-scrollbar min-h-0">
          {activeTab === 'evidence' && (
            <div className="animate-fade-in space-y-2 p-1">
              {claimResult.rincianPart && claimResult.rincianPart.length > 0 ? (
                claimResult.rincianPart.map((p, i) => (
                  <div key={i} className="p-3 bg-white dark:bg-white/5 rounded-xl border border-black/5 flex items-center justify-between shadow-sm">
                    <div className="flex-1">
                      <p className="font-black uppercase text-[0.6rem] tracking-tight">{p.namaPart}</p>
                      <p className="text-[0.45rem] font-bold text-gray-400 uppercase tracking-widest mt-0.5">{p.kondisi}</p>
                    </div>
                    <div className="text-right ml-4">
                      <p className="font-black text-[0.7rem] text-primary-500 leading-none">{formatIDR(p.estimasiBiaya)}</p>
                      <div className={`mt-1.5 text-[0.45rem] font-black uppercase tracking-widest px-2 py-0.5 rounded flex items-center gap-1 ${p.tindakan === 'Ganti' ? 'bg-rose-500/10 text-rose-500' : 'bg-blue-500/10 text-blue-500'}`}>
                        {p.tindakan === 'Ganti' ? <Trash2 size={8}/> : <Wrench size={8}/>}
                        {p.tindakan}
                      </div>
                    </div>
                  </div>
                ))
              ) : (
                <div className="p-6 text-center space-y-2 bg-gray-50 dark:bg-white/5 rounded-2xl border border-dashed border-gray-200 dark:border-white/10">
                   <Info size={24} className="mx-auto text-gray-300"/>
                   <p className="text-[0.55rem] font-black uppercase text-gray-400">Data part tidak ditemukan.</p>
                </div>
              )}
            </div>
          )}

          {activeTab === 'reasoning' && (
            <div className="animate-fade-in space-y-3 p-1">
                <div className="bg-primary-500/5 p-4 rounded-xl border border-primary-500/10">
                    <p className="text-[0.5rem] font-black uppercase text-primary-500 mb-2 tracking-widest flex items-center gap-2"><BrainCircuit size={10}/> Penjelasan Teknis</p>
                    <p className="text-[0.65rem] text-gray-600 dark:text-gray-300 leading-relaxed font-medium">
                        {claimResult.technicalReasoning}
                    </p>
                </div>
                <div className="bg-gray-50 dark:bg-white/5 p-4 rounded-xl border border-gray-100 dark:border-white/5">
                    <p className="text-[0.5rem] font-black uppercase text-gray-400 mb-2 tracking-widest">Rekomendasi Bengkel</p>
                    <p className="text-[0.65rem] font-bold uppercase tracking-tight text-gray-900 dark:text-white flex items-center gap-2"><MapPin size={10} className="text-primary-500"/> {claimResult.rekomendasiBengkel}</p>
                </div>
            </div>
          )}

          {activeTab === 'steps' && (
            <div className="animate-fade-in space-y-2 p-1">
                {claimResult.nextSteps.map((step, idx) => (
                    <div key={idx} className="flex gap-3 p-3 bg-emerald-50 dark:bg-emerald-950/20 rounded-xl border border-emerald-100 dark:border-emerald-900/30 items-center">
                        <div className="w-5 h-5 bg-emerald-500 text-white rounded-lg flex items-center justify-center flex-shrink-0 text-[0.6rem] font-black">{idx + 1}</div>
                        <p className="text-[0.6rem] font-bold text-emerald-900 dark:text-emerald-100 uppercase tracking-tight">{step}</p>
                    </div>
                ))}
            </div>
          )}
        </div>

        <div className="grid grid-cols-2 gap-2 pt-1 flex-shrink-0">
          <button onClick={() => setStep('docUpload')} className="py-3 bg-white dark:bg-white/5 border border-black/5 rounded-xl font-black uppercase text-[0.55rem] tracking-widest flex items-center justify-center gap-1.5 transition-all active:scale-95 shadow-sm">
            <FileSearch size={14}/> Baca Dokumen AI
          </button>
          <button onClick={() => setStep('reporting')} className="py-3 bg-primary-500 text-white rounded-xl font-black uppercase text-[0.55rem] tracking-widest shadow-lg shadow-primary-500/20 transition-all active:scale-95">Konfirmasi Klaim</button>
        </div>
      </div>
    );
  }

  if (step === 'docUpload') {
    return (
      <div className="space-y-4 animate-fade-in flex flex-col h-full justify-center">
        <Header title="Baca Dokumen Otomatis" showBack onBack={() => setStep('result')} />
        <div className="p-6 rounded-[2rem] border-2 border-dashed border-gray-300 dark:border-white/10 flex flex-col items-center justify-center text-center gap-3 relative bg-gray-50 dark:bg-white/5">
          {isSummarizing ? (
            <div className="py-6 space-y-3">
              <Loader2 className="animate-spin text-primary-500 mx-auto" size={28}/>
              <p className="text-[0.55rem] font-black uppercase text-gray-400 animate-pulse">Menghubungkan ke sistem...</p>
            </div>
          ) : (
            <>
              <FileSearch size={32} className="text-gray-300"/>
              <div className="space-y-0.5">
                <p className="font-black text-xs uppercase tracking-tight">Upload Dokumen Klaim</p>
                <p className="text-[0.45rem] font-bold text-gray-400 uppercase tracking-widest">KTP / STNK untuk mempercepat data</p>
              </div>
              <input type="file" className="absolute inset-0 opacity-0 cursor-pointer" onChange={handleDocUpload} />
            </>
          )}
        </div>
        {!isSummarizing && <button onClick={() => setStep('result')} className="w-full py-3 text-[0.5rem] font-black uppercase text-gray-400 tracking-widest">Kembali</button>}
      </div>
    );
  }

  if (step === 'docSummary' && docSummary) {
    return (
      <div className="space-y-3 animate-pop-in h-full flex flex-col">
        <Header title="Hasil Baca Dokumen" showBack onBack={() => setStep('docUpload')} />
        <div className="p-4 bg-primary-500/5 border border-primary-500/20 rounded-xl space-y-1">
          <p className="text-[0.4rem] font-black text-primary-500 uppercase tracking-widest">Nomor Polis Terdeteksi</p>
          <p className="font-black text-base tracking-tight uppercase">{docSummary.policyNumber}</p>
        </div>
        <div className="flex-1 overflow-y-auto space-y-3 no-scrollbar pr-1">
          <div className="space-y-1.5">
             <p className="text-[0.5rem] font-black uppercase text-gray-400 ml-1">Data Tervalidasi AI</p>
             <div className="grid gap-1.5">
               {docSummary.keyPoints.map((point, i) => (
                 <div key={i} className="flex gap-2 p-2.5 bg-white dark:bg-white/5 border border-black/5 rounded-xl text-[0.6rem] font-medium items-start">
                   <div className="w-3 h-3 rounded-full bg-emerald-500/10 flex items-center justify-center text-emerald-500 flex-shrink-0 mt-0.5">
                     <CheckCircle2 size={8}/>
                   </div>
                   {point}
                 </div>
               ))}
             </div>
          </div>
          <div className="p-3 bg-gray-100 dark:bg-white/5 rounded-xl space-y-1 border border-black/5">
            <p className="text-[0.45rem] font-black uppercase text-gray-400">Analisa Resiko</p>
            <p className="text-[0.6rem] italic font-bold leading-snug">{docSummary.riskAssessment}</p>
          </div>
        </div>
        <div className="grid grid-cols-2 gap-2 pt-2">
          <button onClick={() => setStep('docUpload')} className="py-3 bg-white dark:bg-white/5 border border-black/5 rounded-xl font-black uppercase text-[0.5rem] tracking-widest">Ulang Scan</button>
          <button onClick={() => setStep('reporting')} className="py-3 bg-primary-500 text-white rounded-xl font-black uppercase text-[0.5rem] tracking-widest shadow-lg">Lanjut Lapor</button>
        </div>
      </div>
    );
  }

  if (step === 'reporting') {
    return (
      <div className="animate-fade-in flex flex-col h-full">
        <Header title="Lapor Kejadian" showBack onBack={() => setStep('result')} />
        <form onSubmit={handleFinalReport} className="flex-1 overflow-y-auto pr-1 no-scrollbar space-y-3">
          <div className="grid grid-cols-2 gap-2">
            <div className="space-y-1">
              <label className="text-[0.45rem] font-black uppercase tracking-widest text-gray-400 ml-1">Tanggal Kejadian</label>
              <div className="relative">
                <Calendar size={12} className="absolute left-2.5 top-1/2 -translate-y-1/2 text-primary-500 pointer-events-none" />
                <input 
                  type="date" required 
                  min={dateLimits.min} max={dateLimits.max}
                  className="w-full pl-8 pr-2 py-2.5 rounded-xl bg-white dark:bg-white/5 border border-black/5 text-[0.65rem] outline-none focus:border-primary-500 font-bold" 
                  value={reportForm.date}
                  onChange={(e) => setReportForm({...reportForm, date: e.target.value})}
                />
              </div>
            </div>
            <div className="space-y-1">
              <label className="text-[0.45rem] font-black uppercase tracking-widest text-gray-400 ml-1">Waktu</label>
              <div className="relative">
                <Clock size={12} className="absolute left-2.5 top-1/2 -translate-y-1/2 text-primary-500 pointer-events-none" />
                <input 
                  type="time" required 
                  className="w-full pl-8 pr-2 py-2.5 rounded-xl bg-white dark:bg-white/5 border border-black/5 text-[0.65rem] outline-none focus:border-primary-500 font-bold" 
                  value={reportForm.time}
                  onChange={(e) => setReportForm({...reportForm, time: e.target.value})}
                />
              </div>
            </div>
          </div>

          <div className="space-y-1">
            <label className="text-[0.45rem] font-black uppercase tracking-widest text-gray-400 ml-1">Lokasi Kejadian</label>
            <div className="relative">
              <MapPin size={12} className="absolute left-2.5 top-1/2 -translate-y-1/2 text-primary-500" />
              <input 
                type="text" required placeholder="Contoh: Jl. Sudirman No. 12"
                className="w-full pl-8 pr-2 py-2.5 rounded-xl bg-white dark:bg-white/5 border border-black/5 text-[0.65rem] outline-none focus:border-primary-500 font-bold" 
                value={reportForm.location}
                onChange={(e) => setReportForm({...reportForm, location: e.target.value})}
              />
            </div>
          </div>

          <div className="space-y-1">
            <label className="text-[0.45rem] font-black uppercase tracking-widest text-gray-400 ml-1">Kronologi (Cerita Kejadian)</label>
            <textarea 
              required rows={3} placeholder="Ceritakan apa yang terjadi..."
              className="w-full px-3 py-2.5 rounded-xl bg-white dark:bg-white/5 border border-black/5 text-[0.6rem] outline-none focus:border-primary-500 resize-none font-medium leading-tight shadow-inner" 
              value={reportForm.chronology}
              onChange={(e) => setReportForm({...reportForm, chronology: e.target.value})}
            />
          </div>

          <div className="pt-2">
            <label className="flex items-center gap-3 p-4 bg-white dark:bg-white/5 border border-black/5 rounded-2xl cursor-pointer hover:border-primary-500/30 transition-all">
              <div className={`w-10 h-10 rounded-xl flex items-center justify-center transition-all ${reportForm.thirdPartyInvolved ? 'bg-primary-500 text-white' : 'bg-gray-100 dark:bg-white/10 text-gray-400'}`}>
                <Users size={20}/>
              </div>
              <div className="flex-1">
                <p className="text-[0.65rem] font-black uppercase tracking-widest">Ada pihak lain terlibat?</p>
                <p className="text-[0.45rem] font-bold text-gray-400 uppercase">Centang jika menabrak atau ditabrak orang lain.</p>
              </div>
              <div className={`w-6 h-6 rounded-lg border-2 flex items-center justify-center transition-all ${reportForm.thirdPartyInvolved ? 'bg-primary-500 border-primary-500' : 'border-gray-200'}`}>
                {reportForm.thirdPartyInvolved && <Check size={14} className="text-white" strokeWidth={4}/>}
              </div>
              <input 
                type="checkbox" 
                className="hidden" 
                checked={reportForm.thirdPartyInvolved}
                onChange={(e) => setReportForm({...reportForm, thirdPartyInvolved: e.target.checked})}
              />
            </label>
          </div>
        </form>

        <button 
          onClick={handleFinalReport} disabled={isSubmitting}
          className="mt-2 w-full py-4 bg-gray-900 dark:bg-white text-white dark:text-black rounded-xl font-black uppercase text-[0.55rem] tracking-[0.2em] shadow-xl flex items-center justify-center gap-2 disabled:opacity-50 transition-all active:scale-95"
        >
          {isSubmitting ? <Loader2 className="animate-spin" size={14}/> : <Rocket size={14}/>}
          Kirim Laporan Klaim
        </button>
      </div>
    );
  }

  if (step === 'success') {
    return (
      <div className="text-center space-y-4 py-4 animate-pop-in flex flex-col h-full justify-center">
        <div className="w-20 h-20 bg-emerald-500 rounded-full mx-auto flex items-center justify-center text-white shadow-2xl shadow-emerald-500/30">
          <CheckCircle2 size={40} strokeWidth={3} />
        </div>
        <div className="space-y-1">
          <h3 className="text-xl font-black uppercase tracking-tighter">Laporan <span className="text-primary-500">Terkirim</span></h3>
          <p className="text-[0.55rem] text-gray-500 dark:text-gray-400 px-4 leading-relaxed font-bold uppercase tracking-widest">
            Terima kasih! Laporan kamu sudah masuk ke sistem kami. Status klaim akan diperbarui dalam waktu <span className="text-primary-500">60 menit</span>.
          </p>
        </div>
        <div className="p-3 rounded-xl bg-gray-100 dark:bg-white/5 border border-black/5 text-left">
          <p className="text-[0.4rem] font-black text-gray-400 uppercase tracking-widest mb-0.5">Nomor Referensi</p>
          <p className="text-[0.55rem] font-mono text-primary-500 break-all leading-tight">SPD-{Date.now().toString().slice(-8)}</p>
        </div>
        <button onClick={onComplete} className="w-full py-4 bg-gray-900 dark:bg-white text-white dark:text-black rounded-xl font-black uppercase text-[0.5rem] tracking-widest shadow-xl transition-all active:scale-95">Selesai</button>
      </div>
    );
  }

  return null;
};

