            {step === 5 && <StepSurvey survey={survey} setSurvey={setSurvey} stnkResult={stnkResult} setStnkResult={setStnkResult} loading={loading} setLoading={setLoading} loadingType={loadingType} setLoadingType={setLoadingType} photoValidation={photoValidation} setPhotoValidation={setPhotoValidation} vehicle={vehicle} />}
            {step === 6 && <StepFinal vehicle={vehicle} stnkResult={stnkResult} coverage={coverage} survey={survey} premiumBreakdown={premiumBreakdown} handleFinalPayment={handleNext} setStep={setStep} />}
            {step === 7 && <StepPayment premiumBreakdown={premiumBreakdown} onPaymentSuccess={handlePaymentSuccess} loading={loading} />}
          </div>
       </div>

       {/* REVAMPED FOOTER */}
       {step < 7 && (
         <div className="px-6 py-5 bg-white/95 dark:bg-[#0a0a0a]/95 backdrop-blur-2xl border-t border-gray-100 dark:border-white/10 sticky bottom-0 z-[100] shadow-[0_-20px_40px_rgba(0,0,0,0.05)] rounded-t-[2.5rem]">
            <div className="max-w-xl mx-auto">
               <div className="flex items-center justify-between gap-6 mb-1">
                  <div className="flex flex-col">
                     <div className="flex items-center gap-1.5 opacity-60 mb-1">
                        <Zap size={10} className="text-primary-500 fill-primary-500"/>
                        <span className="text-[0.6rem] font-black uppercase text-gray-500 tracking-widest">Estimasi Premi</span>
                     </div>
                     <div className="flex items-baseline gap-1">
                        <span className="text-sm font-black text-primary-500">Rp</span>
                        <p className="text-2xl font-black tracking-tighter text-slate-900 dark:text-white leading-none">
                           {premiumBreakdown ? (premiumBreakdown.totalPayable / 1000).toLocaleString('id-ID') : '0'}
                           <span className="text-xs font-bold text-gray-400 ml-1">rb</span>
                        </p>
                     </div>
                  </div>

                  <div className="flex items-center gap-3">
                     {step > 0 && (
                        <button 
                          onClick={handleBack} 
                          className="w-14 h-14 flex items-center justify-center bg-gray-50 dark:bg-white/5 rounded-[1.5rem] text-gray-400 hover:text-slate-900 dark:hover:text-white transition-all border border-black/5 active:scale-90"
                        >
                           <ChevronLeft size={24} />
                        </button>
                     )}

                     <button 
                        onClick={handleNext} 
                        disabled={(step === 5 && survey.score === 0) || (step === 6 && survey.verdict === 'REJECTED')}
                        className={`h-14 px-10 rounded-[1.5rem] font-black uppercase text-[0.75rem] tracking-[0.2em] transition-all active:scale-95 flex items-center justify-center gap-3 disabled:opacity-30 shadow-xl group
                           ${step === 6 ? 'bg-emerald-500 text-white shadow-emerald-500/20' : 'bg-slate-900 dark:bg-white text-white dark:text-black shadow-slate-900/10'}
                        `}
                     >
                        {step === 6 ? (
                           <>
                              Lanjut Bayar
                              <Wallet size={18} className="group-hover:rotate-12 transition-transform"/>
                           </>
                        ) : (
                           <>
                              Lanjut
                              <ChevronRight size={18} className="group-hover:translate-x-0.5 transition-transform"/>
                           </>
                        )}
                     </button>
                  </div>
               </div>

               {/* Contextual instruction hint */}
               <div className="mt-2 text-center">
                  <p className="text-[0.5rem] font-bold text-gray-400 uppercase tracking-widest">
                     {step === 0 && "Lengkapi data mobilmu"}
                     {step === 1 && "Pilih cakupan proteksi"}
                     {step === 2 && "Pilih asuransi favoritmu"}
                     {step === 3 && "Verifikasi identitas KTP"}
                     {step === 4 && "Cek kembali pesananmu"}
                     {step === 5 && "Mulai audit visual AI"}
                     {step === 6 && "Satu langkah menuju aktif"}
                  </p>
               </div>
            </div>
         </div>
       )}
    </div>
  );
};

