               onClick={() => { setMethod('CC'); setSelectedSubMethod('Credit Card'); }}
               className={`p-4 rounded-2xl border-2 flex flex-col items-center gap-2 transition-all active:scale-95 ${method === 'CC' ? 'border-primary-500 bg-primary-500/5 text-primary-600' : 'border-black/5 text-gray-400 hover:border-black/10 dark:bg-white/5'}`}
            >
               <CreditCard size={24}/>
               <span className="text-[0.5rem] font-black uppercase tracking-widest">Kartu</span>
            </button>
         </div>
      </div>

      {/* Sub-Method Details Area */}
      <div className="min-h-[220px] animate-fade-in">
         {method === 'VA' && (
            <div className="space-y-3">
               <p className="text-[0.6rem] font-black text-gray-400 ml-4 uppercase tracking-[0.2em]">Pilih Bank Transfer</p>
               {vaBanks.map(bank => (
                  <button 
                     key={bank.id}
                     onClick={() => setSelectedSubMethod(bank.name)}
                     className={`w-full p-6 bg-white dark:bg-white/5 rounded-[2rem] border-2 transition-all flex items-center justify-between group active:scale-[0.98] ${selectedSubMethod === bank.name ? 'border-primary-500 shadow-xl' : 'border-black/5'}`}
                  >
                     <div className="flex items-center gap-5">
                        <img src={bank.icon} className="h-5 w-auto grayscale group-hover:grayscale-0 transition-all opacity-60 group-hover:opacity-100" alt={bank.name} />
                        <span className="text-sm font-black uppercase tracking-tight text-gray-700 dark:text-gray-200">{bank.name}</span>
                     </div>
                     <div className={`w-6 h-6 rounded-full border-2 flex items-center justify-center transition-all ${selectedSubMethod === bank.name ? 'bg-primary-500 border-primary-500 text-white' : 'border-black/10'}`}>
                        {selectedSubMethod === bank.name && <Check size={14} strokeWidth={4}/>}
                     </div>
                  </button>
               ))}
            </div>
         )}

         {method === 'EWALLET' && (
            <div className="space-y-3">
               <p className="text-[0.6rem] font-black text-gray-400 ml-4 uppercase tracking-[0.2em]">Pilih Dompet Digital</p>
               <div className="grid grid-cols-1 gap-3">
                  {eWallets.map(wallet => (
                     <button 
                        key={wallet.id}
                        onClick={() => setSelectedSubMethod(wallet.name)}
                        className={`w-full p-6 bg-white dark:bg-white/5 rounded-[2rem] border-2 transition-all flex items-center justify-between group active:scale-[0.98] ${selectedSubMethod === wallet.name ? 'border-primary-500 shadow-xl' : 'border-black/5'}`}
                     >
                        <div className="flex items-center gap-5">
                           <img src={wallet.icon} className="h-8 w-auto object-contain" alt={wallet.name} />
                           <span className="text-sm font-black uppercase tracking-tight text-gray-700 dark:text-gray-200">{wallet.name}</span>
                        </div>
                        <div className={`w-6 h-6 rounded-full border-2 flex items-center justify-center transition-all ${selectedSubMethod === wallet.name ? 'bg-primary-500 border-primary-500 text-white' : 'border-black/10'}`}>
                           {selectedSubMethod === wallet.name && <Check size={14} strokeWidth={4}/>}
                        </div>
                     </button>
                  ))}
               </div>
            </div>
         )}

         {method === 'CC' && (
            <div className="p-8 bg-white dark:bg-white/5 rounded-[3rem] border-2 border-primary-500/20 space-y-6 shadow-lg">
               <div className="flex justify-between items-center mb-2">
                  <div className="flex items-center gap-3">
                     <CreditCard size={20} className="text-primary-500"/>
                     <h4 className="text-lg font-black uppercase tracking-tighter">Kartu Kredit/Debit</h4>
                  </div>
               </div>
               <div className="space-y-4">
                  <div className="space-y-1.5">
                     <label className="text-[0.5rem] font-black text-gray-400 uppercase tracking-widest ml-1">Nomor Kartu</label>
                     <input className="w-full bg-gray-50 dark:bg-black/40 border border-black/5 dark:border-white/5 rounded-xl py-4 px-4 text-xs font-mono tracking-widest outline-none focus:border-primary-500" placeholder="4242 4242 4242 4242" />
                  </div>
                  <div className="grid grid-cols-2 gap-4">
                     <div className="space-y-1.5">
                        <label className="text-[0.5rem] font-black text-gray-400 uppercase tracking-widest ml-1">Berlaku S/D</label>
                        <input className="w-full bg-gray-50 dark:bg-black/40 border border-black/5 dark:border-white/5 rounded-xl py-4 px-4 text-xs font-mono outline-none focus:border-primary-500" placeholder="MM / YY" />
                     </div>
                     <div className="space-y-1.5">
                        <label className="text-[0.5rem] font-black text-gray-400 uppercase tracking-widest ml-1">CVC</label>
                        <input className="w-full bg-gray-50 dark:bg-black/40 border border-black/5 dark:border-white/5 rounded-xl py-4 px-4 text-xs font-mono outline-none focus:border-primary-500" placeholder="***" type="password" />
                     </div>
                  </div>
               </div>
            </div>
         )}

         {!method && (
            <div className="flex flex-col items-center justify-center py-12 opacity-40 text-center space-y-4">
               <Zap size={48} strokeWidth={1.5} className="text-primary-500 animate-pulse"/>
               <p className="text-[0.65rem] font-black uppercase tracking-[0.3em] max-w-[220px]">Pilih metode pembayaran untuk mengaktifkan polis</p>
            </div>
         )}
      </div>

      {/* Action Footer */}
      <div className="space-y-4">
         <button 
            onClick={handlePay}
            disabled={!selectedSubMethod || isProcessing}
            className="w-full py-6 bg-slate-900 dark:bg-white text-white dark:text-black rounded-[2.5rem] font-black uppercase text-base tracking-[0.3em] shadow-2xl active:scale-[0.98] transition-all disabled:opacity-30 disabled:scale-100 flex items-center justify-center gap-4 relative overflow-hidden"
         >
            {isProcessing ? (
               <>
                  <Loader2 size={24} className="animate-spin text-primary-500"/>
                  <span>Memproses...</span>
               </>
            ) : (
               <>
                  <Zap size={24} className="text-primary-500 fill-primary-500"/>
                  <span>BAYAR SEKARANG</span>
               </>
            )}
         </button>

         {/* BAYAR NANTI OPTION */}
         {!isProcessing && (
           <button 
              onClick={handlePayLater}
              className="w-full py-5 bg-white dark:bg-white/5 border border-black/10 dark:border-white/10 text-slate-500 dark:text-gray-400 rounded-[2.5rem] font-black uppercase text-[0.65rem] tracking-[0.3em] active:scale-95 transition-all flex items-center justify-center gap-3 group"
           >
              <CalendarClock size={18} className="group-hover:text-primary-500 transition-colors"/>
              BAYAR NANTI (PROSES POLIS DULU)
           </button>
         )}

         <div className="flex flex-wrap justify-center items-center gap-x-8 gap-y-4 opacity-40 pt-4">
            <div className="flex items-center gap-2"><ShieldCheck size={12}/><span className="text-[0.45rem] font-black uppercase tracking-widest">PCI-DSS Secure</span></div>
            <div className="flex items-center gap-2"><Smartphone size={12}/><span className="text-[0.45rem] font-black uppercase tracking-widest">Xendit Handshake</span></div>
            <div className="flex items-center gap-2"><Info size={12}/><span className="text-[0.45rem] font-black uppercase tracking-widest">Powered by SurePath Pay</span></div>
         </div>
      </div>
    </div>
  );
};

export default StepPayment;

import React, { useState, useMemo, useEffect } from 'react';
import { Car, RefreshCw, X, ChevronLeft, ChevronRight, Zap, ShieldCheck, CheckCircle2, FileText, ArrowRight, Wallet, Clock, AlertTriangle } from 'lucide-react';
import { getOJKRate, EXPANSION_RATES, AUTHORIZED_WORKSHOP_RATE, STAMP_DUTY, PLATE_REGIONS, INSURANCE_PROVIDERS } from '../constants';
import { InsuranceType } from '../types';
import { db, Policy, Transaction } from '../db';
import { DamageIssue, PhotoFlag } from '../services/geminiService';
import { formatIDR } from './car-wizard/WizardUI';

// Import Steps
import StepVehicle from './car-wizard/StepVehicle';
import StepCoverage from './car-wizard/StepCoverage';
import StepProviders from './car-wizard/StepProviders';
import StepKYC from './car-wizard/StepKYC';
import StepPreSummary from './car-wizard/StepPreSummary';
import StepSurvey from './car-wizard/StepSurvey';
import StepFinal from './car-wizard/StepFinal';
import StepPayment from './car-wizard/StepPayment';

const STEPS = [
  { id: 'VEHICLE', label: 'Data Mobil' },
  { id: 'COVERAGE', label: 'Pilih Proteksi' },
  { id: 'PROVIDERS', label: 'Pilih Perusahaan' },
  { id: 'KYC', label: 'Data Diri' },
  { id: 'PRESUMMARY', label: 'Cek Pesanan' },
  { id: 'SURVEY', label: 'Cek Kondisi' },
  { id: 'REVIEW', label: 'Ringkasan' },
  { id: 'PAYMENT', label: 'Bayar' }
];

const CarInsuranceWizard = ({ onComplete, currentUser }: { onComplete: () => void, currentUser?: any }) => {
  const [step, setStep] = useState(0);
  const [loading, setLoading] = useState(false);
  const [loadingType, setLoadingType] = useState<'KTP' | 'STNK' | 'SURVEY' | null>(null);
  const [entryMode, setEntryMode] = useState<'DATABASE' | 'MANUAL'>('DATABASE');
  const [showBreakdown, setShowBreakdown] = useState(false);
  const [showProviderBreakdown, setShowProviderBreakdown] = useState(false);
  const [sortBy, setSortBy] = useState<'RATING' | 'PRICE'>('RATING');
  const [isSuccess, setIsSuccess] = useState(false);
  const [isPayLater, setIsPayLater] = useState(false);
  const [generatedPolicy, setGeneratedPolicy] = useState<Policy | null>(null);

  const [vehicle, setVehicle] = useState({
    brand: '', model: '', year: 2025, isOther: false, 
    price: 0, basePrice: 0, manualPrice: false, plate: '', 
    vin: '', engine: '', color: '',
    region: '3' as '1'|'2'|'3', regionName: 'Region Lainnya', usage: 'PRIVATE', condition: 'NEW'
  });

  const [coverage, setCoverage] = useState({
    type: InsuranceType.COMPREHENSIVE as InsuranceType,
    flood: false, earthquake: false, srcc: false, 
    terrorism: false, authorized: false, 
    tpl: 0, 
    paDriver: 0, 
    paPassenger: 0,
    promo: '', discount: 0, discountType: 'NOMINAL' as 'NOMINAL' | 'PERCENT'
  });

  const [selectedProviderId, setSelectedProviderId] = useState<string | null>(null);
  const [kycData, setKycData] = useState({ 
    name: currentUser?.name || '', 
    ktp: currentUser?.ktp || '', 
    address: currentUser?.address || '', 
    email: currentUser?.email || '', 
    phone: currentUser?.phone || '', 
    photo: null as string|null 
  });
  const [verifiedFields, setVerifiedFields] = useState<Set<string>>(new Set());

  const [stnkResult, setStnkResult] = useState({
    ownerName: '',
    plate: '',
    vin: '',
    engine: '',
    color: '',
    year: '',
    status: ''
  });

  const [survey, setSurvey] = useState({ 
    stnk: null as string|null, 
    photos: {} as Record<string, string>, 
    score: 0, 
    summary: '',
    underwritingReport: '',
    detailedIssues: [] as DamageIssue[], 
    photoFlags: [] as PhotoFlag[],
    verdict: '' as 'CLEAN' | 'REVIEW_REQUIRED' | 'REJECTED' | 'MANUAL_REQUIRED' | '',
    rejectionReason: '',
    manualVerif: false, 
    manualRequestStatus: 'NONE' as 'NONE' | 'REQUESTED',
    manualDate: '',
    manualType: 'VIDEO' as 'VIDEO' | 'PHYSICAL',
    accessories: '' 
  });

  const [photoValidation, setPhotoValidation] = useState<Record<string, { status: 'LOADING' | 'VALID' | 'INVALID', msg?: string }>>({});

  const selectedProvider = useMemo(() => INSURANCE_PROVIDERS.find(p => p.id === selectedProviderId), [selectedProviderId]);

  const premiumBreakdown = useMemo(() => {
    if (!vehicle.price) return null;
    const baseRate = getOJKRate(vehicle.price / 1000000, vehicle.region, coverage.type);
    const basicPremium = (vehicle.price * baseRate) / 100;

    const expansions = [];
    if (coverage.authorized) expansions.push({ name: 'Bengkel Resmi (Authorized)', val: (vehicle.price * AUTHORIZED_WORKSHOP_RATE) / 100, rate: AUTHORIZED_WORKSHOP_RATE });
    if (coverage.flood) expansions.push({ name: 'Banjir & Angin Ribut', val: (vehicle.price * EXPANSION_RATES.FLOOD) / 100, rate: EXPANSION_RATES.FLOOD });
    if (coverage.earthquake) expansions.push({ name: 'Gempa & Tsunami', val: (vehicle.price * EXPANSION_RATES.EARTHQUAKE) / 100, rate: EXPANSION_RATES.EARTHQUAKE });

    const srccRate = coverage.type === InsuranceType.COMPREHENSIVE ? EXPANSION_RATES.SRCC.COMPREHENSIVE : EXPANSION_RATES.SRCC.TLO;
    if (coverage.srcc) expansions.push({ name: 'SRCC (Kerusuhan)', val: (vehicle.price * srccRate) / 100, rate: srccRate });

    const tsRate = coverage.type === InsuranceType.COMPREHENSIVE ? EXPANSION_RATES.TERRORISM.COMPREHENSIVE : EXPANSION_RATES.TERRORISM.TLO;
    if (coverage.terrorism) expansions.push({ name: 'Terorisme & Sabotase', val: (vehicle.price * tsRate) / 100, rate: tsRate });

    const tplPremium = (coverage.tpl / 100); 
    const paDriverPremium = (coverage.paDriver * EXPANSION_RATES.PA_DRIVER) / 100;
    const paPassengerPremium = (coverage.paPassenger * 4 * EXPANSION_RATES.PA_PASSENGER) / 100; // Assume 4 passengers

    const expansionTotal = expansions.reduce((acc: number, curr: any) => acc + curr.val, 0) + tplPremium + paDriverPremium + paPassengerPremium;
    const grossPremium = basicPremium + expansionTotal;

    const discountPercent = Math.min(coverage.discount || 0, 25);
    const discountAmount = grossPremium * (discountPercent / 100);
    const netPremium = grossPremium - discountAmount;

    return {
        baseRate, basicPremium, expansions, tplPremium, paDriverPremium, paPassengerPremium, grossPremium, discountPercent, discountAmount,
        adminFee: selectedProvider?.adminFee || 0,
        stampDuty: STAMP_DUTY,
        netPremium,
        totalPayable: netPremium + (selectedProvider?.adminFee || 0) + STAMP_DUTY
    };
  }, [vehicle, coverage, selectedProvider]);

  const handleNext = () => setStep(s => Math.min(s + 1, STEPS.length - 1));
  const handleBack = () => setStep(s => Math.max(s - 1, 0));

  const handlePlateChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    let inputVal = e.target.value.toUpperCase().replace(/[^A-Z0-9 ]/g, "");
    const prefix = inputVal.split(' ')[0];
    const regionInfo = PLATE_REGIONS[prefix];

    setVehicle({
      ...vehicle, 
      plate: inputVal, 
      region: regionInfo?.region || '3', 
      regionName: regionInfo ? `${regionInfo.name} (Region ${regionInfo.region})` : 'Luar Kota'
    });
  };

  const handlePaymentResult = async (method: string, resultStatus: 'SUCCESS' | 'PENDING_PAYMENT') => {
    if (!currentUser || !premiumBreakdown) return;
    try {
      const isManualPending = survey.verdict === 'MANUAL_REQUIRED' || survey.manualRequestStatus === 'REQUESTED';

      const status: any = resultStatus === 'PENDING_PAYMENT' ? 'PENDING' : (isManualPending ? 'PENDING' : 'ACTIVE');
      setIsPayLater(resultStatus === 'PENDING_PAYMENT');

      const newPolicy: Policy = {
        userId: currentUser.id,
        type: 'CAR',
        status: status,
        startDate: new Date().toISOString(),
        endDate: new Date(new Date().setFullYear(new Date().getFullYear() + 1)).toISOString(),
        premium: premiumBreakdown.totalPayable,
        providerId: selectedProvider?.name || selectedProviderId || '',
        policyNumber: `POL-AUTO-${Date.now().toString().slice(-8)}`,
        createdAt: new Date().toISOString(),
        coverageDetails: { 
            vehicle: { ...vehicle, ...stnkResult }, 
            coverage, 
            survey, 
            kycData,
            financials: { ...premiumBreakdown, paymentMethod: method, finalStatus: resultStatus } 
        }
      };

      const policyId = await db.policies.add(newPolicy);
      setGeneratedPolicy({ ...newPolicy, id: policyId });

      await db.transactions.add({
        userId: currentUser.id,
        type: 'PAYMENT',
        amount: premiumBreakdown.totalPayable,
        status: resultStatus === 'SUCCESS' ? 'SUCCESS' : 'PENDING',
        description: `Pembayaran ${newPolicy.policyNumber} via ${method}`,
        date: new Date().toISOString(),
        referenceId: policyId.toString()
      });

      localStorage.removeItem('SUREPATH_CAR_WIZARD_PROGRESS');
      setIsSuccess(true);
    } catch (e) {
      alert("Neural sync error: Gagal menyimpan data polis. " + e);
    }
  };

  if (isSuccess && generatedPolicy) {
     return (
        <div className="flex flex-col items-center justify-center h-full min-h-screen p-8 text-center bg-[#f0faf7] dark:bg-[#050505] animate-fade-in">
           {isPayLater ? (
              <div className="w-24 h-24 bg-amber-500 rounded-[2.5rem] flex items-center justify-center text-white shadow-2xl mb-8 animate-pop-in">
                 <Clock size={56} strokeWidth={2.5}/>
              </div>
           ) : (
              <div className="w-24 h-24 bg-emerald-500 rounded-[2.5rem] flex items-center justify-center text-white shadow-2xl mb-8 animate-pop-in">
                 <ShieldCheck size={56} strokeWidth={2.5}/>
              </div>
           )}

           <div className="space-y-4 mb-12">
              <h2 className="text-4xl font-black uppercase tracking-tighter text-slate-900 dark:text-white">
                 Polis <span className={isPayLater ? "text-amber-500" : "text-emerald-500"}>{isPayLater ? "Tersimpan" : "Aktif"}</span>
              </h2>
              <p className="text-[0.7rem] font-bold text-gray-500 uppercase tracking-widest max-w-sm mx-auto">
                 {isPayLater 
                   ? "Data pendaftaran telah kami simpan. Segera lakukan pembayaran di menu akun untuk mengaktifkan perlindungan Anda."
                   : "Neural Node Teraktivasi. Perlindungan asuransi Anda telah terdaftar dan aktif secara real-time di sistem kami."}
              </p>
           </div>

           <div className="w-full max-w-sm bg-white dark:bg-white/5 border border-black/5 dark:border-white/5 rounded-[3rem] p-8 space-y-6 shadow-xl mb-10">
              <div className="flex justify-between items-center text-[0.6rem] font-black uppercase text-gray-400 tracking-widest">
                 <span>ID Polis</span>
                 <span className="text-primary-500 font-mono">{generatedPolicy.policyNumber}</span>
              </div>
              <div className="flex justify-between items-center text-[0.6rem] font-black uppercase text-gray-400 tracking-widest">
                 <span>Status</span>
                 <span className={`px-3 py-1 rounded-lg border text-[0.55rem] font-black uppercase tracking-widest ${isPayLater ? 'bg-amber-500/10 text-amber-500 border-amber-500/20' : 'bg-emerald-500/10 text-emerald-500 border-emerald-500/20'}`}>
                    {isPayLater ? 'Menunggu Pembayaran' : generatedPolicy.status}
                 </span>
              </div>
              <div className="pt-6 border-t border-black/5 flex justify-between items-center">
                 <div className="flex items-center gap-3">
                    <div className="w-10 h-10 bg-blue-500/10 rounded-xl flex items-center justify-center text-blue-500"><Car size={20}/></div>
                    <div className="text-left">
                       <p className="text-xs font-black uppercase text-slate-900 dark:text-white">{vehicle.brand} {vehicle.model}</p>
                       <p className="text-[0.5rem] font-bold text-gray-400 uppercase tracking-widest">{vehicle.plate}</p>
                    </div>
                 </div>
                 {isPayLater ? <AlertTriangle size={20} className="text-amber-500"/> : <CheckCircle2 size={20} className="text-emerald-500"/>}
              </div>
           </div>

           <div className="w-full max-w-sm space-y-4">
              <button 
                onClick={onComplete}
                className="w-full py-5 bg-slate-900 dark:bg-white text-white dark:text-black rounded-2xl font-black uppercase text-sm tracking-[0.2em] shadow-xl active:scale-95 transition-all flex items-center justify-center gap-3"
              >
                Kembali ke Beranda <ArrowRight size={18}/>
              </button>
           </div>
        </div>
     );
  }

  return (
    <div className="flex flex-col h-full min-h-screen bg-[#f0faf7] dark:bg-[#050505] text-gray-900 dark:text-white overflow-hidden relative">
       {/* HEADER SECTION */}
       <div className="px-6 pt-6 pb-4 bg-white/80 dark:bg-black/40 backdrop-blur-xl border-b border-gray-100 dark:border-white/5 flex flex-col gap-5 flex-shrink-0 relative z-[100]">
          <div className="flex items-center justify-between">
            <div className="flex items-center gap-4">
               <div className="w-12 h-12 bg-slate-900 dark:bg-white rounded-2xl flex items-center justify-center text-white dark:text-black shadow-xl group border border-white/10 transition-transform hover:scale-105">
                  <Car size={24} className="group-hover:rotate-12 transition-transform text-primary-500"/>
               </div>
               <div>
                  <h3 className="text-lg font-black uppercase tracking-tighter leading-none">Asuransi <span className="text-primary-500">Mobil</span></h3>
                  <p className="text-[0.45rem] font-bold text-gray-400 uppercase tracking-[0.2em] mt-1.5">Pendaftaran Cepat SurePath</p>
               </div>
            </div>
            <div className="flex items-center gap-2">
               <button onClick={onComplete} className="p-2.5 text-gray-400 hover:text-gray-900 dark:hover:text-white bg-gray-50 dark:bg-white/5 rounded-xl transition-all border border-black/5"><X size={20}/></button>
            </div>
          </div>

          <div className="flex items-center justify-between">
             <div className="flex items-center gap-2 bg-gray-100 dark:bg-white/5 px-3 py-1.5 rounded-lg border border-black/5">
                <span className="text-[0.55rem] font-black text-primary-500 uppercase tracking-widest">{STEPS[step].label}</span>
             </div>
             <p className="text-[0.5rem] font-black text-gray-400 uppercase tracking-[0.2em]">Langkah {step + 1} dari {STEPS.length}</p>
          </div>

          <div className="flex gap-1.5">
             {STEPS.map((s, i) => (
               <div key={i} className={`h-1 rounded-full flex-1 transition-all duration-700 ${i === step ? 'bg-primary-500 shadow-[0_0_10px_#10b981]' : i < step ? 'bg-primary-500/30' : 'bg-gray-100 dark:bg-white/10'}`}></div>
             ))}
          </div>
       </div>

       {/* MAIN CONTENT AREA */}
       <div className="flex-1 overflow-y-auto px-6 py-8 no-scrollbar relative z-10">
          <div className="max-w-xl mx-auto">
            {step === 0 && <StepVehicle vehicle={vehicle} setVehicle={setVehicle} entryMode={entryMode} setEntryMode={setEntryMode} handlePlateChange={handlePlateChange} formatInputCurrency={(val) => new Intl.NumberFormat('id-ID').format(parseInt(val || "0"))} loading={loading} setLoading={setLoading} loadingType={loadingType} setLoadingType={setLoadingType} setStnkResult={setStnkResult} />}
            {step === 1 && <StepCoverage coverage={coverage} setCoverage={setCoverage} premiumBreakdown={premiumBreakdown} />}
            {step === 2 && <StepProviders sortBy={sortBy} setSortBy={setSortBy} sortedProviders={INSURANCE_PROVIDERS} selectedProviderId={selectedProviderId} setSelectedProviderId={setSelectedProviderId} premiumBreakdown={premiumBreakdown} showProviderBreakdown={showProviderBreakdown} setShowProviderBreakdown={setShowProviderBreakdown} />}
            {step === 3 && <StepKYC kycData={kycData} setKycData={setKycData} loading={loading} setLoading={setLoading} loadingType={loadingType} setLoadingType={setLoadingType} verifiedFields={verifiedFields} setVerifiedFields={setVerifiedFields} />}
            {step === 4 && <StepPreSummary vehicle={vehicle} coverage={coverage} premiumBreakdown={premiumBreakdown} showBreakdown={showBreakdown} setShowBreakdown={setShowBreakdown} stnkResult={stnkResult} kycData={kycData} />}
            {step === 5 && <StepSurvey survey={survey} setSurvey={setSurvey} stnkResult={stnkResult} setStnkResult={setStnkResult} loading={loading} setLoading={setLoading} loadingType={loadingType} setLoadingType={setLoadingType} photoValidation={photoValidation} setPhotoValidation={setPhotoValidation} vehicle={vehicle} />}
            {step === 6 && <StepFinal vehicle={vehicle} stnkResult={stnkResult} coverage={coverage} survey={survey} premiumBreakdown={premiumBreakdown} handleFinalPayment={handleNext} setStep={setStep} />}
            {step === 7 && <StepPayment premiumBreakdown={premiumBreakdown} onPaymentSuccess={handlePaymentResult} loading={loading} />}
          </div>
       </div>

       {/* FOOTER */}
       {step < 7 && (
         <div className="px-6 py-5 bg-white/95 dark:bg-[#0a0a0a]/95 backdrop-blur-2xl border-t border-gray-100 dark:border-white/10 sticky bottom-0 z-[100] shadow-[0_-20px_40px_rgba(0,0,0,0.05)] rounded-t-[2.5rem]">
            <div className="max-w-xl mx-auto">
               <div className="flex items-center justify-between gap-6 mb-1">
                  <div className="flex flex-col">
                     <div className="flex items-center gap-1.5 opacity-60 mb-1">
                        <Zap size={10} className="text-primary-500 fill-primary-500"/><span className="text-[0.6rem] font-black uppercase text-gray-500 tracking-widest">Estimasi Premi</span>
                     </div>
                     <div className="flex items-baseline gap-1">
                        <span className="text-sm font-black text-primary-500">Rp</span>
                        <p className="text-2xl font-black tracking-tighter text-slate-900 dark:text-white leading-none">
                           {premiumBreakdown ? (premiumBreakdown.totalPayable / 1000).toLocaleString('id-ID') : '0'}
                           <span className="text-xs font-bold text-gray-400 ml-1">rb</span>
                        </p>
                     </div>
                  </div>

                  <div className="flex items-center gap-3">
                     {step > 0 && (
                        <button 
                          onClick={handleBack} 
                          className="w-14 h-14 flex items-center justify-center bg-gray-50 dark:bg-white/5 rounded-[1.5rem] text-gray-400 hover:text-slate-900 dark:hover:text-white transition-all border border-black/5 active:scale-90"
                        >
                           <ChevronLeft size={24} />
