            <div className="w-64 h-1 bg-gray-100 dark:bg-white/5 rounded-full overflow-hidden mx-auto">
                <div className="h-full bg-primary-500 transition-all duration-300" style={{ width: `${progress}%` }}></div>
            </div>
          </div>
        </div>
