            <div className="flex flex-col">
              <span className="font-black text-xl tracking-tighter uppercase leading-none text-slate-900 dark:text-white">Sure<span className="text-brand-500">Path</span></span>
              <span className="text-[0.45rem] font-bold text-gray-400 uppercase tracking-widest">{currentUser?.name || 'Halo!'}</span>
            </div>
          </div>
          <div className="flex items-center gap-2">
            <button onClick={() => setDarkMode(!darkMode)} className="p-2.5 bg-white dark:bg-white/10 rounded-xl text-gray-400 border border-gray-100">
              {darkMode ? <Sun size={18}/> : <Moon size={18}/>}
            </button>
            <button onClick={handleLogout} className="p-2.5 bg-slate-900 dark:bg-white text-white dark:text-black rounded-xl shadow-lg">
               <LogOut size={18}/>
            </button>
          </div>
        </header>
      )}
      <main className={`flex-1 overflow-y-auto w-full no-scrollbar z-10 relative ${isWizardFlow ? 'p-0 h-screen' : 'px-6 py-6'}`}>
        {renderPortalContent()}
      </main>
      {!isWizardFlow && currentUser && (
        <nav className="flex-shrink-0 fixed bottom-6 inset-x-6 h-16 bg-white/90 dark:bg-[#111]/90 backdrop-blur-xl z-[70] flex items-center justify-around px-2 rounded-2xl shadow-2xl border border-gray-100 dark:border-white/10 max-w-xl mx-auto transition-all duration-500">
          {navItems.map(item => (
