    { role: UserRole.INSURANCE_ADMIN, label: 'Insurer Admin', email: 'zurich@surepath.ai', icon: Building2, color: 'bg-blue-600', desc: 'Partnership Data' },
    { role: UserRole.AGENT, label: 'Premier Agent', email: 'agent@surepath.ai', icon: Briefcase, color: 'bg-amber-500', desc: 'Deployment Node' },
    { role: UserRole.CUSTOMER, label: 'Standard User', email: 'user@surepath.ai', icon: UserCircle, color: 'bg-slate-700', desc: 'Protection Layer' },
  ];

  return (
