              <div className="flex-1">
                 <p className="text-[0.6rem] font-black text-brand-400 uppercase tracking-[0.2em] mb-1">VERIFICATION_CODE_RECEIVED</p>
                 <div className="flex items-center gap-4">
                    <span className="text-3xl font-black text-white tracking-[0.3em] font-mono">{generatedOtp}</span>
                    <button onClick={() => { setOtp(generatedOtp); setShowIncomingOtp(false); }} className="ml-auto px-5 py-2 bg-brand-500 text-white rounded-xl text-[0.65rem] font-black uppercase">Copy</button>
                 </div>
