                    <p className="text-[0.55rem] font-bold text-gray-400 uppercase tracking-widest">Select an authorized node</p>
                  </div>
                  <button onClick={() => setMode('LOGIN')} className="p-3 hover:bg-slate-100 dark:hover:bg-white/10 rounded-2xl transition-all text-slate-400"><X size={20}/></button>
               </div>
               <div className="grid grid-cols-1 sm:grid-cols-2 gap-4">
                  {demoRoles.map((dr, i) => (
                    <button 
                      key={i} 
                      onClick={() => handleQuickDemo(dr.email)}
                      disabled={loading}
                      className="p-6 bg-slate-50 dark:bg-white/[0.02] rounded-[2.2rem] border border-black/5 hover:border-brand-500/50 transition-all flex flex-col items-start gap-4 active:scale-95 group relative overflow-hidden"
                    >
                      <div className={`w-12 h-12 ${dr.color} rounded-2xl flex items-center justify-center text-white shadow-lg group-hover:scale-110 transition-transform`}>
                         <dr.icon size={22}/>
                      </div>
                      <div className="text-left relative z-10">
                         <span className="text-xs font-black uppercase tracking-tight text-slate-900 dark:text-white block">{dr.label}</span>
                         <span className="text-[0.5rem] font-bold text-gray-400 uppercase tracking-widest mt-1 block opacity-80">{dr.desc}</span>
                      </div>
                    </button>
                  ))}
               </div>
            </div>
          ) : mode === 'VERIFY' ? (
            <div className="space-y-10 text-center animate-pop-in py-6">
              <div className="space-y-3">
                <h3 className="text-2xl font-black uppercase tracking-tight">Security Token</h3>
                <p className="text-[0.65rem] text-slate-500 font-bold uppercase tracking-widest">Awaiting neural handshake...</p>
              </div>
              <input 
                type="tel" maxLength={6} placeholder="000000"
                className="w-full bg-transparent border-b-2 border-slate-100 dark:border-white/10 text-center text-5xl font-black tracking-[0.4em] text-brand-500 outline-none focus:border-brand-500 transition-all"
                value={otp} onChange={(e) => { setOtp(e.target.value.replace(/\D/g,'')); setError(null); }}
              />
              <button 
                onClick={async () => {
                  if(otp === generatedOtp) {
                    setLoading(true);
                    setStatusMsg('IDENTITY_ANCHORED');
                    // Logic to finalize registration...
                    const newUser: DBUser = {
                      name: formData.name, email: formData.email, phone: formData.phone,
                      role: UserRole.CUSTOMER, nodeId: `SP-NODE-${Math.floor(1000+Math.random()*9000)}`,
                      verified: true, trustScore: 85, memberSince: new Date().toISOString()
                    };
                    setTimeout(() => onAuthSuccess(newUser), 1000);
                  } else {
                    setError("Token mismatch detected.");
                  }
                }} 
                disabled={otp.length < 6} 
                className="w-full py-5 bg-slate-900 dark:bg-white text-white dark:text-black rounded-2xl font-black uppercase text-sm shadow-xl active:scale-95 disabled:opacity-30 tracking-[0.2em]"
              >
                Authenticate Node
              </button>
            </div>
          ) : (
            <form onSubmit={handleAuth} className="space-y-8">
              <div className="flex bg-slate-100 dark:bg-white/[0.05] p-1.5 rounded-[1.8rem] mb-2 border border-black/5">
                <button type="button" onClick={() => setMode('LOGIN')} className={`flex-1 py-3 rounded-2xl text-[0.65rem] font-black uppercase tracking-widest transition-all ${mode === 'LOGIN' ? 'bg-white dark:bg-slate-700 text-brand-500 shadow-xl scale-100' : 'text-gray-400 opacity-60 scale-95'}`}>{lang === Language.ID ? 'Masuk' : 'Log In'}</button>
                <button type="button" onClick={() => setMode('REGISTER')} className={`flex-1 py-3 rounded-2xl text-[0.65rem] font-black uppercase tracking-widest transition-all ${mode === 'REGISTER' ? 'bg-white dark:bg-slate-700 text-brand-500 shadow-xl scale-100' : 'text-gray-400 opacity-60 scale-95'}`}>{lang === Language.ID ? 'Daftar' : 'Sign Up'}</button>
              </div>

              <div className="space-y-6">
                {mode === 'REGISTER' && (
                  <div className="space-y-6 animate-fade-in">
                    <InputField icon={User} label={lang === Language.ID ? 'Nama Lengkap' : 'Full Name'} value={formData.name} onChange={(v:any)=>setFormData({...formData, name: v})} placeholder="Registry Name" />
                    <InputField icon={Smartphone} label={lang === Language.ID ? 'Nomor HP' : 'Mobile Number'} value={formData.phone} onChange={(v:any)=>setFormData({...formData, phone: v})} placeholder="0812..." />
                  </div>
                )}

                <InputField icon={Globe} label="Email Address" type="email" value={formData.email} onChange={(v:any)=>setFormData({...formData, email: v})} placeholder="email@registry.ai" />
                <InputField icon={KeyRound} label="Master Key" type="password" value={formData.password} onChange={(v:any)=>setFormData({...formData, password: v})} showPass={showPass} setShowPass={setShowPass} placeholder="••••••••" />
              </div>

              {error && (
                <div className="flex items-center gap-3 p-4 bg-rose-500/10 border border-rose-500/20 rounded-2xl text-rose-500 animate-pop-in">
                   <ShieldAlert size={18}/>
                   <p className="text-[0.65rem] font-black uppercase tracking-tight">{error}</p>
                </div>
              )}

              <div className="space-y-4 pt-4">
                <button type="submit" disabled={loading} className="w-full py-5 bg-slate-900 dark:bg-white text-white dark:text-black rounded-[1.8rem] font-black uppercase text-sm tracking-[0.2em] shadow-[0_20px_40px_-10px_rgba(0,0,0,0.2)] hover:scale-[1.02] active:scale-95 transition-all flex items-center justify-center gap-4 group disabled:opacity-50">
                   {loading ? <RefreshCw size={20} className="animate-spin text-brand-500"/> : (mode === 'LOGIN' ? 'Access Matrix' : 'Initialize Node')} 
                   {!loading && <ArrowRight size={20} className="group-hover:translate-x-2 transition-transform text-brand-500"/>}
                </button>

                <button 
                  type="button" 
                  onClick={() => setMode('DEMO_SELECT')}
                  className="w-full py-5 bg-brand-500/10 text-brand-600 dark:text-brand-400 border border-brand-500/20 rounded-[1.8rem] font-black uppercase text-[0.65rem] tracking-[0.3em] hover:bg-brand-500 hover:text-white transition-all flex items-center justify-center gap-3 active:scale-95 shadow-sm"
                >
                  <Zap size={16} fill="currentColor"/> {lang === Language.ID ? 'Akses Demo Hub' : 'Enter Demo Hub'}
                </button>
              </div>

              {mode === 'LOGIN' && <button type="button" className="w-full text-center text-[0.6rem] font-black text-slate-400 uppercase hover:text-brand-500 transition-colors tracking-widest">RECOVERY_PROTOCOL_REQUEST</button>}
            </form>
          )}
        </div>

        <div className="flex flex-col items-center gap-6 opacity-40 py-8">
           <div className="flex items-center gap-8">
              <div className="flex items-center gap-3"><ShieldIcon size={16} className="text-brand-500"/><span className="text-[0.6rem] font-black uppercase tracking-widest">OJK REGULATED</span></div>
              <div className="flex items-center gap-3"><Fingerprint size={16} className="text-blue-500"/><span className="text-[0.6rem] font-black uppercase tracking-widest">BIOMETRIC SECURE</span></div>
           </div>
        </div>
      </div>
    </div>
  );
};

export default AuthGate;
